#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void print_usage() {
    fprintf(stderr, "Usage: program [options] [input_file]\n");
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -h, --help          Display help message\n");
    fprintf(stderr, "  -m, --manpage       Output comprehensive manual page\n");
    fprintf(stderr, "  -c, --count-only    Print only the number of lines\n");
    fprintf(stderr, "  -o, --output-file   Specify output file (default: stdout)\n");
}

void print_manpage() {
    printf("Comprehensive manual page for the program...\n");
}

int count_lines(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    int line_count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
    }
    fclose(file);
    return line_count;
}

void process_file(const char *filename, const char *output_filename, int count_only) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening input file");
        return;
    }

    FILE *output = output_filename ? fopen(output_filename, "w") : stdout;
    if (!output) {
        fprintf(stderr, "Error opening output file\n");
        fclose(file);
        return;
    }

    char buffer[256];
    int line_count = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        if (!count_only) {
            fputs(buffer, output);
        }
        line_count++;
    }

    if (!count_only) {
        fclose(output);
    } else {
        printf("Line count: %d\n", line_count);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    int opt;
    int count_only = 0;
    const char *input_file = NULL;
    const char *output_file = NULL;

    while ((opt = getopt(argc, argv, "hmco:")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return 0;
            case 'm':
                print_manpage();
                return 0;
            case 'c':
                count_only = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                print_usage();
                return 1;
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    } else {
        process_file(NULL, output_file, count_only);
        return 0;
    }

    process_file(input_file, output_file, count_only);
    return 0;
}
