#include <string.h>

// Define the structure for an event
typedef struct {
    char *timestamp;
    char *event_type;
    char *description;
} Event;

// Function to process log file and generate summary report
void processLog(const char *inputFile, const char *outputFile, const char *filterCriteria, int includeDetailedErrors) {
    FILE *logFile = fopen(inputFile, "r");
    if (!logFile) {
        fprintf(stderr, "Failed to open input log file: %s\n", inputFile);
        return;
    }

    FILE *summaryFile = fopen(outputFile, "w");
    if (!summaryFile) {
        fprintf(stderr, "Failed to create output summary file: %s\n", outputFile);
        fclose(logFile);
        return;
    }

    // Dynamically allocate memory for events
    Event *events = (Event *)malloc(100 * sizeof(Event)); // Initial capacity of 100 events
    int eventCount = 0;

    char line[256];
    while (fgets(line, sizeof(line), logFile)) {
        // Parse the log line and create an event
        Event event;
        event.timestamp = strsep(&line, " ");
        event.event_type = strsep(&line, " ");
        event.description = strsep(&line, "\n");

        if (!event.timestamp || !event.event_type || !event.description) {
            fprintf(stderr, "Error parsing log line: %s\n", line);
            continue;
        }

        // Apply filter criteria
        if (strstr(event.description, filterCriteria)) {
            events[eventCount++] = event;

            // Reallocate memory if necessary
            if (eventCount >= 100) {
                Event *newEvents = (Event *)realloc(events, (eventCount + 50) * sizeof(Event));
                if (!newEvents) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    break;
                }
                events = newEvents;
            }
        }
    }

    fclose(logFile);

    // Generate summary report
    fprintf(summaryFile, "Summary Report:\n");
    for (int i = 0; i < eventCount; i++) {
        fprintf(summaryFile, "%s %s %s\n", events[i].timestamp, events[i].event_type, events[i].description);
    }

    if (includeDetailedErrors) {
        // Include detailed error logs section
        fprintf(summaryFile, "\nError Logs:\n");
        // Logic to include detailed error logs here
    }

    fclose(summaryFile);

    // Free dynamically allocated memory
    for (int i = 0; i < eventCount; i++) {
        free(events[i].timestamp);
        free(events[i].event_type);
        free(events[i].description);
    }
    free(events);
}

// Main function to handle command-line arguments and call the processing function
int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <filter_criteria> <include_detailed_errors>\n", argv[0]);
        return 1;
    }

    int includeDetailedErrors = atoi(argv[4]) ? 1 : 0;
    processLog(argv[1], argv[2], argv[3], includeDetailedErrors);

    return 0;
}
