#define MAX_INPUT_SIZE 10000

void printErrorAndExit() {
    fprintf(stderr, "Input out of range or non-integer value encountered.\n");
    exit(1);
}

int findLargestInteger(int* arr, int size) {
    if (size <= 0 || arr == NULL) return -1;

    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

int main() {
    int* array = malloc(MAX_INPUT_SIZE * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    int size = 0;
    while (size < MAX_INPUT_SIZE && scanf("%d", &array[size]) != EOF) {
        // Check for valid integer range
        if ((array[size] > 2147483647 || array[size] < -2147483648)) {
            printErrorAndExit();
        }
        size++;
    }

    int largest = findLargestInteger(array, size);
    printf("The largest integer is: %d\n", largest);

    free(array);
    return 0;
}
