import java.util.Arrays;

public class Pokemon {
    private String type;

    public Pokemon(String type) {
        this.type = type;
    }

    public String getType() {
        return type;
    }
}

public class Main {
    public static void main(String[] args) {
        // Create a sample Pokemon object
        Pokemon pokemon = new Pokemon("Fire");

        // Get weaknesses of the Pokemon
        String weaknesses = getPokemonWeaknesses(pokemon);

        System.out.println("Pokemon Weaknesses: " + weaknesses);
    }

    public static String getPokemonWeaknesses(Pokemon pokemon) {
        switch (pokemon.getType()) {
            case "Fire":
                return "Water, Ground";
            case "Water":
                return "Grass, Electric";
            case "Grass":
                return "Fire, Ice, Flying";
            default:
                return "Unknown";
        }
    }
}
