public class PokemonAnalyzer {

    public static void generateReport(Pokemon pokemon) {
        try {
            String name = pokemon.getName();
            List<Type> types = pokemon.getTypes();

            System.out.println("Detailed Report for: " + name);
            System.out.println("Types: " + types.stream().map(Type::getName).collect(Collectors.joining(", ")));

            List<String> weaknesses = new ArrayList<>();
            for (Type type : types) {
                switch (type.getName()) {
                    case "normal":
                        weaknesses.add("fighting");
                        break;
                    case "fire":
                        weaknesses.add("water", "ground", "rock");
                        break;
                    // Add cases for other types
                    default:
                        break;
                }
            }

            System.out.println("Weaknesses: " + weaknesses.stream().collect(Collectors.joining(", ")));

            Map<String, String> countermeasures = new HashMap<>();
            countermeasures.put("fighting", "Use Grass-type moves");
            countermeasures.put("water", "Use Fire-type moves");
            // Add more countermeasures for other weaknesses

            System.out.println("Countermeasures:");
            for (Map.Entry<String, String> entry : countermeasures.entrySet()) {
                System.out.println(entry.getKey() + ": " + entry.getValue());
            }

        } catch (Exception e) {
            System.err.println("Error generating report: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Example usage
        Pokemon pikachu = new Pokemon("pikachu");
        generateReport(pikachu);
    }
}
