#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define NUM_RESOURCES 5

int available_resources;
sem_t resource_semaphore;

void* resource_user(void* arg) {
    int thread_id = *(int*)arg;

    // Request a resource
    sem_wait(&resource_semaphore);
    printf("Thread %d acquired a resource\n", thread_id);

    // Simulate some work
    sleep(1);

    // Release the resource
    sem_post(&resource_semaphore);
    printf("Thread %d released a resource\n", thread_id);

    pthread_exit(NULL);
}

int main() {
    pthread_t threads[NUM_RESOURCES];
    int thread_ids[NUM_RESOURCES];

    // Initialize semaphore with available resources
    sem_init(&resource_semaphore, 0, NUM_RESOURCES);

    // Create threads to simulate concurrent access
    for (int i = 0; i < NUM_RESOURCES; ++i) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, resource_user, &thread_ids[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < NUM_RESOURCES; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up semaphore
    sem_destroy(&resource_semaphore);

    printf("All resources have been released\n");

    return 0;
}
