#include <boost/log/trivial.hpp>
#include <boost/log/sources/severity_logger.hpp>
#include <boost/log/sources/record_ostream.hpp>
#include <boost/log/utility/setup/file.hpp>
#include <boost/log/utility/setup/console.hpp>
#include <boost/log/support/date_time.hpp>
#include <boost/log/expressions.hpp>

namespace LoggerNamespace {
    enum class SeverityLevel {
        Trace,
        Debug,
        Info,
        Warning,
        Error
    };

    namespace keywords = boost::log::keywords;

    class LogManager {
    public:
        static void init() {
            auto core = boost::log::core::get();
            core->add_global_attribute("TimeStamp", boost::log::attributes::local_clock());

            auto file_sink = boost::make_shared<boost::log::sinks::text_file_backend>(
                keywords::file_name = "sample_%N.log",
                keywords::auto_flush = true
            );
            core->add_sink(file_sink);

            auto console_sink = boost::make_shared<boost::log::sinks::text_ostream_backend>();
            core->add_sink(console_sink);

            boost::shared_ptr<boost::log::sinks::synchronous_sink<boost::log::sinks::text_file_backend>> file_sink_wrapper(
                new boost::log::sinks::synchronous_sink<boost::log::sinks::text_file_backend>(file_sink)
            );
            boost::shared_ptr<boost::log::sinks::synchronous_sink<boost::log::sinks::text_ostream_backend>> console_sink_wrapper(
                new boost::log::sinks::synchronous_sink<boost::log::sinks::text_ostream_backend>(console_sink)
            );

            file_sink_wrapper->set_filter(boost::log::trivial::severity >= SeverityLevel::Info);
            console_sink_wrapper->set_filter(boost::log::trivial::severity >= SeverityLevel::Debug);

            boost::log::add_common_attributes();
        }

        static void setLogLevel(SeverityLevel level) {
            boost::this_thread::get_severity_level() = level;
        }

        template<typename T>
        static void log(SeverityLevel level, const T& message) {
            BOOST_LOG_SEV(boost::log::trivial::severity, level) << message;
        }
    };
}

int main() {
    LoggerNamespace::LogManager::init();
    LoggerNamespace::LogManager::setLogLevel(LoggerNamespace::SeverityLevel::Debug);

    LoggerNamespace::LogManager::log(LoggerNamespace::SeverityLevel::Trace, "This is a trace message");
    LoggerNamespace::LogManager::log(LoggerNamespace::SeverityLevel::Debug, "This is a debug message");
    LoggerNamespace::LogManager::log(LoggerNamespace::SeverityLevel::Info, "This is an info message");
    LoggerNamespace::LogManager::log(LoggerNamespace::SeverityLevel::Warning, "This is a warning message");
    LoggerNamespace::LogManager::log(LoggerNamespace::SeverityLevel::Error, "This is an error message");

    return 0;
}
