using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DatabaseQueryExecutor
{
    public async Task<List<Task<IDataReader>>> ExecuteQueriesAsync(List<string> sqlCommands, string connectionString, int timeout)
    {
        var tasks = new List<Task<IDataReader>>();
        using (var connectionPool = new SqlConnectionStringBuilder(connectionString))
        {
            foreach (var command in sqlCommands)
            {
                var task = ExecuteQueryAsync(connectionPool.ConnectionString, command, timeout);
                tasks.Add(task);
            }
        }
        return await Task.WhenAll(tasks);
    }

    private async Task<IDataReader> ExecuteQueryAsync(string connectionString, string query, int timeout)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                var command = new SqlCommand(query, connection) { CommandTimeout = timeout };
                return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
            }
            catch (Exception ex)
            {
                // Handle exceptions gracefully here, e.g., log the error or rethrow it
                throw;
            }
        }
    }
}
