using System;
using System.Collections.Generic;
using System.Xml.XPath;

public class XmlParser
{
    public static Dictionary<string, string> ParseXml(string xml, string elementName)
    {
        if (string.IsNullOrEmpty(xml))
        {
            throw new ArgumentException("XML string cannot be null or empty.");
        }

        var result = new Dictionary<string, string>();
        try
        {
            XPathDocument doc = new XPathDocument(new System.IO.StringReader(xml));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//*[local-name()='{elementName}' or @*[local-name()='{elementName}']]");

            if (nodes.MoveNext())
            {
                XPathNavigator node = nodes.Current;
                result.Add(node.NamespaceURI, node.LocalName);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
        }

        return result;
    }
}
