import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class StateLoader {
    private static final Object lock = new Object();
    private static final int CACHE_SIZE = 100;
    private static final HashMap<String, MoSTState> cache = new LinkedHashMap<>(CACHE_SIZE, 0.75f, true) {
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > CACHE_SIZE;
        }
    };

    public static MoSTState loadState(String filePath) {
        synchronized (lock) {
            if (cache.containsKey(filePath)) {
                return cache.get(filePath);
            }

            File file = new File(filePath);
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    MoSTState state = (MoSTState) obj;
                    if (validateChecksum(state, file)) {
                        cache.put(filePath, state);
                        return state;
                    } else {
                        System.err.println("Integrity check failed for: " + filePath);
                    }
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }

            return null;
        }
    }

    private static boolean validateChecksum(MoSTState state, File file) throws IOException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        String expectedChecksum = getExpectedChecksum(state);
        return Arrays.equals(md.digest(), Base64.getDecoder().decode(expectedChecksum));
    }

    private static String getExpectedChecksum(MoSTState state) {
        // Implement logic to calculate the checksum based on the state object
        // This could involve serializing the state, hashing parts of it, etc.
        return "expected_checksum_here";
    }
}

class MoSTState implements Serializable {
    // Define your fields and methods here
}
