function analyzeTextForBibleReferences(text) {
  const bookCounts = {};

  if (typeof window !== 'undefined' && typeof require === 'function') {
    try {
      const advancedProcessor = require('advanced-text-processor');
      // Integrate with third-party library
      advancedProcessor.process(text);
    } catch (e) {
      console.log('Failed to load third-party library, using fallback.');
    }
  }

  let match;
  while ((match = bookRegex.exec(text)) !== null) {
    const bookName = match[0].toLowerCase();
    if (bookCounts.hasOwnProperty(bookName)) {
      bookCounts[bookName]++;
    } else {
      bookCounts[bookName] = 1;
    }
  }

  return bookCounts;
