function insertWidgets(widgets, sectionId) {
  const validTypes = ['text', 'image', 'video'];
  const section = document.getElementById(sectionId);

  if (!section) return '';

  widgets.forEach(widget => {
    if (validTypes.includes(widget.type)) {
      let element;
      switch (widget.type) {
        case 'text':
          element = document.createElement('p');
          break;
        case 'image':
          element = document.createElement('img');
          element.src = widget.content;
          break;
        case 'video':
          element = document.createElement('iframe');
          element.src = widget.content;
          break;
      }

      if (element) {
        element.innerHTML = widget.title;
        for (const option in widget.options) {
          if (widget.options.hasOwnProperty(option)) {
            element.setAttribute(option, widget.options[option]);
          }
        }
        section.appendChild(element);
      }
    }
  });

  return section.outerHTML;
}
