    this.fieldsToRefresh = ['name', 'email'];

    this.refreshFields = function() {
        angular.forEach($scope.dialogFields, function(field) {
            if (this.fieldsToRefresh.includes(field.name)) {
                $window.parent.postMessage({ field: field.name }, '*');
                window.addEventListener('message', function(event) {
                    if (event.origin !== 'http://your-origin.com') return;
                    if (event.data.success) {
                        field.value = event.data.value;
                    }
                });
            }
        }.bind(this));
    };

    this.sendRequestToPHP = function(action, data) {
        var url = '/api/users';
        var method = action === 'delete' ? 'DELETE' : 'POST';

        return $http({
            method: method,
            url: url,
            data: data
        }).then(function(response) {
            return response.data;
        });
    };

    this.handlePHPRequest = function(reqData) {
        if (reqData.sub_action === 'update') {
            // Update user account
            return this.sendRequestToPHP('PUT', reqData);
        } else if (reqData.sub_action === 'create') {
            // Create new user account
            return this.sendRequestToPHP('POST', reqData);
        } else if (reqData.sub_action === 'delete') {
            // Delete user account
            return this.sendRequestToPHP('DELETE', { id: reqData.id });
        }
    };

    $scope.saveAccount = function() {
        var requestData = {
            name: $scope.user.name,
            email: $scope.user.email,
            password: $scope.user.password,
            sub_action: $scope.subAction
        };

        return this.handlePHPRequest(requestData);
    };
}
