function GraphDatabaseManager() {
    let streamData = [];
    let db = null;
    let isPaused = false;

    function connectToDB() {
        // Connect to a graph database here (e.g., using Neo4j Driver)
        db = neo4j.driver('bolt://localhost', neo4j.auth.basic('username', 'password'));
    }

    function disconnectFromDB() {
        if (db) {
            db.close();
        }
    }

    async function addRandomVerticesAndEdges(count) {
        for (let i = 0; i < count; i++) {
            let vertex = { id: Math.random().toString(36).substr(2, 9), property: Math.floor(Math.random() * 100) };
            let edges = [];
            for (let j = 0; j < Math.floor(Math.random() * 5); j++) {
                let targetVertexId = Math.random().toString(36).substr(2, 9);
                edges.push({ id: `${vertex.id}-${targetVertexId}`, from: vertex.id, to: targetVertexId });
            }
            await db.writeTransaction(tx => tx.run('CREATE (v:Vertex {id: $id, property: $property}) RETURN v', vertex));
            for (let edge of edges) {
                await db.writeTransaction(tx => tx.run('MATCH (from:Vertex {id: $from}), (to:Vertex {id: $to}) CREATE (from)-[:RELATION]->(to)', edge));
            }
        }
    }

    function pauseStream() {
        isPaused = true;
    }

    function resumeStream() {
        isPaused = false;
        processStream();
    }

    async function processStream() {
        while (!isPaused && streamData.length > 0) {
            let dataPoint = streamData.shift();
            await addRandomVerticesAndEdges(dataPoint.count);
        }
    }

    return {
        connect: connectToDB,
        disconnect: disconnectFromDB,
        collectData: (data) => {
            if (!isPaused) {
                streamData.push(data);
                processStream();
            } else {
                streamData.push(data);
            }
        },
        pause: pauseStream,
        resume: resumeStream
    };
}
