const crypto = require('crypto');

class BufferedData {
    constructor(data) {
        this.data = data;
        this.offset = 0;
    }

    copyBytes(numBytes, bufferSize = 16384) {
        if (numBytes <= 0 || !Number.isInteger(numBytes)) {
            throw new Error('Invalid byte count');
        }

        const resultBuffer = Buffer.allocUnsafe(numBytes);
        let bytesCopied = 0;

        while (bytesCopied < numBytes) {
            const chunkSize = Math.min(bufferSize, numBytes - bytesCopied);
            const chunk = this.data.slice(this.offset, this.offset + chunkSize);
            chunk.copy(resultBuffer, bytesCopied);
            bytesCopied += chunk.length;
            this.offset += chunk.length;

            if (this.offset >= this.data.length) {
                break;
            }
        }

        return resultBuffer;
    }

    async processAsync(numBytes, bufferSize = 16384) {
        try {
            const resultBuffer = await new Promise((resolve, reject) => {
                const interval = setInterval(() => {
                    const chunk = this.copyBytes(bufferSize);
                    if (chunk.length === 0) {
                        clearInterval(interval);
                        resolve(resultBuffer);
                    } else {
                        // Simulate asynchronous processing
                        setTimeout(() => {}, 1); // Adjust delay for actual processing time
                    }
                }, 0);
            });

            return resultBuffer;
        } catch (error) {
            console.error('Error during async data processing:', error);
            throw error;
        }
    }

    logOperation(operation, message) {
        console.log(`[${operation}] ${message}`);
    }
}

// Example usage
const dataChunks = [Buffer.from('Hello'), Buffer.from('World')];
const bufferedData = new BufferedData(Buffer.concat(dataChunks));

try {
    const copiedData = bufferedData.copyBytes(5);
    console.log('Copied Data:', copiedData.toString());
} catch (error) {
    console.error('Error during data copy:', error);
}

bufferedData.logOperation('COPY', 'Copying 3 bytes');
const asyncResult = bufferedData.processAsync(3);
asyncResult.then(buffer => {
    console.log('Async Process Result:', buffer.toString());
}).catch(error => {
    console.error('Error during async processing:', error);
});
```

This code defines a `BufferedData` class with methods for copying bytes from a list of buffered data chunks and processing data asynchronously. It includes error handling, logging, and optimization for high concurrency."]

