async function collectAccessibleElements() {
  const accessibleElements = [];
  const walker = document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_ELEMENT,
    {
      acceptNode(node) {
        if (isAccessibleNode(node)) {
          return NodeFilter.FILTER_ACCEPT;
        }
        return NodeFilter.FILTER_SKIP;
      },
    },
    false
  );

  while (walker.nextNode()) {
    accessibleElements.push(walker.currentNode);
  }

  // Handle dynamically loaded content
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.ELEMENT_NODE && isAccessibleNode(node)) {
          accessibleElements.push(node);
        }
      });
    });
  });

  observer.observe(document.body, { childList: true, subtree: true });

  return accessibleElements;
}

function isAccessibleNode(node) {
  // Define your accessibility criteria here
  const hasAltText = node.tagName === 'IMG' && node.alt !== '';
  const hasARIAAttributes = Object.keys(node.attributes).some((attr) => attr.startsWith('aria-'));
  return hasAltText || hasARIAAttributes;
}
