import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.CompletableFuture;

public class FileHasher {

    public static void main(String[] args) {
        String filePath = "path/to/your/file";
        CompletableFuture.runAsync(() -> {
            try {
                byte[] fileHash = calculateFileHash(filePath);
                System.out.println("File hash: " + bytesToHex(fileHash));
            } catch (IOException | NoSuchAlgorithmException e) {
                e.printStackTrace();
            }
        });
    }

    public static byte[] calculateFileHash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        FileInputStream fis = new FileInputStream(filePath);
        byte[] buffer = new byte[8192];
        int bytesRead;
        while ((bytesRead = fis.read(buffer)) != -1) {
            digest.update(buffer, 0, bytesRead);
        }
        fis.close();
        return digest.digest();
    }

    public static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
```

This Java program includes a method `calculateFileHash` that calculates the MD5 hash of a file using an asynchronous approach. It reads the file in chunks to manage memory usage effectively and handles potential I/O errors gracefully. The program also provides a utility method `bytesToHex` to convert the byte array containing the hash into a hexadecimal string.']

