logging.basicConfig(filename='update_log.txt', level=logging.ERROR)

def log_errors(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.error(f"Error in {func.__name__}: {e}")
            raise
    return wrapper

class CacheUpdater:
    @log_errors
    def update_cache(self, release_id, version_info):
        # Simulate cache update
        print(f"Updating cache for release {release_id} with version {version_info}")

class DatabaseUpdater:
    @log_errors
    def update_database(self, release_id, version_info):
        # Simulate database update
        print(f"Updating database for release {release_id} with version {version_info}")

class UpdateManager:
    def __init__(self):
        self.cache_updater = CacheUpdater()
        self.db_updater = DatabaseUpdater()

    @log_errors
    def update_release(self, release_id, version_info):
        with ThreadPoolExecutor() as executor:
            futures = [
                executor.submit(self.cache_updater.update_cache, release_id, version_info),
                executor.submit(self.db_updater.update_database, release_id, version_info)
            ]
            for future in concurrent.futures.as_completed(futures):
                future.result()

