class UserAuthenticator {
    private $apiUrl;
    private $cache;

    public function __construct($apiUrl, $cache) {
        $this->apiUrl = $apiUrl;
        $this->cache = $cache;
    }

    public function authenticateUser($email, $token) {
        try {
            $rateLimitKey = 'auth_rate_limit:' . $email;
            if ($this->cache->get($rateLimitKey)) {
                throw new Exception('Too many authentication attempts. Please try again later.');
            }

            $response = $this->makeApiRequest($email, $token);
            $userData = json_decode($response, true);

            if (isset($userData['error'])) {
                throw new Exception($userData['error']);
            }

            $_SESSION['user'] = $userData;
            $this->cache->set('auth_rate_limit:' . $email, time() + 300); // Allow one attempt per 5 minutes
        } catch (Exception $e) {
            echo 'Authentication failed: ' . $e->getMessage();
        }
    }

    private function makeApiRequest($email, $token) {
        $url = $this->apiUrl . '?email=' . urlencode($email) . '&token=' . urlencode($token);
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        $response = curl_exec($ch);

        if (curl_errno($ch)) {
            throw new Exception('Network error: ' . curl_error($ch));
        }

        return $response;
    }
}

// Usage example:
$apiUrl = 'https://third-party-api.com/verify_email';
$cache = new Memcached();
$cache->addServer('127.0.0.1', 11211);
$userAuthenticator = new UserAuthenticator($apiUrl, $cache);

if (!isset($_SESSION)) {
    session_start();
}

if (isset($_POST['email']) && isset($_POST['token'])) {
    $userAuthenticator->authenticateUser($_POST['email'], $_POST['token']);
}
?>
