typedef struct Transaction {
    time_t timestamp;
    int id;
    double amount;
    unsigned char metadata;
    AgeCategory age_category;
    double weighted_sum;
} Transaction;

Transaction transaction_buffer[MAX_TRANSACTIONS];
int buffer_index = 0;

double calculate_weighted_sum(double amount, AgeCategory age) {
    // Placeholder for dynamic multiplier logic
    return amount * (age == RECENT ? 2 : (age == MEDIUM_AGE ? 1.5 : 1));
}

void process_transaction(Transaction transaction) {
    if (buffer_index >= MAX_TRANSACTIONS) {
        buffer_index = 0; // Reset buffer if full
    }
    transaction_buffer[buffer_index++] = transaction;

    double max_weighted_sum = -1;
    int most_recent_max_id = -1;

    for (int i = 0; i < SLIDING_WINDOW_SIZE && i < buffer_index; i++) {
        Transaction current_transaction = transaction_buffer[(buffer_index - 1) - i];
        current_transaction.weighted_sum = calculate_weighted_sum(current_transaction.amount, current_transaction.age_category);

        if (current_transaction.weighted_sum > max_weighted_sum) {
            max_weighted_sum = current_transaction.weighted_sum;
            most_recent_max_id = current_transaction.id;
        }
    }

    printf("Processed Transaction ID: %d, Weighted Sum: %.2f, Max Weighted Sum: %.2f\n", 
           transaction.id, transaction.weighted_sum, max_weighted_sum);
}

