    process_transaction((Transaction){timestamp, 1, 100.50, 0, RECENT});
    process_transaction((Transaction){timestamp + 1, 2, 200.75, 0, MEDIUM_AGE});
    process_transaction((Transaction){timestamp + 2, 3, -50.25, 0, OLD});

