using System;
using Random = System.Random;

public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        Random random = new Random();
        return (float)(random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public int GenerateRandomInt()
    {
        Random random = new Random();
        int value = (int)((random.NextDouble() * (_maxValue - _minValue)) / 5.0f) * 5;
        return Math.Max(value, (int)_minValue);
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(float shrinkFactor)
    {
        if (shrinkFactor <= 0 || shrinkFactor >= 1)
        {
            throw new ArgumentException("Shrink factor must be between 0 and 1.");
        }
        float newMin = _minValue + (_maxValue - _minValue) * shrinkFactor;
        float newMax = _maxValue - (_maxValue - _minValue) * (1 - shrinkFactor);
        if (newMin < newMax)
        {
            _minValue = newMin;
            _maxValue = newMax;
        }
    }

    public void ExpandRange(float expandFactor)
    {
        if (expandFactor <= 0 || expandFactor >= 1)
        {
            throw new ArgumentException("Expand factor must be between 0 and 1.");
        }
        float newMin = _minValue - (_maxValue - _minValue) * (1 + expandFactor);
        float newMax = _maxValue + (_maxValue - _minValue) * expandFactor;
        if (newMin < newMax)
        {
            _minValue = newMin;
            _maxValue = newMax;
        }
    }
}
