        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }

    memset(bundle, 0, sizeof(ResourceBundle));

    // Read item data from file
    while (bundle->count < MAX_ITEMS && fread(&bundle->items[bundle->count], sizeof(Item), 1, file)) {
        bundle->count++;
    }

    if (ferror(file)) {
        perror("Error reading resource bundle file");
        free(bundle);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return bundle;
}

