#include <string.h>

#define MAX_LINE_LENGTH 1024

void process_line(char *line) {
    int num_fields = 0;
    double sum = 0;
    char *token = strtok(line, " ");

    while (token != NULL && num_fields < 5) {
        char *end;
        long value = strtol(token, &end, 10);

        if (*end == '\0') {
            sum += value;
            num_fields++;
        } else {
            fprintf(stderr, "Error: Invalid numeric conversion at line.\n");
            return;
        }

        token = strtok(NULL, " ");
    }

    if (num_fields != 5) {
        fprintf(stderr, "Error: Invalid number of fields in line.\n");
        return;
    }

    double average = sum / 3.0;

    char *new_line = realloc(line, strlen(line) + 20); // Adjust size as needed
    if (new_line == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    strcat(new_line, ",");
    char buffer[20];
    sprintf(buffer, "%.2f", average);
    strcat(new_line, buffer);

    printf("%s\n", new_line);
    free(line); // Free the original line if it was dynamically allocated
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    char buffer[MAX_LINE_LENGTH];

    while (fgets(buffer, sizeof(buffer), file)) {
        process_line(strdup(buffer)); // Duplicate the line to avoid modifying original input
    }

    fclose(file);
    return 0;
}
