#include <string.h>

#define MAX_FILENAME_LENGTH 256

char* generate_new_filename(const char* original, int digits, const char* new_extension) {
    if (original == NULL || new_extension == NULL || digits <= 0) {
        return NULL;
    }

    size_t len = strlen(original);
    char* dot_pos = strrchr(original, '.');

    char* new_name = (char*)malloc(MAX_FILENAME_LENGTH * sizeof(char));
    if (new_name == NULL) {
        return NULL;
    }

    if (dot_pos != NULL && dot_pos > original) {
        size_t prefix_len = dot_pos - original;
        snprintf(new_name, MAX_FILENAME_LENGTH, "%.*s", (int)prefix_len, original);
        strncat(new_name, new_extension, MAX_FILENAME_LENGTH - prefix_len - 1);
    } else {
        strncpy(new_name, original, MAX_FILENAME_LENGTH - 1);
        strncat(new_name, ".", MAX_FILENAME_LENGTH - strlen(new_name) - 1);
        strncat(new_name, new_extension, MAX_FILENAME_LENGTH - strlen(new_name) - 1);
    }

    size_t ext_len = strlen(new_name) - strlen(dot_pos);
    if (ext_len > digits) {
        free(new_name);
        return NULL;
    }

    char* number_part = malloc(MAX_FILENAME_LENGTH * sizeof(char));
    if (number_part == NULL) {
        free(new_name);
        return NULL;
    }

    snprintf(number_part, MAX_FILENAME_LENGTH, "%0*d", digits, 1);

    size_t new_len = strlen(new_name) + strlen(number_part) - ext_len;
    char* result = realloc(new_name, (new_len + 1) * sizeof(char));
    if (result == NULL) {
        free(new_name);
        free(number_part);
        return NULL;
    }

    strcpy(result, new_name);
    strncat(result, number_part, MAX_FILENAME_LENGTH - strlen(result) - 1);

    free(number_part);
    return result;
}

int main() {
    char* new_filename = generate_new_filename("example.txt", 3, "bak");
    if (new_filename != NULL) {
        printf("New filename: %s\n", new_filename);
        free(new_filename);
    } else {
        printf("Failed to generate new filename.\n");
    }
    return 0;
}
