#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>

#define AES_BLOCK_SIZE 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[AES_BLOCK_SIZE];
} AES_Cipher;

int init_cipher(AES_Cipher *cipher, const char *password, int password_len) {
    EVP_PKEY_CTX *kctx = EVP_PKEY_CTX_new_id(EVP_PKEY_EC, NULL);
    if (!kctx) return 1;

    unsigned char derived_key[32];
    if (EVP_PKEY_derive_init(kctx) <= 0 ||
        EVP_PKEY_CTX_set_password(pass, password_len, kctx) <= 0 ||
        EVP_PKEY_derive(kctx, derived_key, &password_len) <= 0 ||
        EVP_PKEY_CTX_free(kctx) <= 0) {
        return 1;
    }

    memcpy(cipher->key, derived_key, sizeof(derived_key));
    memset(derived_key, 0, sizeof(derived_key));

    if (RAND_bytes(cipher->iv, AES_BLOCK_SIZE) != 1) return 1;

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) return 1;

    return 0;
}

int encrypt(AES_Cipher *cipher, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv) <= 0 ||
        EVP_EncryptUpdate(cipher->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len) <= 0 ||
        EVP_EncryptFinal_ex(cipher->ctx, ciphertext + ciphertext_len, &ciphertext_len) <= 0) {
        return 1;
    }
    return 0;
}

int decrypt(AES_Cipher *cipher, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (EVP_DecryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv) <= 0 ||
        EVP_DecryptUpdate(cipher->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len) <= 0 ||
        EVP_DecryptFinal_ex(cipher->ctx, plaintext + plaintext_len, &plaintext_len) <= 0) {
        return 1;
    }
    return 0;
}

void cleanup_cipher(AES_Cipher *cipher) {
    if (cipher->ctx) EVP_CIPHER_CTX_free(cipher->ctx);
    memset(cipher, 0, sizeof(AES_Cipher));
}
