using System;
using Microsoft.Web.Administration;

public class IISManager
{
    public void AddNewSite(string siteName, string physicalPath)
    {
        using (ServerManager serverManager = new ServerManager())
        {
            if (!serverManager.Sites.Contains(siteName))
            {
                try
                {
                    // Validate directory path and check for web.config file
                    if (!System.IO.Directory.Exists(physicalPath) || !System.IO.File.Exists(Path.Combine(physicalPath, "web.config")))
                    {
                        GenerateBasicWebConfig(physicalPath);
                    }

                    // Create the new site in IIS
                    Site newSite = serverManager.Sites.Add(siteName, physicalPath, "/", "*:80");
                    newSite.Bindings.Clear();
                    newSite.Bindings.Add("*:80:" + siteName);

                    // Apply default settings and start the site
                    newSite.ServerAutoStart = true;
                    newSite.Start();

                    Console.WriteLine($"Site '{siteName}' created and started successfully.");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Failed to create or start site '{siteName}': {ex.Message}");
                }
            }
            else
            {
                Console.WriteLine($"Site '{siteName}' already exists.");
            }
        }
    }

    private void GenerateBasicWebConfig(string physicalPath)
    {
        // Basic template for web.config
        string webConfigContent = @"
<configuration>
  <system.webServer>
    <defaultDocument>
      <files>
        <add value='index.html' />
      </files>
    </defaultDocument>
  </system.webServer>
</configuration>";

        // Write the basic configuration to the physical path
        System.IO.File.WriteAllText(Path.Combine(physicalPath, "web.config"), webConfigContent);
    }
}
