import java.io.*;
import java.util.concurrent.*;

public class CommandExecutor {
    private static final int TIMEOUT = 60; // Timeout in seconds
    private static final int RESOURCE_LIMIT = 100 * 1024 * 1024; // Resource limit in bytes

    public void deleteFileIfExists(String filePath) {
        File file = new File(filePath);
        if (file.exists()) {
            if (!file.delete()) {
                log("Failed to delete file: " + filePath, LogLevel.ERROR);
            } else {
                log("File deleted successfully: " + filePath, LogLevel.INFO);
            }
        } else {
            log("File does not exist: " + filePath, LogLevel.DEBUG);
        }
    }

    public void executeCommandWithStreams(String command, String[] args) {
        Process process = null;
        try {
            process = Runtime.getRuntime().exec(command.split("\\s+"), args);

            ExecutorService executor = Executors.newFixedThreadPool(3);

            Future<String> outputFuture = executor.submit(() -> readStream(process.getInputStream(), "OUTPUT"));
            Future<String> errorFuture = executor.submit(() -> readStream(process.getErrorStream(), "ERROR"));

            int exitCode = process.waitFor();
            String output = outputFuture.get();
            String error = errorFuture.get();

            log("Command executed with exit code: " + exitCode, LogLevel.INFO);
            if (!output.isEmpty()) {
                log(output, LogLevel.DEBUG);
            }
            if (!error.isEmpty()) {
                log(error, LogLevel.ERROR);
            }

        } catch (IOException | InterruptedException e) {
            log("Exception occurred while executing command: " + e.getMessage(), LogLevel.ERROR);
        } finally {
            if (process != null) {
                process.destroy();
            }
        }
    }

    private String readStream(InputStream inputStream, String streamType) {
        StringBuilder output = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
        } catch (IOException e) {
            log("Error reading " + streamType + " stream: " + e.getMessage(), LogLevel.ERROR);
        }
        return output.toString();
    }

    private void log(String message, LogLevel level) {
        // Implement logging to external service or file
        System.out.println(level + ": " + message);
    }

    public static void main(String[] args) {
        CommandExecutor executor = new CommandExecutor();
        executor.deleteFileIfExists("path/to/file.txt");
        executor.executeCommandWithStreams("command", new String[]{"arg1", "arg2"});
    }
}

enum LogLevel {
    INFO, DEBUG, ERROR
}
