typedef struct {
    bool is_valid;
    char *error_message;
} TokenValidationResult;

TokenValidationResult validate_token(const char *token_json) {
    TokenValidationResult result = {false, NULL};
    json_object *parsed_json = json_tokener_parse(token_json);

    if (!parsed_json) {
        result.error_message = "Failed to parse JSON";
        return result;
    }

    json_object *access_token, *expires_in, *token_type, *refresh_token;

    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) &&
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) &&
        json_object_object_get_ex(parsed_json, "token_type", &token_type)) {

        const char *type_str;
        int expires_val;

        if (json_object_is_type(access_token, json_type_string) &&
            json_object_is_type(expires_in, json_type_int) &&
            json_object_is_type(token_type, json_type_string)) {

            type_str = json_object_get_string(token_type);
            expires_val = json_object_get_int(expires_in);

            if (strcmp(type_str, "Bearer") == 0 && expires_val > 0 && expires_val <= 3600) {
                json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

                if (!refresh_token || (json_object_is_type(refresh_token, json_type_string) &&
                                       strlen(json_object_get_string(refresh_token)) <= 1024)) {

                    // Additional claims validation here
                    result.is_valid = true;
                    return result;
                } else if (refresh_token) {
                    result.error_message = "Invalid refresh token";
                } else {
                    result.error_message = "Refresh token missing";
                }
            } else {
                result.error_message = "Invalid token type or expires_in value";
            }
        } else {
            result.error_message = "Invalid data types for access_token, expires_in, or token_type";
        }
    } else {
        result.error_message = "Missing required fields in the JSON object";
    }

    json_object_put(parsed_json);
    return result;
}

int main() {
    const char *token_json = "{\"access_token\":\"example_access_token\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    TokenValidationResult result = validate_token(token_json);

    if (result.is_valid) {
        printf("Token is valid.\n");
    } else {
        printf("Token validation failed: %s\n", result.error_message);
    }

    free(result.error_message);
    return 0;
}
