public class CSVProcessor
{
    public static string ProcessCSV(Stream fileStream)
    {
        List<Record> records = new List<Record>();
        using (StreamReader reader = new StreamReader(fileStream))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                string[] values = line.Split(',');
                if (values.Length == 2)
                {
                    records.Add(new Record
                    {
                        ID = int.Parse(values[0]),
                        Name = values[1],
                        IsValid = true
                    });
                }
                else
                {
                    records.Add(new Record
                    {
                        ID = -1,
                        Name = "Invalid",
                        IsValid = false,
                        ErrorMessage = "Incorrect number of fields"
                    });
                }
            }
        }

        List<Record> insertRecords = new List<Record>();
        foreach (var record in records)
        {
            if (record.IsValid)
            {
                try
                {
                    // Assuming a method InsertRecord exists to handle database insertion
                    InsertRecord(record);
                    insertRecords.Add(new Record
                    {
                        ID = record.ID,
                        Name = record.Name,
                        IsValid = true,
                        Status = "Inserted"
                    });
                }
                catch (Exception ex)
                {
                    insertRecords.Add(new Record
                    {
                        ID = record.ID,
                        Name = record.Name,
                        IsValid = false,
                        ErrorMessage = ex.Message,
                        Status = "Failed"
                    });
                }
            }
        }

        return JsonConvert.SerializeObject(insertRecords);
    }

    private static void InsertRecord(Record record)
    {
        // Implementation of database insertion logic
        using (SqlConnection connection = new SqlConnection("YourConnectionString"))
        {
            connection.Open();
            string query = "INSERT INTO YourTable (ID, Name) VALUES (@ID, @Name)";
            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@ID", record.ID);
                command.Parameters.AddWithValue("@Name", record.Name);
                command.ExecuteNonQuery();
            }
        }
    }

    public class Record
    {
        public int ID { get; set; }
        public string Name { get; set; }
        public bool IsValid { get; set; }
        public string ErrorMessage { get; set; }
        public string Status { get; set; }
    }
}
