public class Crypto
{
    public static string Decrypt(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider desCryptoProvider = new TripleDESCryptoServiceProvider())
        {
            desCryptoProvider.Key = key;
            desCryptoProvider.IV = iv;
            desCryptoProvider.Mode = CipherMode.CBC;
            desCryptoProvider.Padding = PaddingMode.PKCS7;

            byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
            ICryptoTransform decryptor = desCryptoProvider.CreateDecryptor();
            byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return System.Text.Encoding.UTF8.GetString(decryptedBytes);
        }
    }
}

public class Pokemon
{
    public string Name { get; set; }
    public string Type { get; set; }
