        switch (pokemon.getType()) {
            case "Fire":
                return getWeakness(pokemon, "Water", "Ground", "Rock");
            case "Water":
                return getWeakness(pokemon, "Electric", "Grass");
            case "Grass":
                return getWeakness(pokemon, "Fire", "Ice", "Poison", "Flying");
            default:
                return "Unknown type";
        }
    }

    private static String getWeakness(Pokemon pokemon, String... types) {
        StringBuilder weaknesses = new StringBuilder();
        for (String type : types) {
            weaknesses.append(type).append(", ");
        }
        return weaknesses.substring(0, weaknesses.length() - 2);
    }
