using System;
using System.IO;
using System.Security.Cryptography;

public class MD5Hasher
{
    public static string GetMD5Hash(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            return null; // or return an empty string, depending on your design
        }

        using (var md5 = MD5.Create())
        {
            byte[] inputBytes = System.Text.Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public static void LogWithMD5(string input, ILogger logger)
    {
        string hash = GetMD5Hash(input);
        if (hash != null)
        {
            logger.Log($"Input: {input}, MD5 Hash: {hash}");
        }
        else
        {
            logger.Log("Input is null or empty.");
        }
    }

    // Example usage:
    public static void Main()
    {
        ILogger logger = new ConsoleLogger(); // Assuming a simple console logger for demonstration
        string input = "Sample data to hash";
        LogWithMD5(input, logger);
    }
}

public interface ILogger
{
    void Log(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}
