const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');
const path = require('path');

async function validateFile(url, allowedTypes, maxSize) {
  const response = await axios.head(url);
  const contentType = response.headers['content-type'];
  const contentLength = parseInt(response.headers['content-length'], 10);

  if (!allowedTypes.includes(contentType)) {
    throw new Error(`Invalid file type: ${contentType}`);
  }
  if (contentLength > maxSize) {
    throw new Error(`File size exceeds limit: ${contentLength} bytes`);
  }

  return { contentType, contentLength };
}

async function uploadFile(url, allowedTypes = ['image/jpeg', 'image/png'], maxSize = 5 * 1024 * 1024) {
  const start = Date.now();
  try {
    const validation = await validateFile(url, allowedTypes, maxSize);
    const form = new FormData();
    const response = await axios.post('https://your-upload-endpoint.com/upload', form, {
      headers: { ...form.getHeaders(), 'Content-Type': 'multipart/form-data' },
    });
    return { url, uploadTime: Date.now() - start };
  } catch (error) {
    console.error(`Failed to upload ${url}:`, error.message);
    throw error;
  }
}

async function manageUploads(urls, concurrentLimit = 5) {
  const results = [];
  const queue = urls.map(url => ({ url, promise: uploadFile(url) }));

  while (queue.length > 0) {
    const batch = queue.splice(0, concurrentLimit);
    const promises = batch.map(item => item.promise);

    try {
      await Promise.all(promises);
      results.push(...batch.map(item => item.url));
    } catch (error) {
      console.error(`Batch upload failed:`, error.message);
    }
  }

  return results;
}

// Example usage
const urls = [
  'https://example.com/image1.jpg',
  'https://example.com/file2.pdf', // This should fail validation
  'https://example.com/image3.png',
];

manageUploads(urls, 2)
  .then(uploadedUrls => {
    console.log('Successfully uploaded URLs:', uploadedUrls);
  })
  .catch(error => {
    console.error('Error during upload management:', error.message);
  });
```

