using System;
using System.Diagnostics;

public class ShellCommandExecutor
{
    private int _minValue;
    private int _maxValue;

    public ShellCommandExecutor(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(maxValue), "Max value must be greater than min value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomFloat()
    {
        return new Random().NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomIntegerDivisibleByFive()
    {
        int randomInt = _minValue + (new Random().Next((_maxValue - _minValue) / 5)) * 5;
        return Math.Max(randomInt, _minValue);
    }

    public string ExecuteShellCommand(string command)
    {
        Process process = new Process();
        process.StartInfo.FileName = "cmd.exe";
        process.StartInfo.Arguments = $"/c {command}";
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.CreateNoWindow = true;

        process.Start();
        string output = process.StandardOutput.ReadToEnd();
        process.WaitForExit();

        return output;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(int newMax)
    {
        if (newMax < _minValue) newMax = _minValue;
        _maxValue = newMax;
    }

    public void ExpandRange(int newMin, int newMax)
    {
        if (newMin > _maxValue) newMin = _maxValue;
        if (newMax < _minValue) newMax = _minValue;
        _minValue = newMin;
        _maxValue = newMax;
    }
}
