    const numEdges = randomInt(numVertices * 2);

    let graph = {
        vertices: [],
        edges: []
    };

    for (let i = 0; i < numVertices; i++) {
        let vertex = {
            id: `v${i}`,
            property1: Math.random().toString(36).substr(2, 5),
            property2: Math.random().toString(36).substr(2, 5)
        };
        graph.vertices.push(vertex);
    }

    for (let i = 0; i < numEdges; i++) {
        let fromVertex = randomInt(numVertices);
        let toVertex = randomInt(numVertices);
        if (fromVertex !== toVertex) {
            let edge = {
                id: `e${i}`,
                from: graph.vertices[fromVertex].id,
                to: graph.vertices[toVertex].id,
                property1: Math.random().toString(36).substr(2, 5),
                property2: Math.random().toString(36).substr(2, 5)
            };
            graph.edges.push(edge);
        }
