use std::env;
use std::fs::{create_dir_all, metadata};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Duration;

fn create_directory_with_env_var(
    dir_name: &str,
    parent_dir: Option<&str>,
    env_var_name: &str,
) -> Result<PathBuf, String> {
    let mut retry_count = 0;
    const MAX_RETRIES: u32 = 3;

    loop {
        if retry_count >= MAX_RETRIES {
            return Err("Failed to create directory after multiple retries".to_string());
        }

        let full_path = match parent_dir {
            Some(parent) => PathBuf::from(parent).join(dir_name),
            None => PathBuf::from(dir_name),
        };

        if env_var_exists(env_var_name) {
            return Ok(get_env_var_path(env_var_name));
        } else {
            if create_directory(&full_path) {
                set_env_var(env_var_name, &full_path);
                return Ok(full_path);
            }
        }

        retry_count += 1;
        std::thread::sleep(Duration::from_secs(1)); // Wait before retrying
    }
}

fn env_var_exists(name: &str) -> bool {
    env::var(name).is_ok()
}

fn get_env_var_path(name: &str) -> PathBuf {
    PathBuf::from(env::var(name).unwrap())
}

fn create_directory(path: &PathBuf) -> bool {
    if path.exists() {
        return true;
    }

    match create_dir_all(path) {
        Ok(_) => true,
        Err(_) => false, // Retry on failure
    }
}

fn set_env_var(name: &str, value: &PathBuf) {
    env::set_var(name, value.to_str().unwrap());
}
```

