import json
from abc import ABC, abstractmethod

class ConfigType(ABC):
    @abstractmethod
    def load(self, config_data):
        pass

    @abstractmethod
    def save(self):
        pass

class JsonConfigType(ConfigType):
    def __init__(self, data=None):
        self.data = data if data else {}

    def load(self, config_data):
        self.data = json.loads(config_data)

    def save(self):
        return json.dumps(self.data)

class ConfigLoader:
    _plugins = {}

    @staticmethod
    def register_plugin(identifier, plugin_class):
        if identifier in ConfigLoader._plugins:
            raise ValueError(f"Plugin '{identifier}' already registered.")
        ConfigLoader._plugins[identifier] = plugin_class

    @staticmethod
    def get_config_instance(config_type_identifier):
        if config_type_identifier not in ConfigLoader._plugins:
            raise KeyError(f"No plugin registered for type identifier: {config_type_identifier}")
        return ConfigLoader._plugins[config_type_identifier]()

    def load_config(self, environment):
        # Logic to determine which configuration file to load based on the environment
        with open(f"{environment}_config.json", "r") as config_file:
            config_data = config_file.read()
        config_instance = self.get_config_instance("json")
        config_instance.load(config_data)
        return config_instance

    def save_config(self, config_instance, environment):
        # Logic to determine which configuration file to save based on the environment
        with open(f"{environment}_config.json", "w") as config_file:
            config_data = config_instance.save()
            config_file.write(config_data)

# Example usage
ConfigLoader.register_plugin("json", JsonConfigType)
config_loader = ConfigLoader()
dev_config = config_loader.load_config("development")
prod_config = config_loader.load_config("production")

dev_config.data["feature_flag"] = True
config_loader.save_config(dev_config, "development")
