// AES encryption function
void aes_encrypt(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        handleErrors();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        handleErrors();

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        handleErrors();
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    printf("Ciphertext is:\n");
    BIO_dump_fp(stdout, (const char *)ciphertext, ciphertext_len);
}

// Camellia encryption function
void camellia_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        handleErrors();

    if (1 != EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv))
        handleErrors();

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        handleErrors();
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    printf("Ciphertext is:\n");
    BIO_dump_fp(stdout, (const char *)ciphertext, ciphertext_len);
}

// MD5 hash function
void md5_hash(const unsigned char *data, size_t length, unsigned char *output) {
    EVP_MD_CTX *ctx;
    int len;

    if (!(ctx = EVP_MD_CTX_new()))
        handleErrors();

    if (1 != EVP_DigestInit_ex(ctx, EVP_md5(), NULL))
        handleErrors();

    if (1 != EVP_DigestUpdate(ctx, data, length))
        handleErrors();

    if (1 != EVP_DigestFinal_ex(ctx, output, &len))
        handleErrors();

    EVP_MD_CTX_free(ctx);

    printf("MD5 hash is:\n");
    BIO_dump_fp(stdout, (const char *)output, len);
}

// SHA hash function
void sha_hash(const unsigned char *data, size_t length, unsigned char *output) {
    EVP_MD_CTX *ctx;
    int len;

    if (!(ctx = EVP_MD_CTX_new()))
        handleErrors();

    if (1 != EVP_DigestInit_ex(ctx, EVP_sha256(), NULL))
        handleErrors();

    if (1 != EVP_DigestUpdate(ctx, data, length))
        handleErrors();

    if (1 != EVP_DigestFinal_ex(ctx, output, &len))
        handleErrors();

    EVP_MD_CTX_free(ctx);

    printf("SHA hash is:\n");
    BIO_dump_fp(stdout, (const char *)output, len);
}

// RSA encryption function
void rsa_encrypt(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *public_key, unsigned char *ciphertext) {
    RSA *rsa;
    BIGNUM *bn = BN_new();
    if (!(rsa = d2i_RSAPublicKey(NULL, &public_key, -1)))
        handleErrors();

    if (RSA_size(rsa) < plaintext_len + 11)
        handleErrors();

    if (!RSA_public_encrypt(plaintext_len, plaintext, ciphertext, rsa, RSA_PKCS1_PADDING))
        handleErrors();

    RSA_free(rsa);
    BN_free(bn);

    printf("Ciphertext is:\n");
    BIO_dump_fp(stdout, (const char *)ciphertext, RSA_size(rsa));
}

// SHA-1 hash function
void sha1_hash(const unsigned char *data, size_t length, unsigned char *output) {
    EVP_MD_CTX *ctx;
    int len;

    if (!(ctx = EVP_MD_CTX_new()))
        handleErrors();

    if (1 != EVP_DigestInit_ex(ctx, EVP_sha1(), NULL))
        handleErrors();

    if (1 != EVP_DigestUpdate(ctx, data, length))
        handleErrors();

    if (1 != EVP_DigestFinal_ex(ctx, output, &len))
        handleErrors();

    EVP_MD_CTX_free(ctx);

    printf("SHA-1 hash is:\n");
    BIO_dump_fp(stdout, (const char *)output, len);
}

// Error handling function
void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

int main() {
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[1024];

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)))
        handleErrors();
    if (!RAND_bytes(iv, sizeof(iv)))
