#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define TIFF_HEADER_SIZE 8

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint32_t extra_samples_count;
    uint16_t *extra_samples;
} TiffMetadata;

TiffMetadata* parse_tiff(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    TiffMetadata *metadata = (TiffMetadata *)malloc(sizeof(TiffMetadata));
    if (!metadata) {
        fclose(file);
        return NULL;
    }

    uint8_t header[TIFF_HEADER_SIZE];
    if (fread(header, 1, TIFF_HEADER_SIZE, file) != TIFF_HEADER_SIZE) {
        free(metadata);
        fclose(file);
        return NULL;
    }

    // Check for Byte Order marker
    uint16_t byte_order = (header[0] << 8) | header[1];
    if ((byte_order != 0x4D4D && byte_order != 0x4949)) {
        free(metadata);
        fclose(file);
        return NULL;
    }

    // Assuming little-endian for simplicity
    uint16_t magic_number = (header[2] << 8) | header[3];
    if (magic_number != 0x002A) {
        free(metadata);
        fclose(file);
        return NULL;
    }

    // Read the number of IFDs
    fseek(file, 4, SEEK_CUR); // Skip to the offset of the first IFD
    uint32_t ifd_offset = (header[6] << 24) | (header[7] << 16) | (header[8] << 8) | header[9];
    fseek(file, ifd_offset, SEEK_SET);

    // Read each IFD entry
    while (1) {
        uint16_t tag = fgetc(file);
        uint16_t type = fgetc(file);
        uint32_t count = (fgetc(file) << 24) | (fgetc(file) << 16) | (fgetc(file) << 8) | fgetc(file);
        uint32_t value_offset = (fgetc(file) << 24) | (fgetc(file) << 16) | (fgetc(file) << 8) | fgetc(file);

        if (tag == 0 && type == 0 && count == 0 && value_offset == 0) break; // End of IFD

        // Process each tag as needed
        switch (tag) {
            case 256: // Bits Per Sample
                metadata->bits_per_sample = value_offset;
                if (!(metadata->bits_per_sample == 1 || metadata->bits_per_sample == 2 ||
                      metadata->bits_per_sample == 4 || metadata->bits_per_sample == 8 ||
                      metadata->bits_per_sample == 16)) {
                    free(metadata);
                    fclose(file);
                    return NULL;
                }
                break;
            case 257: // Samples Per Pixel
                metadata->samples_per_pixel = value_offset;
                break;
            case 338: // Extra Samples
                metadata->extra_samples_count = count;
                if (metadata->extra_samples_count == 0) {
                    free(metadata);
                    fclose(file);
                    return NULL;
                }
                metadata->extra_samples = (uint16_t *)malloc(metadata->extra_samples_count * sizeof(uint16_t));
                if (!metadata->extra_samples) {
                    free(metadata);
                    fclose(file);
                    return NULL;
                }
                fseek(file, value_offset, SEEK_SET);
                for (uint32_t i = 0; i < metadata->extra_samples_count; i++) {
                    metadata->extra_samples[i] = fgetc(file);
                }
                break;
            case 339: // Compression
                uint16_t compression_type = value_offset;
                if (compression_type != 1) { // Only uncompressed is supported for simplicity
                    free(metadata);
                    fclose(file);
                    return NULL;
                }
                break;
        }
    }

    fclose(file);
    return metadata;
}
