#include <stdio.h>
#include <string.h>

void modifyFilename(const char* filename, char* newFilename) {
    int length = strlen(filename);
    int digits = 1;
    while (length > 0 && filename[length - 1] != '.') {
        if (filename[length - 1] >= '0' && filename[length - 1] <= '9') {
            digits++;
        }
        length--;
    }

    snprintf(newFilename, strlen(filename) + 5, "%.*s.%d", length, filename, digits);
}

int main() {
    char newFilename[256];
    modifyFilename("example.txt", newFilename);
    printf("New Filename: %s\n", newFilename);
    return 0;
}
