#define MAX_PDCCH_CANDIDATES 1024

typedef struct {
    int format;
    // Other PDCCH format-specific information
} PDCCHCandidate;

typedef struct {
    MACControlElement *mac_ce;
    PDCCHCandidate *pdcch_candidates;
    int num_pdcch_candidates;
} LTEUEContext;

LTEUEContext** init_lte_ue_context_list(int initial_size) {
    LTEUEContext **context_list = (LTEUEContext**)malloc(initial_size * sizeof(LTEUEContext*));
    if (!context_list) return NULL;

    for (int i = 0; i < initial_size; i++) {
        context_list[i] = (LTEUEContext*)malloc(sizeof(LTEUEContext));
        if (!context_list[i]) {
            // Rollback changes
            for (int j = 0; j < i; j++) free(context_list[j]);
            free(context_list);
            return NULL;
        }

        context_list[i]->mac_ce = (MACControlElement*)malloc(sizeof(MACControlElement));
        if (!context_list[i]->mac_ce) {
            // Rollback changes
            for (int j = 0; j <= i; j++) {
                free(context_list[j]->pdcch_candidates);
                free(context_list[j]->mac_ce);
                free(context_list[j]);
            }
            free(context_list);
            return NULL;
        }

        context_list[i]->pdcch_candidates = (PDCCHCandidate*)malloc(MAX_PDCCH_CANDIDATES * sizeof(PDCCHCandidate));
        if (!context_list[i]->pdcch_candidates) {
            // Rollback changes
            for (int j = 0; j <= i; j++) {
                free(context_list[j]->pdcch_candidates);
                free(context_list[j]->mac_ce);
                free(context_list[j]);
            }
            free(context_list);
            return NULL;
        }

        context_list[i]->num_pdcch_candidates = 0;
    }

    return context_list;
}

void free_lte_ue_context_list(LTEUEContext **context_list, int size) {
    for (int i = 0; i < size; i++) {
        free(context_list[i]->pdcch_candidates);
        free(context_list[i]->mac_ce);
        free(context_list[i]);
    }
    free(context_list);
}
