#define MAX_ARRAY_SIZE 10000
#define MIN_RECORD_VALUE 0
#define MAX_RECORD_VALUE 100

typedef struct {
    int value;
} Record;

Record* allocate_records(int array_size) {
    if (array_size > MAX_ARRAY_SIZE) {
        // Use memory-efficient alternative for large sizes
        return (Record*)calloc(array_size, sizeof(Record));
    } else {
        // Allocate normally
        return (Record*)malloc(array_size * sizeof(Record));
    }
}

int* allocate_ints(int array_size) {
    return (int*)calloc(array_size, sizeof(int));
}

long* allocate_offsets(int array_size) {
    return (long*)calloc(array_size, sizeof(long));
}

char* process_string(const char* input, size_t buffer_size, char* output_buffer) {
    if (strlen(input) >= buffer_size - 1) {
        // String too large
        return NULL;
    }
    strcpy(output_buffer, input);
    strcat(output_buffer, "/");
    return output_buffer;
}

void free_memory(Record** records, int* ints, long* offsets, char* buffer) {
    if (records != NULL) free(*records);
    if (ints != NULL) free(ints);
    if (offsets != NULL) free(offsets);
    if (buffer != NULL) free(buffer);
}

void initialize_records(Record* records, int array_size, int min_value, int max_value) {
    for (int i = 0; i < array_size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

