    if (output_buffer == NULL) {
        printf("Memory allocation failed\n");
        free_memory(&records, &ints, &offsets, NULL);
        return 1;
    }

    char* result = process_string(input, buffer_size, output_buffer);
    if (result != NULL) {
        printf("Processed string: %s\n", result);
    } else {
        printf("String processing failed\n");
    }

    free_memory(&records, &ints, &offsets, output_buffer);

    return 0;
}
