import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class FileProcessor {

    private static final long TIMEOUT = 10L; // Timeout in milliseconds
    private static final int DEFAULT_SEQUENCE_NUMBER = -1;
    private ExecutorService executorService = Executors.newFixedThreadPool(1);

    public Result processFile(File file) {
        Callable<Result> task = () -> {
            List<String> lines = new ArrayList<>();
            try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    lines.add(line);
                }
            } catch (IOException e) {
                logWarning("Error reading file: " + e.getMessage());
                return new Result(DEFAULT_SEQUENCE_NUMBER, null);
            }

            Collections.sort(lines);

            int sequenceNumber = DEFAULT_SEQUENCE_NUMBER;
            if (!lines.isEmpty()) {
                try {
                    String[] parts = lines.get(lines.size() - 1).split("\\s+");
                    sequenceNumber = Integer.parseInt(parts[parts.length - 1]);
                } catch (NumberFormatException e) {
                    logWarning("Invalid sequence number in file: " + e.getMessage());
                }
            }

            try {
                return new Result(sequenceNumber, calculateMd5(lines));
            } catch (NoSuchAlgorithmException e) {
                logWarning("Error calculating MD5 hash: " + e.getMessage());
                return new Result(sequenceNumber, null);
            }
        };

        Future<Result> future = executorService.submit(task);

        try {
            return future.get(TIMEOUT, TimeUnit.MILLISECONDS);
        } catch (Exception e) {
            if (e.getCause() instanceof InterruptedException || e.getCause() instanceof java.util.concurrent.TimeoutException) {
                logWarning("File processing timed out after " + TIMEOUT + " milliseconds.");
                // Return the last computed sequence number and hash up to that point
                return new Result(DEFAULT_SEQUENCE_NUMBER, null);
            }
            logWarning("Error processing file: " + e.getMessage());
            return new Result(DEFAULT_SEQUENCE_NUMBER, null);
        } finally {
            future.cancel(true); // Cancel the task if it's still running
        }
    }

    private String calculateMd5(List<String> lines) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        for (String line : lines) {
            digest.update(line.getBytes());
        }
        byte[] hashBytes = digest.digest();
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void logWarning(String message) {
        System.err.println("WARNING: " + message);
    }

    static class Result {
        int sequenceNumber;
        String md5Hash;

        Result(int sequenceNumber, String md5Hash) {
            this.sequenceNumber = sequenceNumber;
            this.md5Hash = md5Hash;
        }
    }
}
