        System.out.println("MD5 Hash: " + bytesToHex(fileHash));
    }

    public Octree(int featureSize, int numLeafNodes, int dataCapacity) {
        this.featureSize = featureSize;
        this.numLeafNodes = numLeafNodes;
        this.data = new Object[dataCapacity];
    }

    private void initialize() {
        root = new Node(featureSize);
        // Initialize the octree structure here
    }

    public byte[] calculateFileHash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        FileInputStream fis = null;

        try {
            fis = new FileInputStream(filePath);
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        } finally {
            if (fis != null) {
                fis.close();
            }
        }

        return md.digest();
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

