    Task* new_task_list = NULL;
    Task** new_tail_ptr = &new_task_list;

    for (int i = 0; i < task_count; i++) {
        // Check if the task can transition to the next priority
        if (can_transition(current_tasks[i], scheduler_config, next_priority)) {
            // Create a new task and add it to the new list
            Task* new_task = create_task(current_tasks[i].id, current_tasks[i].priority);
            *new_tail_ptr = new_task;
            new_tail_ptr = &(*new_tail_ptr)->next;
        }
    }

    if (new_task_list != NULL) {
        // Ensure the last task in the initial list points to the new task list
        Task* last_task = current_tasks + task_count - 1;
        while (last_task->next != NULL) {
            last_task = last_task->next;
        }
        last_task->next = new_task_list;
