#include <string.h>
#include "zip.h"

int compress_files(const char *source_path, const char *target_path, int compression_level, size_t max_file_size) {
    zipFile zip = zipOpen(target_path, ZIP_CREATE);
    if (zip == NULL) {
        fprintf(stderr, "Failed to create ZIP archive\n");
        return -1;
    }

    DIR *dir = opendir(source_path);
    if (dir == NULL) {
        fprintf(stderr, "Failed to open source directory: %s\n", strerror(errno));
        zipClose(zip, NULL);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        const char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", source_path, filename);

        FILE *file = fopen(file_path, "rb");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_END);
        size_t file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (max_file_size > 0 && file_size > max_file_size) {
            fprintf(stderr, "File exceeds maximum allowed size: %s\n", filename);
            fclose(file);
            continue;
        }

        zip_source_t *source = zip_source_file(zip, file_path, 0, file_size);
        if (source == NULL) {
            fprintf(stderr, "Failed to create source for file: %s\n", filename);
            fclose(file);
            continue;
        }

        int err = zipFileAdd(zip, filename, source, ZIP_FL_ENC_GUESS | compression_level);
        if (err != 0) {
            fprintf(stderr, "Failed to add file to archive: %s\n", zipGetErrorString(err));
            zip_source_free(source);
            fclose(file);
            continue;
        }

        fclose(file);
    }

    closedir(dir);
    zipClose(zip, NULL);
    return 0;
}
