using System;
using System.Collections.Generic;

public class DynamicValueManager
{
    private float _minValue;
    private float _maxValue;
    private Dictionary<int, double> _customWeights = new Dictionary<int, double>();

    public DynamicValueManager(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)(new Random().NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public int GenerateRandomInt()
    {
        return (int)(_minValue + Math.Floor((new Random().NextDouble() * (_maxValue - _minValue + 1)) / 5)) * 5;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(float reductionFactor)
    {
        if (reductionFactor <= 0 || reductionFactor >= 1)
            throw new ArgumentException("Reduction factor must be between 0 and 1.");

        _minValue += (_maxValue - _minValue) * reductionFactor;
        _maxValue -= (_maxValue - _minValue) * reductionFactor;
    }

    public void ExpandRange(float expansionFactor)
    {
        if (expansionFactor <= 0 || expansionFactor >= 1)
            throw new ArgumentException("Expansion factor must be between 0 and 1.");

        float range = _maxValue - _minValue;
        _minValue -= range * expansionFactor;
        _maxValue += range * expansionFactor;
    }

    public int GenerateRandomWeightedInt(double[] weights)
    {
        double totalWeight = 0;
        foreach (var weight in weights)
            totalWeight += weight;

        if (totalWeight != 1.0)
            throw new ArgumentException("Weights must sum to 1.0.");

        Random random = new Random();
        double randomValue = random.NextDouble() * totalWeight;

        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return i + _minValue; // Assuming the range starts from minValue
        }

        throw new InvalidOperationException("Failed to generate a weighted integer.");
    }

    public List<double> CalculateStatisticalSummary()
    {
        int count = Convert.ToInt32(_maxValue - _minValue) + 1;
        Dictionary<int, int> frequency = new Dictionary<int, int>();

        for (int i = 0; i < count; i++)
        {
            int value = (int)(_minValue + i);
            if (!frequency.ContainsKey(value))
                frequency[value] = 0;
            frequency[value]++;
        }

        double mean = 0;
        foreach (var pair in frequency)
            mean += pair.Key * pair.Value;

        mean /= count;

        List<int> sortedValues = new List<int>(frequency.Keys);
        sortedValues.Sort();
        int median = sortedValues.Count % 2 == 0 
                        ? (sortedValues[sortedValues.Count / 2 - 1] + sortedValues[sortedValues.Count / 2]) / 2 
                        : sortedValues[sortedValues.Count / 2];

        int mode = 0;
        int maxFrequency = 0;
        foreach (var pair in frequency)
        {
            if (pair.Value > maxFrequency)
            {
                maxFrequency = pair.Value;
                mode = pair.Key;
            }
        }

        return new List<double> { mean, median, mode };
    }

    public void SetCustomWeights(Dictionary<int, double> weights)
    {
        double totalWeight = 0;
        foreach (var weight in weights.Values)
            totalWeight += weight;

        if (totalWeight != 1.0)
            throw new ArgumentException("Total weight must be equal to 1.0.");

        _customWeights = weights;
    }

    public int ApplyTransform(int value, Func<int, int> transformFunction)
    {
        return transformFunction(value);
    }
}
