// Define a base class for media processing modules
class MediaProcessor {
public:
    virtual void process(const std::string& file) = 0;
    virtual ~MediaProcessor() {}
};

// Implement specific processors for different formats
class MP3Processor : public MediaProcessor {
public:
    void process(const std::string& file) override {
        // Implementation for processing MP3 files
        std::cout << "Processing MP3: " << file << std::endl;
    }
};

class AACProcessor : public MediaProcessor {
public:
    void process(const std::string& file) override {
        // Implementation for processing AAC files
        std::cout << "Processing AAC: " << file << std::endl;
    }
};

// Class to manage media processors dynamically
class MediaManager {
private:
    std::vector<MediaProcessor*> processors;
    std::mutex processorMutex;
    std::condition_variable cv;

public:
    void addProcessor(MediaProcessor* processor) {
        std::lock_guard<std::mutex> lock(processorMutex);
        processors.push_back(processor);
        cv.notify_one();
    }

    void processFile(const std::string& file, int threadCount) {
        std::vector<std::thread> threads;
        for (int i = 0; i < threadCount; ++i) {
            threads.emplace_back([this, &file]() {
                while (true) {
                    MediaProcessor* processor = nullptr;
                    {
                        std::unique_lock<std::mutex> lock(processorMutex);
                        cv.wait(lock, [this] { return !processors.empty(); });
                        processor = processors.back();
                        processors.pop_back();
                    }
                    if (!processor) break;
                    processor->process(file);
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }
};

int main() {
    MediaManager manager;
    manager.addProcessor(new MP3Processor());
    manager.addProcessor(new AACProcessor());

    int threadCount = std::thread::hardware_concurrency();
    manager.processFile("example.mp3", threadCount);

    return 0;
}
