struct State {
    int id;
    std::vector<int> transitions; // List of next states based on environmental factors and character state
};

// Function to simulate fetching weather data (return fixed values for simplicity)
int getWeatherData() {
    return 20; // Simulated temperature, e.g., 20 degrees Celsius
}

// Cleanup function to properly free allocated memory
void cleanupStates(std::vector<State*> states) {
    for (auto state : states) {
        delete state;
    }
}

std::vector<State*> selectAttackStrategy(int* initialStates, int count, const std::vector<State>& fsa, int lastStateIndex) {
    std::vector<State*> newStateList;

    for (int i = 0; i < count; ++i) {
        int currentStateId = initialStates[i];
        bool hasTransitions = false;

        // Check each transition from the current state
        for (int nextState : fsa[currentStateId].transitions) {
            // Simulate checking if the next state is valid based on environmental factors and character state
            if (nextState == fsa[nextState].id && getWeatherData() > 15) { // Example condition
                hasTransitions = true;
                newStateList.push_back(new State{nextState, fsa[nextState].transitions});
            }
        }

        // If there are no valid transitions from the current state, skip it
        if (!hasTransitions) {
            delete new State{currentStateId, fsa[currentStateId].transitions};
        }
    }

    return newStateList;
}

int main() {
    // Example FSA setup (simplified for demonstration)
    std::vector<State> fsa = {
        {0, {1}},
        {1, {2}},
        {2, {}}
    };

    int initialStates[] = {0, 1};
    int count = sizeof(initialStates) / sizeof(initialStates[0]);
    int lastStateIndex = count - 1;

    std::vector<State*> newStateList = selectAttackStrategy(initialStates, count, fsa, lastStateIndex);

    for (auto state : newStateList) {
        std::cout << "Selected State ID: " << state->id << std::endl;
    }

    // Cleanup
    cleanupStates(newStateList);

    return 0;
}
