        {
            throw new ArgumentOutOfRangeException(nameof(maxValue), "Max value must be greater than min value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
        _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
