    {
        using var process = new Process
        {
            StartInfo =
            {
                FileName = "cmd",
                Arguments = $"/c {command}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            }
        };

        process.OutputDataReceived += (sender, e) => _loggingService.LogInfo(e.Data);
        process.ErrorDataReceived += (sender, e) => _loggingService.LogError(e.Data);

        try
        {
            await process.StartAsync();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();
            var result = await process.WaitForExitAsync();
            if (result != 0)
            {
                throw new InvalidOperationException("Shell command failed with exit code: " + result);
            }
