    {
        if (newMinValue >= newMaxValue || newMinValue < _minValue || newMaxValue > _maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(newMaxValue), "New range is invalid.");
        }
        _minValue = newMinValue;
        _maxValue = newMaxValue;
