#include <stdlib.h>
#include <pthread.h>

typedef struct ConnectionState {
    int id;
    long timestamp;
    // List of protocols
    char** protocols;
    int protocol_count;
} ConnectionState;

typedef struct NetworkConnectionManager {
    ConnectionState* states;
    int state_count;
    pthread_mutex_t mutex;
} NetworkConnectionManager;

NetworkConnectionManager* init_network_manager(int initial_states) {
    NetworkConnectionManager* manager = (NetworkConnectionManager*)malloc(sizeof(NetworkConnectionManager));
    manager->states = (ConnectionState*)calloc(initial_states, sizeof(ConnectionState));
    manager->state_count = initial_states;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void update_connection_state(NetworkConnectionManager* manager, int id, long timestamp, char** protocols, int protocol_count) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->state_count; i++) {
        if (manager->states[i].id == id) {
            // Update the state
            free(manager->states[i].protocols);
            manager->states[i].id = id;
            manager->states[i].timestamp = timestamp;
            manager->states[i].protocols = (char**)malloc(protocol_count * sizeof(char*));
            for (int j = 0; j < protocol_count; j++) {
                manager->states[i].protocols[j] = strdup(protocols[j]);
            }
            manager->states[i].protocol_count = protocol_count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void free_network_manager(NetworkConnectionManager* manager) {
    for (int i = 0; i < manager->state_count; i++) {
        free(manager->states[i].protocols);
    }
    free(manager->states);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
```

This code provides a basic structure for managing network connection states in a multi-threaded environment. It includes functions to initialize the manager, update connection states based on incoming events, and clean up resources when no longer needed. The use of mutex locks ensures that all operations are thread-safe, preventing data corruption or race conditions under high concurrency loads.']

