import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class StringHashProcessor {

    public static Map<String, String> processStringsAndGenerateHashes(List<String> strings) {
        Map<String, String> resultMap = new HashMap<>();
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            for (String input : strings) {
                if (input != null) {
                    byte[] hashBytes = digest.digest(input.trim().getBytes());
                    String hashHex = bytesToHex(hashBytes);
                    resultMap.put(input, hashHex);
                }
            }
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not found", e);
        }
        return resultMap;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // Example usage
    public static void main(String[] args) {
        List<String> strings = List.of("  example  ", " test ", null, "java ");
        Map<String, String> hashes = processStringsAndGenerateHashes(strings);
        System.out.println(hashes);
    }
}
