import hashlib
import asyncio
from aiohttp import ClientSession, ClientTimeout
from socket import getaddrinfo

async def compute_md5_for_large_file(file_path, chunk_size=1024*1024):
    async with aiofiles.open(file_path, mode='rb') as file:
        hasher = hashlib.md5()
        while True:
            data = await file.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

async def fetch_file_with_retry(url, retries=3, timeout=10):
    async with ClientSession(timeout=ClientTimeout(total=timeout)) as session:
        for _ in range(retries):
            try:
                async with session.get(url) as response:
                    if response.status == 200:
                        return await response.read()
            except (aiohttp.ClientError, asyncio.TimeoutError) as e:
                continue
    raise Exception("Failed to fetch file after retries")

def resolve_dns(hostname):
    try:
        result = getaddrinfo(hostname, None)
        return result[0][-1][0]  # Return the first IP address
    except OSError as e:
        return None

# Example usage in Python module
async def process_large_file(url_or_path):
    if url_or_path.startswith('http'):
        file_data = await fetch_file_with_retry(url_or_path)
        temp_file_path = 'temp_large_file'
        with open(temp_file_path, 'wb') as f:
            f.write(file_data)
        md5_hash = await compute_md5_for_large_file(temp_file_path)
    else:
        md5_hash = await compute_md5_for_large_file(url_or_path)

    return md5_hash
