#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *key;
    char *value;
} Field;

int parse_json(const char *json_str, Field **fields, int *field_count) {
    // Simulate parsing JSON and extracting fields
    if (strcmp(json_str, "{\"temperature\":25}") != 0) {
        return -1; // Error code for data format mismatch
    }

    *field_count = 1;
    *fields = (Field *)malloc(sizeof(Field));
    (*fields)[0].key = strdup("temperature");
    (*fields)[0].value = strdup("25");

    return 0; // Success
}

// Example usage of the parse_json function
int main() {
    const char *json_str = "{\"temperature\":25}";
    Field *fields;
    int field_count;

    int result = parse_json(json_str, &fields, &field_count);
    if (result == 0) {
        printf("Parsed fields:\n");
        for (int i = 0; i < field_count; i++) {
            printf("%s: %s\n", fields[i].key, fields[i].value);
        }
        free(fields[0].key);
        free(fields[0].value);
        free(fields);
    } else {
        printf("Failed to parse JSON\n");
    }

    return 0;
}
