// Function to read a text file and process each line
void processFile(const char* filename) {
    std::ifstream file(filename);
    if (file.is_open()) {
        std::string line;
        while (std::getline(file, line)) {
            size_t pos = 0;
            std::string token;
            std::vector<std::string> tokens;
            while ((pos = line.find(',')) != std::string::npos) {
                token = line.substr(0, pos);
                tokens.push_back(token);
                line.erase(0, pos + 1);
            }
            tokens.push_back(line);

            size_t lastField = tokens.size() - 1;
            if (lastField > 1 && !tokens[lastField].empty() && !tokens[lastField - 1].empty()) {
                double average = std::stod(tokens[lastField]) + std::stod(tokens[lastField - 1]);
                average /= 2.0;
                tokens[lastField] = std::to_string(average);
            }

            for (size_t i = 0; i < tokens.size(); ++i) {
                if (i != 0) std::cout << ",";
                std::cout << tokens[i];
            }
            std::cout << std::endl;
        }
        file.close();
    } else {
        std::cerr << "Unable to open file: " << filename << std::endl;
    }
}

// Function to modify a forward list of strings
void insertAfter(std::forward_list<std::string>& fl, const std::string& target, const std::string& value) {
    auto prev = fl.before_begin();
    for (auto it = fl.begin(); it != fl.end(); ++it) {
        if (*it == target) {
            fl.insert_after(prev, value);
            return;
        }
        prev = it;
    }
    fl.push_back(value);
}

int main() {
    const char* filename = "example.txt";
    processFile(filename);

    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfter(myList, "banana", "date");
    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    std::cout << std::endl;

    return 0;
}
