#include <stdlib.h>
#include <pthread.h>

#define MAX_CONTEXTS 1024

typedef struct {
    int pdcch_id;
    // PDCCH format information
} MacControlElement;

typedef struct {
    MacControlElement *mac_ce;
    pthread_mutex_t mutex;
} LTE_UE_Context;

LTE_UE_Context *ue_context_pool[MAX_CONTEXTS];
int context_count = 0;
pthread_mutex_t pool_mutex;

void init_ue_context_pool() {
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        ue_context_pool[i] = malloc(sizeof(LTE_UE_Context));
        if (!ue_context_pool[i]) {
            perror("Failed to allocate memory for UE context");
            exit(EXIT_FAILURE);
        }
        pthread_mutex_init(&ue_context_pool[i]->mutex, NULL);
    }
}

LTE_UE_Context *allocate_ue_context() {
    pthread_mutex_lock(&pool_mutex);
    if (context_count >= MAX_CONTEXTS) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Pool is full
    }

    LTE_UE_Context *new_context = ue_context_pool[context_count++];
    new_context->mac_ce = malloc(sizeof(MacControlElement));
    if (!new_context->mac_ce) {
        perror("Failed to allocate memory for MAC CE");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    pthread_mutex_init(&new_context->mutex, NULL);

    pthread_mutex_unlock(&pool_mutex);
    return new_context;
}

void free_ue_context(LTE_UE_Context *context) {
    pthread_mutex_lock(&context->mutex);
    free(context->mac_ce);
    context->mac_ce = NULL;

    // Find and replace with last element to maintain contiguous block
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < context_count; i++) {
        if (ue_context_pool[i] == context) {
            ue_context_pool[i] = ue_context_pool[--context_count];
            break;
        }
    }

    pthread_mutex_unlock(&pool_mutex);

    pthread_mutex_destroy(&context->mutex);
    free(context);
}

void monitor_ue_context_pool() {
    // Implement monitoring logic here
}

// Thread-safe function to access/modify a context
int get_pdcch_format(LTE_UE_Context *context, int pdcch_id) {
    pthread_mutex_lock(&context->mutex);
    if (pdcch_id < 0 || pdcch_id >= sizeof(context->mac_ce) / sizeof(MacControlElement)) {
        pthread_mutex_unlock(&context->mutex);
        return -1; // Invalid PDCCH ID
    }

    MacControlElement *pdcch = &context->mac_ce[pdcch_id];
    int format_info = pdcch->format_info;
    pthread_mutex_unlock(&context->mutex);
    return format_info;
}

void set_pdcch_format(LTE_UE_Context *context, int pdcch_id, int format_info) {
    pthread_mutex_lock(&context->mutex);
    if (pdcch_id < 0 || pdcch_id >= sizeof(context->mac_ce) / sizeof(MacControlElement)) {
        pthread_mutex_unlock(&context->mutex);
        return; // Invalid PDCCH ID
    }

    context->mac_ce[pdcch_id].format_info = format_info;
    pthread_mutex_unlock(&context->mutex);
}

void cleanup_ue_context_pool() {
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (ue_context_pool[i]) {
            free(ue_context_pool[i]->mac_ce);
            pthread_mutex_destroy(&ue_context_pool[i]->mutex);
            free(ue_context_pool[i]);
        }
    }
}
