import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileEncryptionService {
    private static final Logger logger = LoggerFactory.getLogger(FileEncryptionService.class);
    private static final int BUFFER_SIZE = 8192;
    private static final String KAFKA_TOPIC = "file_processing";
    private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
    private KafkaProducer<String, String> kafkaProducer;

    public FileEncryptionService() {
        Properties props = new Properties();
        props.put("bootstrap.servers", KAFKA_BOOTSTRAP_SERVERS);
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        kafkaProducer = new KafkaProducer<>(props);
    }

    public void encryptFile(String inputFilePath, String outputFilePath, String password) throws Exception {
        SecretKey key = deriveKey(password);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        byte[] ivBytes = generateIV();
        IvParameterSpec iv = new IvParameterSpec(ivBytes);
        cipher.init(Cipher.ENCRYPT_MODE, key, iv);

        try (FileInputStream fis = new FileInputStream(inputFilePath);
             FileOutputStream fos = new FileOutputStream(outputFilePath)) {
            writeHeader(fos, ivBytes);
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                byte[] encryptedData = cipher.update(buffer, 0, bytesRead);
                if (encryptedData != null) {
                    fos.write(encryptedData);
                }
            }
            byte[] finalBytes = cipher.doFinal();
            if (finalBytes != null) {
                fos.write(finalBytes);
            }
        }
    }

    public void decryptFile(String inputFilePath, String outputFilePath, String password) throws Exception {
        SecretKey key = deriveKey(password);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        byte[] ivBytes = readHeader(inputFilePath);
        IvParameterSpec iv = new IvParameterSpec(ivBytes);
        cipher.init(Cipher.DECRYPT_MODE, key, iv);

        try (FileInputStream fis = new FileInputStream(inputFilePath);
             FileOutputStream fos = new FileOutputStream(outputFilePath)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                byte[] decryptedData = cipher.update(buffer, 0, bytesRead);
                if (decryptedData != null) {
                    fos.write(decryptedData);
                }
            }
            byte[] finalBytes = cipher.doFinal();
            if (finalBytes != null) {
                fos.write(finalBytes);
            }
        }
    }

    private SecretKey deriveKey(String password) throws Exception {
        KeyDerivationFunction kdf = KeyFactory.getInstance("PBKDF2WithHmacSHA256");
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 10000, 256);
        SecretKey secretKey = kdf.generateSecret(spec);
        return new SecretKeySpec(secretKey.getEncoded(), "AES");
    }

    private byte[] generateIV() {
        SecureRandom random = new SecureRandom();
        byte[] ivBytes = new byte[16];
        random.nextBytes(ivBytes);
        return ivBytes;
    }

    private void writeHeader(OutputStream fos, byte[] ivBytes) throws IOException {
        fos.write(ivBytes.length);
        fos.write(ivBytes);
    }

    private byte[] readHeader(String inputFilePath) throws IOException {
        try (FileInputStream fis = new FileInputStream(inputFilePath)) {
            int ivLength = fis.read();
            if (ivLength == -1) {
                throw new IOException("Invalid file format");
            }
            byte[] ivBytes = new byte[ivLength];
            if (fis.read(ivBytes) != ivLength) {
                throw new IOException("Invalid file format");
            }
            return ivBytes;
        }
    }

    public String calculateMD5(String filePath) throws IOException {
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            MessageDigest md = DigestUtils.getMd5Digest();
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            return DigestUtils.md5Hex(md.digest());
        }
    }

    public void sendShutdownMessage() {
        kafkaProducer.send(new ProducerRecord<>(KAFKA_TOPIC, "shutdown"));
    }

    private void cleanup(Cipher cipher) throws Exception {
        if (cipher != null) {
            cipher.doFinal();
        }
    }

    public void shutdown() {
        kafkaProducer.close();
    }

    // Add unit tests for the calculateMD5 method here
}
