#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int id;
    time_t timestamp;
    char protocols[50];
} ConnectionState;

typedef struct {
    ConnectionState* connections;
    pthread_mutex_t lock;
} NetworkConnectionManager;

NetworkConnectionManager* init_network_connection_manager() {
    NetworkConnectionManager* manager = (NetworkConnectionManager*)malloc(sizeof(NetworkConnectionManager));
    if (!manager) return NULL;

    manager->connections = (ConnectionState*)calloc(MAX_CONNECTIONS, sizeof(ConnectionState));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void update_connection_state(NetworkConnectionManager* manager, int id, char* protocol) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (manager->connections[i].id == id) {
            time_t now = time(NULL);
            strcpy(manager->connections[i].protocols, protocol);
            manager->connections[i].timestamp = now;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void free_network_connection_manager(NetworkConnectionManager* manager) {
    if (manager->connections) free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
