int derive_key(const char *password, unsigned int iterations, unsigned char *out_key, size_t key_len) {
    SHA256_CTX sha_ctx;
    unsigned char intermediate_key[SHA256_DIGEST_LENGTH];

    // Perform password stretching
    memcpy(intermediate_key, password, strlen(password));
    for (unsigned int i = 0; i < iterations; ++i) {
        SHA256_Init(&sha_ctx);
        SHA256_Update(&sha_ctx, intermediate_key, SHA256_DIGEST_LENGTH);
        SHA256_Final(intermediate_key, &sha_ctx);
    }

    // Ensure minimum entropy
    if (RAND_bytes(out_key, key_len) != 1 || !PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), key_len, out_key)) {
        return -1;
    }

    log_crypto_operation("Key Derivation", out_key, key_len);
    return 0;
}

int initialize_cipher(const char *password, unsigned int iterations, EVP_CIPHER_CTX **ctx) {
    unsigned char derived_key[KEY_LEN];
    if (derive_key(password, iterations, derived_key, KEY_LEN) != 0) {
        return -1;
    }

    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) {
        return -1;
    }

    // Initialize cipher
    if (EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, derived_key, NULL) != 1) {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    log_crypto_operation("Cipher Initialization", derived_key, KEY_LEN);
    return 0;
}

int encrypt_data(const EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    int len;

    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        return -1;
    }

    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        return -1;
    }

    ciphertext_len += len;

    log_crypto_operation("Data Encryption", plaintext, plaintext_len);
    return ciphertext_len;
}

int decrypt_data(const EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    int len, plaintext_len = 0;

    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        return -1;
    }

    plaintext_len += len;

    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
        return -1;
    }

    plaintext_len += len;

    log_crypto_operation("Data Decryption", ciphertext, ciphertext_len);
    return plaintext_len;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
