#include <stdlib.h>
#include <string.h>

#define PBKDF2_ITERATIONS 100000
#define KEY_LENGTH 32
#define IV_LENGTH 16

EVP_CIPHER_CTX *initialize_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    unsigned char key[KEY_LENGTH], iv[IV_LENGTH];
    int key_len, iv_len;

    // Derive the key and IV using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, PBKDF2_ITERATIONS,
                           EVP_sha256(), KEY_LENGTH, key) != 1 ||
        RAND_bytes(iv, IV_LENGTH) != 1) {
        fprintf(stderr, "Failed to derive key or generate IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    if (EVP_EncryptInit_ex2(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
