        fprintf(stderr, "Error creating SSL context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }

    SSL_CTX_set_min_proto_version(*ctx, TLS1_3_VERSION);
    SSL_CTX_set_max_proto_version(*ctx, TLS1_3_VERSION);

    if (SSL_CTX_use_certificate_file(*ctx, cert_file, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Error loading server certificate: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }

    if (SSL_CTX_use_PrivateKey_file(*ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Error loading server private key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }

    if (!SSL_CTX_check_private_key(*ctx)) {
        fprintf(stderr, "Private key does not match the certificate public key\n");
        exit(EXIT_FAILURE);
    }

    if (SSL_CTX_load_verify_locations(*ctx, ca_list, NULL) <= 0) {
        fprintf(stderr, "Error loading CA list: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }

    SSL_CTX_set_verify(*ctx, SSL_VERIFY_PEER | SSL_VERIFY_FAIL_IF_NO_PEER_CERT, NULL);

    SSL_CTX_enable_tickets(*ctx);
}

int main() {
    SSL_CTX *ctx = NULL;
    initialize_tls_server(&ctx, "server-cert.pem", "server-key.pem", "ca-list.pem");

    // Additional code for establishing connection, sending/receiving data, logging, and resource cleanup

    SSL_CTX_free(ctx);

    return 0;
}
