        return NULL;
    }

    // Extract or create the extension
    char* dot_pos = strrchr(original_filename, '.');
    const char* base_name, *extension;
    if (dot_pos != NULL) {
        base_name = original_filename;
        extension = dot_pos + 1;
    } else {
        base_name = original_filename;
        extension = "";
    }

    // Validate num_digits
    if (num_digits > strlen(extension)) {
        return NULL;
    }

    // Allocate memory for the new filename
    char* new_filename = (char*)memory_pool_malloc(&memory_pool, MAX_FILENAME_LENGTH);
    if (new_filename == NULL) {
        return NULL;
    }

    // Construct the new filename
    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s%.*d.%s", base_name, num_digits, 0, new_file_type);

    return new_filename;
