EVP_CIPHER_CTX *initialize_aes_cipher(const char *password, size_t password_len) {
    if (password == NULL || password_len < 8) {
        fprintf(stderr, "Password is too short or invalid\n");
        return NULL;
    }

    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, SALT_SIZE)) {
        fprintf(stderr, "Failed to generate salt\n");
        return NULL;
    }

    unsigned char key[KEY_SIZE], iv[IV_SIZE];
    if (!PKCS5_PBKDF2_HMAC_SHA1(password, password_len, salt, SALT_SIZE, PBKDF2_ITERATIONS, EVP_sha1(), KEY_SIZE, key) ||
        !RAND_bytes(iv, IV_SIZE)) {
        fprintf(stderr, "Failed to derive key or generate IV\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
