aes_key_iv* init_aes_cipher(const char* passphrase, size_t passphrase_len) {
    if (passphrase == NULL || passphrase_len < 8) {
        fprintf(stderr, "Passphrase too short\n");
        return NULL;
    }

    aes_key_iv *key_iv = malloc(sizeof(aes_key_iv));
    if (!key_iv) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    unsigned char salt[SALT_LEN];
    if (!RAND_bytes(salt, SALT_LEN)) {
        fprintf(stderr, "Failed to generate random salt\n");
        free(key_iv);
        return NULL;
    }

    int derived_key_len = 0;
    if (PKCS5_PBKDF2_HMAC(passphrase, passphrase_len, salt, SALT_LEN,
                          100000, EVP_sha256(), KEY_LEN, key_iv->key) != 1) {
        fprintf(stderr, "PBKDF2 failed\n");
        free(key_iv);
        return NULL;
    }

    if (!RAND_bytes(key_iv->iv, IV_LEN)) {
        fprintf(stderr, "Failed to generate random IV\n");
        free(key_iv);
        return NULL;
    }

    key_iv->derived_key_len = KEY_LEN;

    return key_iv;
}

void cleanup_aes_cipher(aes_key_iv* key_iv) {
    if (key_iv != NULL) {
        memset(key_iv->key, 0, sizeof(key_iv->key));
        memset(key_iv->iv, 0, sizeof(key_iv->iv));
        free(key_iv);
