#include <stdlib.h>
#include <pthread.h>

typedef struct {
    void (*read)(void* io_context);
    void (*write)(void* io_context);
    void (*interrupt)(void* io_context);
} HardwareOps;

typedef struct {
    HardwareOps ops;
    void* io_context;
    pthread_mutex_t mutex;
} NetworkDriver;

NetworkDriver* drivers[MAX_DRIVERS];
int driver_count = 0;
pthread_mutex_t driver_lock;

int register_driver(HardwareOps* ops, void* io_context) {
    pthread_mutex_lock(&driver_lock);
    if (driver_count >= MAX_DRIVERS) {
        pthread_mutex_unlock(&driver_lock);
        return -ENOMEM; // Resource exhaustion
    }
    NetworkDriver* new_driver = (NetworkDriver*)malloc(sizeof(NetworkDriver));
    if (!new_driver) {
        pthread_mutex_unlock(&driver_lock);
        return -ENOMEM; // Memory allocation failure
    }
    new_driver->ops = *ops;
    new_driver->io_context = io_context;
    pthread_mutex_init(&new_driver->mutex, NULL);
    drivers[driver_count++] = new_driver;
    pthread_mutex_unlock(&driver_lock);
    return 0; // Success
}

int unregister_driver(int index) {
    if (index < 0 || index >= driver_count) {
        return -EINVAL; // Invalid index
    }
    pthread_mutex_lock(&driver_lock);
    NetworkDriver* driver = drivers[index];
    pthread_mutex_destroy(&driver->mutex);
    free(driver);
    for (int i = index; i < driver_count - 1; i++) {
        drivers[i] = drivers[i + 1];
    }
    driver_count--;
    pthread_mutex_unlock(&driver_lock);
    return 0; // Success
}

void process_io_event(int event_type, int index) {
    if (index < 0 || index >= driver_count) {
        return; // Invalid index
    }
    NetworkDriver* driver = drivers[index];
    pthread_mutex_lock(&driver->mutex);
    switch (event_type) {
        case READ_EVENT:
            driver->ops.read(driver->io_context);
            break;
        case WRITE_EVENT:
            driver->ops.write(driver->io_context);
            break;
        case INTERRUPT_EVENT:
            driver->ops.interrupt(driver->io_context);
            break;
    }
    pthread_mutex_unlock(&driver->mutex);
}
