#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <unordered_set>
#include <fstream>
#include <memory>

// Define file operation struct
struct FileOperation {
    std::string filePath;
    std::unordered_set<std::string> metadataTags;
    std::vector<std::function<void()>> processingStages;
};

class FileManager {
public:
    FileManager(size_t numThreads) : stop(false), threadCount(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~FileManager() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addFileOperation(const FileOperation& operation) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.push(operation);
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<FileOperation> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
    size_t threadCount;
};

void processFile(const FileOperation& operation) {
    // Simulate file processing
    std::cout << "Processing file: " << operation.filePath << std::endl;
}

int main() {
    FileManager manager(5);

    // Example usage
    FileOperation op1 = {"path/to/image.jpg", {"image"}, {processFile}};
    FileOperation op2 = {"path/to/video.mp4", {"video"}, {processFile}};

    manager.addFileOperation(op1);
    manager.addFileOperation(op2);

    return 0;
}
