int processAndEncrypt(const char *input, size_t sizeLimit, unsigned char **outputBuffer, const char *password,
                      size_t outputBufferSize, EncryptionContext *ctx, int logErrors, int *errorOccurred) {
    if (strlen(input) >= sizeLimit) {
        return -1; // String exceeds size limit
    }

    // Append slash if within limit
    char buffer[sizeLimit + 2];
    strncpy(buffer, input, sizeLimit);
    buffer[sizeLimit] = '/';
    buffer[sizeLimit + 1] = '\0';

    unsigned char *key = deriveKey(password, 1000); // Example iterations value
    if (!key) {
        return -2; // Key derivation failed
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(key);
        return -3; // Failed to create cipher context
    }

    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(iv, EVP_MAX_IV_LENGTH)) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        return -4; // Failed to generate IV
    }

    ctx->iv_len = EVP_CIPHER_iv_length(EVP_aes_256_cbc());
    memcpy(ctx->iv, iv, ctx->iv_len);

    if (outputBuffer) {
        *outputBuffer = buffer;
    } else {
        *outputBuffer = malloc(sizeLimit + 2);
        if (!*outputBuffer) {
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            return -5; // Memory allocation failed
        }
        memcpy(*outputBuffer, buffer, sizeLimit + 2);
    }

    // Encrypt the data
    int encryptedLen;
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        if (outputBuffer && *outputBuffer != buffer) {
            free(*outputBuffer);
        }
        return -6; // Encryption failed
    }

    if (1 != EVP_EncryptUpdate(ctx, *outputBuffer, &encryptedLen, buffer, strlen(buffer))) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        if (outputBuffer && *outputBuffer != buffer) {
            free(*outputBuffer);
        }
        return -7; // Encryption update failed
    }

    int finalLen;
    if (1 != EVP_EncryptFinal_ex(ctx, (*outputBuffer + encryptedLen), &finalLen)) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        if (outputBuffer && *outputBuffer != buffer) {
            free(*outputBuffer);
        }
        return -8; // Encryption final failed
    }

    encryptedLen += finalLen;
    ctx->iv_len = 0; // Reset IV length for the context

    EVP_CIPHER_CTX_free(ctx);
    free(key);

    if (logErrors && errorOccurred) {
        *errorOccurred = 0; // No errors occurred
    }

    return encryptedLen;
}
