int derive_key(const char *password, int iterations, unsigned char *key) {
    // Use a strong hash function like PBKDF2 or bcrypt
    PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), NULL, 0, iterations, AES_KEY_SIZE, key);
    return 1;
}

AesCipherCtx* aes_init(const char *password, int iterations) {
    AesCipherCtx *ctx = malloc(sizeof(AesCipherCtx));
    if (!ctx) return NULL;

    // Derive the encryption key from the password
    if (!derive_key(password, iterations, ctx->key)) {
        free(ctx);
        return NULL;
    }

    // Generate a random IV (use OS randomness)
    if (!RAND_bytes(ctx->iv, IV_SIZE)) {
        free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Set the last used time
    ctx->last_used = time(NULL);

    return ctx;
}

void aes_cleanup(AesCipherCtx *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        memset(ctx, 0, sizeof(AesCipherCtx));
        free(ctx);
    }
}
