// Define the structure for a network driver
typedef struct {
    void (*read)(void);
    void (*write)(void);
    void (*interrupt_handler)(void);
} NetworkDriver;

// Define a node in the linked list of drivers
typedef struct DriverNode {
    NetworkDriver driver;
    struct DriverNode* next;
} DriverNode;

// Global head of the driver list and mutex for thread safety
DriverNode* driver_list_head = NULL;
pthread_mutex_t driver_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to register a new network driver
int ManageNetworkDrivers(NetworkDriver* new_driver) {
    pthread_mutex_lock(&driver_mutex);

    // Allocate memory for the new node
    DriverNode* newNode = (DriverNode*)malloc(sizeof(DriverNode));
    if (newNode == NULL) {
        pthread_mutex_unlock(&driver_mutex);
        return -1; // Memory allocation failed
    }

    // Initialize the new node with the driver data
    *newNode = (DriverNode){.driver = *new_driver, .next = NULL};

    // Add the new driver to the front of the list
    newNode->next = driver_list_head;
    driver_list_head = newNode;

    pthread_mutex_unlock(&driver_mutex);
    return 0; // Success
}

