class ComplexEventProcessor {
public:
    struct Message {
        std::string content;
        // Other message properties
    };

    enum class DeliveryMode { Sync, Async };
    enum class DataFormat { JSON, ProtocolBuffers, Avro };

    ComplexEventProcessor(DeliveryMode mode = DeliveryMode::Sync, size_t numThreads = 4)
        : deliveryMode(mode), messageQueue(), stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex);
                    condition.wait(lock, [this] { return !messageQueue.empty() || stop; });
                    if (stop && messageQueue.empty()) break;
                    auto msg = std::move(messageQueue.front());
                    messageQueue.pop();
                    lock.unlock();

                    processMessage(msg);
                }
            });
        }
    }

    ~ComplexEventProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addMessage(const Message& msg) {
        messageQueue.push(msg);
        condition.notify_one();
    }

private:
    DeliveryMode deliveryMode;
    std::queue<Message> messageQueue;
    bool stop;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable condition;

    void processMessage(const Message& msg) {
        // Validate and store message
        if (validateMessage(msg)) {
            if (deliveryMode == DeliveryMode::Sync) {
                syncProcess(msg);
            } else {
                asyncProcess(msg);
            }
        } else {
            logError("Invalid message", msg);
        }
    }

