// Function to sort lines in a file and extract sequence number from the last line
int extractSequenceNumber(const std::string& filePath) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filePath << std::endl;
        return -1;
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    file.close();

    if (lines.empty()) {
        std::cerr << "File is empty." << std::endl;
        return -1;
    }

    // Sort the lines
    std::sort(lines.begin(), lines.end());

    // Extract sequence number from the last line
    int sequenceNumber;
    try {
        sequenceNumber = std::stoi(lines.back());
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error parsing sequence number: " << e.what() << std::endl;
        return -1;
    }

    return sequenceNumber;
}

int main() {
    std::string filePath = "example.txt";
    int seqNum = extractSequenceNumber(filePath);
    if (seqNum != -1) {
        std::cout << "Sequence number from the last line: " << seqNum << std::endl;
    }
    return 0;
}
