import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.PBEParameterSpec;
import java.io.*;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;
import java.security.spec.KeySpec;

public class FileEncryptor {

    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/CBC/PKCS5Padding";

    public static void main(String[] args) {
        try {
            // Example usage
            String inputFilePath = "input.txt";
            String encryptedFilePath = "encrypted.dat";
            String decryptedFilePath = "decrypted.txt";
            String password = "securepassword123";

            encryptFile(inputFilePath, encryptedFilePath, password);
            decryptFile(encryptedFilePath, decryptedFilePath, password);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void encryptFile(String inputFilePath, String outputFilePath, String password) throws Exception {
        SecretKey secretKey = generateSecretKey(password);
        byte[] iv = generateIv();
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, new IvParameterSpec(iv));

        try (FileInputStream fis = new FileInputStream(inputFilePath);
             FileOutputStream fos = new FileOutputStream(outputFilePath)) {
            fos.write(iv); // Write IV to the output file
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                fos.write(cipher.update(buffer, 0, bytesRead));
            }
        }

        cipher.doFinal();
    }

    public static void decryptFile(String inputFilePath, String outputFilePath, String password) throws Exception {
        SecretKey secretKey = generateSecretKey(password);
        try (FileInputStream fis = new FileInputStream(inputFilePath)) {
            byte[] iv = new byte[16];
            fis.read(iv); // Read IV from the input file
            Cipher cipher = Cipher.getInstance(TRANSFORMATION);
            cipher.init(Cipher.DECRYPT_MODE, secretKey, new IvParameterSpec(iv));

            try (FileOutputStream fos = new FileOutputStream(outputFilePath)) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    fos.write(cipher.update(buffer, 0, bytesRead));
                }
            }

            cipher.doFinal();
        }
    }

    private static SecretKey generateSecretKey(String password) throws NoSuchAlgorithmException, InvalidKeySpecException {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 65536, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKey() {
            @Override
            public String getAlgorithm() {
                return ALGORITHM;
            }

            @Override
            public String getFormat() {
                return "RAW";
            }

            @Override
            public byte[] getEncoded() {
                return keyBytes;
            }
        };
    }

    private static byte[] generateIv() throws NoSuchAlgorithmException {
        SecureRandom random = SecureRandom.getInstance("SHA1PRNG");
        byte[] iv = new byte[16];
        random.nextBytes(iv);
        return iv;
    }
}
