#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

// Function to derive AES-256-CBC key using SHA-256 and password stretching
int deriveKey(const char *password, int iterations, unsigned char *key) {
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) return 0;
    unsigned char derived_key[32] = {0};
    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                       iterations, EVP_sha256(), 32, derived_key);
    memcpy(key, derived_key, 32);
    return 1;
}

// Function to process and encrypt string using AES-256-CBC
unsigned char* processAndEncrypt(const char *str, size_t limit, unsigned char *buf, const char *password, int log) {
    if (strlen(str) < limit) {
        if (buf) {
            strcpy((char*)buf, str);
            strcat((char*)buf, "/");
        } else {
            buf = malloc(strlen(str) + 2); // +1 for '/', +1 for '\0'
            if (!buf) return NULL;
            strcpy((char*)buf, str);
            strcat((char*)buf, "/");
        }
    } else {
        return NULL; // String exceeds limit
    }

    unsigned char key[32];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (!deriveKey(password, 10000, key)) {
        if (buf && buf != str) free(buf);
        return NULL;
    }
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        if (buf && buf != str) free(buf);
        return NULL;
    }

    int len, ciphertext_len;
    unsigned char ciphertext[128];
    if (log) printf("Initializing AES-256-CBC encryption...\n");
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        if (buf && buf != str) free(buf);
        return NULL;
    }

    if (log) printf("Encrypting data...\n");
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, buf, strlen((char*)buf))) {
        EVP_CIPHER_CTX_free(ctx);
        if (buf && buf != str) free(buf);
        return NULL;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        if (buf && buf != str) free(buf);
        return NULL;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    unsigned char *result = malloc(ciphertext_len);
    if (!result) {
        if (buf && buf != str) free(buf);
        return NULL;
    }

    memcpy(result, ciphertext, ciphertext_len);

    if (log) printf("Encryption successful. Ciphertext length: %d\n", ciphertext_len);

    // Clean up
    memset(key, 0, sizeof(key));
    memset(iv, 0, sizeof(iv));

    return result;
}
