void initialize_arrays(long* offsets, int* keys, Record* records, size_t array_size, int min_value, int max_value) {
    for (size_t i = 0; i < array_size; i++) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void process_strings(char** strings, size_t array_size, int max_string_length, char* buffer, size_t buffer_size) {
    for (size_t i = 0; i < array_size && i * max_string_length + strlen(strings[i]) + 1 <= buffer_size; i++) {
        if (strlen(strings[i]) < max_string_length - 1) {
            strcat(buffer + i * max_string_length, "/");
        }
        strcpy(buffer + i * max_string_length, strings[i]);
    }
}

int main() {
    size_t array_size = 1000;
    long* offsets = allocate_memory(array_size * sizeof(long));
    int* keys = allocate_memory(array_size * sizeof(int));
    Record* records = allocate_memory(array_size * sizeof(Record));

    initialize_arrays(offsets, keys, records, array_size, 1, 100);

    char** strings = (char**)allocate_memory(array_size * sizeof(char*));
    for (size_t i = 0; i < array_size; i++) {
        strings[i] = allocate_memory(256);
        snprintf(strings[i], 256, "String %zu", i);
    }

    size_t buffer_size = array_size * 256;
    char* buffer = allocate_memory(buffer_size);

    process_strings(strings, array_size, 255, buffer, buffer_size);

    for (size_t i = 0; i < array_size; i++) {
        free(strings[i]);
    }
    free(strings);
    free(offsets);
    free(keys);
    free(records);
    free(buffer);

    return 0;
}
