import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.ArrayList;

public class HashUtil {

    public static String computeHash(String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }
    }

    public static List<String> computeHashes(List<String> inputs) {
        List<String> hashes = new ArrayList<>();
        for (String input : inputs) {
            hashes.add(computeHash(input));
        }
        return hashes;
    }

    // Method to precompute MD5 hashes of common strings
    public static void precomputeCommonHashes() {
        String[] commonStrings = {"example", "data", "hash", "precomputation"};
        for (String str : commonStrings) {
            computeHash(str);
        }
    }
}
