import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class MD5Hasher {
    public static String computeHash(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public static List<String> computeHashes(List<String> inputs) {
        List<String> hashes = new ArrayList<>();
        for (String input : inputs) {
            hashes.add(computeHash(input));
        }
        return hashes;
    }

    // Precomputation of MD5 hashes for common strings
    private static final List<String> COMMON_STRINGS = List.of("common1", "common2");
    private static final List<String> PRECOMPUTED_HASHES = new ArrayList<>();

    static {
        for (String str : COMMON_STRINGS) {
            PRECOMPUTED_HASHES.add(computeHash(str));
        }
    }

    public static String getPrecomputedHash(String input) {
        int index = COMMON_STRINGS.indexOf(input);
        if (index != -1) {
            return PRECOMPUTED_HASHES.get(index);
        } else {
            throw new IllegalArgumentException("Input string not in precomputed set");
        }
    }

    // Thread-safe implementation using synchronization
    public static synchronized String computeHashThreadSafe(String input) {
        return computeHash(input);
    }
}
