import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.ArrayList;

public class HashGenerator {

    private static final List<String> commonHashes = new ArrayList<>();

    public static void precomputeCommonHashes() {
        // Precompute MD5 hashes of common strings
        String[] commonStrings = {"common", "strings", "here"};
        for (String str : commonStrings) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(str.getBytes());
                commonHashes.add(bytesToHex(hashBytes));
            } catch (NoSuchAlgorithmException e) {
                e.printStackTrace();
            }
        }
    }

    public static List<String> computeHash(List<String> strings) {
        List<String> hashes = new ArrayList<>();
        for (String str : strings) {
            if (str == null || str.length() > 1024 * 1024) { // Handle invalid input
                hashes.add("Invalid input");
                continue;
            }
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(str.getBytes());
                hashes.add(bytesToHex(hashBytes));
            } catch (NoSuchAlgorithmException e) {
                hashes.add("Error computing hash");
            }
        }
        return hashes;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
