        commands[i].cell_name_tag = strdup(default_cell_name);
        if (!commands[i].cell_name_tag) {
            perror("Failed to allocate memory for cell name");
            // Free previously allocated structures and return NULL
            for (int j = 0; j < i; j++) {
                free(commands[j].cell_name_tag);
            }
            free(commands);
            return NULL;
        }
    }

    // Function is complete, no further allocation needed
    return commands;
}

