typedef struct PacketNode {
    PACKET_DATA_T packet;
    struct PacketNode *next;
} PacketNode;

typedef struct {
    PacketNode *front;
    PacketNode *rear;
    pthread_mutex_t lock;
} PacketQueue;

void initPacketQueue(PacketQueue *queue) {
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueuePacket(PacketQueue *queue, PACKET_DATA_T packet) {
    pthread_mutex_lock(&queue->lock);
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->packet = packet;
    new_node->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    pthread_mutex_unlock(&queue->lock);
}

PACKET_DATA_T dequeuePacket(PacketQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->lock);
        PACKET_DATA_T empty_packet;
        memset(&empty_packet, 0, sizeof(empty_packet));
        return empty_packet;
    }

    PacketNode *temp = queue->front;
    PACKET_DATA_T packet = temp->packet;

    if (queue->front == queue->rear) {
        queue->front = queue->rear = NULL;
    } else {
        queue->front = queue->front->next;
    }
    free(temp);
    pthread_mutex_unlock(&queue->lock);
    return packet;
}

