#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1460
#define INITIAL_QUEUE_CAPACITY 1000

typedef struct {
    uint32_t SRC_IP;
    uint32_t DST_IP;
    uint16_t PORT;
    uint16_t CHECKSUM;
    char PAYLOAD[MAX_PACKET_SIZE];
} PACKET_DATA_T;

typedef struct packet_node {
    PACKET_DATA_T data;
    struct packet_node* next;
} PACKET_NODE_T;

typedef struct {
    PACKET_NODE_T* front;
    PACKET_NODE_T* rear;
    size_t size;
    pthread_mutex_t lock;
} QUEUE_T;

void initQueue(QUEUE_T* queue) {
    queue->front = queue->rear = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

int enqueue(QUEUE_T* queue, PACKET_DATA_T packet) {
    pthread_mutex_lock(&queue->lock);
    PACKET_NODE_T* newNode = (PACKET_NODE_T*)malloc(sizeof(PACKET_NODE_T));
    if (!newNode) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    newNode->data = packet;
    newNode->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }

    queue->size++;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(QUEUE_T* queue, PACKET_DATA_T* packet) {
    pthread_mutex_lock(&queue->lock);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }

    PACKET_NODE_T* temp = queue->front;
    *packet = temp->data;

    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);

    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void destroyQueue(QUEUE_T* queue) {
    PACKET_NODE_T* current = queue->front;
    while (current != NULL) {
        PACKET_NODE_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
}
```

