#define MAX_CONNECTIONS 100

typedef struct {
    int id;
    char ip[16];
    int port;
    int state;
} ConnectionHandler_t;

typedef struct {
    ConnectionHandler_t *handlers[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
} ConnectionManager_t;

void initializeConnectionManager(ConnectionManager_t *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void addConnection(ConnectionManager_t *manager, int id, const char *ip, int port, int state) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_CONNECTIONS) {
        manager->handlers[manager->count] = (ConnectionHandler_t *)malloc(sizeof(ConnectionHandler_t));
        manager->handlers[manager->count]->id = id;
        strcpy(manager->handlers[manager->count]->ip, ip);
        manager->handlers[manager->count]->port = port;
        manager->handlers[manager->count]->state = state;
        manager->count++;
    } else {
        printf("ConnectionManager is full!\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

void freeConnections(ConnectionManager_t *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        free(manager->handlers[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    ConnectionManager_t manager;
    initializeConnectionManager(&manager);

    addConnection(&manager, 1, "192.168.1.1", 5432, ESTABLISHED);
    addConnection(&manager, 2, "10.0.0.1", 1234, TIME_WAIT);
    addConnection(&manager, 3, "172.16.0.1", 8080, CLOSE_WAIT);

    freeConnections(&manager);

    return 0;
}
