#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_MEMORY_POOL_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *blocks[MAX_MEMORY_POOL_SIZE];
    int head;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool) {
    memset(pool, 0, sizeof(*pool));
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->head >= MAX_MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *block = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (block == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pool->blocks[pool->head++] = block;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_to_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *block) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->head; ++i) {
        if (pool->blocks[i] == block) {
            pool->blocks[i] = NULL;
            free(block);
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_ind_pdu_list(int N, MemoryPool *pool) {
    if (N > MAX_MEMORY_POOL_SIZE) {
        printf("Error: Input size exceeds available memory pool capacity.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T **list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list == NULL) {
        printf("Error: Memory allocation failed for list.\n");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *block = allocate_from_pool(pool);
        if (block == NULL) {
            printf("Error: Failed to allocate memory block from pool.\n");
            free(list);
            return NULL;
        }
        list[i] = block;

        // Populate the structure with valid data
        block->RX_UE_INFORMATION_TAG = i;  // Example value
        block->RNTI = i % 1024;  // Example RNTI
        block->CRC_INDICATION_REL8_TAG = rand() % 256;  // Random CRCFLAG

        // Validate data (example check)
        if (block->RNTI > 1023) {
            printf("Warning: Invalid RNTI value encountered.\n");
        }
    }

    return list;
}

void free_nfa_pi_crc_ind_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int N, MemoryPool *pool) {
    for (int i = 0; i < N; ++i) {
        if (list[i] != NULL) {
            free_to_pool(pool, list[i]);
        }
    }
    free(list);
}
