} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_ind_pdu(int n, int max_sessions) {
    static NFAPI_CRC_INDICATION_PDU_T pool[MAX_UE_SESSIONS];
    static int next_index = 0;

    if (n > max_sessions || n <= 0) {
        return NULL; // Invalid request
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = &pool[next_index];
    for (int i = 0; i < n; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % max_sessions;
        pdus[i].RNTI = rand() % 16384; // Valid RNTI range
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
    }

    next_index = (next_index + n) % max_sessions;
    return pdus;
}
