#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define CACHE_SIZE 100

typedef struct {
    char *key;
    void *value;
    time_t expiration;
} CacheEntry_t;

typedef struct {
    CacheEntry_t entries[CACHE_SIZE];
    int head;
    int tail;
    int count;
} Cache_t;

Cache_t *cache_create() {
    Cache_t *cache = (Cache_t *)malloc(sizeof(Cache_t));
    cache->head = -1;
    cache->tail = -1;
    cache->count = 0;
    return cache;
}

void cache_destroy(Cache_t *cache) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        free(cache->entries[i].key);
        free(cache->entries[i].value);
    }
    free(cache);
}

void cache_put(Cache_t *cache, char *key, void *value, time_t expiration) {
    if (cache->count == CACHE_SIZE) {
        // LRU eviction
        int index = cache->head;
        cache->head = (cache->head + 1) % CACHE_SIZE;
        free(cache->entries[index].key);
        free(cache->entries[index].value);
    } else {
        cache->count++;
    }

    CacheEntry_t *entry = &cache->entries[cache->tail];
    entry->key = strdup(key);
    entry->value = value;
    entry->expiration = expiration;
    cache->tail = (cache->tail + 1) % CACHE_SIZE;

    if (cache->count == 1) {
        cache->head = cache->tail;
    }
}

void *cache_get(Cache_t *cache, char *key) {
    for (int i = cache->tail; i != cache->head; i = (i + 1) % CACHE_SIZE) {
        if (strcmp(cache->entries[i].key, key) == 0 && time(NULL) < cache->entries[i].expiration) {
            return cache->entries[i].value;
        }
    }

    return NULL;
}

void cache_remove(Cache_t *cache, char *key) {
    for (int i = cache->tail; i != cache->head; i = (i + 1) % CACHE_SIZE) {
        if (strcmp(cache->entries[i].key, key) == 0) {
            free(cache->entries[i].key);
            free(cache->entries[i].value);
            for (int j = i; j != cache->tail; j = (j + 1) % CACHE_SIZE) {
                cache->entries[j] = cache->entries[(j + 1) % CACHE_SIZE];
            }
            cache->count--;
            return;
        }
    }
}
