}

void deallocateStructs(NFAPI_CRC_INDICATION_PDU_T* structs, int N, MemoryPoolManager* pool) {
    if (!structs || N <= 0 || !pool) {
        return;
    }

    for (int i = 0; i < N; i++) {
        if (structs[i]) {
            pool->deallocate(pool, structs[i]);
        }
    }

    free(structs);
}

void checkMemoryPool(MemoryPoolManager* pool, double reclamationThreshold) {
    if (!pool || reclamationThreshold <= 0.0 || reclamationThreshold >= 1.0) {
        return;
    }

