#include <iostream>
#include <fstream>
#include <string>
#include <openssl/md5.h>

namespace RandomGenerator {
    class RandomService {
        static std::mt19937 generator;
    public:
        RandomService() : generator(std::random_device{}()) {}
        ~RandomService() = default;

        static uint32_t GenerateRandomNumber() {
            return generator();
        }
    };
}

class FileHasher {
public:
    static void HashFile(const std::string& filePath) {
        std::ifstream file(filePath, std::ios::binary);
        if (!file) {
            std::cerr << "Error opening file: " << filePath << std::endl;
            return;
        }

        MD5_CTX md5Context;
        MD5_Init(&md5Context);

        const size_t bufferSize = 4096; // Adjust buffer size as needed
        char buffer[bufferSize];
        while (file.read(buffer, bufferSize)) {
            MD5_Update(&md5Context, buffer, file.gcount());
        }

        if (!file.eof()) {
            std::cerr << "Error reading file: " << filePath << std::endl;
            return;
        }

        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5_Final(hash, &md5Context);

        std::cout << "File: " << filePath << " - Hash: ";
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            printf("%02x", hash[i]);
        }
        std::cout << std::endl;
    }
};

int main() {
    RandomGenerator::RandomService randomService;
    std::this_thread::sleep_for(std::chrono::seconds(RandomGenerator::RandomService::GenerateRandomNumber() % 10));
    FileHasher::HashFile("example.txt");
    return 0;
}
