#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

int allocate_and_initialize(char *hostname, Record **offsets, int **keys, Record **records, int range_start, int range_end) {
    // Allocate memory and initialize arrays
    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1;  // Memory allocation failed
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = range_start + rand() % (range_end - range_start + 1);
        (*records)[i].value = rand();
    }

    return 0;
}

int resolve_dns(const char *hostname, u_char ip_address[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // Free the linked list
        return 0;  // Success
    }

    freeaddrinfo(res);  // Free the linked list if no valid address was found
    return -1;  // No valid address found
}

int main() {
    char *hostname = "example.com";
    Record *offsets, *keys;
    Record *records;
    u_char ip_address[4];

    allocate_and_initialize(hostname, &offsets, &keys, &records, 0, 100);

    int status = resolve_dns(hostname, ip_address);
    if (status == 0) {
        printf("IP address: %d.%d.%d.%d\n", ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    } else {
        printf("DNS resolution failed.\n");
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
