import aioboto3  # For AWS S3 integration
import paramiko  # For SSH connections

async def compute_md5(file_path, storage_system='local', chunk_size=65536):
    if storage_system == 's3':
        s3 = aioboto3.client('s3')
        async with async_open(f's3://{file_path}', mode='rb') as f:
            hash_md5 = hashlib.md5()
            while True:
                data = await f.read(chunk_size)
                if not data:
                    break
                hash_md5.update(data)
            return hash_md5.hexdigest()
    elif storage_system == 'ssh':
        transport = paramiko.SSHClient()
        transport.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        async with async_open(file_path, mode='rb') as f:
            hash_md5 = hashlib.md5()
            while True:
                data = await f.read(chunk_size)
                if not data:
                    break
                hash_md5.update(data)
            return hash_md5.hexdigest()
    else:
        with open(file_path, 'rb') as f:
            hash_md5 = hashlib.md5()
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hash_md5.update(data)
            return hash_md5.hexdigest()

# Example usage
