#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} record;

int allocate_and_initialize_arrays(size_t *offsets, int **keys, record **records, size_t num_records, int range_min, int range_max) {
    offsets = malloc(num_records * sizeof(size_t));
    keys = malloc(num_records * sizeof(int *));
    records = malloc(num_records * sizeof(record *));

    if (!offsets || !keys || !records)
        return -1; // Memory allocation failed

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * 1024;
        keys[i] = malloc(sizeof(int));
        records[i] = malloc(sizeof(record));

        if (!keys[i] || !records[i]) {
            free(offsets);
            for (size_t j = 0; j < i; ++j) {
                free(keys[j]);
                free(records[j]);
            }
            return -1; // Memory allocation failed
        }

        *keys[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    return 0; // Success
}

#include <arpa/inet.h>

int dns_resolve(const char *hostname, u_char ip_address[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; /* Internet address family */
    hints.ai_socktype = SOCK_STREAM; /* Socket type */

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip_address[0] = ipv4->sin_addr.s_addr & 0xFF;
        ip_address[1] = (ipv4->sin_addr.s_addr >> 8) & 0xFF;
        ip_address[2] = (ipv4->sin_addr.s_addr >> 16) & 0xFF;
        ip_address[3] = (ipv4->sin_addr.s_addr >> 24) & 0xFF;
    }

    freeaddrinfo(res);
    return 0; // Success
}
