import hashlib
import os
from abc import ABC, abstractmethod

class FileHasher(ABC):
    @abstractmethod
    def hash_file(self, file_path: str) -> str:
        pass

class MD5FileHasher(FileHasher):
    def hash_file(self, file_path: str) -> str:
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

class StorageSystem(ABC):
    @abstractmethod
    def store(self, file_hash: str) -> None:
        pass

class LocalStorage(StorageSystem):
    def store(self, file_hash: str) -> None:
        with open('file_hashes.txt', 'a') as f:
            f.write(file_hash + '\n')

class CloudStorage(StorageSystem):
    @abstractmethod
    def authenticate(self) -> None:
        pass

class OAuth2CloudStorage(CloudStorage):
    def authenticate(self) -> None:
        # OAuth2 authentication logic here
        pass

class SAMLCloudStorage(CloudStorage):
    @abstractmethod
    def authenticate(self) -> None:
        pass

# Add more storage systems and authentication methods as needed

class ProcessingPipeline:
    def __init__(self, hasher: FileHasher, storage_systems: list[StorageSystem]):
        self.hasher = hasher
        self.storage_systems = storage_systems

    def process_file(self, file_path: str) -> None:
        file_hash = self.hasher.hash_file(file_path)
        for storage in self.storage_systems:
            storage.store(file_hash)

# Usage example
hasher = MD5FileHasher()
storage_systems = [LocalStorage(), OAuth2CloudStorage()]
pipeline = ProcessingPipeline(hasher, storage_systems)
pipeline.process_file('large_file.txt')
```

