#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint8_t *buffer;
    size_t length;
} video_frame;

video_frame* allocate_and_initialize_frames(size_t num_frames, size_t frame_size) {
    video_frame *frames = (video_frame*)malloc(num_frames * sizeof(video_frame));
    if (frames == NULL) return NULL;

    for (size_t i = 0; i < num_frames; i++) {
        frames[i].buffer = (uint8_t*)malloc(frame_size);
        if (frames[i].buffer == NULL) {
            // Handle memory allocation failure
            free(frames);
            return NULL;
        }
        frames[i].length = frame_size;
    }

    return frames;
}

void free_frames(video_frame *frames, size_t num_frames) {
    for (size_t i = 0; i < num_frames; i++) {
        free(frames[i].buffer);
    }
    free(frames);
}
