# Python module code

import av  # FFmpeg binding for Python
from queue import Queue, Full, Empty
from threading import Thread
import time

class VideoProcessor:
    def __init__(self):
        self.input_queue = Queue(maxsize=10)
        self.output_queue = Queue(maxsize=10)
        self.processing_thread = Thread(target=self._process_frames)
        self.processing_thread.start()

    def process_frame(self, frame):
        try:
            self.input_queue.put(frame, timeout=5)
        except Full:
            print("Input queue is full. Dropping frame.")

    def get_output_frame(self):
        try:
            return self.output_queue.get(timeout=5)
        except Empty:
            return None

    def _process_frames(self):
        while True:
            try:
                frame = self.input_queue.get(timeout=1)
                processed_frame = self._decode_frame(frame)
                self.output_queue.put(processed_frame, timeout=5)
            except (Empty, Full):
                pass
            except Exception as e:
                print(f"Error processing frame: {e}")

    def _decode_frame(self, frame):
        try:
            decoded_frame = av.VideoFrame.from_ndarray(frame, format='rgb24')
            return decoded_frame.to_ndarray()
        except Exception as e:
            print(f"Error decoding frame: {e}")
            return None
