class LogEntry:
    def __init__(self, timestamp: time_t, event_id: uint64_t, message: str):
        self.timestamp = timestamp
        self.event_id = event_id
        self.message = message

def parse_log_line(line: str, log_format: str) -> LogEntry:
    if log_format == 'json':
        data = json.loads(line)
        return LogEntry(data['timestamp'], data['event_id'], data['message'])
    elif log_format == 'csv':
        timestamp, event_id, message = csv.reader([line]).__next__()
        return LogEntry(int(timestamp), int(event_id), message)
    else:
        # Custom format parsing logic using regular expressions
        match = re.match(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}), (\d+), (.*)', line)
        if match:
            timestamp, event_id, message = match.groups()
            return LogEntry(datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S').timestamp(), int(event_id), message)
    raise ValueError("Unsupported log format")

def process_log_file(file_path: str, log_format: str) -> List[LogEntry]:
    log_entries = []
    with open(file_path, 'r') as file:
        for line in file:
            entry = parse_log_line(line.strip(), log_format)
            log_entries.append(entry)
    return log_entries

