import time
from collections import OrderedDict
import threading

class CacheEntry:
    def __init__(self, key, value, expire_time):
        self.key = key
        self.value = value
        self.expire_time = expire_time

class DistributedCache:
    def __init__(self, eviction_policy='LRU', max_size=100):
        self.eviction_policy = eviction_policy
        self.max_size = max_size
        self.cache = OrderedDict()
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                entry = self.cache[key]
                if time.time() < entry.expire_time:
                    self.cache.move_to_end(key)
                    return entry.value
                else:
                    del self.cache[key]
            return None

    def set(self, key, value, expire_time=None):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
            if len(self.cache) >= self.max_size:
                if self.eviction_policy == 'LRU':
                    self.cache.popitem(last=False)
                elif self.eviction_policy == 'LFU':
                    least_frequent = min(self.cache.values(), key=lambda x: x['count'])
                    del self.cache[least_frequent['key']]
            if expire_time is not None:
                expire_time += time.time()
            self.cache[key] = CacheEntry(key, value, expire_time)

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]

# Example usage
cache = DistributedCache(eviction_policy='LRU', max_size=5)
cache.set('key1', 'value1')
print(cache.get('key1'))
