# Python module for distributed cache management
import threading
from collections import OrderedDict

class CacheNode:
    def __init__(self):
        self.data = {}
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            return self.data.get(key)

    def set(self, key, value):
        with self.lock:
            self.data[key] = value

    def delete(self, key):
        with self.lock:
            if key in self.data:
                del self.data[key]

class DistributedCache:
    def __init__(self, policy='LRU', nodes=None):
        self.policy = policy
        self.nodes = nodes or []
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            for node in self.nodes:
                value = node.get(key)
                if value is not None:
                    return value
        raise KeyError("Key not found")

    def set(self, key, value):
        with self.lock:
            for node in self.nodes:
                node.set(key, value)

    def delete(self, key):
        with self.lock:
            for node in self.nodes:
                node.delete(key)
