import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class SecureHashService {

    private static final Map<String, byte[]> hashCache = new ConcurrentHashMap<>();
    private static int totalHashComputations = 0;
    private static long totalHashTime = 0;

    public String computeMD5(String input) {
        return computeHash(input, "MD5");
    }

    public String computeSHA256(String input) {
        return computeHash(input, "SHA-256");
    }

    public String computeCustomHash(String input, String algorithm) {
        return computeHash(input, algorithm);
    }

    public String computeMD5(byte[] byteArray) {
        return computeHash(new String(byteArray), "MD5");
    }

    public String computeSHA256(byte[] byteArray) {
        return computeHash(new String(byteArray), "SHA-256");
    }

    public String computeCustomHash(byte[] byteArray, String algorithm) {
        return computeHash(new String(byteArray), algorithm);
    }

    public byte[] hashFile(String filePath, String algorithm) throws IOException {
        try (InputStream inputStream = new FileInputStream(filePath)) {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
            return digest.digest();
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("Unsupported hash algorithm", e);
        }
    }

    public byte[] hashFile(File file, String algorithm) throws IOException {
        return hashFile(file.getAbsolutePath(), algorithm);
    }

    private String computeHash(String input, String algorithm) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        String key = input + "_" + algorithm;
        if (hashCache.containsKey(key)) {
            return bytesToHex(hashCache.get(key));
        }

        long startTime = System.nanoTime();
        byte[] hashBytes = computeHashBytes(input, algorithm);
        totalHashTime += System.nanoTime() - startTime;

        hashCache.put(key, hashBytes);
        totalHashComputations++;

        return bytesToHex(hashBytes);
    }

    private byte[] computeHashBytes(String input, String algorithm) {
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            return digest.digest(input.getBytes());
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Unsupported hash algorithm", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public int getTotalHashComputations() {
        return totalHashComputations;
    }

    public long getTotalHashTime() {
        return totalHashTime;
    }

    // Add unit tests for the methods here
}
