import java.util.concurrent.*;
import org.quartz.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ServiceManager {
    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);
    private Scheduler scheduler;
    private ExecutorService messageBus;

    public ServiceManager() throws SchedulerException, InterruptedException {
        StdSchedulerFactory factory = new StdSchedulerFactory();
        scheduler = factory.getScheduler();
        scheduler.start();

        messageBus = Executors.newFixedThreadPool(100);

        // Example service configuration
        JobDetail job = JobBuilder.newJob(ServiceTask.class)
                .withIdentity("service", "group")
                .build();
        CronTrigger trigger = TriggerBuilder.newTrigger()
                .withIdentity("trigger", "group")
                .withSchedule(CronScheduleBuilder.cronSchedule("* * * * * ?")) // Every second
                .build();

        scheduler.scheduleJob(job, trigger);
    }

    public void addService(String name, String cronExpression) throws SchedulerException {
        JobDetail job = JobBuilder.newJob(ServiceTask.class)
                .withIdentity(name, "group")
                .usingJobData("name", name)
                .build();
        CronTrigger trigger = TriggerBuilder.newTrigger()
                .withIdentity(name, "group")
                .withSchedule(CronScheduleBuilder.cronSchedule(cronExpression))
                .build();

        scheduler.scheduleJob(job, trigger);
    }

    public void adjustSchedule(String serviceName, String newCronExpression) throws SchedulerException {
        JobKey jobKey = new JobKey(serviceName, "group");
        CronTrigger trigger = TriggerBuilder.newTrigger()
                .withIdentity(serviceName, "group")
                .withSchedule(CronScheduleBuilder.cronSchedule(newCronExpression))
                .build();

        scheduler.rescheduleJob(jobKey, trigger);
    }

    public void shutdown() throws SchedulerException {
        scheduler.shutdown();
        messageBus.shutdown();
    }

    public static class ServiceTask implements Job {
        @Override
        public void execute(JobExecutionContext context) throws JobExecutionException {
            String serviceName = context.getJobDetail().getJobDataMap().getString("name");
            // Simulate service start and stop logic
            logger.info("{} is running", serviceName);
        }
    }

    public static void main(String[] args) {
        try {
            ServiceManager manager = new ServiceManager();
            manager.addService("service1", "* * * * * ?");
            // Adjust schedule dynamically
            manager.adjustSchedule("service1", "0 0/15 * * * ?");
            manager.shutdown();
        } catch (Exception e) {
            logger.error("Error in service management", e);
        }
    }
}
```

