#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 5000

typedef struct {
    MAC_RX_DATA_PDU_TAG tag;
    PDCP_SN sn;
    time_t timestamp;
} MAC_RX_DATA_PDU;

typedef struct node {
    MAC_RX_DATA_PDU data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} MAC_RX_LIST;

void init_mac_rx_list(MAC_RX_LIST* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_mac_rx_list(MAC_RX_LIST* list, MAC_RX_DATA_PDU data) {
    if (list->count >= MAX_ENTRIES) {
        return -1; // Error: Maximum entries reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return -2; // Error: Memory allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void print_mac_rx_list(MAC_RX_LIST* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        printf("Tag: %d, SN: %u, Timestamp: %ld\n", 
               current->data.tag, current->data.sn, current->data.timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_mac_rx_list(MAC_RX_LIST* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    MAC_RX_LIST mac_rx_list;
    init_mac_rx_list(&mac_rx_list);

    // Example usage
    for (int i = 0; i < MAX_ENTRIES - 1; i++) {
        MAC_RX_DATA_PDU data = {i, i * 2, time(NULL)};
        add_to_mac_rx_list(&mac_rx_list, data);
    }

    print_mac_rx_list(&mac_rx_list);

    free_mac_rx_list(&mac_rx_list);

    return 0;
}
```

This code provides a basic implementation of a thread-safe linked list for managing MAC_RX_DATA_PDU structures. It includes initialization, adding elements, printing the list, and freeing the memory. The function ensures that no more than 5,000 entries are stored in the list and handles dynamic memory allocation with error checking. The use of pthread_mutex_t for synchronization ensures thread safety when modifying the list.']

