    private int _minValue;
    private int _maxValue;

    public BinaryFileProcessor(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _minValue + (float)(new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        while (true)
        {
            int value = _minValue + new Random().Next(_maxValue - _minValue);
            if (value % 5 == 0)
            {
                return value;
            }
        }
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(double percentage)
    {
        if (percentage <= 0 || percentage >= 1)
        {
            throw new ArgumentOutOfRangeException(nameof(percentage), "Percentage must be between 0 and 1.");
        }
        _minValue = (int)(_minValue + (_maxValue - _minValue) * percentage);
    }

    public void ExpandRange(double percentage)
    {
        if (percentage <= 0 || percentage >= 1)
        {
            throw new ArgumentOutOfRangeException(nameof(percentage), "Percentage must be between 0 and 1.");
        }
        _maxValue = (int)(_maxValue + (_maxValue - _minValue) * percentage);
