    // Allocate initial memory for the array of metrics
    *metrics = (PerformanceMetrics_t *)malloc(initial_size * sizeof(PerformanceMetrics_t));

    if (*metrics == NULL) {
        // Handle memory allocation failure
        return -1; // Return an error code
    }

    // Initialize each structure in the array
    for (int i = 0; i < initial_size; i++) {
        (*metrics)[i].component_id = i + 1;
        (*metrics)[i].cpu_usage = (float)i / initial_size * 100.0;
        (*metrics)[i].memory_consumption = (float)i / initial_size * 500.0;
        (*metrics)[i].disk_io = (float)i / initial_size * 1000.0;
        (*metrics)[i].network_throughput = (float)i / initial_size * 2000.0;
    }

    return 0; // Success
}

// Function to free all allocated memory
void free_logging_framework(PerformanceMetrics_t **metrics, int size) {
    if (*metrics != NULL) {
        free(*metrics);
        *metrics = NULL;
    }
