typedef struct {
    int id;
    double cpu_usage;
    double memory_consumption;
    double disk_io;
    double network_throughput;
} PerformanceMetrics_t;

typedef struct {
    PerformanceMetrics_t* metrics;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PerformanceLogger_t;

PerformanceLogger_t* initPerformanceLogger(size_t initial_capacity) {
    PerformanceLogger_t* logger = malloc(sizeof(PerformanceLogger_t));
    if (!logger) {
        // Handle memory allocation failure
        return NULL;
    }

    logger->metrics = malloc(initial_capacity * sizeof(PerformanceMetrics_t));
    if (!logger->metrics) {
        free(logger);
        // Handle memory allocation failure
        return NULL;
    }

    logger->size = 0;
    logger->capacity = initial_capacity;
    pthread_mutex_init(&logger->lock, NULL);

    return logger;
}

void destroyPerformanceLogger(PerformanceLogger_t* logger) {
    if (logger) {
        free(logger->metrics);
        pthread_mutex_destroy(&logger->lock);
        free(logger);
    }
}

void logMetrics(PerformanceLogger_t* logger, PerformanceMetrics_t metrics) {
    pthread_mutex_lock(&logger->lock);

    if (logger->size >= logger->capacity) {
        size_t new_capacity = logger->capacity * 2;
        PerformanceMetrics_t* new_metrics = realloc(logger->metrics, new_capacity * sizeof(PerformanceMetrics_t));
        if (!new_metrics) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&logger->lock);
            return;
        }

        logger->metrics = new_metrics;
        logger->capacity = new_capacity;
    }

    logger->metrics[logger->size++] = metrics;

    pthread_mutex_unlock(&logger->lock);
}

