using UnityEngine;
using System.Collections.Generic;

public class RandomValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;
    private MemoryPool<float> floatMemoryPool;
    private MemoryPool<int> intMemoryPool;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        floatMemoryPool = new MemoryPool<float>(100); // Initial allocation size
        intMemoryPool = new MemoryPool<int>(100); // Initial allocation size
    }

    public float GetRandomFloat()
    {
        return floatMemoryPool.Get() ?? UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return intMemoryPool.Get() ?? UnityEngine.Random.Range((int)minValue, (int)maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

public class MemoryPool<T>
{
    private Queue<T> pool;
    private Func<T> allocator;

    public MemoryPool(int initialSize)
    {
        pool = new Queue<T>(initialSize);
        allocator = () => (T)Activator.CreateInstance(typeof(T));
    }

    public T Get()
    {
        if (pool.Count > 0)
        {
            return pool.Dequeue();
        }
        else
        {
            try
            {
                return allocator();
            }
            catch
            {
                // Handle memory allocation failure
                return default(T);
            }
        }
    }

    public void Release(T item)
    {
        pool.Enqueue(item);
    }
}
