using System;
using System.Collections.Generic;

public class ValueGenerator
{
    private Dictionary<string, (int Min, int Max)> integerRanges = new Dictionary<string, (int Min, int Max)>();
    private Dictionary<string, (double Min, double Max)> floatRanges = new Dictionary<string, (double Min, double Max)>();

    public void AddIntegerRange(string key, int min, int max)
    {
        if (!integerRanges.ContainsKey(key))
        {
            integerRanges[key] = (min, max);
        }
    }

    public void AddFloatRange(string key, double min, double max)
    {
        if (!floatRanges.ContainsKey(key))
        {
            floatRanges[key] = (min, max);
        }
    }

    public int GenerateIntegerValue(string key)
    {
        if (!integerRanges.ContainsKey(key))
        {
            throw new ArgumentException("Key not found for integer range.");
        }

        var range = integerRanges[key];
        return random.Next(range.Min, range.Max + 1);
    }

    public double GenerateFloatValue(string key)
    {
        if (!floatRanges.ContainsKey(key))
        {
            throw new ArgumentException("Key not found for float range.");
        }

        var range = floatRanges[key];
        return random.NextDouble() * (range.Max - range.Min) + range.Min;
    }

    private Random random = new Random();

    public override string ToString()
    {
        return $"Integer Ranges: {string.Join(", ", integerRanges)}\nFloat Ranges: {string.Join(", ", floatRanges)}";
    }
}
