#include <stdio.h>
#include <stdlib.h>

struct TCP_CONNECTION_INFO {
    char ip_address[16];
    int port_number;
    int connection_state;
    int logging_level;
    int timeout;
};

int allocate_connections(int N, struct TCP_CONNECTION_INFO **connections, int config) {
    *connections = malloc(N * sizeof(struct TCP_CONNECTION_INFO));
    if (*connections == NULL) {
        perror("Memory allocation failed");
        return -1;
    }
    for (int i = 0; i < N; i++) {
        // Initialize each structure based on config
        snprintf((*connections)[i].ip_address, 16, "%d.%d.%d.%d", 
                 rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        (*connections)[i].port_number = rand() % 65535;
        (*connections)[i].connection_state = rand() % 2; // 0 or 1
        (*connections)[i].logging_level = config & 0x0F;
        (*connections)[i].timeout = (config >> 4) * 10;
    }
    return 0;
}

void free_connections(struct TCP_CONNECTION_INFO *connections, int N) {
    free(connections);
}

