#include <iostream>
#include <filesystem>
#include <string>
#include <vector>
#include <regex>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include "log_system.h"

namespace fs = std::filesystem;

struct Options {
    bool help = false;
    bool verbose = false;
    bool summary = false;
    std::string filter = "*.txt";
    std::string output_directory = "";
};

class LineCounter {
public:
    void process(const fs::path& dir, const Options& options);
    void logProgress(int fileCount, int totalFiles);

private:
    static constexpr size_t BATCH_SIZE = 1024;
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::thread> workers;
    std::atomic<int> lineCount{0};
    bool stopProcessing = false;

    void workerThread(const fs::path& dir, const Options& options);
};

void LineCounter::process(const fs::path& dir, const Options& options) {
    // Initialize log system with appropriate level and destinations
    LogSystem log;
    log.setLevel(options.verbose ? LogLevel::DEBUG : LogLevel::INFO);
    log.addDestination("console");
    if (!options.output_directory.empty()) {
        log.addDestination(options.output_directory + "/log.txt");
    }

    workers.reserve(4); // Example: 4 worker threads

    for (size_t i = 0; i < 4; ++i) {
        workers.emplace_back(&LineCounter::workerThread, this, dir, options);
    }

    logProgress(0, std::distance(fs::recursive_directory_iterator(dir), fs::recursive_directory_iterator()));

    cv.notify_all();
    for (auto& w : workers) {
        w.join();
    }

    if (options.summary) {
        log.info("Total lines processed: " + std::to_string(lineCount.load()));
    }
}

void LineCounter::logProgress(int fileCount, int totalFiles) {
    LogSystem::instance().info("Processing files: " + std::to_string(fileCount) + "/" + std::to_string(totalFiles));
}

void LineCounter::workerThread(const fs::path& dir, const Options& options) {
    std::regex filterPattern(options.filter);
    auto it = fs::recursive_directory_iterator(dir);
    while (it != fs::recursive_directory_iterator() && !stopProcessing) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return stopProcessing || !workers.empty(); });
        if (!stopProcessing && workers.empty()) {
            auto entry = it++;
            if (entry.is_regular_file() && regex_match(entry.path().filename(), filterPattern)) {
                int lines = 0;
                std::ifstream file(entry.path());
                if (file) {
                    std::string line;
                    while (std::getline(file, line)) {
                        ++lines;
                    }
                } else {
                    LogSystem::instance().error("Failed to open file: " + entry.path().string());
                }
                lock.unlock();
                std::unique_lock<std::mutex> logLock(mtx);
                lineCount += lines;
            }
        }
    }
}

int main(int argc, char* argv[]) {
    Options options;
    LineCounter counter;

    // Parse command-line arguments
    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "-h" || std::string(argv[i]) == "--help") {
            options.help = true;
        } else if (std::string(argv[i]) == "-v" || std::string(argv[i]) == "--verbose") {
            options.verbose = true;
