        } else if (std::string(argv[i]) == "-f" || std::string(argv[i]) == "--filter") {
            ++i;
            options.filter = argv[i];
        } else if (std::string(argv[i]) == "-o" || std::string(argv[i]) == "--output-directory") {
            ++i;
            options.output_directory = argv[i];
        } else {
            // Assume the first non-option argument is the directory path
            fs::path dir = argv[i];
            counter.process(dir, options);
        }
    }

    if (options.help) {
        std::cout << "Usage: program [OPTIONS] DIRECTORY" << std::endl;
        std::cout << "Options:" << std::endl;
        std::cout << "  -h, --help          Display this help message" << std::endl;
