NFAPI_CRC_INDICATION_PDU_T* create_network_data(uint32_t N, size_t memory_pool_size, float max_fragmentation_threshold, uint64_t reclamation_interval) {
    if (N == 0 || memory_pool_size < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *network_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (network_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

