    for (uint32_t i = 0; i < N; ++i) {
        network_data[i].tcp_info = malloc(sizeof(TCP_CONNECTION_INFO));
        if (network_data[i].tcp_info == NULL) {
            fprintf(stderr, "Memory allocation failed for TCP_CONNECTION_INFO\n");
            // Free previously allocated memory
            while (i > 0) {
                free(network_data[--i].tcp_info);
            }
            free(network_data);
            return NULL;
        }

        network_data[i].ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (network_data[i].ue_info == NULL) {
            fprintf(stderr, "Memory allocation failed for RX_UE_INFORMATION_TAG\n");
            // Free previously allocated memory
            while (i > 0) {
                free(network_data[--i].tcp_info);
                free(network_data[i].ue_info);
            }
            free(network_data);
            return NULL;
        }

        // Initialize RNTI and CRCFLAG randomly or based on system parameters
        network_data[i].ue_info->RNTI = rand() % (MAX_RNTI + 1);
        network_data[i].ue_info->CRCFLAG = rand() % 2;

        if (network_data[i].ue_info->RNTI > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI value\n");
            // Mark structure as uninitialized
            free(network_data[i].tcp_info);
            free(network_data[i].ue_info);
            network_data[i].tcp_info = NULL;
            network_data[i].ue_info = NULL;
        }
    }

    return network_data;
}

