namespace fs = std::filesystem;

std::atomic<int> totalLines(0);
std::mutex logMutex;
std::mutex fileMutex;

void processFile(const fs::path& filePath, bool verbose) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cerr << "Error opening file: " << filePath << std::endl;
        return;
    }

    int lines = 0;
    std::string line;
    while (std::getline(file, line)) {
        ++lines;
    }
    file.close();

    if (verbose) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "Processed file: " << filePath << ", Lines: " << lines << std::endl;
    }

    std::lock_guard<std::mutex> lock(fileMutex);
    totalLines += lines;
}

void processDirectory(const fs::path& dirPath, bool verbose, const std::string& filterPattern) {
    if (!fs::exists(dirPath)) {
        std::cerr << "Directory does not exist: " << dirPath << std::endl;
        return;
    }

    for (const auto& entry : fs::recursive_directory_iterator(dirPath)) {
        if (entry.is_regular_file() && entry.path().extension() == filterPattern) {
            processFile(entry.path(), verbose);
        }
    }
}

int main(int argc, char* argv[]) {
    bool help = false;
    bool verbose = false;
    bool summary = false;
    std::string filterPattern = ".txt";
    fs::path outputDir;
    int numThreads = 4;

    // Parse command line arguments
    for (int i = 1; i < argc; ++i) {
        if (argv[i] == "-h" || argv[i] == "--help") {
            help = true;
        } else if (argv[i] == "-v" || argv[i] == "--verbose") {
            verbose = true;
        } else if (argv[i] == "-s" || argv[i] == "--summary") {
            summary = true;
        } else if (argv[i] == "-f" || argv[i] == "--filter") {
            ++i;
            filterPattern = argv[i];
        } else if (argv[i] == "-o" || argv[i] == "--output-directory") {
            ++i;
            outputDir = argv[i];
        }
    }

    if (help) {
        std::cout << "Usage: program_name [options]\n\n";
        std::cout << "Options:\n";
        std::cout << "  -h, --help\tDisplay help message with usage information.\n";
        std::cout << "  -v, --verbose\tOutput detailed information about each file processed.\n";
        std::cout << "  -s, --summary\tPrint a summary report of the total number of lines found across all files.\n";
        std::cout << "  -f, --filter <pattern>\tSpecify a pattern to filter files based on their names (e.g., *.log).\n";
        std::cout << "  -o, --output-directory <dir>\tSpecify an output directory for processed files.\n";
        return 0;
    }

    fs::path inputDir = argc > 1 ? argv[1] : ".";

    // Process the directory in parallel
    std::vector<std::thread> threads(numThreads);
    int threadIndex = 0;
    for (const auto& entry : fs::recursive_directory_iterator(inputDir)) {
        if (entry.is_regular_file() && entry.path().extension() == filterPattern) {
            threads[threadIndex].join();
            threads[threadIndex] = std::thread(processFile, entry.path(), verbose);
            threadIndex = (threadIndex + 1) % numThreads;
        }
    }
    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }

    if (summary) {
        std::cout << "Total lines processed: " << totalLines << std::endl;
    }

    return 0;
}
