#define MAX_INTERFACES 10

typedef struct {
    int interface_id;
    TCP_CONNECTION_INFO* tcp_connections;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications;
    size_t num_connections;
} NetworkInterface;

NetworkInterface** network_interfaces[MAX_INTERFACES];
size_t current_interface_count = 0;

int allocate_memory_for_interface(size_t N, int interface_id) {
    if (current_interface_count >= MAX_INTERFACES) return -1; // No more interfaces allowed

    NetworkInterface* new_interface = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    if (!new_interface) return -2; // Memory allocation failed

    new_interface->interface_id = interface_id;
    new_interface->tcp_connections = (TCP_CONNECTION_INFO*)calloc(N, sizeof(TCP_CONNECTION_INFO));
    new_interface->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_interface->num_connections = N;

    if (!new_interface->tcp_connections || !new_interface->crc_indications) {
        free(new_interface);
        return -2; // Memory allocation failed
    }

    network_interfaces[current_interface_count] = new_interface;
    current_interface_count++;

    return 0; // Success
}

void deallocate_memory_for_interface(int interface_id) {
    for (size_t i = 0; i < current_interface_count; i++) {
        if (network_interfaces[i]->interface_id == interface_id) {
            free(network_interfaces[i]->tcp_connections);
            free(network_interfaces[i]->crc_indications);
            free(network_interfaces[i]);
            network_interfaces[i] = NULL;
            for (; i < current_interface_count - 1; i++) {
                network_interfaces[i] = network_interfaces[i + 1];
            }
            current_interface_count--;
            break;
        }
    }
}

void log_memory_event(int interface_id, const char* event_type, size_t size) {
    printf("[%s] Interface %d: %s, Size: %zu\n", __TIMESTAMP__, interface_id, event_type, size);
}

int main() {
    // Example usage
    if (allocate_memory_for_interface(1000, 1) == 0) {
        log_memory_event(1, "Allocated", sizeof(TCP_CONNECTION_INFO) * 1000 + sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1000);
    } else {
        printf("Failed to allocate memory for interface 1\n");
    }

    deallocate_memory_for_interface(1);

    return 0;
}
