#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    double cpu_usage;
    double memory_consumption;
    double disk_io;
    double network_throughput;
    // Add more KPIs as needed
} PerformanceMetrics_t;

typedef struct {
    PerformanceMetrics_t *metrics;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PerformanceMonitor_t;

void init_performance_monitor(PerformanceMonitor_t *monitor, size_t initial_capacity) {
    monitor->capacity = initial_capacity;
    monitor->count = 0;
    monitor->metrics = (PerformanceMetrics_t *)malloc(initial_capacity * sizeof(PerformanceMetrics_t));
    if (monitor->metrics == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&monitor->mutex, NULL);
}

void add_metric(PerformanceMonitor_t *monitor, PerformanceMetrics_t metric) {
    pthread_mutex_lock(&monitor->mutex);
    if (monitor->count >= monitor->capacity) {
        size_t new_capacity = monitor->capacity == 0 ? 1 : monitor->capacity * 2;
        PerformanceMetrics_t *new_metrics = realloc(monitor->metrics, new_capacity * sizeof(PerformanceMetrics_t));
        if (new_metrics == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&monitor->mutex);
            exit(EXIT_FAILURE);
        }
        monitor->metrics = new_metrics;
        monitor->capacity = new_capacity;
    }
    monitor->metrics[monitor->count++] = metric;
    pthread_mutex_unlock(&monitor->mutex);
}

void free_performance_monitor(PerformanceMonitor_t *monitor) {
    pthread_mutex_lock(&monitor->mutex);
    free(monitor->metrics);
    pthread_mutex_destroy(&monitor->mutex);
}

int main() {
    PerformanceMonitor_t monitor;
    init_performance_monitor(&monitor, 10);

    // Example usage
    PerformanceMetrics_t metric = {0};
    metric.id = 1;
    metric.cpu_usage = 85.2;
    metric.memory_consumption = 3.4;
    metric.disk_io = 67.8;
    metric.network_throughput = 90.1;

    add_metric(&monitor, metric);

    free_performance_monitor(&monitor);
    return 0;
}
