typedef struct {
    time_t timestamp;
    char service_id[64];
    int log_level;
    char message[256];
    void* metadata;
} LogEntry_t;

typedef struct {
    LogEntry_t** entries;
    size_t capacity;
    size_t count;
} LogSystem_t;

LogSystem_t* create_log_system(size_t initial_capacity) {
    LogSystem_t* system = malloc(sizeof(LogSystem_t));
    if (!system) return NULL;

    system->entries = calloc(initial_capacity, sizeof(LogEntry_t*));
    if (!system->entries) {
        free(system);
        return NULL;
    }

    system->capacity = initial_capacity;
    system->count = 0;

    return system;
}

void destroy_log_system(LogSystem_t* system) {
    for (size_t i = 0; i < system->count; ++i) {
        free(system->entries[i]);
    }
    free(system->entries);
    free(system);
}

int add_log_entry(LogSystem_t* system, LogEntry_t* entry) {
    if (system->count == system->capacity) {
        size_t new_capacity = system->capacity * 2;
        LogEntry_t** new_entries = reallocarray(system->entries, new_capacity, sizeof(LogEntry_t*));
        if (!new_entries) return -1; // Memory allocation failed

        system->entries = new_entries;
        system->capacity = new_capacity;
    }

    system->entries[system->count++] = entry;
    return 0;
}

LogEntry_t* create_log_entry(time_t timestamp, const char* service_id, int log_level, const char* message, void* metadata) {
    LogEntry_t* entry = malloc(sizeof(LogEntry_t));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    strncpy(entry->service_id, service_id, sizeof(entry->service_id) - 1);
    entry->log_level = log_level;
    strncpy(entry->message, message, sizeof(entry->message) - 1);
    entry->metadata = metadata; // Note: Memory management of metadata is left to the caller

    return entry;
}

void free_log_entry(LogEntry_t* entry) {
    if (entry->metadata) free(entry->metadata); // Freeing allocated metadata
    free(entry);
}

// Additional functions for log processing, rotation, and other features can be implemented here

