#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>

// Function to read file, sort lines, and extract sequence number from last line
int processFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    file.close();

    if (lines.empty()) {
        throw std::runtime_error("File is empty");
    }

    std::sort(lines.begin(), lines.end());

    try {
        // Assuming the last line contains a sequence number
        size_t pos = lines.back().find_last_of('0') - 1;
        if (pos == std::string::npos || !isdigit(lines.back()[pos])) {
            throw std::runtime_error("Invalid sequence number format");
        }
        int sequenceNumber = std::stoi(lines.back());
        return sequenceNumber;
    } catch (...) {
        throw std::runtime_error("Error processing sequence number");
    }
}

int main() {
    try {
        int result = processFile("example.txt");
