void derive_keys(const unsigned char* password, size_t password_len, UE_Session* session, int index) {
    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);
    EVP_HKDF_derive(ctx, NULL, 0, (unsigned char*)"hkdf_key", strlen("hkdf_key"),
                    password, password_len, NULL, 0,
                    (unsigned char*)session->iv, EVP_CIPHER_iv_length(session->pdu.cipher));
    EVP_PKEY_derive_init(ctx);
    EVP_PKEY_derive_set_peer(ctx, NULL); // No peer key
    EVP_PKEY_derive_key(ctx, session->session_key, &session_len, sizeof(session->session_key));
    EVP_PKEY_CTX_free(ctx);
}

void encrypt_file(UE_Session* session, const char* input_file, const char* output_file) {
    FILE *in = fopen(input_file, "rb");
    FILE *out = fopen(output_file, "wb");
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len;

    EVP_EncryptInit_ex(ctx, session->pdu.cipher, NULL, session->session_key, session->iv);
    while ((len = fread(input_buffer, 1, sizeof(input_buffer), in)) > 0) {
        EVP_EncryptUpdate(ctx, output_buffer, &len, input_buffer, len);
        fwrite(output_buffer, 1, len, out);
    }
    EVP_EncryptFinal_ex(ctx, output_buffer, &len);
    fwrite(output_buffer, 1, len, out);

    fclose(in);
    fclose(out);
    EVP_CIPHER_CTX_free(ctx);
}

