#include <iostream>
#include <vector>

// Define the state structure for the FSA
struct State {
    int id;
    std::vector<int> transitions; // List of valid next states
};

// Define the FSA structure
struct FiniteStateAutomaton {
    std::vector<State> states;
    int currentStateId;
};

// Function to dynamically allocate memory for a new state list
std::vector<State>* createNewStateList(const State* initialStates, int initialStateCount,
                                        const FiniteStateAutomaton& fsa) {
    std::vector<State>* newStateList = new (std::nothrow) std::vector<State>();
    if (!newStateList) return NULL; // Insufficient memory

    for (int i = 0; i < initialStateCount; ++i) {
        const State& currentState = initialStates[i];
        for (int nextStateId : fsa.states[currentState.id].transitions) {
            newStateList->push_back(fsa.states[nextStateId]);
        }
    }

    return newStateList;
}

// Function to free allocated memory
void cleanup(std::vector<State>* stateList) {
    delete[] stateList;
}

int main() {
    // Example usage
    State initialState = {0, {1, 2}};
    FiniteStateAutomaton fsa = {{initialState, {1, 3}, {4}}, 0};

    std::vector<State>* newStateList = createNewStateList(&initialState, 1, fsa);
    if (newStateList) {
        // Process the new state list
        cleanup(newStateList); // Clean up allocated memory
    }

    return 0;
}
```

