using System;
using System.IO;
using System.Threading.Tasks;

public class FileProcessor : IDisposable
{
    private long _minFileSize;
    private long _maxFileSize;
    private IMonitoringService _monitoringService;

    public FileProcessor(long minFileSize, long maxFileSize, IMonitoringService monitoringService)
    {
        if (minFileSize >= maxFileSize)
            throw new ArgumentException("Min file size must be less than max file size.");

        _minFileSize = minFileSize;
        _maxFileSize = maxFileSize;
        _monitoringService = monitoringService;
    }

    public async Task<(bool Success, string Details)> ProcessFile(string filePath)
    {
        try
        {
            using (var fileInfo = new FileInfo(filePath))
            {
                if (fileInfo.Length < _minFileSize || fileInfo.Length > _maxFileSize)
                    return (false, "File size out of range.");

                var processingResult = await _monitoringService.ProcessFileAsync(fileInfo);
                return processingResult;
            }
        }
        catch (Exception ex)
        {
            // Log error locally if monitoring service is unavailable
            Console.WriteLine($"Error processing file: {ex.Message}");
            return (false, "Failed to process file.");
        }
    }

    public void ShrinkRange(long newMinFileSize, long newMaxFileSize)
    {
        if (newMinFileSize >= newMaxFileSize || newMinFileSize < _minFileSize || newMaxFileSize > _maxFileSize)
            throw new ArgumentException("Invalid range specified.");

        _minFileSize = newMinFileSize;
        _maxFileSize = newMaxFileSize;
    }

    public void ExpandRange(long newMinFileSize, long newMaxFileSize)
    {
        if (newMinFileSize <= _minFileSize || newMaxFileSize >= _maxFileSize)
            throw new ArgumentException("Invalid range specified.");

        _minFileSize = newMinFileSize;
        _maxFileSize = newMaxFileSize;
    }

    public void Dispose()
    {
        // Dispose resources if necessary
    }
}

public interface IMonitoringService
{
    Task<(bool Success, string Details)> ProcessFileAsync(FileInfo fileInfo);
}
