const crypto = require('crypto');
const fs = require('fs');
const util = require('util');

// Define constants
const BATCH_SIZE = 100;
const LOG_FILE_PATH = 'logs.txt';

// Define regex patterns for book names
const BOOK_PATTERN = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Moses|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Songs|Isaiah |Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;

// Define function to process text and count book occurrences
async function processText(text) {
  let books = {};
  try {
    const matches = text.match(BOOK_PATTERN);
    if (matches) {
      for (let match of matches) {
        books[match] = (books[match] || 0) + 1;
      }
    }
    logActivity({ timestamp: Date.now(), inputSize: text.length, matchedBooks: Object.keys(books).length });
  } catch (error) {
    logError(error);
  }
  return books;
}

// Define function to compute MD5 hash of input text
function computeHash(text) {
  return crypto.createHash('md5').update(text).digest('hex');
}

// Define function to log activity
async function logActivity(activity) {
  const logEntry = `${util.format(new Date(), 'YYYY-MM-DD HH:mm:ss')}: ${JSON.stringify(activity)}\n`;
  await fs.promises.appendFile(LOG_FILE_PATH, logEntry);
}

// Define function to log error
async function logError(error) {
  const logEntry = `${util.format(new Date(), 'YYYY-MM-DD HH:mm:ss')}: ERROR - ${error.message}\n`;
  await fs.promises.appendFile(LOG_FILE_PATH, logEntry);
}

// Export module functions
module.exports = {
  processText,
  computeHash,
};
