#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    int id;
    char peer_address[16];
    int port_number;
    unsigned char *bytes_exchanged;
    size_t bytes_count;
    pthread_mutex_t mutex;
} TCPConnection;

TCPConnection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t global_mutex;

int allocate_connection(int id, const char *peer_address, int port_number) {
    pthread_mutex_lock(&global_mutex);
    if (connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&global_mutex);
        return -1; // No more connections available
    }
    TCPConnection *new_conn = &connections[connection_count++];
    new_conn->id = id;
    strncpy(new_conn->peer_address, peer_address, sizeof(new_conn->peer_address));
    new_conn->port_number = port_number;
    new_conn->bytes_exchanged = malloc(1024); // Example buffer size
    if (!new_conn->bytes_exchanged) {
        connection_count--;
        pthread_mutex_unlock(&global_mutex);
        return -2; // Memory allocation failed
    }
    new_conn->bytes_count = 0;
    pthread_mutex_init(&new_conn->mutex, NULL);
    pthread_mutex_unlock(&global_mutex);
    return 0;
}

void free_connection(int id) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            pthread_mutex_destroy(&connections[i].mutex);
            free(connections[i].bytes_exchanged);
            memmove(&connections[i], &connections[i + 1], sizeof(TCPConnection) * (connection_count - i - 1));
            connection_count--;
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void update_connection_bytes(int id, unsigned char *new_bytes, size_t new_size) {
    TCPConnection *conn = NULL;
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            conn = &connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);

    if (!conn || !new_bytes || new_size == 0) return;

    pthread_mutex_lock(&conn->mutex);
    free(conn->bytes_exchanged);
    conn->bytes_exchanged = malloc(new_size);
    if (conn->bytes_exchanged) {
        memcpy(conn->bytes_exchanged, new_bytes, new_size);
        conn->bytes_count = new_size;
    }
    pthread_mutex_unlock(&conn->mutex);
}

void *connection_manager_thread(void *arg) {
    int id = *(int *)arg;
    free(arg);

    // Simulate some work with the connection
    sleep(1); // Example: simulate time-consuming network operation

    // Clean up after work is done
    free_connection(id);

    return NULL;
}

void manage_connections(int N) {
    pthread_t threads[N];
    int *ids = malloc(N * sizeof(int));
    if (!ids) return;

    for (int i = 0; i < N; i++) {
        ids[i] = allocate_connection(i, "127.0.0.1", 80);
        if (ids[i] == 0) {
            pthread_create(&threads[i], NULL, connection_manager_thread, &ids[i]);
        } else {
            free(ids[i]); // Cleanup on error
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(ids);
}
```

This code snippet demonstrates a basic implementation of managing TCP connections with thread safety and memory allocation. It includes functions to allocate, update, and free connection states, as well as a simple thread management function that simulates work for each connection and cleans up afterward. The code uses mutexes to ensure thread safety and includes error handling for memory allocation failures.']

