namespace fs = std::filesystem;

class FileProcessor {
public:
    FileProcessor(const fs::path& inputDir, const fs::path& outputDir, bool verbose, bool summary, const std::string& filter, bool compress, bool dryRun)
        : m_inputDir(inputDir), m_outputDir(outputDir), m_verbose(verbose), m_summary(summary), m_filter(filter), m_compress(compress), m_dryRun(dryRun) {}

    void process() {
        m_lineCount = 0;
        m_totalFilesProcessed = 0;

        if (m_verbose) std::cout << "Starting file processing..." << std::endl;

        for (const auto& entry : fs::recursive_directory_iterator(m_inputDir)) {
            if (entry.is_regular_file()) {
                processFile(entry.path());
            }
        }

        if (m_summary) std::cout << "Total lines processed: " << m_lineCount << std::endl;
    }

private:
    void processFile(const fs::path& filePath) {
        if (!matchesFilter(filePath)) return;

        if (m_verbose) std::cout << "Processing file: " << filePath << std::endl;

        std::ifstream file(filePath);
        int lineCount = 0;
        std::string line;
        while (std::getline(file, line)) {
            ++lineCount;
        }

        m_lineCount += lineCount;
        ++m_totalFilesProcessed;

        if (!m_dryRun) {
            fs::path outputPath = m_outputDir / (filePath.filename().stem() + "_" + std::to_string(m_totalFilesProcessed) + ".txt");
            std::ofstream outputFile(outputPath);
            outputFile << file.rdbuf();
        }

        if (m_verbose) std::cout << "Processed lines: " << lineCount << std::endl;
    }

    bool matchesFilter(const fs::path& filePath) {
        return m_filter.empty() || filePath.filename().string().find(m_filter) != std::string::npos;
    }

    fs::path m_inputDir;
    fs::path m_outputDir;
    bool m_verbose;
    bool m_summary;
    std::string m_filter;
    bool m_compress;
    bool m_dryRun;
    int m_lineCount;
    size_t m_totalFilesProcessed;
};

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    FileProcessor processor(/* parse arguments here */);
    processor.process();
    return 0;
}
