namespace fs = std::filesystem;

struct FileData {
    fs::path path;
    size_t lineCount;
};

std::mutex queueMutex;
std::condition_variable notEmpty;
std::queue<FileData> fileQueue;
bool done = false;

void processFile(const FileData& data, bool verbose) {
    std::ifstream file(data.path);
    if (file.is_open()) {
        if (verbose) {
            std::cout << "Processing file: " << data.path << std::endl;
        }
        size_t lineCount = 0;
        std::string line;
        while (std::getline(file, line)) {
            ++lineCount;
        }
        if (verbose) {
            std::cout << "File processed. Line count: " << lineCount << std::endl;
        }
        file.close();
        // Simulate processing by updating the line count
        data.lineCount = lineCount;
    } else {
        std::cerr << "Error opening file: " << data.path << std::endl;
    }
}

void worker(bool verbose) {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        notEmpty.wait(lock, []{ return !fileQueue.empty() || done; });
        if (done && fileQueue.empty()) {
            break;
        }
        FileData data = fileQueue.front();
        fileQueue.pop();
        lock.unlock();

        processFile(data, verbose);
    }
}

void traverseDirectory(const fs::path& dirPath, bool verbose) {
    for (const auto& entry : fs::recursive_directory_iterator(dirPath)) {
        if (entry.is_regular_file() && entry.path().extension() == ".txt") {
            fileQueue.push({entry.path(), 0});
            notEmpty.notify_one();
        }
    }
}

