        std::cout << "  -f, --filter pattern Specify a pattern to filter files based on their names (e.g., *.log, *.txt)" << std::endl;
        std::cout << "  -o, --output-directory Specify an output directory to save processed files with a modified timestamp appended to their filenames" << std::endl;
        std::cout << "  -c, --compress      Compress the processed files into a single ZIP archive after processing, with the archive filename generated based on the current date and time" << std::endl;
        std::cout << "  -d, --dry-run       Simulate the processing without making any changes to the filesystem" << std::endl;
        return 0;
    }

    if (argc <= 1) {
        std::cerr << "No input directory specified." << std::endl;
        return 1;
    }

    fs::path dirPath = argv[1];
    if (!fs::exists(dirPath)) {
        std::cerr << "Directory does not exist: " << dirPath << std::endl;
        return 1;
    }

    if (dryRun) {
        std::cout << "Dry-run mode enabled. No changes will be made to the filesystem." << std::endl;
    }

    std::vector<std::thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(worker, verbose);
    }

    traverseDirectory(dirPath, verbose);

    done = true;
    notEmpty.notify_all();

    for (auto& thread : workers) {
        thread.join();
    }

    if (summary) {
        size_t totalLines = 0;
        while (!fileQueue.empty()) {
            FileData data = fileQueue.front();
            fileQueue.pop();
            totalLines += data.lineCount;
        }
        std::cout << "Total number of lines: " << totalLines << std::endl;
    }

    if (compress) {
        std::vector<std::string> processedFiles;
        // Collect processed files
        while (!fileQueue.empty()) {
            FileData data = fileQueue.front();
            fileQueue.pop();
            processedFiles.push_back(data.path.string());
        }
        compressFiles(outputDir, processedFiles);
    }

    return 0;
}
