#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct MEDIA_PACKET_T {
    int STREAM_ID;
    char MEDIA_TYPE[50];
    char SOURCE_URL[256];
    char DESTINATION_URI[256];
    long PACKET_TIMESTAMP;
} MEDIA_PACKET_T;

typedef struct QUEUE_NODE_T {
    MEDIA_PACKET_T packet;
    struct QUEUE_NODE_T *next;
} QUEUE_NODE_T;

typedef struct STREAM_QUEUE_T {
    QUEUE_NODE_T *front;
    QUEUE_NODE_T *rear;
    int size;
    sem_t semaphore;
    pthread_mutex_t mutex;
    int max_size;
    int max_concurrent;
} STREAM_QUEUE_T;

void initQueue(STREAM_QUEUE_T *queue, int max_size, int max_concurrent) {
    queue->front = queue->rear = NULL;
    queue->size = 0;
    sem_init(&queue->semaphore, 0, max_concurrent);
    pthread_mutex_init(&queue->mutex, NULL);
    queue->max_size = max_size;
    queue->max_concurrent = max_concurrent;
}

int enqueue(STREAM_QUEUE_T *queue, MEDIA_PACKET_T packet) {
    if (sem_wait(&queue->semaphore) != 0) return -1; // Block if necessary
    pthread_mutex_lock(&queue->mutex);
    if (queue->size >= queue->max_size) {
        pthread_mutex_unlock(&queue->mutex);
        sem_post(&queue->semaphore);
        return -2;
    }
    QUEUE_NODE_T *new_node = (QUEUE_NODE_T *)malloc(sizeof(QUEUE_NODE_T));
    new_node->packet = packet;
    new_node->next = NULL;
    if (queue->rear != NULL) {
        queue->rear->next = new_node;
    } else {
        queue->front = new_node;
    }
    queue->rear = new_node;
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);
    return 0;
}

int dequeue(STREAM_QUEUE_T *queue, MEDIA_PACKET_T *packet) {
    if (sem_wait(&queue->semaphore) != 0) return -1; // Block if necessary
    pthread_mutex_lock(&queue->mutex);
    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        sem_post(&queue->semaphore);
        return -2;
    }
    QUEUE_NODE_T *temp = queue->front;
    *packet = temp->packet;
    queue->front = temp->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->semaphore);
    return 0;
}

void destroyQueue(STREAM_QUEUE_T *queue) {
    while (queue->front != NULL) {
        QUEUE_NODE_T *temp = queue->front;
        queue->front = temp->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->mutex);
    sem_destroy(&queue->semaphore);
}
```

This code provides a basic implementation of a thread-safe, lock-free FIFO queue for streaming media packets. It includes functions to initialize the queue, enqueue and dequeue packets, and destroy the queue when it is no longer needed. The use of `sem_t` and `pthread_mutex_t` ensures that the operations are both thread-safe and efficient under high load conditions.']

