std::string calculate_md5_hash(const std::string& file_path, size_t chunk_size) {
    std::ifstream file(file_path, std::ios_base::binary);
    if (!file) {
        throw std::runtime_error("Error opening file: " + file_path);
    }

    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[chunk_size];
    while (file.read(buffer, chunk_size)) {
        MD5_Update(&md5, buffer, static_cast<unsigned int>(file.gcount()));
    }
    if (!file.eof()) {
        throw std::runtime_error("Error reading file: " + file_path);
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_Final(hash, &md5);

    // Convert hash to hexadecimal string
    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }

    return ss.str();
}

void* allocate_octree(size_t feature_size, size_t num_leaf_nodes, size_t& capacity) {
    size_t required_capacity = calculate_octree_memory_requirement(feature_size, num_leaf_nodes);
    if (required_capacity > capacity) {
        deallocate_memory(capacity, "Octree Capacity");
        capacity = required_capacity;
        allocate_memory(capacity, "Octree Capacity");
    }
    void* octree_ptr = allocate_memory(get_octree_size(), "Octree Data Structure");
    return octree_ptr;
}

void initialize_octree(OCTREE_T& octree, size_t feature_size, size_t num_leaf_nodes) {
    static std::mutex mutex;
    std::lock_guard<std::mutex> lock(mutex);

    octree.feature_size = feature_size;
    octree.num_leaf_nodes = num_leaf_nodes;

    if (octree.capacity < calculate_octree_memory_requirement(feature_size, num_leaf_nodes)) {
        deallocate_memory(octree.prefix_leafs, "Prefix Leafs");
        deallocate_memory(octree.data_array, "Data Array");

        octree.capacity = calculate_octree_memory_requirement(feature_size, num_leaf_nodes);
        octree.prefix_leafs = static_cast<uint8_t*>(allocate_memory(octree.capacity * sizeof(uint8_t), "Prefix Leafs"));
        octree.data_array = static_cast<void**>(allocate_memory(octree.capacity * sizeof(void*), "Data Array"));
    }

    // Initialize octree structure here
}

void* allocate_and_populate_data(size_t size, size_t& capacity) {
    if (size > capacity) {
        deallocate_memory(capacity, "Data Capacity");
        capacity = size;
        allocate_memory(capacity, "Data Capacity");
    }
    void* data_ptr = allocate_memory(get_data_size(), "Data Array");
    // Populate data array here
    return data_ptr;
}

void run_file_hashing_async(const std::string& file_path, size_t chunk_size) {
    std::thread hash_thread([file_path, chunk_size]() {
        try {
            std::cout << "Hashing file: " << file_path << std::endl;
            std::string hash = calculate_md5_hash(file_path, chunk_size);
            std::cout << "MD5 Hash: " << hash << std::endl;
        } catch (const std::exception& e) {
            std::cerr << "Error during MD5 calculation: " << e.what() << std::endl;
        }
    });
    hash_thread.detach();
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " feature_size num_leaf_nodes data_capacity file_path chunk_size" << std::endl;
        return 1;
    }

    size_t feature_size = static_cast<size_t>(std::atoi(argv[1]));
    size_t num_leaf_nodes = static_cast<size_t>(std::atoi(argv[2]));
    size_t data_capacity = static_cast<size_t>(std::atoi(argv[3]));
    std::string file_path = argv[4];
    size_t chunk_size = static_cast<size_t>(std::atoi(argv[5]));

    OCTREE_T octree;
    initialize_octree(octree, feature_size, num_leaf_nodes);

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = allocate_and_populate_crc_indications(100, 200);

