    void* octree_data = allocate_octree(feature_size, num_leaf_nodes, data_capacity_octree);

    run_file_hashing_async(file_path, chunk_size);

    // Clean up allocations
    deallocate_memory(crc_indications, "CRC Indications");
    deallocate_memory(octree_data, "Octree Data Structure");

    return 0;
}
