// Define packet structure
typedef struct {
    char* data;
    int length;
} Packet;

// Define queue structure
typedef struct {
    Packet** packets;
    int front, rear, size, capacity;
} Queue;

Queue* createQueue(int capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->capacity = capacity;
    q->front = 0;
    q->rear = -1;
    q->size = 0;
    q->packets = (Packet**)malloc(capacity * sizeof(Packet*));
    return q;
}

void enqueue(Queue* q, Packet* packet) {
    if (q->size == q->capacity) {
        printf("Queue is full. Dropped packet.\n");
        free(packet);
    } else {
        q->rear = (q->rear + 1) % q->capacity;
        q->packets[q->rear] = packet;
        q->size++;
    }
}

Packet* dequeue(Queue* q) {
    if (q->size == 0) {
        printf("Queue is empty.\n");
        return NULL;
    } else {
        Packet* packet = q->packets[q->front];
        q->front = (q->front + 1) % q->capacity;
        q->size--;
        return packet;
    }
}

void destroyQueue(Queue* q) {
    while (!isEmpty(q)) {
        free(dequeue(q));
    }
    free(q->packets);
    free(q);
}

int isEmpty(Queue* q) {
    return q->size == 0;
}

// Function to process and queue network packets
void processAndQueueNetworkPackets(int M, Packet** packets, int packetCount) {
    Queue* queue = createQueue(M);

    for (int i = 0; i < packetCount; i++) {
        if (isValidPacket(packets[i])) {
            enqueue(queue, packets[i]);
        } else {
            printf("Invalid packet. Dropped.\n");
            free(packets[i]);
        }
    }

    // Process packets in the queue
    while (!isEmpty(queue)) {
        Packet* packet = dequeue(queue);
        if (processPacket(packet)) {
            free(packet->data);
            free(packet);
        } else {
            printf("Packet processing failed. Retrying...\n");
            enqueue(queue, packet);  // Retry enqueuing failed packet
        }
    }

    destroyQueue(queue);
}

// Dummy function to validate a packet
int isValidPacket(Packet* packet) {
    return packet->length > 0;
}

// Dummy function to process a packet
int processPacket(Packet* packet) {
    // Simulate processing logic
