#include <stdio.h>
#include <stdlib.h>

#define MAX_INT 9223372036854775807
#define MIN_INT -9223372036854775808

int readIntegers(int **array) {
    int *tempArray = (int *)malloc(1000 * sizeof(int)); // Initial allocation for 1000 elements
    if (!tempArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    int count = 0;
    char ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {
        if (ch >= '0' && ch <= '9') {
            ungetc(ch, stdin); // Put back the digit to be read by scanf
            int value;
            scanf("%d", &value);
            if (value < MIN_INT || value > MAX_INT) {
                fprintf(stderr, "Integer out of range\n");
                continue;
            }
            tempArray[count++] = value;
        } else if (ch == '-' && count > 0 && tempArray[count - 1] == 0) {
            ungetc(ch, stdin); // Put back the negative sign to be read by scanf
            int value;
            scanf("%d", &value);
            if (value < MIN_INT || value > MAX_INT) {
                fprintf(stderr, "Integer out of range\n");
                continue;
            }
            tempArray[count++] = value;
        }
    }

    *array = realloc(tempArray, count * sizeof(int)); // Resize array to fit actual data
    if (!*array) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    return count;
}

int findLargest(int *array, int count) {
    int max = MIN_INT;
    for (int i = 0; i < count; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void freeArray(int *array) {
    free(array);
}

int main() {
    int *array;
    int count = readIntegers(&array);

    if (count == 0) {
        printf("No valid integers found\n");
        return 1;
    }

    int largest = findLargest(array, count);
    printf("The largest integer is: %d\n", largest);

    freeArray(array);
    return 0;
}
