import java.util.List;
import java.util.concurrent.CompletableFuture;

public class PokemonReportGenerator {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/";

    public CompletableFuture<String> generateReports(List<Pokemon> pokemonList) {
        return CompletableFuture.allOf(pokemonList.stream()
                .map(this::generateReportAsync)
                .toArray(CompletableFuture[]::new))
                .thenApply(v -> "All reports generated successfully");
    }

    private CompletableFuture<String> generateReportAsync(Pokemon pokemon) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                String name = getPokemonName(pokemon.getId());
                String type = getPokemonType(pokemon.getId());
