CipherObject* encrypt_data(const char* domain, const char* encryption_option) {
    // Initialize OpenSSL library
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Resolve DNS and get IP address
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(domain, NULL, &hints, &res) != 0) {
        return NULL; // Handle DNS resolution error
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    u_char ip[4];
    memcpy(ip, &(ipv4->sin_addr), 4);

    // Allocate memory for cipher object
    CipherObject* cipher_obj = (CipherObject*)malloc(sizeof(CipherObject));
    if (!cipher_obj) {
        freeaddrinfo(res);
        return NULL; // Handle memory allocation error
    }

    // Initialize encryption context
    cipher_obj->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_obj->ctx) {
        freeaddrinfo(res);
        free(cipher_obj);
        return NULL; // Handle OpenSSL initialization error
    }

    // Set up key and IV (for demonstration purposes, using random values)
    if (!RAND_bytes(cipher_obj->key, sizeof(cipher_obj->key)) ||
        !RAND_bytes(cipher_obj->iv, sizeof(cipher_obj->iv))) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        freeaddrinfo(res);
        free(cipher_obj);
        return NULL; // Handle random number generation error
    }

    // Initialize encryption with the specified option
    if (EVP_EncryptInit_ex(cipher_obj->ctx, EVP_aes_256_cbc(), NULL, cipher_obj->key, cipher_obj->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        freeaddrinfo(res);
        free(cipher_obj);
        return NULL; // Handle encryption initialization error
    }

    // Add DNS resolution and encryption logic here

    // Free resources
    freeaddrinfo(res);

    return cipher_obj;
}
