import hashlib

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(65536)  # read in 64K chunks
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

