#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_RESOURCES 10

typedef struct {
    sem_t resourceSemaphore;
    int availableResources;
    pthread_mutex_t usageMutex;
    int totalRequests;
    int successfulRequests;
    int deniedRequests;
} ResourcePool;

void initializeResourcePool(ResourcePool *pool, int initialResources) {
    pool->availableResources = initialResources;
    sem_init(&pool->resourceSemaphore, 0, initialResources);
    pthread_mutex_init(&pool->usageMutex, NULL);
    pool->totalRequests = 0;
    pool->successfulRequests = 0;
    pool->deniedRequests = 0;
}

int acquireResource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->usageMutex);
    pool->totalRequests++;
    if (sem_wait(&pool->resourceSemaphore) == -1) {
        pthread_mutex_unlock(&pool->usageMutex);
        return -1; // Failed to acquire resource
    }
    pool->availableResources--;
    pool->successfulRequests++;
    pthread_mutex_unlock(&pool->usageMutex);
    return 0;
}

void releaseResource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->usageMutex);
    if (sem_post(&pool->resourceSemaphore) == -1) {
        printf("Failed to release resource\n");
        return;
    }
    pool->availableResources++;
    pthread_mutex_unlock(&pool->usageMutex);
}

void printResourceUsageStatistics(ResourcePool *pool) {
    pthread_mutex_lock(&pool->usageMutex);
    printf("Total Requests: %d, Successful Requests: %d, Denied Requests: %d\n",
           pool->totalRequests, pool->successfulRequests, pool->deniedRequests);
    pthread_mutex_unlock(&pool->usageMutex);
}

int main() {
    ResourcePool pool;
    initializeResourcePool(&pool, MAX_RESOURCES);

    pthread_t threads[MAX_RESOURCES];
    for (int i = 0; i < MAX_RESOURCES; i++) {
        pthread_create(&threads[i], NULL, acquireResource, &pool);
    }

    for (int i = 0; i < MAX_RESOURCES; i++) {
        pthread_join(threads[i], NULL);
    }

    printResourceUsageStatistics(&pool);

    sem_destroy(&pool.resourceSemaphore);
    pthread_mutex_destroy(&pool.usageMutex);

    return 0;
}
