using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Threading.Tasks;

public class DatabaseQueryExecutor
{
    private static readonly int DefaultMaxConcurrentConnections = 10;
    private static readonly int DefaultRetryAttempts = 3;
    private static readonly TimeSpan ConnectionTimeout = TimeSpan.FromSeconds(30);

    public async Task<List<Task<IDataReader>>> ExecuteQueriesAsync(
        List<string> sqlCommands,
        string connectionString,
        int timeout,
        int maxConcurrentConnections = DefaultMaxConcurrentConnections)
    {
        var tasks = new List<Task<IDataReader>>();
        var semaphoreSlim = new SemaphoreSlim(maxConcurrentConnections);

        foreach (var sqlCommand in sqlCommands)
        {
            await semaphoreSlim.WaitAsync();
            tasks.Add(Task.Run(async () =>
            {
                try
                {
                    using (var connection = CreateConnection(connectionString, timeout))
                    {
                        connection.Open();
                        for (int attempt = 0; attempt < DefaultRetryAttempts; attempt++)
                        {
                            try
                            {
                                var command = new SqlCommand(sqlCommand, connection);
                                command.CommandTimeout = timeout;
                                LogExecutionStatus($"Executing query: {sqlCommand}");
                                return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
                            }
                            catch (Exception ex)
                            {
                                if (attempt == DefaultRetryAttempts - 1)
                                {
                                    LogError($"Failed to execute query after {DefaultRetryAttempts} attempts: {ex.Message}");
                                    throw;
                                }
                                await Task.Delay(100); // Wait before retrying
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    LogError($"An error occurred while executing the query: {ex.Message}");
                    return null;
                }
                finally
                {
                    semaphoreSlim.Release();
                }
            }));
        }

        await Task.WhenAll(tasks);
        return tasks;
    }

    private DbConnection CreateConnection(string connectionString, int timeout)
    {
        var connection = new SqlConnection(connectionString);
        connection.ConnectionTimeout = timeout;
        return connection;
    }

    private void LogExecutionStatus(string message)
    {
        Console.WriteLine($"[INFO] {DateTime.Now}: {message}");
    }

    private void LogError(string message)
    {
        Console.WriteLine($"[ERROR] {DateTime.Now}: {message}");
