import redis
import time

app = Flask(__name__)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

SESSION_TIMEOUT = 3600  # 1 hour in seconds
CACHE_EXPIRY = 60  # 1 minute in seconds

def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        session_token = request.headers.get('Authorization')
        if not session_token or not redis_client.exists(session_token):
            return jsonify({"error": "Unauthorized"}), 401
        return f(*args, **kwargs)
    return decorated_function

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')
    # Validate credentials and obtain user ID from authentication system or third-party API
    user_id = authenticate_user(username, password)
    if not user_id:
        return jsonify({"error": "Invalid credentials"}), 403

    session_token = str(time.time()) + '-' + str(user_id)
    redis_client.setex(session_token, SESSION_TIMEOUT, 'active')
    return jsonify({'session_token': session_token}), 200

@app.route('/logout', methods=['POST'])
@login_required
def logout():
    session_token = request.headers.get('Authorization')
    redis_client.delete(session_token)
