const fs = require('fs').promises;
const path = require('path');
const crypto = require('crypto');

class FileCache {
  constructor() {
    this.cache = new Map();
    this.locks = new Map();
  }

  async readFile(filePath) {
    const key = crypto.createHash('sha256').update(filePath).digest('hex');

    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    let lock;
    if (!this.locks.has(key)) {
      lock = this.locks.set(key, new Promise(async resolve => {
        while (this.cache.has(key)) await resolve();
      }));
    } else {
      lock = this.locks.get(key);
    }

    try {
      await lock;

      if (this.cache.has(key)) {
        return this.cache.get(key);
      }

      const content = await fs.readFile(filePath, 'utf8');
      this.cache.set(key, content);

      if (!this.locks.has(key)) {
        throw new Error('Lock not found');
      }

      this.locks.delete(key);

      return content;
    } catch (error) {
      console.error(`Error reading file: ${filePath}`, error);
      throw error;
    }
  }

  async updateFile(filePath, newContent) {
    const key = crypto.createHash('sha256').update(filePath).digest('hex');

    if (!this.cache.has(key)) {
      this.cache.set(key, newContent);
      return;
    }

    let lock;
    if (!this.locks.has(key)) {
      lock = this.locks.set(key, new Promise(async resolve => {
        while (this.cache.has(key)) await resolve();
      }));
    } else {
      lock = this.locks.get(key);
    }

    try {
      await lock;

      if (!this.locks.has(key)) {
        throw new Error('Lock not found');
      }

      this.locks.delete(key);

      this.cache.set(key, newContent);
    } catch (error) {
      console.error(`Error updating file: ${filePath}`, error);
      throw error;
    }
  }

  invalidateCache(filePath) {
    const key = crypto.createHash('sha256').update(filePath).digest('hex');

    if (this.cache.has(key)) {
      this.cache.delete(key);
    }
  }
}

const fileCache = new FileCache();

async function readFileAsync(filePath, externalMetadataService) {
  try {
    // Validate file path
    if (!path.isAbsolute(filePath)) {
      throw new Error('File path must be absolute');
    }

    // Fetch file attributes from external metadata service
    const fileAttributes = await externalMetadataService.getFileAttributes(filePath);

    // Invalidate cache if necessary
    if (fileCache.cache.has(fileAttributes.key) && fileAttributes.modified !== fileCache.cache.get(fileAttributes.key).modified) {
      fileCache.invalidateCache(fileAttributes.key);
    }

    // Read file content from cache or disk
    const content = await fileCache.readFile(filePath);

    return content;
  } catch (error) {
    console.error('Error reading file:', error);
    throw error;
  }
}

// Example usage:
const externalMetadataService = {
  getFileAttributes: async filePath => {
    // Simulate fetching file attributes from external service
    const stats = await fs.stat(filePath);
    return { key: crypto.createHash('sha256').update(filePath).digest('hex'), modified: stats.mtimeMs };
  }
};

readFileAsync('/path/to/file.txt', externalMetadataService)
  .then(content => console.log(content))
  .catch(error => console.error(error));
```

