function processBibleReferences(text, language = 'English') {
    const bookRegexes = {
        English: [
            /Genesis/i,
            /Exodus/i,
            // Add more book regexes here
        ],
        French: [
            /Genèse/i,
            /Éxode/i,
            // Add more book regexes here
        ]
    };

    const frequency = {};
    const firstOccurrences = [];
    const verses = {};

    let bookRegex;
    if (language === 'English') {
        bookRegex = new RegExp(bookRegexes.English.join('|'), 'gi');
    } else if (language === 'French') {
        bookRegex = new RegExp(bookRegexes.French.join('|'), 'gi');
    }

    text.split('. ').forEach(sentence => {
        let match;
        while ((match = bookRegex.exec(sentence)) !== null) {
            const bookName = match[0];
            const start = match.index;
            if (!frequency[bookName]) {
                frequency[bookName] = 1;
