['```javascript
// JavaScript function to copy specified number of bytes from a list of buffered data chunks
function copyBufferedData(chunks, startByte, numBytes) {
    let totalLength = 0;
    for (let i = 0; i < chunks.length; i++) {
        totalLength += chunks[i].length;
        if (totalLength >= startByte + numBytes) break;
    }

    if (startByte + numBytes > totalLength || numBytes <= 0) {
        throw new Error("Invalid byte range");
    }

    let resultBuffer = Buffer.alloc(numBytes);
    let offset = 0;

    for (let i = 0; i < chunks.length; i++) {
        let bytesToCopy = Math.min(chunks[i].length, numBytes - offset);
        chunks[i].copy(resultBuffer, offset, startByte >= totalLength ? 0 : startByte - totalLength, startByte + bytesToCopy);
        offset += bytesToCopy;
        if (offset === numBytes) break;
        startByte = 0; // Reset startByte after the first chunk
    }

    return resultBuffer;
}

// Example usage:
const chunks = [Buffer.from('Hello'), Buffer.from(' World')];
try {
    const copiedData = copyBufferedData(chunks, 6, 5); // Should return 'World'
    console.log(copiedData.toString());
} catch (error) {
    console.error(error.message);
}
