public class FileDataProcessor
{
    private int _minValue;
    private int _maxValue;

    public FileDataProcessor(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(maxValue), "MaxValue must be greater than MinValue.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _minValue + (float)(new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        var random = new Random();
        while (true)
        {
            int num = random.Next(_minValue, _maxValue + 1);
            if (num % 5 == 0) return num;
        }
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public async Task<byte[]> CopyBufferAsync(List<byte[]> bufferChunks, int offset, int count)
    {
        if (offset < 0 || count < 0 || offset + count > bufferChunks.Sum(chunk => chunk.Length))
            throw new ArgumentException("Invalid offset or count.");

        var result = new byte[count];
        int readBytes = 0;

        foreach (var chunk in bufferChunks)
        {
            int bytesToCopy = Math.Min(count - readBytes, chunk.Length);
            Buffer.BlockCopy(chunk, 0, result, readBytes, bytesToCopy);
            readBytes += bytesToCopy;
            if (readBytes >= count) break;
        }

        return result;
    }

    public async Task<string> CalculateMd5HashAsync(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            await stream.CopyToAsync(md5);
            return md5.ToString();
        }
    }
