    {
        if (minValue >= maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _minValue + (float)Math.Random() * (_maxValue - _minValue);
    }

    public int GenerateRandomInt()
    {
        Random random = new Random();
        int value = random.Next(_minValue, _maxValue);
        while (value % 5 != 0)
        {
            value = random.Next(_minValue, _maxValue);
        }
        return value;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public byte[] CopyBuffer(List<byte[]> dataChunks, int startIndex, int length)
    {
        if (startIndex < 0 || length < 0 || startIndex + length > dataChunks.Sum(chunk => chunk.Length))
        {
            throw new ArgumentOutOfRangeException(nameof(length), "Invalid start index or length.");
        }
        var destination = new byte[length];
        int offset = 0;
        foreach (var chunk in dataChunks)
        {
            int bytesToCopy = Math.Min(length - offset, chunk.Length);
            Buffer.BlockCopy(chunk, 0, destination, offset, bytesToCopy);
            offset += bytesToCopy;
            if (offset >= length) break;
        }
        return destination;
    }

    public async Task<string> CalculateMD5HashAsync(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            var buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                md5.TransformBlock(buffer, 0, bytesRead, null, 0);
            }
            md5.TransformFinalBlock(new byte[0], 0, 0);
            return BitConverter.ToString(md5.Hash).Replace("-", "").ToLower();
        }
    }

