public class FileDataProcessor
{
    private float _minValue;
    private float _maxValue;

    public FileDataProcessor(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _minValue + (float)(new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        var random = new Random();
        int value = random.Next((int)_minValue, (int)(_maxValue + 1));
        if (value % 5 != 0)
            return GenerateRandomInt(); // Ensure the number is divisible by 5
        return value;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public async Task<byte[]> CopyBytesAsync(List<byte[]> buffer, int start, int count)
    {
        if (start < 0 || count < 0 || start + count > buffer.Sum(b => b.Length))
            throw new ArgumentException("Invalid byte range.");

        using var ms = new MemoryStream();
        foreach (var chunk in buffer.Select((b, i) => new { b, index = i }))
        {
            int bytesToCopy = Math.Min(chunk.b.Length - (start - chunk.index * chunk.b.Length), count);
            if (bytesToCopy <= 0)
                break;
            await ms.WriteAsync(chunk.b, start - chunk.index * chunk.b.Length, bytesToCopy);
            count -= bytesToCopy;
        }
        return ms.ToArray();
    }

    public async Task<string> CalculateFileMd5Hash(string filePath)
    {
        using var md5 = MD5.Create();
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192, true))
        {
            await fileStream.CopyToAsync(md5);
        }
        return BitConverter.ToString(md5.Hash).Replace("-", "").ToLowerInvariant();
    }
}
