using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AdvancedFileDataProcessor
{
    private double _minValue;
    private double _maxValue;

    public AdvancedFileDataProcessor(double minValue, double maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentOutOfRangeException("maxValue", "MaxValue must be greater than MinValue.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomFloat()
    {
        return _minValue + (new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        var random = new Random();
        return random.Next((int)_minValue, (int)(_maxValue + 1)) + (random.Next(5) * 5);
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public static byte[] CopyBuffer(List<byte[]> dataChunks, int numBytesToCopy)
    {
        if (dataChunks == null || !dataChunks.Any())
            throw new ArgumentException("Data chunks cannot be empty.");

        var buffer = new byte[numBytesToCopy];
        int totalCopied = 0;

        foreach (var chunk in dataChunks)
        {
            if (totalCopied >= numBytesToCopy)
                break;

            int bytesToCopyFromChunk = Math.Min(chunk.Length, numBytesToCopy - totalCopied);
            Array.Copy(chunk, 0, buffer, totalCopied, bytesToCopyFromChunk);
            totalCopied += bytesToCopyFromChunk;
        }

        if (totalCopied != numBytesToCopy)
            throw new InvalidOperationException("Failed to copy the specified number of bytes.");

        return buffer;
    }

    public static async Task<string> CalculateFileMD5Async(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            var hashBytes = await ReadStreamInChunksAsync(stream, 4096, md5);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    private static async Task<byte[]> ReadStreamInChunksAsync(Stream input, int bufferSize, MD5 md5)
    {
        var buffer = new byte[bufferSize];
        int bytesRead;
        var hash = md5.ComputeHash(new byte[] { });

        while ((bytesRead = await input.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            hash = md5.ComputeHash(hash.Concat(buffer.Take(bytesRead)).ToArray());
        }

        return hash;
    }
}
