public class FileDataProcessor
{
    private readonly long _minValue;
    private readonly long _maxValue;
    private readonly Random _random = new Random();

    public FileDataProcessor(long minValue, long maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _random.NextSingle() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next((int)_minValue, (int)(_maxValue + 1)) * 5;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public async Task<byte[]> CopyBufferAsync(List<byte[]> buffers, int startIndex, int length)
    {
        if (startIndex < 0 || length <= 0 || startIndex + length > buffers.Sum(b => b.Length))
            throw new ArgumentException("Invalid start index or length.");

        var newBuffer = new byte[length];
        int offset = 0;

        foreach (var buffer in buffers)
        {
            if (offset >= startIndex && offset < startIndex + length)
            {
                int copyLength = Math.Min(length, buffer.Length - (startIndex - offset));
                Buffer.BlockCopy(buffer, startIndex - offset, newBuffer, offset - startIndex, copyLength);
                length -= copyLength;
                if (length == 0) break;
            }
            offset += buffer.Length;
        }

        return newBuffer;
    }

    public string CalculateMD5Hash(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            var hashBytes = md5.ComputeHash(stream);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}
