public class FileDataProcessor
{
    private double _minValue;
    private double _maxValue;

    public FileDataProcessor(double minValue, double maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue), "MinValue must be less than MaxValue.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GenerateRandomFloat()
    {
        return _minValue + (new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        var randomInt = new Random().Next((int)_minValue, (int)_maxValue);
        if (randomInt % 5 != 0)
            return GenerateRandomInt();
        return randomInt;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public async Task<byte[]> CopyBufferedDataAsync(List<byte[]> dataChunks, int startIndex, int length)
    {
        if (startIndex < 0 || length <= 0 || startIndex + length > dataChunks.Sum(chunk => chunk.Length))
            throw new ArgumentOutOfRangeException(nameof(length), "Invalid start index or length.");

        var result = new byte[length];
        await Task.Run(() =>
        {
            int offset = 0;
            foreach (var chunk in dataChunks)
            {
                if (offset >= startIndex && offset + chunk.Length <= startIndex + length)
                {
                    Buffer.BlockCopy(chunk, 0, result, offset - startIndex, chunk.Length);
                }
                else if (offset < startIndex + length && offset + chunk.Length > startIndex)
                {
                    var bytesToCopy = Math.Min(length, chunk.Length) - (startIndex - offset);
                    Buffer.BlockCopy(chunk, startIndex - offset, result, 0, bytesToCopy);
                }
                offset += chunk.Length;
            }
        });
        return result;
    }

    public string CalculateFileMD5(string filePath)
    {
        using (var md5 = MD5.Create())
        using (var stream = File.OpenRead(filePath))
        {
            var hashBytes = md5.ComputeHash(stream);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    // Additional methods and properties can be added here for advanced functionality
}
