['```javascript
// JavaScript function to copy specified number of bytes from buffered data chunks

function copyBufferedData(chunks, byteOffset, numBytes) {
    try {
        if (!Array.isArray(chunks)) throw new Error('Chunks must be an array');
        if (typeof byteOffset !== 'number' || typeof numBytes !== 'number') throw new Error('Byte offset and number of bytes must be numbers');

        let totalBuffer = Buffer.alloc(numBytes);
        let copiedBytes = 0;

        for (let chunk of chunks) {
            if (!Buffer.isBuffer(chunk)) continue;
            let toCopy = Math.min(numBytes - copiedBytes, chunk.length - byteOffset);
            if (toCopy > 0) {
                chunk.copy(totalBuffer, copiedBytes, byteOffset, byteOffset + toCopy);
                copiedBytes += toCopy;
            }
            if (copiedBytes === numBytes) break;
        }

        return totalBuffer.slice(0, copiedBytes);

    } catch (error) {
        console.error('Error copying buffered data:', error.message);
        throw error;
    }
}
