["```javascript
const { Readable } = require('stream');
const { promisify } = require('util');
const fs = require('fs');

async function copyBytesFromChunks(chunks, byteCount) {
  const tempBuffer = Buffer.alloc(byteCount);
  let bytesRead = 0;

  for (let i = 0; i < chunks.length && bytesRead < byteCount; i++) {
    if (bytesRead + chunks[i].length > byteCount) {
      chunks[i].copy(tempBuffer, bytesRead, 0, byteCount - bytesRead);
      bytesRead = byteCount;
    } else {
      chunks[i].copy(tempBuffer, bytesRead);
      bytesRead += chunks[i].length;
    }
  }

  if (bytesRead < byteCount) {
    throw new Error('Not enough data available to copy the specified number of bytes.');
  }

  return tempBuffer;
}

async function processLargeDataSet(dataStreamURL) {
  const response = await fetch(dataStreamURL);
  const reader = response.body.getReader();
  const chunks = [];

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
  }

  try {
    const dataBuffer = await copyBytesFromChunks(chunks, 1024 * 1024); // Copy 1MB of bytes
    console.log('Data processing complete:', dataBuffer.length);

    // Simulate data transfer to external service
    await transferToExternalService(dataBuffer);
  } catch (error) {
    console.error('Error during data processing:', error.message);
  }
}

async function transferToExternalService(dataBuffer) {
  const writeStream = fs.createWriteStream('/path/to/external/data');
  await promisify(writeStream.write.bind(writeStream))(dataBuffer);
  writeStream.end();
}

// Example usage
processLargeDataSet('https://example.com/large-data-stream')
  .then(() => console.log('Processing complete'))
  .catch(error => console.error('Error:', error));
```

