#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 100

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
} List;

void log_event(const char* message) {
    printf("%s\n", message);
}

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        log_event("Failed to allocate memory for list");
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int is_rnti_valid(uint16_t rnti) {
    return rnti >= 0 && rnti <= 65535;
}

uint8_t generate_crcflag() {
    return rand() % 2;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log_event("Failed to allocate memory for node");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

int add_entry(List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ENTRIES) {
        log_event("List is full. Cannot add more entries.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    if (!is_rnti_valid(rnti)) {
        log_event("Invalid RNTI value");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = {rnti, rnti, 0x01, generate_crcflag()};
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    log_event("Entry added with RNTI: %d", rnti);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void print_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    srand(time(NULL));
    List* list = create_list();
    if (!list) return -1;

    for (int i = 0; i < 50; ++i) {
        add_entry(list, rand() % 65536);
    }

    print_list(list);

    destroy_list(list);
    return 0;
}
