    if (!list->pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    list->size = initial_size;
    list->count = 0;
    return 0;
}

int update_mac_list(MAC_List_T *list, PDCP_PDU_T pdp, MAC_HEADER_T header) {
    if (list->count == list->size) {
        size_t new_size = list->size ? list->size * 2 : 1;
        void *new_memory = realloc(list->pdus, new_size * sizeof(MAC_PDU_T));
        if (!new_memory) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        list->pdus = (MAC_PDU_T *)new_memory;
        list->size = new_size;
    }
    if (pdp.sqn < 0 || pdp.sqn > UINT_MAX) {
        fprintf(stderr, "Invalid PDCP_SQN value\n");
        return -1;
    }
    list->pdus[list->count].pdp = pdp;
    list->pdus[list->count].header = header;
    list->count++;
    return 0;
}

void free_mac_list(MAC_List_T *list) {
    if (list->pdus) {
        free(list->pdus);
        list->pdus = NULL;
        list->size = 0;
        list->count = 0;
    }
}
