void list_cleanup_expired_entries(List* list, time_t now) {
    Node* prev = NULL;
    Node* current = list->head;
    while (current) {
        if (now - current->data.timestamp > TIMEOUT_PERIOD) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            current = prev ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }
