typedef struct {
    PDCP_PDU_T pdcp_pdu;
    MAC_HEADER_T mac_header;
} MAC_PDU;

typedef struct {
    MAC_PDU *pdus;
    size_t allocated_size;
    size_t used_size;
    size_t memory_quota;
    pthread_mutex_t lock;
} MAC_PDU_List;

int mac_pdu_list_init(MAC_PDU_List *list, size_t initial_size, size_t memory_quota) {
    list->pdus = (MAC_PDU *)malloc(initial_size * sizeof(MAC_PDU));
    if (!list->pdus) return -1; // Allocation failed
    list->allocated_size = initial_size;
    list->used_size = 0;
    list->memory_quota = memory_quota;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

int mac_pdu_list_add(MAC_PDU_List *list, PDCP_PDU_T pdcp_pdu, MAC_HEADER_T mac_header) {
    pthread_mutex_lock(&list->lock);
    if (list->used_size == list->allocated_size) {
        size_t new_size = list->allocated_size ? list->allocated_size * 2 : 1;
        if (new_size > list->memory_quota / sizeof(MAC_PDU)) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Exceeds memory quota
        }
        MAC_PDU *new_pdus = (MAC_PDU *)realloc(list->pdus, new_size * sizeof(MAC_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Allocation failed
        }
        list->pdus = new_pdus;
        list->allocated_size = new_size;
    }
    list->pdus[list->used_size].pdcp_pdu = pdcp_pdu;
    list->pdus[list->used_size].mac_header = mac_header;
    list->used_size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void mac_pdu_list_cleanup(MAC_PDU_List *list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdus);
    list->pdus = NULL;
    list->allocated_size = 0;
    list->used_size = 0;
    pthread_mutex_unlock(&list->lock);
}

void mac_pdu_list_get_memory_usage(MAC_PDU_List *list, double *usage_percentage) {
    pthread_mutex_lock(&list->lock);
    *usage_percentage = (double)(list->used_size * sizeof(MAC_PDU)) / list->memory_quota * 100;
    pthread_mutex_unlock(&list->lock);
}
