typedef struct {
    PDCP_PDU_T pdcp_pdu;
    MAC_HEADER_T mac_header;
} MAC_PDU;

typedef struct {
    MAC_PDU* pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    clock_t total_time;
    size_t total_pdus;
} MAC_PDULIST;

void init_mac_pdu_list(MAC_PDULIST* list, size_t initial_capacity) {
    list->pdus = (MAC_PDU*)malloc(initial_capacity * sizeof(MAC_PDU));
    if (!list->pdus) {
        perror("Failed to allocate memory for MAC PDUs");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->total_time = 0;
    list->total_pdus = 0;
}

void free_mac_pdu_list(MAC_PDULIST* list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

int add_mac_pdu(MAC_PDULIST* list, MAC_PDU pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_PDUS_PER_CONNECTION || 
        ((list->count + 1) * sizeof(MAC_PDU)) > MAX_MEMORY_FOOTPRINT) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Overflow or memory limit exceeded
    }
    list->pdus[list->count++] = pdu;
    clock_t start_time = clock();
    // Process PDU (not shown)
    clock_t end_time = clock();
    list->total_time += (end_time - start_time);
    list->total_pdus++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

double average_processing_time(MAC_PDULIST* list) {
    if (list->total_pdus == 0) return 0.0;
    return (double)list->total_time / CLOCKS_PER_SEC / list->total_pdus;
}
