#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_QUOTA 1024 * 1024 // 1MB for example
#define MEMORY_USAGE_THRESHOLD 90

typedef struct {
    PDCP_PDU_T pdcp_pdu;
    MAC_HEADER_T mac_header;
} MAC_PDU;

typedef struct MacList {
    MAC_PDU *pdu_array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MacList;

void init_mac_list(MacList *list, size_t initial_capacity) {
    list->pdu_array = (MAC_PDU *)malloc(initial_capacity * sizeof(MAC_PDU));
    if (list->pdu_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_mac_list(MacList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdu_array);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_pdu(MacList *list, PDCP_PDU_T pdcp_pdu, MAC_HEADER_T mac_header) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        MAC_PDU *new_array = (MAC_PDU *)realloc(list->pdu_array, new_capacity * sizeof(MAC_PDU));
        if (new_array == NULL) {
            pthread_mutex_unlock(&list->lock);
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        list->pdu_array = new_array;
        list->capacity = new_capacity;
    }
    MAC_PDU *entry = &list->pdu_array[list->size++];
    entry->pdcp_pdu = pdcp_pdu;
    entry->mac_header = mac_header;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

