['```c
#include <stdlib.h>
#include <stdio.h>

#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    unsigned char* data;
    size_t size;
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    unsigned char* payload;
    size_t payload_size;
    int extended_info_flag;
} MAC_PDU_T;

MAC_PDU_T* allocate_pdus(int N, const MAC_PDU_T config[], int* error_code) {
    if (N <= 0 || !config || !error_code) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    MAC_PDU_T* pdus = (MAC_PDU_T*)malloc(N * sizeof(MAC_PDU_T));
    if (!pdus) {
        *error_code = 1; // Memory allocation failure
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        if (config[i].payload_size > MAX_PAYLOAD_SIZE) {
            *error_code = 2; // Payload size overflow
            continue;
        }

        pdus[i] = config[i];

        pdus[i].header.data = (unsigned char*)malloc(sizeof(MAC_HEADER));
        if (!pdus[i].header.data) {
            *error_code = 3; // Header allocation failure
            free(pdus);
            return NULL;
        }

        pdus[i].payload = (unsigned char*)malloc(config[i].payload_size);
        if (!pdus[i].payload) {
            *error_code = 4; // Payload allocation failure
            free(pdus[i].header.data);
            free(pdus);
            return NULL;
        }
    }

    *error_code = 0; // Success
    return pdus;
}

void deallocate_pdus(MAC_PDU_T* pdus, int N) {
    if (!pdus || N <= 0) {
        return;
    }

    for (int i = 0; i < N; i++) {
        free(pdus[i].header.data);
        free(pdus[i].payload);
    }
    free(pdus);
}

void log_error(int error_code) {
    switch (error_code) {
        case -1:
            printf("Invalid input\n");
            break;
        case 1:
            printf("Memory allocation failure\n");
            break;
        case 2:
            printf("Payload size overflow\n");
            break;
        case 3:
            printf("Header allocation failure\n");
            break;
        case 4:
            printf("Payload allocation failure\n");
            break;
    }
}

int main() {
    MAC_PDU_T config = { {0}, 512, 0 };
    int error_code;

    MAC_PDU_T* pdus = allocate_pdus(10, &config, &error_code);
    if (!pdus) {
        log_error(error_code);
        return 1;
    }

    // Process PDUs
    deallocate_pdus(pdus, 10);

    return 0;
}
