    LTE_PHY_FRAME_STRUCT** frames = malloc(num_frames * sizeof(LTE_PHY_FRAME_STRUCT*));
    if (!frames) return NULL;

    for (int i = 0; i < num_frames; ++i) {
        frames[i] = malloc(sizeof(LTE_PHY_FRAME_STRUCT));
        if (!frames[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) free(frames[j]);
            free(frames);
            return NULL;
        }
        memset(frames[i], 0, sizeof(LTE_PHY_FRAME_STRUCT));
    }

    return frames;
}

void cleanup_lte_phy_frames(LTE_PHY_FRAME_STRUCT** frames, int num_frames) {
    for (int i = 0; i < num_frames; ++i) free(frames[i]);
    free(frames);
}

EVP_CIPHER_CTX* initialize_aes_cipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using SHA-1
    unsigned char key[32];
    unsigned char iv[EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    int salt_len;
    unsigned char salt[SALT_LEN];

    if (RAND_bytes(salt, sizeof(salt)) != 1 ||
        EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), salt,
                       (unsigned char*)password, strlen(password),
                       1, key, iv) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
