               request->hostname,
               request->ip_address[0],
               request->ip_address[1],
               request->ip_address[2],
               request->ip_address[3]);
    } else {
        fprintf(stderr, "Failed to resolve DNS for %s\n", request->hostname);
    }

    free(request->hostname);
    free(request);
    pthread_exit(NULL);
}

int main() {
    pthread_t thread_id;
    DNSRequest *request = (DNSRequest*) malloc(sizeof(DNSRequest));
    request->hostname = strdup("example.com");

    if (pthread_create(&thread_id, NULL, dns_worker, request) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    free(request);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a DNS resolution function in C that uses standard library functions. The `dns_lookup` function takes a hostname and an IP address array as parameters, resolves the hostname to an IP address using `gethostbyname`, and stores it in the provided array. It returns 0 on success or appropriate error codes.

The `main` function demonstrates how to use this DNS resolution function within a thread. A new `DNSRequest` structure is allocated and initialized with a sample hostname. The thread is created, and the `dns_worker` function is executed to perform the DNS lookup asynchronously. After the thread completes, the resources are cleaned up.

This example provides a simple framework for implementing concurrent DNS resolution using threads in C. You can expand upon this by adding error handling, logging, and other features as needed.']

