import asyncio
from abc import ABC, abstractmethod

class Notification(ABC):
    @abstractmethod
    def send(self, message: str) -> None:
        pass

class PushNotification(Notification):
    def __init__(self, service: str):
        self.service = service

    def send(self, message: str) -> None:
        # Logic to send a push notification through the specified service
        print(f"Sending {message} via {self.service}")

class InAppMessage(Notification):
    def send(self, message: str) -> None:
        # Logic to display an in-app message
        print(f"Displaying in-app message: {message}")

class NotificationSystem:
    def __init__(self):
        self.notifications = {
            "push": PushNotification("Firebase"),
            "in_app": InAppMessage()
        }
        self.user_preferences = {}

    def send_notification(self, user_id: str, notification_type: str, message: str) -> None:
        if user_id not in self.user_preferences:
            self.user_preferences[user_id] = {"push": True, "in_app": True}

        if self.user_preferences[user_id][notification_type]:
            asyncio.create_task(self.notifications[notification_type].send(message))

    def update_user_preference(self, user_id: str, notification_type: str, enabled: bool) -> None:
        if user_id in self.user_preferences:
            self.user_preferences[user_id][notification_type] = enabled

async def main():
    notification_system = NotificationSystem()
    await asyncio.gather(
        notification_system.send_notification("user1", "push", "Hello!"),
        notification_system.send_notification("user2", "in_app", "New Features Available!")
    )

if __name__ == "__main__":
    asyncio.run(main())
