#define MAX_FRAMES 1000
#define MAX_AES_KEY_LENGTH 32

typedef struct LTE_PHY_RX_FRAME_INFO_TAG {
    // Define the structure for LTE PHY layer frame information
} LTE_PHY_RX_FRAME_INFO;

typedef enum RF_PATH {
    PATH_A,
    PATH_B,
    // Add more RF paths as needed
} RF_PATH;

typedef struct MeasurementMetrics {
    int RSSI;
    float SNR;
    double BER;
    float signal_strength;
    float noise_power;
    // Add more measurement metrics as needed
} MeasurementMetrics;

typedef struct FrameContext {
    LTE_PHY_RX_FRAME_INFO *frame_info;
    RF_PATH rf_path;
    MeasurementMetrics metrics[10];
    AES_KEY aes_key;
    unsigned char iv[AES_BLOCK_SIZE];
    int cipher_enabled;
} FrameContext;

FrameContext* initialize_frame_context(int num_frames, const char* password) {
    if (num_frames <= 0 || num_frames > MAX_FRAMES || !password) return NULL;

    FrameContext *ctx = malloc(sizeof(FrameContext) * num_frames);
    if (!ctx) return NULL;

    for (int i = 0; i < num_frames; i++) {
        ctx[i].frame_info = malloc(sizeof(LTE_PHY_RX_FRAME_INFO));
        if (!ctx[i].frame_info) {
            // Handle memory allocation failure
            free_frame_context(ctx, num_frames);
            return NULL;
        }
        memset(&ctx[i], 0, sizeof(FrameContext));

        SHA1_CTX sha1_ctx;
        SHA1_Init(&sha1_ctx);
        SHA1_Update(&sha1_ctx, password, strlen(password));
        SHA1_Final(ctx[i].iv, &sha1_ctx);

        if (AES_set_encrypt_key((unsigned char*)ctx[i].iv, MAX_AES_KEY_LENGTH * 8, &ctx[i].aes_key) != 0) {
            // Handle AES key set failure
            free_frame_context(ctx, num_frames);
            return NULL;
        }
    }

    return ctx;
}

void clean_up_cipher(FrameContext* ctx) {
    if (ctx && ctx->cipher_enabled) {
        AES_set_encrypt_key((unsigned char*)ctx->iv, 0, &ctx->aes_key);
        ctx->cipher_enabled = 0;
    }
}

void free_frame_context(FrameContext* ctx, int num_frames) {
    if (!ctx) return;

    for (int i = 0; i < num_frames; i++) {
        free(ctx[i].frame_info);
    }

    free(ctx);
}
