const cors = require('cors');
const Redis = require('redis');
const mongoose = require('mongoose');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(bodyParser.json());
app.use(cors());

// MongoDB connection setup
mongoose.connect('mongodb://localhost/user_sessions', { useNewUrlParser: true, useUnifiedTopology: true });

// Redis client setup
const redisClient = Redis.createClient();

// Mongoose schema for sessions
const sessionSchema = new mongoose.Schema({
  token: String,
  userPreferences: Object,
  lastActivity: Date,
});

const Session = mongoose.model('Session', sessionSchema);

// External authentication service mock
const validateToken = async (token) => {
  // Simulate token validation logic
  return true;
};

// Middleware for rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Route for handling session operations
app.route('/session')
  .post(async (req, res) => {
    const { token } = req.body;

    if (!token || !(await validateToken(token))) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    // Check if session exists
    let session = await Session.findOne({ token });

    if (!session) {
      // Create new session
      session = new Session({
        token,
        userPreferences: {},
        lastActivity: new Date(),
      });
      await session.save();
    } else {
      // Update session activity time
      session.lastActivity = new Date();
      await session.save();
    }

    res.json({ message: 'Login successful', session });
  })
  .delete(async (req, res) => {
    const { token } = req.body;

    if (!token || !(await validateToken(token))) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    // Delete session
    await Session.deleteOne({ token });

    res.json({ message: 'Logout successful' });
  })
  .get(async (req, res) => {
    const { token } = req.query;

    if (!token || !(await validateToken(token))) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    // Get session status
    const session = await Session.findOne({ token });

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    res.json({ message: 'Session active', session });
  })
  .put(async (req, res) => {
    const { token, preferences } = req.body;

    if (!token || !(await validateToken(token))) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    // Update user preferences
    let session = await Session.findOne({ token });

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.userPreferences = { ...session.userPreferences, ...preferences };
    await session.save();

    res.json({ message: 'Preferences updated', changes: preferences });
  });

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

