        if (!array[i].payload_buffer) {
            // Free previously allocated memory before returning failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j].payload_buffer);
            }
            free(array);
            return NULL;
        }

        array[i].RF_PATH = 0; // Default value, can be set later
        array[i].RX_TIMESTAMP = 0; // Default value, can be set later
        array[i].payload_size = initial_payload_size;
    }

    return array;
}

void free_nfaapi_rx_frame_info_array(NFAPI_RX_FRAME_INFO* array, size_t N) {
    if (array != NULL) {
