['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_FRAMES 1024

typedef struct NFAPI_RX_FRAME_INFO {
    int RF_PATH;
    long RX_TIMESTAMP;
    uint8_t *payload_buffer;
    size_t payload_size;
    float signal_strength;
    float error_rate;
} NFAPI_RX_FRAME_INFO;

typedef struct FramePool {
    NFAPI_RX_FRAME_INFO frames[MAX_FRAMES];
    int next_frame_index;
    pthread_mutex_t lock;
} FramePool;

FramePool frame_pool = { .next_frame_index = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

NFAPI_RX_FRAME_INFO* initialize_rx_frames(int RF_PATH, long RX_TIMESTAMP, size_t payload_size) {
    pthread_mutex_lock(&frame_pool.lock);
    if (frame_pool.next_frame_index >= MAX_FRAMES) {
        pthread_mutex_unlock(&frame_pool.lock);
        fprintf(stderr, "Frame pool full!\n");
        return NULL;
    }

    NFAPI_RX_FRAME_INFO* frame = &frame_pool.frames[frame_pool.next_frame_index++];
    frame->RF_PATH = RF_PATH;
    frame->RX_TIMESTAMP = RX_TIMESTAMP;
    frame->payload_buffer = (uint8_t*)malloc(payload_size);
    if (!frame->payload_buffer) {
        pthread_mutex_unlock(&frame_pool.lock);
        fprintf(stderr, "Failed to allocate payload buffer!\n");
        return NULL;
    }
    frame->payload_size = payload_size;
    frame->signal_strength = 0.0f;
    frame->error_rate = 0.0f;

    pthread_mutex_unlock(&frame_pool.lock);
    return frame;
}

void update_frame(NFAPI_RX_FRAME_INFO* frame, uint8_t* new_payload, size_t new_payload_size, float signal_strength, float error_rate) {
    pthread_mutex_lock(&frame_pool.lock);
    if (new_payload_size > frame->payload_size) {
        free(frame->payload_buffer);
        frame->payload_buffer = (uint8_t*)realloc(frame->payload_buffer, new_payload_size);
        if (!frame->payload_buffer) {
            fprintf(stderr, "Failed to reallocate payload buffer!\n");
            pthread_mutex_unlock(&frame_pool.lock);
            return;
        }
    }
    memcpy(frame->payload_buffer, new_payload, new_payload_size);
    frame->payload_size = new_payload_size;
    frame->signal_strength = signal_strength;
    frame->error_rate = error_rate;

    pthread_mutex_unlock(&frame_pool.lock);
}

void free_frame(NFAPI_RX_FRAME_INFO* frame) {
    pthread_mutex_lock(&frame_pool.lock);
    if (frame >= frame_pool.frames && frame < &frame_pool.frames[MAX_FRAMES]) {
        free(frame->payload_buffer);
        frame->payload_buffer = NULL;
        frame->payload_size = 0;
        frame->signal_strength = 0.0f;
        frame->error_rate = 0.0f;
    }
    pthread_mutex_unlock(&frame_pool.lock);
}
