typedef struct {
    NFAPIStructure* structures;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} StructurePool;

StructurePool* create_structure_pool(size_t initial_capacity) {
    StructurePool* pool = malloc(sizeof(StructurePool));
    if (pool == NULL) return NULL;
    pool->structures = malloc(initial_capacity * sizeof(NFAPIStructure));
    if (pool->structures == NULL) {
        free(pool);
        return NULL;
    }
    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_structure_pool(StructurePool* pool) {
    if (pool != NULL) {
        pthread_mutex_destroy(&pool->mutex);
        free(pool->structures);
        free(pool);
    }
}

NFAPIStructure* allocate_structure(StructurePool* pool) {
    NFAPIStructure* new_struct = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (pool->size < pool->capacity) {
        new_struct = &pool->structures[pool->size++];
    }
    pthread_mutex_unlock(&pool->mutex);
    return new_struct;
}

void free_structure(StructurePool* pool, NFAPIStructure* struct_ptr) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->size; ++i) {
        if (&pool->structures[i] == struct_ptr) {
            pool->structures[i] = pool->structures[--pool->size];
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

// Additional functions for managing memory pool, error handling,
// structure validation, and performance optimization can be implemented here.

int main() {
    StructurePool* pool = create_structure_pool(1000000); // Example capacity
    if (pool == NULL) {
        // Handle allocation failure
    }

    // Allocate and populate structures based on input size N

    destroy_structure_pool(pool);
    return 0;
}
