    size_t pool_size;
    size_t block_size;
    size_t used_blocks;
} MemoryPoolManager;

void initialize_memory_pool(MemoryPoolManager* manager, size_t initial_size) {
    // Initialize the memory pool here
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure(MemoryPoolManager* manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->used_blocks >= manager->pool_size / manager->block_size) {
        // Handle memory allocation failure or expand the pool
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_structure = (NFAPI_CRC_INDICATION_PDU_T*)manager->memory_pool + manager->used_blocks * manager->block_size;
    memset(new_structure, 0, manager->block_size); // Initialize the structure
    manager->used_blocks++;
    pthread_mutex_unlock(&manager->lock);
    return new_structure;
}

void free_structure(MemoryPoolManager* manager, NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&manager->lock);
    size_t block_index = (size_t)((char*)structure - (char*)manager->memory_pool) / manager->block_size;
    if (block_index < manager->used_blocks) {
        memset(structure, 0, manager->block_size); // Clear the structure
        manager->used_blocks--;
    }
