#define MAX_ENTRIES 1024
#define RETRY_ATTEMPTS 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    time_t now = time(NULL);
    pthread_t thread_id = pthread_self();
    printf("[%s] [%lu] %s\n", ctime(&now), thread_id, message);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry() {
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entry == NULL) {
        log_message("Failed to allocate memory for new entry");
        return NULL;
    }
    pthread_mutex_lock(&lock);
    entry->RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
    do {
        entry->RNTI = rand() % (65536 - 1) + 1; // Ensure RNTI is non-zero and within range
    } while (count > 0 && find_entry(entry->RNTI) != NULL);
    entry->CRC_INDICATION_REL8_TAG = rand() % 256; // Example tag generation
    entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_unlock(&lock);
    log_message("Created new entry");
    return entry;
}

NFAPI_CRC_INDICATION_PDU_T* find_entry(unsigned short RNTI) {
    for (int i = 0; i < count; i++) {
        if (list[i].RNTI == RNTI) {
            return &list[i];
        }
    }
    return NULL;
}

void free_list() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < count; i++) {
        free(&list[i]);
    }
    free(list);
    list = NULL;
    count = 0;
    pthread_mutex_unlock(&lock);
    log_message("Freed all entries");
}

void* manage_list(void* arg) {
    int attempts = RETRY_ATTEMPTS;
    while (count < MAX_ENTRIES && attempts > 0) {
        NFAPI_CRC_INDICATION_PDU_T* entry = create_entry();
        if (entry != NULL) {
            if (list == NULL) {
                list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (list == NULL) {
                    log_message("Failed to allocate initial memory for list");
                    free(entry);
                    attempts--;
                    continue;
                }
            } else {
                if (count >= MAX_ENTRIES) {
                    NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list, (MAX_ENTRIES + 100) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    if (new_list == NULL) {
                        log_message("Failed to reallocate memory for list");
                        free(entry);
                        attempts--;
                        continue;
                    }
                    list = new_list;
                }
            }
            list[count++] = *entry;
        } else {
            attempts--;
        }
    }
    if (count >= MAX_ENTRIES) {
        log_message("Maximum entries reached, no further allocations allowed");
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t thread;
    pthread_create(&thread, NULL, manage_list, NULL);
    pthread_join(thread, NULL);
    free_list();
    return 0;
}
