// Function to initialize memory pool
void init_memory_pool(MEMORY_POOL *pool, size_t size) {
    pool->pool = malloc(size);
    if (pool->pool == NULL) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }
    pool->size = size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Function to allocate memory from memory pool
void *allocate_from_pool(MEMORY_POOL *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size + size > pool->size) {
        // Handle allocation failure
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void *ptr = ((char *)pool->pool) + pool->used_size;
    pool->used_size += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to deallocate memory from memory pool
void deallocate_from_pool(MEMORY_POOL *pool, void *ptr, size_t size) {
    pthread_mutex_lock(&pool->lock);
    // Implement memory reclamation logic here
    pool->used_size -= size;
    pthread_mutex_unlock(&pool->lock);
}

