public class MD5Hasher {
    public static String getMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
```

```c
#include <stdint.h>
#include <time.h>

#define NFAPI_RX_FRAME_PDU_T struct {
    int MAC_RX_FRAME_PDU;
    uint8_t frame_sync_metadata[16];
    uint8_t error_correction_metadata[32];
};

NFAPI_RX_FRAME_PDU_T* generate_rx_frame_pdus(int N) {
    if (N <= 0) {
        return NULL;
    }
    NFAPI_RX_FRAME_PDU_T* pdus = (NFAPI_RX_FRAME_PDU_T*)malloc(N * sizeof(NFAPI_RX_FRAME_PDU_T));
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].MAC_RX_FRAME_PDU = rand() % 1024;
        for (int j = 0; j < 16; j++) {
            pdus[i].frame_sync_metadata[j] = (uint8_t)rand();
        }
        for (int j = 0; j < 32; j++) {
            pdus[i].error_correction_metadata[j] = (uint8_t)rand();
        }
    }
    return pdus;
}
