import os

class MD5FileHasher:
    def __init__(self):
        self.supported_auth_methods = ['OAuth2', 'SAML', 'Basic']

    def get_md5_file_hash(self, file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError("The provided file path does not exist.")
        hash_md5 = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def handle_auth(self, method):
        if method not in self.supported_auth_methods:
            raise ValueError("Unsupported authentication method.")
        # Placeholder for actual auth logic
        pass
