import logging

class MD5FileHasherWithLogging(MD5FileHasher):
    def __init__(self, log_file_path):
        super().__init__()
        self.logger = logging.getLogger('MD5FileHasher')
        self.logger.setLevel(logging.DEBUG)
        file_handler = logging.FileHandler(log_file_path)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def get_md5_file_hash(self, file_path):
        try:
            return super().get_md5_file_hash(file_path)
        except Exception as e:
            self.logger.error(f"Error hashing file {file_path}: {e}")
            raise
