import os

class FileLock:
    def __init__(self, lock_file_path):
        self.lock_file_path = lock_file_path

    def acquire(self):
        with open(self.lock_file_path, "w") as f:
            f.write("Locked")

    def release(self):
        try:
            os.remove(self.lock_file_path)
        except OSError:
            pass

# Example usage:
lock = FileLock("/path/to/lockfile")
try:
    lock.acquire()
    # Perform file operations
finally:
    lock.release()
```

