import asyncio

class AsynchronousFileProcessor(MD5FileHasher):
    async def process_file(self, file_path):
        return await self.get_md5_file_hash(file_path)

    async def process_files(self, file_paths):
        tasks = [self.process_file(path) for path in file_paths]
        return await asyncio.gather(*tasks)

# Example usage:
hasher = MD5FileHasher()
processor = AsynchronousFileProcessor(hasher)
file_paths = ["path/to/file1", "path/to/file2"]
results = asyncio.run(processor.process_files(file_paths))
```

