class ReconnectionStrategy(MD5FileHasher):
    def __init__(self, max_retries=3):
        super().__init__()
        self.max_retries = max_retries

    def reconnect(self, storage_system):
        retries = 0
        while retries < self.max_retries:
            try:
                storage_system.connect()
                return True
            except ConnectionError as e:
                time.sleep(2 ** retries)  # Exponential backoff
                retries += 1
        return False

# Example usage:
storage_system = StorageSystem("local")
reconnection_strategy = ReconnectionStrategy()
if not reconnection_strategy.reconnect(storage_system):
    raise Exception("Failed to reconnect to storage system after maximum retries")

hasher = MD5FileHasherWithStorageSystem(storage_system)
