```python
class Caching(MD5FileHasher):
    def __init__(self, cache_size):
        super().__init__()
        self.cache = {}
        self.cache_size = cache_size

    def get_md5_file_hash(self, file_path):
        if file_path in self.cache:
            return self.cache[file_path]
        elif len(self.cache) >= self.cache_size:
            # Remove least recently used item from cache
            lru_key = min(self.cache, key=self.cache.get)
            del self.cache[lru_key]
        result = super().get_md5_file_hash(file_path)
        self.cache[file_path] = result
        return result

# Example usage:
hasher = Caching(100)
file_paths = ["path/to/file1", "path/to/file2"]
results = list(hasher.get_md5_file_hash(path) for path in file_paths)
```

