#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    char MAC_RX_FRAME_PDU[1024];
    // Additional metadata for frame synchronization and error correction
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    char MAC_RX_FRAME_PDU[1024];
    // Additional metadata for frame synchronization and error correction
} NFAPI_RX_FRAME_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int n) {
    if (n <= 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&mutex);
        pdu_list[i].RX_UE_INFORMATION_TAG = i * 2;
        pdu_list[i].RNTI = i * 1000;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        snprintf(pdu_list[i].MAC_RX_FRAME_PDU, sizeof(pdu_list[i].MAC_RX_FRAME_PDU), "SimulatedData%d", i);
        // Populate additional metadata
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return pdu_list;
}
