typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
} record;

long generateRandomOffset(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int generateRandomKey(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void generateNfadatas(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        exit(1);
    }

    int N = atoi(argv[1]);
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *nfapi_data_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    long *offsets = (long *)malloc(N * sizeof(long));
    int *keys = (int *)malloc(N * sizeof(int));
    record *records = (record *)malloc(N * sizeof(record));

    if (!nfapi_data_list || !offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < N; i++) {
        nfapi_data_list[i].RX_UE_INFORMATION_TAG = generateRandomKey(1, 100);
        nfapi_data_list[i].RNTI = generateRandomKey(1, 500);
        nfapi_data_list[i].CRC_INDICATION_REL8_TAG = generateRandomKey(1, 200);
        nfapi_data_list[i].CRCFLAG = rand() % (256 - 32) + 32; // Ensures it falls within the specified range
        offsets[i] = generateRandomOffset(10000, 99999);
        keys[i] = generateRandomKey(100, 999);
        records[i].value = rand() % (500 - 100) + 100; // Random value within a given range
    }

    int max_value = 0;
    for (int i = 0; i < N; i++) {
        if (nfapi_data_list[i].CRCFLAG > max_value) {
            max_value = nfapi_data_list[i].CRCFLAG;
        }
    }
    printf("Largest CRCFLAG: %d\n", max_value);

    free(nfapi_data_list);
    free(offsets);
    free(keys);
    free(records);
}

