import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class MD5HashGenerator {

    private static final String[] COMMON_STRINGS = {"commonString1", "commonString2"};

    public static List<String> computeHash(List<String> inputs) {
        List<String> hashes = new ArrayList<>();
        for (String input : inputs) {
            try {
                hashes.add(computeSingleHash(input));
            } catch (NoSuchAlgorithmException e) {
                e.printStackTrace();
                hashes.add(null);
            }
        }
        return hashes;
    }

    private static String computeSingleHash(String input) throws NoSuchAlgorithmException {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Invalid input");
        }
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    static {
        try {
            for (String s : COMMON_STRINGS) {
                computeSingleHash(s); // Precompute hashes for common strings
            }
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

}
