void* generate_crc_indications(int N, unsigned int seed) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        // Fallback mechanism to save partially generated data to disk
        fprintf(stderr, "Memory allocation failed. Saving partial data to disk.\n");
        FILE* file = fopen("partial_data.bin", "wb");
        if (file) {
            fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
            fclose(file);
        }
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < N; i++) {
        data[i].RX_UE_INFORMATION_TAG = rand();
        data[i].RNTI = rand();
        data[i].CRC_INDICATION_REL8_TAG = rand();
        data[i].CRCFLAG = rand() % 2;
    }

    // Verify integrity of the generated list
    int failed_checks = 0;
    for (int i = 0; i < N; i++) {
        if (!(data[i].RX_UE_INFORMATION_TAG ^ data[i].RNTI ^ data[i].CRC_INDICATION_REL8_TAG)) {
            failed_checks++;
        }
    }

    printf("Failed CRC checks: %d\n", failed_checks);

    return data;
}

int main() {
    int N = 1000000;
    unsigned int seed = time(NULL);
    void* result = generate_crc_indications(N, seed);
    if (result) {
        // Use the generated data
        free(result);
    }
    return 0;
}
