    for (int i = 0; i < N; i++) {
        if (strncmp(pdus[i].tag, "RX_UE_INFORMATION_TAG_", 24) != 0 ||
            pdus[i].rnti > 65535 ||
            pdus[i].crcflag > 1) {
            return -1;
        }
    }

    return 0;
}

