#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indication_pdu_list(int N, int seed, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    if (N <= 0) {
        *pdu_list = NULL;
        return;
    }

    *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);
    int total_records = 0;

    for (int i = 0; i < N; i++) {
        (*pdu_list)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pdu_list)[i].RNTI = rand() % 1000 + 1;
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        (*pdu_list)[i].CRCFLAG = rand() % 2;

        // Check for valid tag formats and ensure all fields are correctly initialized
        if ((*pdu_list)[i].RX_UE_INFORMATION_TAG < 0 ||
            (*pdu_list)[i].RNTI <= 0 ||
            (*pdu_list)[i].CRC_INDICATION_REL8_TAG < 0) {
            fprintf(stderr, "Invalid tag format\n");
            free(*pdu_list);
            *pdu_list = NULL;
            return;
        }

        total_records++;
    }

    // Ensure no duplicate RNTI values in the NFAPI_CRC_INDICATION_PDU_T list
    int *rnti_set = malloc(N * sizeof(int));
    memset(rnti_set, 0, N * sizeof(int));
    for (int i = 0; i < total_records; i++) {
        if (rnti_set[(*pdu_list)[i].RNTI]) {
            fprintf(stderr, "Duplicate RNTI value\n");
            free(*pdu_list);
            free(rnti_set);
            *pdu_list = NULL;
            return;
        }
        rnti_set[(*pdu_list)[i].RNTI] = 1;
    }

    // Check that the sum of all record integers does not exceed a predefined limit
    int total_sum = 0;
    for (int i = 0; i < total_records; i++) {
        total_sum += (*pdu_list)[i].RX_UE_INFORMATION_TAG +
                      (*pdu_list)[i].RNTI +
                      (*pdu_list)[i].CRC_INDICATION_REL8_TAG;
        if (total_sum > 100000) { // Predefined limit
            fprintf(stderr, "Sum of record integers exceeds limit\n");
            free(*pdu_list);
            free(rnti_set);
            *pdu_list = NULL;
            return;
        }
    }

    free(rnti_set);
}

void log_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int N) {
    if (pdu_list == NULL || N <= 0) return;

    for (int i = 0; i < N; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               pdu_list[i].RX_UE_INFORMATION_TAG,
               pdu_list[i].RNTI,
               pdu_list[i].CRC_INDICATION_REL8_TAG,
               pdu_list[i].CRCFLAG);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    generate_crc_indication_pdu_list(10, 42, &pdu_list);
    log_crc_indication_pdu_list(pdu_list, 10);
    free(pdu_list);
    return 0;
}
