import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5Hasher {

    private static final Map<String, String> cache = new HashMap<>();

    public static String getMD5(String input) {
        try {
            if (cache.containsKey(input)) {
                return cache.get(input);
            }

            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            cache.put(input, hexString.toString());
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static Map<String, String> getMD5(String[] inputs) {
        Map<String, String> results = new HashMap<>();
        for (String input : inputs) {
            results.put(input, getMD5(input));
        }
        return results;
    }

    public static void main(String[] args) {
        System.out.println(getMD5("hello world"));
        System.out.println(getMD5(new String[]{"hello", "world"}));
    }
}
