import java.io.*;
import java.net.Socket;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class TCPClient {
    private static final int MAX_RETRIES = 5;
    private static final long BACKOFF_MS = 1000L;
    private static final Lock lock = new ReentrantLock();

    public static void sendData(String serverAddress, int port, NFAPI_CRC_INDICATION_PDU_T[] data) {
        for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
            try (Socket socket = new Socket(serverAddress, port)) {
                lock.lock();
                try (ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream())) {
                    out.writeObject(data);
                }
                lock.unlock();

                break;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES - 1) throw new RuntimeException("Failed to send data after retries", e);
                Thread.sleep(BACKOFF_MS * (1 << attempt));
            }
        }
    }
}
