import time
from collections import OrderedDict, Counter
from concurrent.futures import ThreadPoolExecutor
from functools import wraps

class DistributedCache:
    def __init__(self, max_size, eviction_policy='LRU', ttl=None):
        self.cache = OrderedDict()
        self.max_size = max_size
        self.eviction_policy = eviction_policy
        self.ttl = ttl if ttl is not None else float('inf')
        self.executor = ThreadPoolExecutor(max_workers=4)

    def _evict(self):
        while len(self.cache) > self.max_size:
            if self.eviction_policy == 'LRU':
                key, value = self.cache.popitem(last=False)
            elif self.eviction_policy == 'LFU':
                key, value = min(self.cache.items(), key=lambda item: item[1][1])
                del self.cache[key]
            elif self.eviction_policy == 'TTL':
                current_time = time.time()
                for key, (value, timestamp) in self.cache.copy().items():
                    if current_time - timestamp > self.ttl:
                        del self.cache[key]

    def get(self, key):
        if key not in self.cache:
            return None
        value, timestamp = self.cache[key]
        self.cache.move_to_end(key)
        return value

    def set(self, key, value):
        with self.executor.submit(self._evict) as future:
            future.result()
        self.cache[key] = (value, time.time())

    def delete(self, key):
        if key in self.cache:
            del self.cache[key]

