#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 1024

typedef struct {
    int interface_id;
    uint64_t bytes_sent;
    uint64_t bytes_received;
} LOGICAL_INTERFACE_STATISTICS;

typedef struct {
    LOGICAL_INTERFACE_STATISTICS *stats[MAX_INTERFACES];
    size_t count;
    pthread_mutex_t mutex;
} INTERFACE_STATS_POOL;

INTERFACE_STATS_POOL pool;

void init_stats_pool() {
    pthread_mutex_init(&pool.mutex, NULL);
    memset(pool.stats, 0, sizeof(pool.stats));
    pool.count = 0;
}

LOGICAL_INTERFACE_STATISTICS* create_interface_stat(int interface_id) {
    LOGICAL_INTERFACE_STATISTICS *stat = (LOGICAL_INTERFACE_STATISTICS *)malloc(sizeof(LOGICAL_INTERFACE_STATISTICS));
    if (!stat) return NULL;
    stat->interface_id = interface_id;
    stat->bytes_sent = 0;
    stat->bytes_received = 0;
    return stat;
}

int add_interface_stat(int interface_id) {
    pthread_mutex_lock(&pool.mutex);
    if (pool.count >= MAX_INTERFACES) {
        pthread_mutex_unlock(&pool.mutex);
        fprintf(stderr, "Error: Pool is full\n");
        return -1;
    }
    pool.stats[pool.count++] = create_interface_stat(interface_id);
    pthread_mutex_unlock(&pool.mutex);
    return 0;
}

void free_stats_pool() {
    for (size_t i = 0; i < pool.count; ++i) {
        free(pool.stats[i]);
    }
    memset(pool.stats, 0, sizeof(pool.stats));
    pool.count = 0;
    pthread_mutex_destroy(&pool.mutex);
}

// Example usage
int main() {
    init_stats_pool();

    add_interface_stat(1);
    add_interface_stat(2);

    // Access statistics
    for (size_t i = 0; i < pool.count; ++i) {
        printf("Interface %d: Sent=%lu, Received=%lu\n", 
               pool.stats[i]->interface_id,
               pool.stats[i]->bytes_sent,
