        self.cache = {}
        self.evict_policy = policy.upper()
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                if self.evict_policy == 'LRU':
                    self.cache.move_to_end(key)
                elif self.evict_policy == 'LFU':
                    # Implement LFU logic
