    private static final String[] COMMON_STRINGS = {
        "example1", "example2", "commonString1", "commonString2"
    };

    public static List<String> computeHash(List<String> strings) {
        List<String> hashes = new ArrayList<>();
        for (String str : strings) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(str.getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) {
                    sb.append(String.format("%02x", b));
                }
                hashes.add(sb.toString());
            } catch (NoSuchAlgorithmException e) {
                System.err.println("Error computing hash: " + e.getMessage());
                hashes.add(null);
            }
        }
        return hashes;
    }

