import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.*;

public class FileHasher {

    private static final Map<String, String> cache = new HashMap<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static Map<String, String> computeMD5(String[] filePaths) {
        Map<String, String> result = new ConcurrentHashMap<>();

        for (String filePath : filePaths) {
            executorService.submit(() -> {
                try {
                    String hash = cache.get(filePath);
                    if (hash == null) {
                        hash = calculateMD5(filePath);
                        cache.put(filePath, hash);
                    }
                    result.put(filePath, hash);
                } catch (IOException | NoSuchAlgorithmException e) {
                    System.err.println("Error computing MD5 for file: " + filePath);
                    e.printStackTrace();
                }
            });
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }

        return result;
    }

    private static String calculateMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String[] filePaths = {"file1.txt", "file2.txt"}; // Example file paths
        Map<String, String> hashes = computeMD5(filePaths);
        for (Map.Entry<String, String> entry : hashes.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}
