import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StringHasher {
    private static final Lock lock = new ReentrantLock();
    private static final MessageDigest md;

    static {
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public byte[] hashString(String input, int threads) {
        if (input == null || threads <= 0) {
            throw new IllegalArgumentException("Invalid input or thread count");
        }

        byte[][] hashes = new byte[threads][];
        Thread[] threadsArray = new Thread[threads];

        for (int i = 0; i < threads; i++) {
            final int start = i * input.length() / threads;
            final int end = (i == threads - 1) ? input.length() : (i + 1) * input.length() / threads;

            threadsArray[i] = new Thread(() -> {
                lock.lock();
                try {
                    hashes[i] = md.digest(input.substring(start, end).getBytes());
                } finally {
                    lock.unlock();
                }
            });
            threadsArray[i].start();
        }

        for (Thread thread : threadsArray) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // Concatenate all hashes
        byte[] finalHash = new byte[0];
        for (byte[] hash : hashes) {
            finalHash = concatenate(finalHash, hash);
        }

        return finalHash;
    }

    private byte[] concatenate(byte[] a, byte[] b) {
        byte[] result = new byte[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }
}
