import hashlib
from functools import lru_cache
import threading

class DistributedCache:
    def __init__(self, eviction_policy="LRU", max_size=100):
        self.cache = {}
        self.eviction_policy = eviction_policy
        self.max_size = max_size
        self.lock = threading.Lock()

    @lru_cache(maxsize=None)
    def get(self, key):
        return self.cache.get(key)

    def set(self, key, value):
        with self.lock:
            if len(self.cache) >= self.max_size and self.eviction_policy == "LRU":
                self.cache.popitem(last=False)
            elif len(self.cache) >= self.max_size and self.eviction_policy == "LFU":
                lfu_key = min(self.cache, key=lambda k: self.cache[k][1])
                self.cache.pop(lfu_key)
            elif len(self.cache) >= self.max_size and self.eviction_policy == "TTL":
                ttl_keys = [k for k, v in self.cache.items() if time.time() > v[2]]
                for key in ttl_keys:
                    del self.cache[key]

            self.cache[key] = (value, 1, time.time())

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]

