```java
import java.io.File;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class FileChecksum {
    public static Map<String, String> calculateFileChecksums(String[] filePaths) throws Exception {
        Map<String, String> checksumMap = new HashMap<>();
        MessageDigest md = MessageDigest.getInstance("SHA-256");

        for (String filePath : filePaths) {
            File file = new File(filePath);
            if (!file.exists()) {
                continue;
            }

            try (java.nio.file.Files.ReadableByteChannel channel = java.nio.file.Files.newReadableByteChannel(file.toPath())) {
                byte[] buffer = new byte[8192];
                int bytesRead;
                while ((bytesRead = channel.read(java.nio.ByteBuffer.wrap(buffer))) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
            }

            String checksum = bytesToHex(md.digest());
            checksumMap.put(filePath, checksum);
        }

        return checksumMap;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // Main method to test
    public static void main(String[] args) {
        try {
            String[] filePaths = {"file1.txt", "file2.txt"};
            Map<String, String> checksums = calculateFileChecksums(filePaths);
            for (Map.Entry<String, String> entry : checksums.entrySet()) {
                System.out.println(entry.getKey() + ": " + entry.getValue());
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
