#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TrafficEvent {
    int timestamp;
    char eventType[20];
    int eventID;
} TrafficEvent;

typedef struct DynamicArray {
    TrafficEvent* events;
    size_t count;
    size_t capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->events = NULL;
    array->count = 0;
    array->capacity = 0;
    return array;
}

void addEvent(DynamicArray* array, TrafficEvent event) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;
        TrafficEvent* newEvents = (TrafficEvent*)realloc(array->events, newCapacity * sizeof(TrafficEvent));
        if (newEvents == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->events = newEvents;
        array->capacity = newCapacity;
    }
    array->events[array->count++] = event;
}

void removeEvent(DynamicArray* array, int eventID) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].eventID == eventID) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->events[j] = array->events[j + 1];
            }
            array->count--;
            return;
        }
    }
}

TrafficEvent* getMostRecentEvent(DynamicArray* array) {
    if (array->count == 0) {
        return NULL;
    }
    size_t maxIndex = 0;
    for (size_t i = 1; i < array->count; ++i) {
        if (array->events[i].timestamp > array->events[maxIndex].timestamp) {
            maxIndex = i;
        }
    }
    return &array->events[maxIndex];
}

void freeDynamicArray(DynamicArray* array) {
    free(array->events);
    free(array);
}
