```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int data;
    struct Record *next;
} Record;

typedef struct RecordList {
    pthread_mutex_t lock;
    Record *head;
    Record *tail;
} RecordList;

Record* create_record(int data) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->data = data;
    record->next = NULL;
    return record;
}

void add_record(RecordList *list, int data) {
    pthread_mutex_lock(&list->lock);
    Record *new_record = create_record(data);
    if (new_record == NULL) {
        pthread_mutex_unlock(&list->lock);
        // Handle memory allocation failure
        return;
    }
    if (list->head == NULL) {
        list->head = new_record;
        list->tail = new_record;
    } else {
        list->tail->next = new_record;
        list->tail = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_records(Record *record) {
    Record *current = record;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }
}

void free_record_list(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    free_records(list->head);
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
}
