                    System.err.println("Failed to send data after " + MAX_RETRIES + " attempts");
                    break;
                }
                int delay = INITIAL_DELAY * (int)Math.pow(2, i);
                try { Thread.sleep(delay); } catch (InterruptedException ie) {}
            }
        }
    }
}
