```javascript
function copyBufferChunks(bufferList, numBytesToCopy) {
    const newBuffer = Buffer.alloc(numBytesToCopy);
    let copiedBytes = 0;

    for (const buffer of bufferList) {
        if (copiedBytes >= numBytesToCopy) break;
        const bytesToCopy = Math.min(numBytesToCopy - copiedBytes, buffer.length);
        buffer.copy(newBuffer, copiedBytes, 0, bytesToCopy);
        copiedBytes += bytesToCopy;
    }

    return newBuffer.slice(0, copiedBytes);
}
