TCP_CONNECTION_STATUS_UPDATE_PDU_T* generateConnectionUpdates(int numConnections, unsigned long maxTimestampSum) {
    TCP_CONNECTION_STATUS_UPDATE_PDU_T* connections = (TCP_CONNECTION_STATUS_UPDATE_PDU_T*)malloc(numConnections * sizeof(TCP_CONNECTION_STATUS_UPDATE_PDU_T));
    if (connections == NULL) {
