    unsigned long currentSum = 0;

    for (int i = 0; i < numConnections; i++) {
        // Generate unique IP addresses
        sprintf(connections[i].clientIP, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        sprintf(connections[i].serverIP, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);

        // Generate valid connection state
        if (currentSum == maxTimestampSum) {
            connections[i].state = STATE_DISCONNECTED;
        } else {
            connections[i].state = (ConnectionState)((rand() % 3) + 1);
            if (connections[i].state == STATE_CONNECTED && currentSum + rand() > maxTimestampSum) {
                connections[i].state = STATE_DISCONNECTED;
