        return -1; // Invalid parameters
    }
    if (config->num_mac_entities >= config->max_mac_entities) {
        return -2; // Maximum number of MAC entities reached
    }
    MacEntity* new_entity = (MacEntity*)malloc(sizeof(MacEntity));
    if (new_entity == NULL) {
        return -3; // Handle memory allocation failure
    }
    new_entity->mac_entity_id = mac_entity_id;
    new_entity->rlc_instance = rlc_instance;
    new_entity->lower_layer_protocols = lower_layer_protocols;
    config->mac_entities[config->num_mac_entities++] = new_entity;
    return 0; // Success
}

void free_wireless_comm_config(WirelessCommConfig* config) {
    if (config == NULL) {
        return;
    }
    for (size_t i = 0; i < config->num_mac_entities; ++i) {
        MacEntity* entity = config->mac_entities[i];
        if (entity != NULL) {
            free(entity);
