#include <stdio.h>
#include <stdlib.h>

#define MAX_MAC_ENTITIES 256

typedef struct rlc_entity {
    // Define RLC entity structure here
} rlc_entity;

typedef struct ll_protocol {
    struct ll_protocol *next;
    // Define lower layer protocol structure here
} ll_protocol;

typedef struct mac_entity {
    rlc_entity *rlc_ptr;
    ll_protocol *protocols;
    // Add other MAC entity attributes as needed
} mac_entity;

typedef struct config_struct {
    mac_entity mac_entities[MAX_MAC_ENTITIES];
    int num_mac_entities;
    // Add other configuration parameters as needed
} config_struct;

void init_config(config_struct *config) {
    config->num_mac_entities = 0;
    for (int i = 0; i < MAX_MAC_ENTITIES; i++) {
        config->mac_entities[i].rlc_ptr = NULL;
        config->mac_entities[i].protocols = NULL;
        // Initialize other MAC entity attributes
    }
}

void add_mac_entity(config_struct *config) {
    if (config->num_mac_entities >= MAX_MAC_ENTITIES) {
        printf("Error: Maximum number of MAC entities reached\n");
        return;
    }
    config->mac_entities[config->num_mac_entities].rlc_ptr = malloc(sizeof(rlc_entity));
    if (!config->mac_entities[config->num_mac_entities].rlc_ptr) {
        printf("Error: Memory allocation failed for RLC entity\n");
        return;
    }
    // Initialize RLC entity
    config->mac_entities[config->num_mac_entities].protocols = NULL;
    config->num_mac_entities++;
}

void add_protocol(config_struct *config, int mac_index, ll_protocol *protocol) {
    if (mac_index < 0 || mac_index >= config->num_mac_entities) {
        printf("Error: Invalid MAC entity index\n");
        return;
    }
    protocol->next = config->mac_entities[mac_index].protocols;
    config->mac_entities[mac_index].protocols = protocol;
}

void remove_protocol(config_struct *config, int mac_index, ll_protocol *protocol) {
    if (mac_index < 0 || mac_index >= config->num_mac_entities) {
        printf("Error: Invalid MAC entity index\n");
        return;
    }
    ll_protocol **current_ptr = &config->mac_entities[mac_index].protocols;
    while (*current_ptr != NULL) {
        if (*current_ptr == protocol) {
            *current_ptr = protocol->next;
            free(protocol);
            return;
        }
        current_ptr = &(*current_ptr)->next;
    }
    printf("Error: Protocol not found\n");
}

void log_config_change(config_struct *config, int mac_index, char *action) {
    if (mac_index < 0 || mac_index >= config->num_mac_entities) {
        printf("Error: Invalid MAC entity index\n");
        return;
    }
    printf("MAC Entity %d - Action: %s\n", mac_index, action);
}

void cleanup_config(config_struct *config) {
    for (int i = 0; i < config->num_mac_entities; i++) {
        free(config->mac_entities[i].rlc_ptr);
        ll_protocol *protocol = config->mac_entities[i].protocols;
        while (protocol != NULL) {
            ll_protocol *next_protocol = protocol->next;
            free(protocol);
            protocol = next_protocol;
        }
    }
}

int main() {
    config_struct my_config;
    init_config(&my_config);

    add_mac_entity(&my_config);
    ll_protocol *new_protocol = malloc(sizeof(ll_protocol));
    if (new_protocol) {
        new_protocol->next = NULL;
        // Initialize protocol
        add_protocol(&my_config, 0, new_protocol);
        log_config_change(&my_config, 0, "Added Protocol");
    }

    remove_protocol(&my_config, 0, new_protocol);
    log_config_change(&my_config, 0, "Removed Protocol");

    cleanup_config(&my_config);

    return 0;
}
