```java
public void sendDataWithRetry(NFAPI_CRC_INDICATION_PDU_T[] data, int maxRetries) {
    for (int attempt = 0; attempt <= maxRetries; ++attempt) {
        try {
            sendData(data);
            return;
        } catch (IOException e) {
            if (attempt == maxRetries) throw e;
            Thread.sleep((1 << attempt) * 100); // Exponential backoff
        }
    }
}
