import java.util.concurrent.TimeUnit;

public class TCPClient {

    public static void connectToServer(String serverAddress, int port, NFAPI_CRC_INDICATION_PDU_T[] data) {
        try (Socket socket = new Socket(serverAddress, port)) {
            // Send data
            ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
            oos.writeObject(data);
            oos.flush();

            // Receive confirmation
            ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
            boolean confirmation = (boolean) ois.readObject();
            System.out.println("Server confirmed: " + confirmation);

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

    public static void connectWithRetry(String serverAddress, int port, NFAPI_CRC_INDICATION_PDU_T[] data, int maxRetries, long initialDelay) {
        for (int i = 0; i <= maxRetries; i++) {
            try {
                connectToServer(serverAddress, port, data);
                return;
            } catch (Exception e) {
                if (i == maxRetries) throw e;
                try {
                    TimeUnit.SECONDS.sleep((long) Math.pow(2, i));
                } catch (InterruptedException ie) {}
            }
        }
    }
}
