#include <openssl/rand.h>
#include <openssl/evp.h>

EVP_CIPHER_CTX* initAES256CBC(const char *password, size_t password_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[32];
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];

    // Derive key using a robust hashing algorithm
    int key_len;
    PKCS5_PBKDF2_HMAC(password, password_len, (unsigned char *)"salt", 4, 100000, EVP_sha256(), 32, key);
    key_len = EVP_CIPHER_key_length(EVP_aes_256_cbc());

    // Generate IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize cipher context
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
