            ObjectMapper mapper = new ObjectMapper();
            return mapper.readValue(jsonString, ConfigObject.class);
        } catch (Exception e) {
            throw new Exception("Failed to parse JSON", e);
        }
    }

    // Synchronized method for thread safety
    public synchronized static Map<String, ConfigObject> batchFromJsonStrings(List<String> jsonStrings) throws Exception {
        if (jsonStrings == null || jsonStrings.isEmpty()) {
            throw new IllegalArgumentException("Invalid JSON input list");
        }

        Map<String, ConfigObject> configMap = new HashMap<>();
        for (String jsonString : jsonStrings) {
            ConfigObject configObject = fromJsonString(jsonString);
            configMap.put(configObject.getKey(), configObject);
        }
        return configMap;
    }
}
