import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.Socket;
import java.util.concurrent.ConcurrentHashMap;

public class NetworkClient {
    private ConcurrentHashMap<String, Socket> connectionPool = new ConcurrentHashMap<>();

    public String sendMessages(List<NetworkMessage> messages) throws Exception {
        Socket socket = getSocket();
        // Send messages and receive response
        String response = sendMessage(socket, serializeMessages(messages));
        releaseSocket(socket);
        return response;
    }

    private Socket getSocket() {
        // Get a socket from the connection pool or create a new one
        return connectionPool.computeIfAbsent("serverAddress", key -> connectToServer());
    }

    private void releaseSocket(Socket socket) {
        // Release the socket back to the connection pool
        connectionPool.remove(socket.getInetAddress().toString(), socket);
    }

    private Socket connectToServer() {
        try {
            return new Socket("serverAddress", 12345);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private String serializeMessages(List<NetworkMessage> messages) throws Exception {
        // Serialize the list of NetworkMessage objects to a string
        StringBuilder sb = new StringBuilder();
        for (NetworkMessage message : messages) {
            sb.append(message.type).append(",").append(message.sequenceNumber).append(";");
        }
        return sb.toString();
    }

    private String sendMessage(Socket socket, String message) throws Exception {
        try (
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()))
        ) {
            out.println(message);
            return in.readLine();
        }
    }
}
