import java.io.IOException;

public class MD5Validator {

    private static final String EXTERNAL_API_URL = "https://example.com/validate-md5";
    private static final int MAX_RETRIES = 3;
    private static final long MIN_DELAY = 100; // milliseconds
    private static final long MAX_DELAY = 1000; // milliseconds

    public static void validateMD5(String input, boolean enableValidation) throws Exception {
        String md5Hash = computeMD5(input);

        if (enableValidation) {
            for (int i = 0; i <= MAX_RETRIES; i++) {
                try {
                    boolean isValid = ExternalAPIService.isValidMd5(md5Hash);
                    if (isValid) {
                        logTime("Validation successful", System.currentTimeMillis());
                        return;
                    }
                } catch (Exception e) {
                    // Handle exceptions from external service
                }

                long delay = new Random().nextLong(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
                Thread.sleep(delay);
            }

            throw new Exception("MD5 hash validation failed after " + MAX_RETRIES + " retries.");
        } else {
            logTime("Validation skipped", System.currentTimeMillis());
        }
    }

    private static String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());

        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    }

    private static void logTime(String message, long timestamp) {
        try (FileWriter writer = new FileWriter("log.txt", true)) {
            writer.write(message + " at " + timestamp + "\n");
        } catch (IOException e) {
            // Handle logging errors
        }
    }
}
