public class MD5Validator {

    public static void validateMD5Hash(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hash = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();

        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        System.out.println("MD5 Hash: " + hexString.toString());
    }

    public static void retryWithExponentialBackoff(String input, int maxRetries) throws Exception {
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                validateMD5Hash(input);
                return;
            } catch (Exception e) {
                if (attempt == maxRetries) throw e;

                // Random delay between attempts
                int delay = (int) Math.pow(2, attempt) * 1000;
                Thread.sleep(delay);
            }
        }
    }

    public static void main(String[] args) {
        try {
            retryWithExponentialBackoff("testString", 3);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
