// Java component code for MD5 hash computation and validation with retry logic

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private boolean validateHash = true;

    public String computeAndValidateMD5(String input) {
        if (!validateHash) return null;

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();

        } catch (NoSuchAlgorithmException e) {
            // Handle the exception
            return null;
        }
    }

    public void enableHashValidation(boolean enable) {
        this.validateHash = enable;
    }

    private String retryWithExponentialBackoff(String input, int maxRetries) {
        for (int i = 0; i <= maxRetries; i++) {
            String result = computeAndValidateMD5(input);
            if (result != null) return result;

            try {
                TimeUnit.SECONDS.sleep((long) Math.pow(2, i));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return null; // Return null on failure
    }

    public String computeAndValidateMD5WithRetries(String input, int maxRetries) {
        return retryWithExponentialBackoff(input, maxRetries);
    }
}
