#include <pthread.h>
#include <time.h>

typedef struct {
    int socket_id;
    char connection_state[20];
    time_t timestamp;
} ConnectionStatus;

typedef struct Node {
    ConnectionStatus data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex;

void initializeConnectionList() {
    pthread_mutex_init(&mutex, NULL);
}

void addConnectionStatus(int socket_id, const char* connection_state) {
    pthread_mutex_lock(&mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data.socket_id = socket_id;
    strcpy(newNode->data.connection_state, connection_state);
    newNode->data.timestamp = time(NULL);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutex);
}

void clearConnectionList() {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&mutex);
}
