    public static void logTimeTaken(String task, long startTime) {
        try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
            writer.write(task + ": " + (System.currentTimeMillis() - startTime) + " ms\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static String getTCPConnectionStatus(String address, int port, boolean validateResponse) {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            long startTime = System.currentTimeMillis();
            try {
                InetAddress inetAddress = InetAddress.getByName(address);
                if (!inetAddress.isReachable(500)) {
                    logTimeTaken("Connectivity check", startTime);
                    return "Connection not reachable";
                }
                // Simulate connection status retrieval
                String status = (validateResponse) ? "Active" : "Status from external service";
                logTimeTaken("Service response validation", startTime);
                return status;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES - 1) {
                    logTimeTaken("Service unavailability", startTime);
                    throw new RuntimeException("Failed to retrieve connection details after " + MAX_RETRIES + " attempts");
                }
                try {
                    TimeUnit.SECONDS.sleep((long) (Math.random() * 3));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        return null;
    }

