```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    TCP_STATE_IDLE,
    TCP_STATE_CONNECTING,
    TCP_STATE_ESTABLISHED,
    TCP_STATE_CLOSING,
    TCP_STATE_CLOSED,
    TCP_STATE_TIME_WAIT
} TcpState;

typedef struct {
    int socket_id;
    TcpState state;
    time_t timestamp;
} TcpConnectionStatus;

typedef struct {
    TcpConnectionStatus *list;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} TcpConnectionList;

TcpConnectionList* tcp_connection_list_create(size_t initial_capacity) {
    TcpConnectionList *list = malloc(sizeof(TcpConnectionList));
    if (list == NULL) return NULL;

    list->capacity = initial_capacity;
    list->count = 0;
    list->list = malloc(initial_capacity * sizeof(TcpConnectionStatus));
    if (list->list == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void tcp_connection_list_destroy(TcpConnectionList *list) {
    if (list != NULL) {
        pthread_mutex_lock(&list->mutex);
        free(list->list);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int tcp_connection_list_add(TcpConnectionList *list, int socket_id, TcpState state) {
    if (list == NULL || list->count >= list->capacity) return -1;

    pthread_mutex_lock(&list->mutex);
    list->list[list->count].socket_id = socket_id;
    list->list[list->count].state = state;
    list->list[list->count].timestamp = time(NULL);
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void tcp_connection_list_clear(TcpConnectionList *list) {
    if (list == NULL) return;

    pthread_mutex_lock(&list->mutex);
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}
