        try {
            TcpConnectionDetails details = getTcpConnectionDetails(address, port);
            System.out.println(details);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static TcpConnectionDetails getTcpConnectionDetails(String address, int port) throws IOException {
        for (int i = 0; i <= MAX_RETRIES; i++) {
            try {
                InetAddress inetAddress = InetAddress.getByName(address);
                long startTime = System.nanoTime();

                // Simulate API call to external monitoring service
                TcpConnectionDetails details = fetchTcpConnectionDetails(inetAddress, port);

                long endTime = System.nanoTime();
                logTimeTaken(startTime, endTime);

                return details;
            } catch (IOException e) {
                if (i == MAX_RETRIES) throw e;

                try {
                    Thread.sleep(RETRY_DELAY_MIN + (long) (Math.random() * RETRY_DELAY_MAX));
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new IOException("Interrupted while retrying", ie);
                }
            }
        }

        return null;
    }

