import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashValidator {

    private static final Map<String, String> cache = new HashMap<>();
    private static final int MAX_CACHE_SIZE = 1000;
    private static final int RETRY_LIMIT = 3;
    private static final long CACHE_EXPIRATION_MS = 60 * 60 * 1000; // 1 hour

    public String validateHash(String input) {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        for (int i = 0; i < RETRY_LIMIT; i++) {
            try {
                String hash = calculateMd5(input);
                cache.put(input, hash);
                clearCache();
                return hash;
            } catch (Exception e) {
                // Log the failure information
            }
        }

        throw new RuntimeException("Failed to validate hash after multiple retries");
    }

    private String calculateMd5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void clearCache() {
        long currentTime = System.currentTimeMillis();
        cache.entrySet().removeIf(entry -> currentTime - entry.getValue().getTimestamp() > CACHE_EXPIRATION_MS);
    }
}
