// C code for managing a lock-free queue of network connection requests

#include <stdatomic.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct Connection {
    int clientID;
    char *ipAddress;
    int portNumber;
} Connection;

typedef struct Node {
    Connection data;
    atomic_flag locked = ATOMIC_FLAG_INIT;
    struct Node *next;
} Node;

typedef struct Queue {
    Node *front, *rear;
    atomic_int size;
} Queue;

void initQueue(Queue *q) {
    q->front = q->rear = NULL;
    atomic_init(&q->size, 0);
}

bool isQueueEmpty(Queue *q) {
    return (q->front == NULL);
}

int getSize(Queue *q) {
    return atomic_load(&q->size);
}

void enqueue(Queue *q, Connection conn) {
    Node *temp = (Node*)malloc(sizeof(Node));
    temp->data = conn;
    temp->next = NULL;

    while (atomic_flag_test_and_set(&temp->locked)) {}

    if (isQueueEmpty(q)) {
        q->front = q->rear = temp;
    } else {
        q->rear->next = temp;
        q->rear = temp;
    }

    atomic_fetch_add(&q->size, 1);
    atomic_flag_clear(&temp->locked);
}

void dequeue(Queue *q) {
    if (isQueueEmpty(q)) return;

    Node *temp = q->front;

    while (atomic_flag_test_and_set(&temp->locked)) {}

    if (q->front == q->rear) {
        q->front = q->rear = NULL;
    } else {
        q->front = temp->next;
    }

    atomic_fetch_sub(&q->size, 1);
    free(temp);
}

void flushQueue(Queue *q) {
    while (!isQueueEmpty(q)) {
        dequeue(q);
    }
}
