# Python script for processing URLs and fetching HTTP headers

import requests
from time import sleep
from logging import getLogger, basicConfig, INFO
from urllib.parse import urlparse

basicConfig(filename='url_fetch.log', level=INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = getLogger(__name__)

def fetch_url(url, max_retries=3):
    headers = {
        'User-Agent': 'Custom User Agent'
    }
    for _ in range(max_retries + 1):
        try:
            response = requests.get(url, headers=headers, timeout=5)
            return response
        except requests.RequestException as e:
            logger.error(f"Failed to fetch {url}: {e}")
            sleep(0.1 * (2 ** (_ - 1)))
    return None

def process_urls(urls, check_status_codes=True):
    for url in urls:
        parsed_url = urlparse(url)
        if not all([parsed_url.scheme, parsed_url.netloc]):
            logger.error(f"Invalid URL: {url}")
            continue

        response = fetch_url(url)
        if response is not None:
            logger.info(f"Fetched {url} with status code {response.status_code}")
            if check_status_codes and response.status_code not in [200, 301]:
                logger.warning(f"Unexpected status code for {url}: {response.status_code}")

# Example usage
urls = [
    "http://example.com",
    "https://www.example.org",
    "ftp://invalid-url"
]
process_urls(urls, check_status_codes=True)
