NFAPI_CRC_INDICATION_PDU_T** crc_indications = NULL;
int current_size = 0;
int max_size = MAX_N;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_crc_indications() {
    pthread_mutex_lock(&lock);
    if (crc_indications == NULL) {
        crc_indications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        for (int i = 0; i < max_size; i++) {
            crc_indications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&lock);
            return;
        }
    } else {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "CRC indications already initialized.\n");
    }
}

void update_crc_indication(int N) {
    if (N > max_size) {
        pthread_mutex_lock(&lock);
        if (N > MAX_N) {
            pthread_mutex_unlock(&lock);
            fprintf(stderr, "Input exceeds maximum allowed value.\n");
            return;
        }
        max_size = N;
        crc_indications = realloc(crc_indications, max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        for (int i = current_size; i < max_size; i++) {
            crc_indications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        crc_indications[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        crc_indications[i]->RNTI = rand();
        crc_indications[i]->CRC_INDICATION_REL8_TAG = rand() % 100;
        crc_indications[i]->CRCFLAG = (rand() % 2) ? 1 : 0;
    }
    current_size = N;
    pthread_mutex_unlock(&lock);
}

void free_crc_indications() {
    pthread_mutex_lock(&lock);
    if (crc_indications != NULL) {
        for (int i = 0; i < max_size; i++) {
            free(crc_indications[i]);
        }
        free(crc_indications);
        crc_indications = NULL;
    } else {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "CRC indications not initialized.\n");
    }
}
