NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;
pthread_mutex_t crc_lock;
int current_size = 0, max_size = 0;

void init_crc_indications(int N) {
    if (N > MAX_N) {
        fprintf(stderr, "Error: Input N exceeds maximum allowed value.\n");
        return;
    }
    pthread_mutex_init(&crc_lock, NULL);
    crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    max_size = N;
}

void update_crc_indications(int index) {
    if (index < 0 || index >= current_size) {
        fprintf(stderr, "Error: Invalid index for CRC indication.\n");
        return;
    }
    pthread_mutex_lock(&crc_lock);
    crc_indication_list[index].CRCFLAG = rand() % 256; // Randomly update CRCFLAG
    pthread_mutex_unlock(&crc_lock);
}

void allocate_and_update_crc_indications(int N) {
    if (N > max_size) {
        init_crc_indications(N);
    } else {
        current_size = N;
    }

    for (int i = 0; i < current_size; i++) {
        pthread_mutex_lock(&crc_lock);
        crc_indication_list[i].RX_UE_INFORMATION_TAG = i;
