        crc_indication_list[i].CRCFLAG = rand() % 256; // Initialize CRCFLAG
        crc_indication_list[i].CRC_INDICATION_REL8_TAG = i * 100;
        pthread_mutex_unlock(&crc_lock);
    }
}

void cleanup_crc_indications() {
    pthread_mutex_destroy(&crc_lock);
    free(crc_indication_list);
