typedef struct {
    int64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int main() {
    const int64_t INT64_MAX = 9223372036854775807;
    const int64_t INT64_MIN = -9223372036854775808;

    int count = 0;
    int valid_count = 0;
    int *input_array = NULL;
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_list = NULL;
    int largest_int = INT_MIN;
    char input[1024];
    int64_t value;

    // Read integers from standard input
    while (fgets(input, sizeof(input), stdin)) {
        for (char *p = input; *p != '\0'; p++) {
            if (*p == ' ') continue;
            if (!isdigit(*p) && *p != '-' && *p != '+') {
                continue;
            }
            char buffer[20];
            int pos = 0;
            while (isdigit(*p) || *p == '-' || *p == '+') {
                buffer[pos++] = *p++;
            }
            buffer[pos] = '\0';
            if (sscanf(buffer, "%lld", &value) != 1) continue;
            if (value < INT64_MIN || value > INT64_MAX) {
                fprintf(stderr, "Error: Integer out of range.\n");
                exit(1);
            }
            valid_count++;
            count++;
        }
    }

    // Allocate memory for input array
    input_array = (int *)malloc(valid_count * sizeof(int));
    if (!input_array) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Allocate memory for NFAPI list
    nfaapi_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(valid_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaapi_list) {
        perror("Memory allocation failed");
        free(input_array);
        exit(1);
    }

    // Populate input array and NFAPI list
    rewind(stdin);
    while (fgets(input, sizeof(input), stdin)) {
        for (char *p = input; *p != '\0'; p++) {
            if (*p == ' ') continue;
            if (!isdigit(*p) && *p != '-' && *p != '+') {
                continue;
            }
            char buffer[20];
            int pos = 0;
            while (isdigit(*p) || *p == '-' || *p == '+') {
                buffer[pos++] = *p++;
            }
            buffer[pos] = '\0';
            if (sscanf(buffer, "%lld", &value) != 1) continue;
            input_array[count - valid_count] = (int)value;
            nfaapi_list[count - valid_count].RX_UE_INFORMATION_TAG = count - valid_count + 1;
            nfaapi_list[count - valid_count].RNTI = (uint16_t)(count - valid_count);
            nfaapi_list[count - valid_count].CRC_INDICATION_REL8_TAG = rand() % 256;
            largest_int = value > largest_int ? value : largest_int;
        }
    }

    // Free dynamically allocated memory
    free(input_array);
    free(nfaapi_list);

    printf("Total valid integers processed: %d\n", valid_count);
    printf("Largest integer found: %d\n", largest_int);
    return 0;
}
