#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define L2_HEADER_SIZE 4
#define L2_PAYLOAD_SIZE 100
#define MAX_INPUT_SIZE (1 * 1024 * 1024 * 1024) // 1 GB

typedef struct {
    uint8_t header[L2_HEADER_SIZE];
    uint8_t payload[L2_PAYLOAD_SIZE];
} L2_FRAME;

int process_input() {
    char input[MAX_INPUT_SIZE + 1];
    if (!fgets(input, sizeof(input), stdin)) {
        return 0;
    }

    L2_FRAME *frames = (L2_FRAME *)malloc(sizeof(L2_FRAME) * MAX_INPUT_SIZE);
    int valid_count = 0;
    int longest_length = 0;

    for (const char *ptr = input; ptr < input + strlen(input);) {
        if (*ptr == '0' && *(ptr + 1) == 'x') {
            // Skip the '0x' prefix
            ptr += 2;

            int length = 0;
            while (isxdigit(*ptr)) {
                length++;
                ptr++;
            }

            if (length > 0 && (length % 2 == 0 || length == L2_HEADER_SIZE || length <= L2_PAYLOAD_SIZE * 2)) {
                uint8_t *data = (uint8_t *)malloc((length / 2) * sizeof(uint8_t));
                sscanf(ptr, "%hhx", data);

                if (length == L2_HEADER_SIZE + L2_PAYLOAD_SIZE * 2) {
                    memcpy(frames[valid_count].header, data, L2_HEADER_SIZE);
                    memcpy(frames[valid_count].payload, data + L2_HEADER_SIZE, L2_PAYLOAD_SIZE);
                } else if (length == L2_HEADER_SIZE) {
                    memcpy(frames[valid_count].header, data, length);
                }

                free(data);

                valid_count++;
                if (length > longest_length) {
                    longest_length = length;
                }
            }
        } else {
            ptr++;
        }
    }

    for (int i = 0; i < valid_count; i++) {
        free(&frames[i]);
    }

    free(frames);

    printf("Total valid hexadecimal strings processed: %d\n", valid_count);
    printf("Length of the longest byte sequence found: %d\n", longest_length);

    return longest_length;
}
