#define L2_FRAME_SIZE 1500

typedef struct {
    char header[6];
    char payload[L2_FRAME_SIZE - 8];
} L2_HEADER;

typedef struct {
    L2_HEADER header;
    unsigned int timestamp_ms;
} L2_FRAME;

int validate_hex_string(const char *hex_str) {
    while (*hex_str) {
        if (((*hex_str >= '0' && *hex_str <= '9') ||
             (*hex_str >= 'A' && *hex_str <= 'F') ||
             (*hex_str >= 'a' && *hex_str <= 'f'))) {
            hex_str++;
        } else {
            return 0;
        }
    }
    return 1;
}

int convert_hex_to_binary(const char *hex_str, unsigned char **binary_data) {
    size_t len = strlen(hex_str);
    if (len % 2 != 0) {
        return -1;
    }
    *binary_data = (unsigned char *)malloc(len / 2);
    for (size_t i = 0; i < len; i += 2) {
        (*binary_data)[i / 2] = (hex_str[i] <= '9' ? hex_str[i] - '0' : toupper(hex_str[i]) - 'A' + 10) << 4 |
                                 (hex_str[i + 1] <= '9' ? hex_str[i + 1] - '0' : toupper(hex_str[i + 1]) - 'A' + 10);
    }
    return len / 2;
}

void generate_histogram(int *histogram, size_t count, size_t max_length) {
    for (size_t i = 0; i < count; i++) {
        histogram[(unsigned char)binary_data[i][0]]++;
    }
}

L2_FRAME* create_and_populate_list(size_t *longest_sequence_length, int *histogram) {
    L2_FRAME *frames = NULL;
    size_t allocated_size = 1000;
    size_t current_count = 0;
    char buffer[4096];
    time_t timestamp;

    frames = (L2_FRAME *)malloc(allocated_size * sizeof(L2_FRAME));
    if (!frames) {
        return NULL;
    }

    while (fgets(buffer, sizeof(buffer), stdin)) {
        size_t len = strlen(buffer);
        if (len > 1 && buffer[len - 1] == '\n') {
            buffer[--len] = '\0';
        }
        if (validate_hex_string(buffer)) {
            unsigned char *binary_data;
            int binary_len = convert_hex_to_binary(buffer, &binary_data);
            if (binary_len != -1) {
                if (current_count >= allocated_size) {
                    allocated_size *= 2;
                    frames = realloc(frames, allocated_size * sizeof(L2_FRAME));
                    if (!frames) {
                        free(binary_data);
                        return NULL;
                    }
                }
                memcpy(&frames[current_count].header, binary_data, len < 8 ? len : 8);
                timestamp = time(NULL);
                frames[current_count].timestamp_ms = (unsigned int)((timestamp - (timestamp / 1000) * 1000) * 1000);
                if (binary_len > *longest_sequence_length) {
                    *longest_sequence_length = binary_len;
                }
                current_count++;
                free(binary_data);
            }
        }
    }

    size_t max_length = current_count ? frames[0].header.length : 0;
    int *histogram = (int *)calloc(max_length, sizeof(int));
    if (!histogram) {
        free(frames);
        return NULL;
    }

    generate_histogram(histogram, current_count, max_length);

    *longest_sequence_length = *longest_sequence_length / 2;
    frames[current_count].header.length = max_length;

    return frames;
}

int main() {
    size_t longest_sequence_length = 0;
    int *histogram = NULL;
    L2_FRAME *frames = create_and_populate_list(&longest_sequence_length, histogram);

    if (frames) {
        printf("Longest sequence length: %zu\n", longest_sequence_length);
        for (size_t i = 0; i < longest_sequence_length; i++) {
            printf("%d ", histogram[i]);
        }
        printf("\n");
        free(frames);
        free(histogram);
    } else {
        printf("Error in processing input.\n");
    }

    return 0;
}
