#include <pthread.h>
#include <stdlib.h>

typedef struct LTE_UE_Context {
    unsigned long IMSI;
    // Add PDCP PDUs here
    struct LTE_UE_Context* next;
} LTE_UE_Context;

typedef struct LTE_UE_List {
    pthread_mutex_t lock;
    LTE_UE_Context* head;
} LTE_UE_List;

LTE_UE_List* create_UE_list() {
    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (list) {
        pthread_mutex_init(&list->lock, NULL);
        list->head = NULL;
    }
    return list;
}

void destroy_UE_list(LTE_UE_List* list) {
    pthread_mutex_lock(&list->lock);
    LTE_UE_Context* current = list->head;
    while (current) {
        LTE_UE_Context* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

LTE_UE_Context* find_UE_context(LTE_UE_List* list, unsigned long IMSI) {
    pthread_mutex_lock(&list->lock);
    LTE_UE_Context* current = list->head;
    while (current && current->IMSI != IMSI) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

int add_or_update_UE_context(LTE_UE_List* list, unsigned long IMSI, /* PDCP PDUs */) {
    LTE_UE_Context* context = find_UE_context(list, IMSI);
    if (context) {
        // Update existing context
        // context->pdcppdus = new_pdcppdus;
    } else {
        pthread_mutex_lock(&list->lock);
        context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
        if (context) {
            context->IMSI = IMSI;
            // Initialize PDCP PDUs
            // context->pdcppdus = new_pdcppdus;
            context->next = list->head;
            list->head = context;
        }
        pthread_mutex_unlock(&list->lock);
    }
    return context ? 0 : -1;
}
