#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 100000
#define MEMORY_POOL_SIZE 1024 * 1024

typedef struct {
    char imsi[16];
    void* pdcp_pdus;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context** contexts;
    size_t size;
    pthread_mutex_t lock;
} UE_Context_Manager;

LTE_UE_Context* create_ue_context(const char* imsi, void* pdcp_pdus) {
    LTE_UE_Context* context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!context) {
        perror("Failed to allocate memory for UE context");
        return NULL;
    }
    strncpy(context->imsi, imsi, sizeof(context->imsi));
    context->pdcp_pdus = pdcp_pdus;
    return context;
}

void destroy_ue_context(LTE_UE_Context* context) {
    if (context) {
        free(context);
    }
}

UE_Context_Manager* create_ue_context_manager() {
    UE_Context_Manager* manager = (UE_Context_Manager*)malloc(sizeof(UE_Context_Manager));
    if (!manager) {
        perror("Failed to allocate memory for UE context manager");
        return NULL;
    }
    manager->contexts = (LTE_UE_Context**)calloc(MAX_UE_CONTEXTS, sizeof(LTE_UE_Context*));
    if (!manager->contexts) {
        free(manager);
        perror("Failed to allocate memory for contexts array");
        return NULL;
    }
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_ue_context_manager(UE_Context_Manager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->size; ++i) {
            destroy_ue_context(manager->contexts[i]);
        }
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_or_update_ue_context(UE_Context_Manager* manager, const char* imsi, void* pdcp_pdus) {
    if (!manager || !imsi) {
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->contexts[i]->imsi, imsi) == 0) {
            destroy_ue_context(manager->contexts[i]);
            manager->contexts[i] = create_ue_context(imsi, pdcp_pdus);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->size >= MAX_UE_CONTEXTS) {
        perror("Maximum number of UE contexts reached");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->contexts[manager->size++] = create_ue_context(imsi, pdcp_pdus);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

LTE_UE_Context* get_ue_context_by_imsi(UE_Context_Manager* manager, const char* imsi) {
    if (!manager || !imsi) {
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->contexts[i]->imsi, imsi) == 0) {
            LTE_UE_Context* context = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int main() {
    UE_Context_Manager* manager = create_ue_context_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create UE context manager\n");
        return 1;
    }

    // Example usage
    LTE_UE_Context* context = create_ue_context("IMSI000000000000001", NULL);
    add_or_update_ue_context(manager, context->imsi, context);

    LTE_UE_Context* retrieved_context = get_ue_context_by_imsi(manager, "IMSI000000000000001");
    if (retrieved_context) {
        printf("Retrieved IMSI: %s\n", retrieved_context->imsi);
    } else {
        fprintf(stderr, "Failed to retrieve UE context\n");
    }

    destroy_ue_context_manager(manager);

    return 0;
}
```

This code provides a basic structure for managing LTE UE contexts with the specified requirements. It includes functions for creating and destroying contexts, adding or updating contexts in a thread-safe manner, and retrieving contexts by IMSI. The use of a mutex ensures that concurrent access to the context manager is controlled safely.

Remember that this is a simplified example, and you should expand upon it to handle memory pooling, integration with an external database, configuration options, error handling, and comprehensive testing as required.']

