typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int initialize_list(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    *list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return -1;
    for (int i = 0; i < N; i++) {
        (*list)[i].CRCFLAG = rand() % 2;
    }
    return 0;
}

void cleanup_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    free(list);
}

int validate_and_populate(NFAPI_CRC_INDICATION_PDU_T* list, int N, int RNTI) {
    if (RNTI < RNTI_MIN || RNTI > RNTI_MAX) return -1;
    for (int i = 0; i < N; i++) {
        list[i].CRCFLAG = rand() % 2;
    }
    return 0;
}

void* send_to_network(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    // Simulate network transmission
    if (rand() % 2 == 0) {
        printf("Transmission failed\n");
        return NULL;
    }
    printf("Transmission successful\n");
    return arg;
}

void thread_manager(NFAPI_CRC_INDICATION_PDU_T* list, int N, int RNTI, int max_threads) {
    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    for (int i = 0; i < N; i++) {
        if (num_threads == max_threads) {
            pthread_join(threads[num_threads - 1], NULL);
            num_threads--;
        }
        if (pthread_create(&threads[num_threads++], NULL, send_to_network, &list[i])) {
            printf("Error creating thread\n");
            return;
        }
    }

    for (; num_threads > 0; num_threads--) {
        pthread_join(threads[num_threads - 1], NULL);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* list;
    int N = 1000, RNTI = 32768, max_threads = MAX_THREADS;

    if (initialize_list(&list, N) != 0) {
        printf("Failed to initialize list\n");
        return -1;
    }

    if (validate_and_populate(list, N, RNTI) != 0) {
        cleanup_list(list, N);
        printf("Validation failed\n");
        return -1;
    }

    thread_manager(list, N, RNTI, max_threads);

    cleanup_list(list, N);
    return 0;
}
