<?php

class ClinicUpdater {
    private $db;
    private $logTable;

    public function __construct($dbConfig, $logTable) {
        $this->db = new PDO("mysql:host={$dbConfig['host']};dbname={$dbConfig['dbname']}", $dbConfig['username'], $dbConfig['password']);
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $this->logTable = $logTable;
    }

    public function updateClinic($clinicId, $newStatus, $lastModifiedIp) {
        try {
            // Begin transaction
            $this->db->beginTransaction();

            // Lock the clinic record to prevent concurrent updates
            $stmtLock = $this->db->prepare("SELECT * FROM clinics WHERE id = :id FOR UPDATE");
            $stmtLock->execute(['id' => $clinicId]);

            // Check if clinic exists
            if ($stmtLock->rowCount() == 0) {
                return json_encode(['success' => false, 'message' => 'Clinic ID does not exist']);
            }

            // Prepare update statement
            $stmtUpdate = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
            $stmtUpdate->execute([
                'status' => $newStatus,
                'ip' => $lastModifiedIp,
                'id' => $clinicId
            ]);

            // Log the update
            $this->logAction($clinicId, 'update', $newStatus);

            // Commit transaction
            $this->db->commit();

            return json_encode(['success' => true, 'message' => 'Clinic updated successfully']);
        } catch (PDOException $e) {
            // Rollback transaction on error
            if ($this->db->inTransaction()) {
                $this->db->rollBack();
            }

            // Log the error
            $this->logAction($clinicId, 'error', $e->getMessage());

            return json_encode(['success' => false, 'message' => 'Error updating clinic: ' . $e->getMessage()]);
        }
    }

    private function logAction($clinicId, $action, $details) {
        $stmtLog = $this->db->prepare("INSERT INTO {$this->logTable} (clinic_id, action, details) VALUES (:id, :action, :details)");
        $stmtLog->execute(['id' => $clinicId, 'action' => $action, 'details' => $details]);
    }
}
