    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 256;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return pdus;
}

PerformanceMetricT* initialize_performance_monitoring(int num_components) {
    PerformanceMetricT* metrics = (PerformanceMetricT*)malloc(num_components * sizeof(PerformanceMetricT));
    if (!metrics) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_components; ++i) {
        metrics[i].component_tag = malloc(50 * sizeof(char)); // Assuming component tag is up to 49 characters long
        if (!metrics[i].component_tag) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        snprintf(metrics[i].component_tag, 50, "Component_%d", i);
        metrics[i].cpu_usage = ((float)(rand() % 100)) / 100.0; // Random float between 0 and 1
        metrics[i].memory_consumption = rand() % (2 * 1024 * 1024); // Random memory consumption in bytes up to 2 MB
        metrics[i].disk_io = rand() % 100; // Random disk I/O value
        metrics[i].network_throughput = ((double)(rand() % 100)) / 1.0; // Random network throughput value between 0 and 100
    }

    return metrics;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T* pdus, int N, PerformanceMetricT* metrics, int num_components) {
    for (int i = 0; i < num_components; ++i) {
        free(metrics[i].component_tag);
    }
    free(pdus);
    free(metrics);
}

int main() {
    int N = 10;
    int num_components = 5;

    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_NFAPI_CRC_PDUs(N);
    if (pdus) {
        PerformanceMetricT* metrics = initialize_performance_monitoring(num_components);
        if (metrics) {
            // Use pdus and metrics as needed
            free_memory(pdus, N, metrics, num_components);
        } else {
            printf("Failed to initialize performance monitoring\n");
            free(pdus);
        }
    } else {
        printf("Failed to generate NFAPI CRC PDUs\n");
    }

    return 0;
}
