#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_FILES 1000
#define LOG_FILE "file_processor.log"

typedef struct {
    int id;
    time_t timestamp;
    int status; // 0: success, 1: failure
} FILE_PROCESS_RECORD;

void log_message(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int generate_file_records(FILE_PROCESS_RECORD** records, int* count, CURL* curl_handle) {
    *count = 0;
    for (int i = 0; i < MAX_FILES; i++) {
        records[i].id = i + 1;
        records[i].timestamp = time(NULL);
        records[i].status = rand() % 2;

        if (records[i].status == 0 && curl_easy_perform(curl_handle) != CURLE_OK) {
            log_message("Network error: Failed to send file record");
            free(records);
            return -1;
        }

        (*count)++;
    }
    return 0;
}

int main() {
    CURL* curl = curl_easy_init();
    if (curl == NULL) {
        log_message("Error initializing libcurl");
        return -1;
    }

    FILE_PROCESS_RECORD** records = malloc(sizeof(FILE_PROCESS_RECORD*) * MAX_FILES);
    int count;

    int result = generate_file_records(records, &count, curl);
    if (result != 0) {
        free(records);
        curl_easy_cleanup(curl);
        return -1;
    }

    for (int i = 0; i < count; i++) {
        log_message("Processed file: ID = %d, Timestamp = %s, Status = %d", 
                      records[i].id, ctime(&records[i].timestamp), records[i].status);
    }

    free(records);
    curl_easy_cleanup(curl);
    return 0;
}
