```python
import json
import logging
from threading import Lock
from queue import Queue
import time

class FileProcessor:
    def __init__(self, config_file_path, max_threads=5):
        self.config = self.load_config(config_file_path)
        self.lock = Lock()
        self.queue = Queue(maxsize=max_threads)

    def load_config(self, file_path):
        try with open(file_path, 'r') as file:
            return json.load(file)
        except FileNotFoundError:
            logging.error(f"Error: Config file not found at {file_path}")
            return {}
        except json.JSONDecodeError:
            logging.error("Error: Invalid JSON in config file")
            return {}

    def process_file(self):
        while True:
            record = self.queue.get()
            if record is None:
                break
            # Simulate processing
            time.sleep(0.1)
            logging.info(f"Processed file: ID = {record['id']}, Timestamp = {record['timestamp']}, Status = {record['status']}")

    def start_processing(self, records):
        for _ in range(self.max_threads):
            thread = threading.Thread(target=self.process_file)
            thread.start()

        for record in records:
            self.queue.put(record)

        for _ in range(self.max_threads):
            self.queue.put(None)

        self.queue.join()
```

