        records->data = realloc(records->data, (records->size + 1) * sizeof(TCP_CONNECTION_RECORD_T));
        if (!records->data) {
            log_message(ERROR, "Failed to allocate memory for connection records");
            free_connection_record(record);
            return -1;
        }
        memcpy(&((TCP_CONNECTION_RECORD_T*)records->data)[records->size], record, sizeof(TCP_CONNECTION_RECORD_T));
        free_connection_record(record);
