public class DynamicBinaryFileProcessor {
    private int _minValue;
    private int _maxValue;

    public DynamicBinaryFileProcessor(int minValue, int maxValue) {
        if (minValue >= maxValue) {
            throw new ArgumentOutOfRangeException("Invalid range: minValue must be less than maxValue.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat() {
        return (float) (_minValue + ((double)(new Random().Next()) / int.MaxValue) * (_maxValue - _minValue));
    }

    public int GenerateRandomInt() {
        return _minValue + (int)((_maxValue - _minValue + 1) * (new Random().NextDouble()));
    }

    public void ShrinkRange(double shrinkFactor) {
        _maxValue = (int)(_maxValue * shrinkFactor);
        if (_maxValue < _minValue) _maxValue = _minValue;
    }

    public void ExpandRange(double expandFactor) {
        _minValue = (int)(_minValue / expandFactor);
        if (_maxValue < _minValue) _minValue = _maxValue;
    }

    public void ProcessFile(string inputFilePath, string outputFilePath, string[] transformations) {
        try {
