#include <mutex>

class DynamicDataProcessor {
private:
    double _minValue, _maxValue;
    std::mt19937 _generator;
    std::uniform_real_distribution<double> _distribution;
    std::mutex _mutex;

public:
    DynamicDataProcessor(double minValue, double maxValue) : _minValue(minValue), _maxValue(maxValue) {
        if (_minValue >= _maxValue) throw std::invalid_argument("Invalid range");
        _generator = std::mt19937(std::random_device{}());
        _distribution = std::uniform_real_distribution<double>(_minValue, _maxValue);
    }

    double GenerateRandomFloat() {
        return _distribution(_generator);
    }

    int GenerateRandomInt() {
        while (true) {
            int value = static_cast<int>(GenerateRandomFloat() * (_maxValue - _minValue)) + static_cast<int>(_minValue);
            if (value % 3 == 0) return value;
        }
    }

    void ShrinkRange(double decreaseFactor, double increaseFactor) {
        std::lock_guard<std::mutex> lock(_mutex);
        _minValue *= decreaseFactor;
        _maxValue *= increaseFactor;
        if (_minValue < 0 || _maxValue > 1) throw std::invalid_argument("Invalid range after shrink");
    }

    void ProcessStream(std::istream& input, std::ostream& output, const std::string& configFilePath) {
