        metrics[i].memory_consumption = ((size_t)rand() / RAND_MAX) * 1024 * 1024 * 1024; // in bytes
        metrics[i].disk_io = ((double)rand() / RAND_MAX) * 100;
        metrics[i].network_throughput = ((double)rand() / RAND_MAX) * 1000; // in Mbps
    }

    return metrics;
}

// Function to simulate system monitoring updates
void* update_performance_metrics(void* arg) {
    PerformanceMetric** metrics_ptr = (PerformanceMetric**)arg;
    PerformanceMetric* metrics = *metrics_ptr;

    while (1) {
        for (int i = 0; i < num_components; i++) {
            // Simulate updating metrics with new values
            metrics[i].cpu_usage += ((double)rand() / RAND_MAX) * 2 - 1;
            metrics[i].memory_consumption += ((size_t)rand() / RAND_MAX) * 1024 * 1024; // in bytes
            metrics[i].disk_io += ((double)rand() / RAND_MAX) * 5;
            metrics[i].network_throughput += ((double)rand() / RAND_MAX) * 50; // in Mbps

            // Ensure values stay realistic
            if (metrics[i].cpu_usage > 100) metrics[i].cpu_usage = 100;
            if (metrics[i].memory_consumption > 16ULL * 1024 * 1024 * 1024) metrics[i].memory_consumption = 16ULL * 1024 * 1024 * 1024; // 16GB
            if (metrics[i].disk_io > 100) metrics[i].disk_io = 100;
            if (metrics[i].network_throughput > 1000) metrics[i].network_throughput = 1000; // 1Gbps
        }

        sleep(1); // Update frequency
    }

    return NULL;
}

int main() {
    int N = 10; // Number of CRC indications
    int num_components = 5; // Number of performance metrics components

    NFAPI_CRC_INDICATION_PDU_T* crc_array = generate_crc_indications(N);
    if (crc_array == NULL) {
        return -1;
    }

    PerformanceMetric* metrics = init_performance_monitoring(num_components);
    if (metrics == NULL) {
        free(crc_array);
        return -1;
    }

    pthread_t monitoring_thread;
    if (pthread_create(&monitoring_thread, NULL, update_performance_metrics, &metrics) != 0) {
        perror("Failed to create performance monitoring thread");
        free(crc_array);
        free(metrics);
        return -1;
    }

    // Join the monitoring thread
    pthread_join(monitoring_thread, NULL);

    free(crc_array);
    free(metrics);

    return 0;
}
