<?php

function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    global $dbConnection; // Assume this is initialized elsewhere
    $maxRetries = 3;
    $retryDelay = 2; // in seconds
    $logTable = 'audit_logs';

    for ($attempt = 0; $attempt <= $maxRetries; $attempt++) {
        try {
            $dbConnection->beginTransaction();

            // Lock the clinic record to prevent concurrent updates
            $stmtLock = $dbConnection->prepare("SELECT * FROM clinics WHERE id = :id FOR UPDATE");
            $stmtLock->execute(['id' => $clinicId]);

            if ($stmtLock->rowCount() == 0) {
                $stmtInsert = $dbConnection->prepare("INSERT INTO clinics (id, status, last_modified_ip, last_modified_date) VALUES (:id, :status, :ipAddress, NOW())");
                $stmtInsert->execute(['id' => $clinicId, 'status' => $newStatus, 'ipAddress' => $ipAddress]);
            } else {
                $stmtUpdate = $dbConnection->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified_date = NOW() WHERE id = :id");
                $stmtUpdate->execute(['status' => $newStatus, 'ipAddress' => $ipAddress, 'id' => $clinicId]);
            }

            $dbConnection->commit();
            return json_encode(['success' => true, 'message' => 'Clinic status updated successfully']);
        } catch (PDOException $e) {
            if ($attempt == $maxRetries) {
                logError($e->getMessage(), $logTable);
                return json_encode(['success' => false, 'error' => 'Max retries exceeded. Please try again later.']);
            }
            $dbConnection->rollBack();
            sleep($retryDelay);
        } catch (Exception $e) {
            if ($attempt == $maxRetries) {
                logError($e->getMessage(), $logTable);
                return json_encode(['success' => false, 'error' => 'An unexpected error occurred. Please try again later.']);
            }
            sleep($retryDelay);
        }
    }
}

function logError($message, $table) {
    global $dbConnection; // Assume this is initialized elsewhere
    $stmt = $dbConnection->prepare("INSERT INTO $table (error_message, timestamp) VALUES (:message, NOW())");
    $stmt->execute(['message' => $message]);
}
