pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and populate the dynamic list
int initialize_and_populate_list(uint32_t N, LogLevel log_level) {
    pthread_mutex_lock(&mutex);
    // Allocate memory for the list
    list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand(time(NULL));
    uint32_t valid_rnti_range_min = 0x0001;
    uint32_t valid_rnti_range_max = 0xFFFF;

    for (uint32_t i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            for (uint32_t j = 0; j < i; j++)
                free(list[j]);
            free(list);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Populate the structure with random values within valid ranges
        list[i]->ue_info.ue_id = rand() % 10000;
        list[i]->rnti.value = valid_rnti_range_min + (rand() % (valid_rnti_range_max - valid_rnti_range_min + 1));
        list[i]->crc_indication.crc_value = rand() % 100;
        list[i]->crcflag = rand() % 2; // Randomly set CRCFLAG

        // Log the operation
        log_message(log_level, "Populated structure at index %u with CRCFLAG: %u", i, list[i]->crcflag);
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to send each structure to the network layer
int send_to_network() {
    for (uint32_t i = 0; i < list_size; i++) {
        if (send_to_network_layer(list[i]) != 0) {
            // Log error and clean up
            log_message(ERROR, "Failed to send PDU at index %u to network layer", i);
            for (uint32_t j = 0; j <= i; j++)
                free(list[j]);
            free(list);
            return -1;
        }
    }
    return 0;
}

// Function to log messages
void log_message(LogLevel level, const char *message, ...) {
    va_list args;
    va_start(args, message);

    switch (level) {
        case DEBUG:
            printf("[DEBUG] ");
            break;
        case INFO:
            printf("[INFO] ");
            break;
        case WARNING:
            printf("[WARNING] ");
            break;
        case ERROR:
            printf("[ERROR] ");
            break;
    }

    vprintf(message, args);
    printf("\n");

    va_end(args);
}

// Function to free allocated resources
void cleanup() {
    for (uint32_t i = 0; i < list_size; i++)
        free(list[i]);
    free(list);
}

// Main function to demonstrate the usage of the functions
int main() {
    uint32_t N = 10;
    LogLevel log_level = INFO;

    if (initialize_and_populate_list(N, log_level) != 0) {
        printf("Initialization failed\n");
        return -1;
    }

    if (send_to_network() != 0) {
        printf("Network sending failed\n");
        cleanup();
        return -1;
    }

    cleanup();
    return 0;
}
