    EXECUTION_STATUS: str = "EXECUTION_STATUS"
    TRADE_PRICE: str = "TRADE_PRICE"

    @abstractmethod
    def parse_event(self, data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def create_json_object(self) -> Dict[str, Any]:
        pass

class StreamAPIFinancialEventProcessor(FinancialEventProcessor):
    def parse_event(self, data: Dict[str, Any]) -> None:
        # Parse event from streaming API
        self.ORDER_ID = data.get("order_id")
        self.EXECUTION_STATUS = data.get("execution_status")
        self.TRADE_PRICE = data.get("trade_price")

    def create_json_object(self) -> Dict[str, Any]:
        return {
            "ORDER_ID": self.ORDER_ID,
            "EXECUTION_STATUS": self.EXECUTION_STATUS,
            "TRADE_PRICE": self.TRADE_PRICE
        }

class HistoricalDBFinancialEventProcessor(FinancialEventProcessor):
    def parse_event(self, data: Dict[str, Any]) -> None:
        # Parse event from historical database
        self.ORDER_ID = data.get("order_id")
        self.EXECUTION_STATUS = data.get("execution_status")
        self.TRADE_PRICE = data.get("trade_price")

    def create_json_object(self) -> Dict[str, Any]:
        return {
            "ORDER_ID": self.ORDER_ID,
            "EXECUTION_STATUS": self.EXECUTION_STATUS,
            "TRADE_PRICE": self.TRADE_PRICE
        }

class FinancialEventProcessorFactory:
    _registry: Dict[int, Type[FinancialEventProcessor]] = {}

    @staticmethod
    def register_factory(id: int, cls: Type[FinancialEventProcessor]) -> None:
        FinancialEventProcessorFactory._registry[id] = cls

    @staticmethod
    def create_instance(id: int, data: Dict[str, Any]) -> Optional[FinancialEventProcessor]:
        if id in FinancialEventProcessorFactory._registry:
            processor = FinancialEventProcessorFactory._registry[id]()
            processor.parse_event(data)
            return processor
        else:
            return None

# Example usage
FinancialEventProcessorFactory.register_factory(1, StreamAPIFinancialEventProcessor)
event_processor = FinancialEventProcessorFactory.create_instance(1, {"order_id": "123", "execution_status": "completed", "trade_price": 150.75})
if event_processor:
    json_object = event_processor.create_json_object()
    print(json.dumps(json_object))
