#define MAX_ELEMENTS 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t mutex;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (list == NULL) {
        return NULL;
    }
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(CRCList* list) {
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_crc_list(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = list->elements[i];
            memmove(list->elements + i, list->elements + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->count - i - 1));
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

