#define MAX_LIST_SIZE 5000

typedef struct LTE_PHY_RX_FRAME {
    PHY_FRAME_INFO info;
    CHANNEL_ID channel_id;
    RECEPTION_STATUS status;
} LTE_PHY_RX_FRAME;

typedef struct ListNode {
    LTE_PHY_RX_FRAME data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    ListNode* head;
    pthread_mutex_t mutex;
    int size;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    return list;
}

void destroy_list(List* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_frame(List* list, LTE_PHY_RX_FRAME frame) {
    if (list->size >= MAX_LIST_SIZE) return -1;

    pthread_mutex_lock(&list->mutex);

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = frame;
    new_node->next = NULL;

    if (!list->head || list->head->data.channel_id > frame.channel_id) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        ListNode* current = list->head;
        while (current->next && current->next->data.channel_id < frame.channel_id) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int check_frame_integrity(LTE_PHY_RX_FRAME* frame) {
    // Assume this function performs integrity checks using an external library
    if (signal_processing_library_check(frame)) {
        return 0; // Frame is valid
    }
    return -1; // Frame is invalid
}

void test_insertion(List* list, LTE_PHY_RX_FRAME frames[], int count) {
    for (int i = 0; i < count; i++) {
        if (insert_frame(list, frames[i]) != 0) {
            printf("Failed to insert frame %d\n", i);
        }
    }
}

void test_concurrency(List* list, LTE_PHY_RX_FRAME frames[], int count, int threads) {
    pthread_t* thread_ids = (pthread_t*)malloc(threads * sizeof(pthread_t));
    if (!thread_ids) return;

    for (int i = 0; i < threads; i++) {
        pthread_create(&thread_ids[i], NULL, (void*)(insert_frame), list, &frames[i * count / threads]);
    }

    for (int i = 0; i < threads; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    free(thread_ids);
}

int main() {
    LTE_PHY_RX_FRAME frames[MAX_LIST_SIZE];
    // Populate frames array with valid data

    List* list = create_list();
    if (!list) return -1;

    test_insertion(list, frames, MAX_LIST_SIZE);

    test_concurrency(list, frames, MAX_LIST_SIZE, 4);

    destroy_list(list);
    return 0;
}
