import java.nio.file.*;
import java.security.MessageDigest;
import java.time.LocalDateTime;
import java.util.concurrent.ConcurrentHashMap;

public class LogArchiveManager {
    private static final ConcurrentHashMap<String, Path> archiveLocations = new ConcurrentHashMap<>();
    private static final String ARCHIVE_BASE_DIR = "/path/to/archive/directory";
    private static final int THREAD_POOL_SIZE = 10;

    public void processLogEntry(String logEntry) {
        try {
            byte[] compressedData = compress(logEntry.getBytes());
            byte[] encryptedData = encrypt(compressedData);
            Path archivePath = getArchivePath(LocalDateTime.now());
            Files.write(archivePath, encryptedData, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            handleException(e);
        }
    }

    private Path getArchivePath(LocalDateTime timestamp) {
        String year = Integer.toString(timestamp.getYear());
        String month = String.format("%02d", timestamp.getMonthValue());
        String day = String.format("%02d", timestamp.getDayOfMonth());
        String hour = String.format("%02d", timestamp.getHour());

        Path yearlyDir = archiveLocations.computeIfAbsent(year, k -> Paths.get(ARCHIVE_BASE_DIR, year));
        Path monthlyDir = archiveLocations.computeIfAbsent(year + "-" + month, k -> Paths.get(yearlyDir.toString(), month));
        Path dailyDir = archiveLocations.computeIfAbsent(year + "-" + month + "-" + day, k -> Paths.get(monthlyDir.toString(), day));
        Path hourlyDir = archiveLocations.computeIfAbsent(year + "-" + month + "-" + day + "-" + hour, k -> Paths.get(dailyDir.toString(), hour));

        return hourlyDir;
    }

    private byte[] compress(byte[] data) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             DeflaterOutputStream dos = new DeflaterOutputStream(bos)) {
            dos.write(data);
            dos.finish();
            dos.flush();
            return bos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Compression failed", e);
        }
    }

    private byte[] encrypt(byte[] data) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(data);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Encryption algorithm not found", e);
        }
    }

    private void handleException(Exception e) {
        // Implement robust error handling mechanism here
        System.err.println("Error processing log entry: " + e.getMessage());
    }

    public static void main(String[] args) {
        LogArchiveManager manager = new LogArchiveManager();
        for (int i = 0; i < 10000; i++) {
            manager.processLogEntry("Sample log entry " + i);
        }
    }
}
