#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    char SSID[64];
    char BSSID[18];
    int CONNECTIVITY_STATUS;
    int SECURITY_TYPE;
} WIFI_AP_CONNECTION;

typedef struct {
    WIFI_AP_CONNECTION *list[MAX_LIST_SIZE];
    size_t count;
    pthread_mutex_t lock;
} AP_LIST;

AP_LIST* create_ap_list() {
    AP_LIST *ap_list = (AP_LIST*)malloc(sizeof(AP_LIST));
    if (!ap_list) return NULL;
    ap_list->count = 0;
    pthread_mutex_init(&ap_list->lock, NULL);
    return ap_list;
}

void destroy_ap_list(AP_LIST *ap_list) {
    for (size_t i = 0; i < ap_list->count; ++i) {
        free(ap_list->list[i]);
    }
    pthread_mutex_destroy(&ap_list->lock);
    free(ap_list);
}

int add_connection(AP_LIST *ap_list, WIFI_AP_CONNECTION *conn) {
    pthread_mutex_lock(&ap_list->lock);
    if (ap_list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&ap_list->lock);
        return -1; // List is full
    }
    size_t index = ap_list->count;
    for (; index > 0 && strcmp(ap_list->list[index - 1]->SSID, conn->SSID) > 0; --index) {
        ap_list->list[index] = ap_list->list[index - 1];
    }
    ap_list->list[index] = (WIFI_AP_CONNECTION*)malloc(sizeof(WIFI_AP_CONNECTION));
    if (!ap_list->list[index]) {
        pthread_mutex_unlock(&ap_list->lock);
        return -2; // Memory allocation failed
    }
    memcpy(ap_list->list[index], conn, sizeof(WIFI_AP_CONNECTION));
    ++ap_list->count;
    pthread_mutex_unlock(&ap_list->lock);
    return 0;
}

int find_connection(AP_LIST *ap_list, const char *SSID) {
    pthread_mutex_lock(&ap_list->lock);
    for (size_t i = 0; i < ap_list->count; ++i) {
        if (!strcmp(ap_list->list[i]->SSID, SSID)) {
            pthread_mutex_unlock(&ap_list->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&ap_list->lock);
    return -1; // Connection not found
}

