#define MAX_LIST_SIZE 1000

typedef struct {
    WIFI_AP_CONNECTION ap;
    pthread_mutex_t lock;
} WIFI_AP_ENTRY;

typedef struct {
    WIFI_AP_ENTRY entries[MAX_LIST_SIZE];
    int size;
    pthread_mutex_t list_lock;
} WIFI_AP_LIST;

WIFI_AP_LIST wifi_list;

void init_wifi_list() {
    memset(&wifi_list, 0, sizeof(wifi_list));
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        pthread_mutex_init(&wifi_list.entries[i].lock, NULL);
    }
    pthread_mutex_init(&wifi_list.list_lock, NULL);
}

int insert_wifi_ap(const WIFI_AP_CONNECTION *ap) {
    pthread_mutex_lock(&wifi_list.list_lock);
    if (wifi_list.size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&wifi_list.list_lock);
        return -1;
    }

    int index = wifi_list.size;
    for (; index > 0; index--) {
        pthread_mutex_lock(&wifi_list.entries[index-1].lock);
        if (strcmp(ap->SSID, wifi_list.entries[index-1].ap.SSID) < 0) {
            break;
        }
        pthread_mutex_unlock(&wifi_list.entries[index-1].lock);
    }

    for (int i = wifi_list.size; i > index; i--) {
        memcpy(&wifi_list.entries[i], &wifi_list.entries[i-1], sizeof(WIFI_AP_ENTRY));
        pthread_mutex_lock(&wifi_list.entries[i].lock);
    }

    memcpy(&wifi_list.entries[index].ap, ap, sizeof(WIFI_AP_CONNECTION));
    wifi_list.entries[index].ap.CONNECTIVITY_STATUS = check_connectivity(ap->SSID, ap->BSSID);
    wifi_list.size++;
    pthread_mutex_unlock(&wifi_list.list_lock);

    return 0;
}

void *health_check_thread(void *arg) {
    while (1) {
        for (int i = 0; i < wifi_list.size; i++) {
            pthread_mutex_lock(&wifi_list.entries[i].lock);
            WIFI_AP_CONNECTION *ap = &wifi_list.entries[i].ap;
            if (!check_connection_quality(ap->SSID, ap->BSSID)) {
                log_event("Connection quality degraded for SSID: %s", ap->SSID);
            }
            pthread_mutex_unlock(&wifi_list.entries[i].lock);
        }
        sleep(60); // Check every minute
    }
}

void start_health_check() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, health_check_thread, NULL);
}
