#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdatomic.h>

#define MAX_N 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications;
    size_t count;
    atomic_flag lock;
} CRCIndicationList;

void initialize_crc_list(CRCIndicationList* list, size_t N) {
    if (N > MAX_N) {
        fprintf(stderr, "Error: Input exceeds maximum allowed value.\n");
        exit(EXIT_FAILURE);
    }

    list->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->crc_indications) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    list->count = N;
    atomic_flag_clear(&list->lock);
}

void populate_crc_list(CRCIndicationList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        list->crc_indications[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        list->crc_indications[i].RNTI = rand() % UINT16_MAX;
        list->crc_indications[i].CRCFLAG = (rand() % 2 == 0);
    }
}

void add_crc_indication(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T new_cri) {
    atomic_flag_lock(&list->lock);
    list->crc_indications[list->count++] = new_cri;
    atomic_flag_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_crc_indication(const CRCIndicationList* list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }

    return list->crc_indications[index];
}

void free_crc_list(CRCIndicationList* list) {
    atomic_flag_lock(&list->lock);
    free(list->crc_indications);
    atomic_flag_unlock(&list->lock);
}
