void initialize_tunnel_list() {
    for (size_t i = 0; i < MAX_TUNNELS; ++i) {
        tunnel_list[i] = NULL;
    }
    tunnel_count = 0;
}

int add_tunnel_pdu(uint32_t header, uint32_t group_id) {
    if (tunnel_count >= MAX_TUNNELS) {
        return -1; // Maximum tunnels reached
    }

    NR_CU_UP_TNL_FAR_TNL_PDU_T *new_pdu = (NR_CU_UP_TNL_FAR_TNL_PDU_T *)malloc(sizeof(NR_CU_UP_TNL_FAR_TNL_PDU_T));
    if (!new_pdu) {
        return -2; // Memory allocation failed
    }

    new_pdu->PDU_HEADER = header;
    new_pdu->LOGICAL_CHANNEL_GROUP_ID = group_id;
    atomic_init(&new_pdu->SEQUENCE_NUMBER, 0);

    atomic_flag_clear(&list_mutex);
    tunnel_list[tunnel_count++] = new_pdu;
    atomic_flag_set(&list_mutex);

    return tunnel_count - 1; // Return the index of the newly added tunnel
}

void* get_tunnel_pdu(size_t index) {
    if (index >= tunnel_count || tunnel_list[index] == NULL) {
        return NULL; // Invalid or empty index
    }

    return tunnel_list[index];
}
