    public function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
        $response = new stdClass();
        $response->success = false;
        $response->logs = [];
        $response->warnings = [];

        // Start transaction for data integrity
        $this->db->beginTransaction();

        try {
            // Prepare update statement
            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
            $stmt->bind_param("ssi", $newStatus, $ipAddress, $clinicId);

            if ($stmt->execute()) {
                $response->success = true;
                $this->logAction($clinicId, "status updated to $newStatus by IP: $ipAddress");
            } else {
                $response->logs[] = "Failed to update clinic status for ID: $clinicId";
            }

            // Check for concurrent updates
            $stmt = $this->db->prepare("SELECT last_modified_ip FROM clinics WHERE id = ?");
            $stmt->bind_param("i", $clinicId);
            $stmt->execute();
            $result = $stmt->get_result();
            if ($row = $result->fetch_assoc()) {
                if ($row['last_modified_ip'] !== $ipAddress) {
                    $response->warnings[] = "Concurrent update detected. Last modified by IP: {$row['last_modified_ip']}";
                }
            }

        } catch (Exception $e) {
            $response->logs[] = "Error during update: " . $e->getMessage();
        } finally {
            // Commit or rollback transaction
            if ($response->success || empty($response->warnings)) {
                $this->db->commit();
            } else {
                $this->db->rollback();
            }
        }

        return $response;
    }

    private function logAction($clinicId, $action) {
        // Log the action asynchronously to avoid blocking the main operation
        // Example using a background process or queue system like RabbitMQ/Symfony Messenger
    }
}
