            perror("Memory allocation failed");
            goto cleanup;
        }

        list[i]->UE_ID = rand() % (MAX_UE_ID + 1);
        list[i]->CELL_ID = rand() % (MAX_CELL_ID + 1);
        list[i]->SNR = rand() % 20; // Random SNR value between 0 and 19

        pthread_create(&threads[i], NULL, populate_and_transmit, &lock);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

cleanup:
    for (int i = 0; i < MAX_THREADS; i++) {
        free(list[i]);
    }
    free(list);

