import time
import logging
from functools import wraps

# Initialize logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def rate_limited(max_calls: int, period: float):
    def decorator(func):
        calls = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            calls.append(now)
            calls = [x for x in calls if now - x < period]

            if len(calls) > max_calls:
                raise Exception("Rate limit exceeded")

            return func(*args, **kwargs)
        return wrapper
    return decorator

def retry(max_attempts: int):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logger.error(f"Attempt {attempts + 1} failed: {e}")
                    time.sleep(2 ** attempts)  # Exponential backoff
                    attempts += 1
            raise Exception("Max attempts reached")
        return wrapper
    return decorator

def log_execution(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        logger.info(f"Execution of {func.__name__} took {end_time - start_time:.2f}s")
        return result
    return wrapper

@rate_limited(max_calls=10, period=60)
@retry(max_attempts=3)
@log_execution
def update_cache_and_db(releases):
    for release in releases:
        # Update cache and database logic here
        logger.info(f"Updating cache for release {release['id']}")
        logger.info(f"Updating database for release {release['id']}")

# Example usage
releases = [
    {'id': 1, 'version': '1.0.1'},
    {'id': 2, 'version': '2.0.0'}
]

update_cache_and_db(releases)
