    float cpu_usage;
    float memory_consumption;
    float disk_io;
    float network_throughput;
} PerformanceMetrics_t;

typedef struct {
    pthread_mutex_t lock;
    PerformanceMetrics_t *metrics;
    int size;
    int capacity;
} MetricsCache_t;

void initialize_logging_framework() {
    // Implementation for logging framework initialization
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_crl_indication_pdu(int N) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed for NFAPI CRC indication PDU array");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536; // Random RNTI value
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Random CRC flag
    }

    return array;
}

PerformanceMetrics_t* allocate_performance_metrics(int initial_capacity) {
    PerformanceMetrics_t *metrics = (PerformanceMetrics_t*)malloc(initial_capacity * sizeof(PerformanceMetrics_t));
    if (!metrics) {
        perror("Memory allocation failed for performance metrics");
        return NULL;
    }
    return metrics;
}

void initialize_metrics_cache(MetricsCache_t *cache, int initial_capacity) {
    cache->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    cache->metrics = allocate_performance_metrics(initial_capacity);
    if (!cache->metrics) {
        perror("Failed to allocate memory for metrics cache");
        exit(EXIT_FAILURE);
    }
    cache->size = 0;
    cache->capacity = initial_capacity;
}

void add_metric_to_cache(MetricsCache_t *cache, PerformanceMetrics_t metric) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size == cache->capacity) {
        // Double the capacity and reallocate memory
        cache->metrics = realloc(cache->metrics, 2 * cache->capacity * sizeof(PerformanceMetrics_t));
        if (!cache->metrics) {
            perror("Failed to reallocate memory for metrics cache");
            exit(EXIT_FAILURE);
        }
        cache->capacity *= 2;
    }
    cache->metrics[cache->size++] = metric;
    pthread_mutex_unlock(&cache->lock);
}

void clean_up_metrics_cache(MetricsCache_t *cache) {
    free(cache->metrics);
    pthread_mutex_destroy(&cache->lock);
}
