ResourceHandler* initialize_resource_handler() {
    ResourceHandler *handler = (ResourceHandler*)malloc(sizeof(ResourceHandler));
    if (!handler) {
        perror("Failed to allocate memory for ResourceHandler");
        return NULL;
    }

    handler->crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(NFAPI_CRC_INDICATION_PDU_T_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!handler->crc_indication_pdu_array) {
        perror("Failed to allocate memory for CRC indication PDU array");
        free(handler);
        return NULL;
    }

    handler->performance_metrics_array = (PerformanceMetrics_t**)calloc(PERFORMANCE_METRICS_ARRAY_SIZE, sizeof(PerformanceMetrics_t*));
    if (!handler->performance_metrics_array) {
        perror("Failed to allocate memory for performance metrics array");
        free(handler->crc_indication_pdu_array);
        free(handler);
        return NULL;
    }

