    if (!handler || !metric) return;

    pthread_mutex_lock(&handler->mutex);

    if (handler->metrics_count >= PERFORMANCE_METRICS_ARRAY_SIZE) {
        perror("Performance metrics array is full");
        pthread_mutex_unlock(&handler->mutex);
        return;
    }

    handler->performance_metrics_array[handler->metrics_count] = metric;
    handler->metrics_count++;

    pthread_mutex_unlock(&handler->mutex);
}

