#include <pthread.h>
#include <time.h>

#define MAX_NFAPI_PDUS 1000
#define CACHE_SIZE 50

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char unique_id[50];
    float cpu_usage;
    float memory_consumption;
    float disk_io;
    float network_throughput;
} PerformanceMetrics_t;

typedef struct {
    PerformanceMetrics_t metrics[CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
} Cache_t;

NFAPI_CRC_INDICATION_PDU_T pdus[MAX_NFAPI_PDUS];
Cache_t performance_cache;
int pdu_count = 0;

void initialize_pdus() {
    srand(time(NULL));
    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void* manage_performance_metrics(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        pthread_mutex_lock(&performance_cache.lock);
        if (performance_cache.size == CACHE_SIZE) {
            // Cache is full, remove the oldest entry
            memmove(performance_cache.metrics, performance_cache.metrics + 1, sizeof(PerformanceMetrics_t) * (CACHE_SIZE - 1));
            performance_cache.size--;
        }
        PerformanceMetrics_t new_metric;
        sprintf(new_metric.unique_id, "Thread%d_Metric%d", thread_id, i);
        new_metric.cpu_usage = (float)(rand() % 100) / 100.0;
        new_metric.memory_consumption = (float)(rand() % 50) + 50;
        new_metric.disk_io = (float)(rand() % 20) + 10;
        new_metric.network_throughput = (float)(rand() % 100);
        performance_cache.metrics[performance_cache.size] = new_metric;
        performance_cache.size++;
        pthread_mutex_unlock(&performance_cache.lock);
    }
    return NULL;
}

int main() {
    initialize_pdus();
    performance_cache.size = 0;
    pthread_t threads[MAX_NFAPI_PDUS];
    int thread_ids[MAX_NFAPI_PDUS];

    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, manage_performance_metrics, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_NFAPI_PDUS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
