#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char* level, const char* message) {
    // Implement a simple logging mechanism here
    printf("[%s] %s\n", level, message);
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T** array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(array[i]);
    }
    free(array);
}

void* initialize_pdu(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** array = arg;
    pthread_t thread_id = pthread_self();
    log_message("INFO", "Thread started");

    // Simulate initialization of PDU
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            log_message("ERROR", "Memory allocation failed");
            free_memory(array, i);
            pthread_exit(NULL);
        }
        array[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i]->RNTI = rand() % 256;
        array[i]->CRC_INDICATION_REL8_TAG = rand() % 2;
