    log_message("INFO", "Thread completed");
    pthread_exit(NULL);
}

int initialize_crc_pdu_array(size_t size, NFAPI_CRC_INDICATION_PDU_T** array) {
    if (size > MAX_ELEMENTS) {
        log_message("ERROR", "Size exceeds maximum allowed elements");
        return -1;
    }

    array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * size);
    if (!array) {
        log_message("ERROR", "Memory allocation failed for array");
        return -1;
    }

    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * size);
    if (!threads) {
        log_message("ERROR", "Memory allocation failed for thread IDs");
        free_memory(array, 0);
        return -1;
    }

    // Initialize random seed
    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_pdu, &array)) {
            log_message("ERROR", "Failed to create thread");
            free_memory(array, i);
            free(threads);
            return -1;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    log_message("INFO", "Initialization complete");
    return 0;
}
