    struct NFAPI_CRC_INDICATION_PDU_S *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(uint32_t max_pdu_count, uint64_t initial_tag) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;
    uint16_t rnti = 100; // Starting RNTI value
    uint32_t pdu_count = 0;

    while (pdu_count < max_pdu_count) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            // Handle memory allocation error
            return head;
        }

        new_pdu->ue_information.RX_UE_INFORMATION_TAG = initial_tag + pdu_count;
        new_pdu->ue_information.RNTI = rnti++;
        uint64_t tag_rnti_sum = new_pdu->ue_information.RX_UE_INFORMATION_TAG ^ (uint64_t)new_pdu->ue_information.RNTI;
        new_pdu->crc_indication_rel8.CRCFLAG = (tag_rnti_sum % 2) == 0 ? 1 : 0; // Simple rolling checksum
        new_pdu->next = NULL;

        if (!head) {
            head = new_pdu;
        } else {
            current->next = new_pdu;
        }
        current = new_pdu;
        pdu_count++;
    }

    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
