public class ValueGenerator<T> where T : struct
{
    private Random _random = new Random();
    private ConcurrentDictionary<string, T> _cache = new ConcurrentDictionary<string, T>();
    private int _resourceLimit;

    public ValueGenerator(int resourceLimit)
    {
        _resourceLimit = resourceLimit;
    }

    public T GenerateRandomValue(string key, Func<T> valueGenerator)
    {
        if (!_cache.TryGetValue(key, out _))
        {
            lock (this)
            {
                if (!_cache.TryGetValue(key, out _))
                {
                    if (_cache.Count >= _resourceLimit)
                    {
                        string oldestKey = _cache.Keys.First();
                        _cache.TryRemove(oldestKey, out _);
                    }
                    T value = valueGenerator();
                    _cache[key] = value;
                }
            }
        }
        return _cache[key];
    }

    public override string ToString()
    {
        return $"Resource Limit: {_resourceLimit}, Cache Count: {_cache.Count}";
    }
}

