#define MAX_CONTEXT_COUNT 100

typedef struct {
    int CELL_ID;
    int PCI;
    int TIME_SLOT_INDEX;
    int SUBFRAME_INDEX;
} PHY_CONTEXT_T;

typedef struct {
    PHY_CONTEXT_T *contexts[MAX_CONTEXT_COUNT];
    int count;
    pthread_mutex_t mutex;
} PHY_CONTEXT_LIST_T;

PHY_CONTEXT_LIST_T phy_context_list = {0, PTHREAD_MUTEX_INITIALIZER};

int calculate_subframe_index(int cell_id, int time_slot_index) {
    return (cell_id + time_slot_index) % 256; // Simplified example
}

int add_phy_context(int cell_id, int pci, int time_slot_index) {
    pthread_mutex_lock(&phy_context_list.mutex);
    if (phy_context_list.count >= MAX_CONTEXT_COUNT) {
        pthread_mutex_unlock(&phy_context_list.mutex);
        return -1; // Maximum context count reached
    }
    for (int i = 0; i < phy_context_list.count; i++) {
        if (phy_context_list.contexts[i]->PCI == pci) {
            pthread_mutex_unlock(&phy_context_list.mutex);
            return -2; // Duplicate PCI found
        }
    }
    PHY_CONTEXT_T *new_context = malloc(sizeof(PHY_CONTEXT_T));
    if (!new_context) {
        pthread_mutex_unlock(&phy_context_list.mutex);
        return -3; // Memory allocation failed
    }
    new_context->CELL_ID = cell_id;
    new_context->PCI = pci;
    new_context->TIME_SLOT_INDEX = time_slot_index;
    new_context->SUBFRAME_INDEX = calculate_subframe_index(cell_id, time_slot_index);
    phy_context_list.contexts[phy_context_list.count++] = new_context;
    pthread_mutex_unlock(&phy_context_list.mutex);
    return 0; // Success
}

void free_phy_context_list() {
    pthread_mutex_lock(&phy_context_list.mutex);
    for (int i = 0; i < phy_context_list.count; i++) {
        free(phy_context_list.contexts[i]);
    }
    phy_context_list.count = 0;
    pthread_mutex_unlock(&phy_context_list.mutex);
}

void* handle_request(void* arg) {
    int cell_id, pci, time_slot_index;
    // Parse request arguments
    if (/* parsing logic here */) {
        return NULL; // Invalid request
    }
    int result = add_phy_context(cell_id, pci, time_slot_index);
    switch (result) {
        case 0:
            printf("PHY context added successfully.\n");
            break;
        case -1:
            printf("Maximum context count reached.\n");
            break;
        case -2:
            printf("Duplicate PCI found.\n");
            break;
        case -3:
            printf("Memory allocation failed.\n");
            break;
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, handle_request, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    free_phy_context_list();
    return 0;
}
