    rolling_timestamp += (latency * 2); // Simplified example
    return (rolling_timestamp + last_index) % MAX_CONTEXT_COUNT;
}

void manage_memory() {
    if (context_count < MAX_CONTEXT_COUNT) {
        phy_context_list[context_count] = malloc(sizeof(PHY_CONTEXT_T));
        context_count++;
    }
}

void deallocate_memory() {
    for (int i = 0; i < context_count; i++) {
