public class AdvancedRandomValueGenerator : IDisposable
{
    private float minValue;
    private float maxValue;
    private MemoryPool memoryPool;
    private bool disposed = false;

    public AdvancedRandomValueGenerator(float min, float max)
    {
        if (min > max)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        minValue = min;
        maxValue = max;
        memoryPool = new MemoryPool();
    }

    ~AdvancedRandomValueGenerator()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                memoryPool.Dispose();
            }
            disposed = true;
        }
    }

    public float GetRandomFloat()
    {
        byte[] buffer = memoryPool.GetBuffer(sizeof(float));
        try
        {
            UnityEngine.Random.Range(minValue, maxValue);
            // Assuming the range method fills the buffer with a random float value
            return BitConverter.ToSingle(buffer, 0);
        }
        finally
        {
            memoryPool.ReleaseBuffer(buffer);
        }
    }

    public int GetRandomInt()
    {
        byte[] buffer = memoryPool.GetBuffer(sizeof(int));
        try
        {
            UnityEngine.Random.Range((int)minValue, (int)maxValue);
            // Assuming the range method fills the buffer with a random integer value
            return BitConverter.ToInt32(buffer, 0);
        }
        finally
        {
            memoryPool.ReleaseBuffer(buffer);
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

public class MemoryPool : IDisposable
{
    private object[] pool;
    private int index = 0;
    private bool disposed = false;

    public MemoryPool(int initialSize = 1024)
    {
        pool = new object[initialSize];
    }

    ~MemoryPool()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                Array.Clear(pool, 0, pool.Length);
            }
            disposed = true;
        }
    }

    public byte[] GetBuffer(int size)
    {
        if (index + size > pool.Length)
        {
            ExpandPool(size);
        }

        var buffer = new byte[size];
        Buffer.BlockCopy(pool, index * sizeof(object), buffer, 0, size);
        index++;
        return buffer;
    }

    public void ReleaseBuffer(byte[] buffer)
    {
        // No-op for simplicity; in a real implementation, you might want to put the buffer back into the pool or recycle it.
    }

    private void ExpandPool(int additionalSize)
    {
        Array.Resize(ref pool, pool.Length + additionalSize);
    }
}
