    private float maxValue;
    private MemoryPool memoryPool;
    private readonly object lockObject = new object();

    public AdvancedRandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        memoryPool = new MemoryPool(typeof(float), 1024); // Initial allocation size
    }

    ~AdvancedRandomValueGenerator()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            memoryPool.Dispose();
        }
    }

    public float GetRandomFloatInclusive()
    {
        lock (lockObject)
        {
            byte[] buffer = new byte[sizeof(float)];
            UnityEngine.Random.instance.NextBytes(buffer);
            return BitConverter.ToSingle(buffer, 0) * (maxValue - minValue + 1) + minValue;
        }
    }

    public int GetRandomIntExclusive(int exclusiveMax)
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range(0, exclusiveMax);
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    // Additional methods and properties for memory management can be added here
}
