['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CONNECTION_COUNT 100

typedef struct {
    int USER_ID;
    char SESSION_TOKEN[32];
    time_t LAST_ACTIVE_TIME;
    float CURRENT_BANDWIDTH;
} USER_CONNECTION_T;

USER_CONNECTION_T* user_connections[MAX_CONNECTION_COUNT];
int connection_count = 0;

int create_user_connection(int user_id, const char* session_token) {
    if (connection_count >= MAX_CONNECTION_COUNT) return -1; // Exceeding max limit

    for (int i = 0; i < connection_count; i++) {
        if (strcmp(user_connections[i]->SESSION_TOKEN, session_token) == 0) return -2; // Duplicate token
    }

    USER_CONNECTION_T* new_connection = malloc(sizeof(USER_CONNECTION_T));
    if (!new_connection) return -3; // Memory allocation failed

    new_connection->USER_ID = user_id;
    strcpy(new_connection->SESSION_TOKEN, session_token);
    time(&new_connection->LAST_ACTIVE_TIME);
    new_connection->CURRENT_BANDWIDTH = 0.0;

    user_connections[connection_count++] = new_connection;

    return 0; // Success
}

void update_user_connection(int user_id) {
    for (int i = 0; i < connection_count; i++) {
        if (user_connections[i]->USER_ID == user_id) {
            time(&user_connections[i]->LAST_ACTIVE_TIME);
            break;
        }
    }
}

void free_user_connections() {
    for (int i = 0; i < connection_count; i++) {
        free(user_connections[i]);
    }
    connection_count = 0;
}
