public class DataProcessor
{
    private List<int> inputData;
    private List<int> processedResults;
    private long totalRecordsProcessed;
    private TimeSpan averageProcessingTime;

    public void ProcessData(List<int> data)
    {
        inputData = data;
        processedResults = new List<int>();
        totalRecordsProcessed = 0;
        averageProcessingTime = TimeSpan.Zero;

        Stopwatch stopwatch = Stopwatch.StartNew();
        Parallel.ForEach(inputData, item =>
        {
            int result = Transform(item);
            if (IsValid(result))
            {
                lock (processedResults)
                {
                    processedResults.Add(result);
                }
            }
        });
        stopwatch.Stop();

        totalRecordsProcessed = processedResults.Count;
        averageProcessingTime = new TimeSpan((long)(stopwatch.ElapsedTicks / totalRecordsProcessed));
    }

    private int Transform(int item)
    {
        // Custom transformation logic
        return item * 2;
    }

    private bool IsValid(int result)
    {
        // Validation logic
        return result >= 0 && result <= 1000;
    }

    public override string ToString()
    {
        return $"Total Records Processed: {totalRecordsProcessed}, Average Processing Time per Record: {averageProcessingTime}";
    }
}
