DATA_PROCESSOR_T** processors = NULL;
int processor_count = 0;
int max_processors = 0;

void add_processor(int processor_id, int buffer_size) {
    if (processor_count >= max_processors) {
        max_processors += 10;
        processors = realloc(processors, sizeof(DATA_PROCESSOR_T*) * max_processors);
        if (!processors) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    DATA_PROCESSOR_T* new_processor = malloc(sizeof(DATA_PROCESSOR_T));
    new_processor->processor_id = processor_id;
    new_processor->buffer_size = buffer_size;
    new_processor->last_data_processed = time(NULL);
    new_processor->error_count = 0;
    processors[processor_count++] = new_processor;
}

int find_processor(int processor_id) {
    for (int i = 0; i < processor_count; ++i) {
        if (processors[i]->processor_id == processor_id) {
            return i;
        }
    }
    return -1;
}

void adjust_buffer_size() {
    // Implement logic to adjust buffer size based on system metrics
    int available_ram, cpu_load;
    // Assume some function to get these values
    get_system_metrics(&available_ram, &cpu_load);
    if (cpu_load > 80 || available_ram < MAX_BUFFER_SIZE / 2) {
        for (int i = 0; i < processor_count; ++i) {
            processors[i]->buffer_size = MAX_BUFFER_SIZE / 2;
        }
    } else {
        for (int i = 0; i < processor_count; ++i) {
            processors[i]->buffer_size = MAX_BUFFER_SIZE;
        }
    }
}

void update_last_data_processed(int processor_id, time_t timestamp) {
    int index = find_processor(processor_id);
    if (index != -1) {
        processors[index]->last_data_processed = timestamp;
    } else {
        fprintf(stderr, "Processor ID not found\n");
    }
}

void log_operation(const char* operation, int result) {
    // Implement logging mechanism
    FILE* log_file = fopen("operations.log", "a");
    if (log_file) {
        if (result == 0) {
            fprintf(log_file, "%s succeeded\n", operation);
        } else {
            fprintf(log_file, "%s failed\n", operation);
        }
        fclose(log_file);
    }
}

void free_processors() {
    for (int i = 0; i < processor_count; ++i) {
        free(processors[i]);
    }
    free(processors);
    processors = NULL;
    processor_count = 0;
    max_processors = 0;
}
