use std::time::{Duration, Instant};
use tokio::net::TcpStream;
use tokio::prelude::*;

struct AsyncIOClient {
    stream: TcpStream,
}

impl AsyncIOClient {
    async fn new(endpoint: &str) -> Result<AsyncIOClient, Box<dyn std::error::Error>> {
        let stream = TcpStream::connect(endpoint).await?;
        Ok(AsyncIOClient { stream })
    }

    async fn read_to_end(&mut self, buf: &mut Vec<u8>) -> Result<usize, Box<dyn std::error::Error>> {
        let n = self.stream.read(buf).await?;
        buf.resize(n, 0);
        Ok(n)
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = AsyncIOClient::new("127.0.0.1:8080").await?;
    let mut buffer = vec![0; 4096];
    loop {
        match client.read_to_end(&mut buffer).await {
            Ok(n) if n == 0 => break,
            Ok(n) => println!("Received {} bytes", n),
            Err(e) => {
                eprintln!("Error reading from stream: {}", e);
                // Handle error, possibly retry or exit
            }
        }
    }
    Ok(())
}
