using System;
using System.Drawing;

public class AdvancedImageProcessingEngine
{
    private double _minContrast;
    private double _maxContrast;
    private double _minBrightness;
    private double _maxBrightness;

    public AdvancedImageProcessingEngine(double minContrast, double maxContrast, double minBrightness, double maxBrightness)
    {
        if (minContrast < 0 || maxContrast > 1 || minBrightness < 0 || maxBrightness > 1 ||
            minContrast > maxContrast || minBrightness > maxBrightness)
        {
            throw new ArgumentOutOfRangeException("Invalid filter range.");
        }

        _minContrast = minContrast;
        _maxContrast = maxContrast;
        _minBrightness = minBrightness;
        _maxBrightness = maxBrightness;
    }

    public void ApplyContrast(Bitmap image, double contrastFactor)
    {
        if (contrastFactor < 0 || contrastFactor > 1) return;

        for (int y = 0; y < image.Height; y++)
        {
            for (int x = 0; x < image.Width; x++)
            {
                Color pixel = image.GetPixel(x, y);
                int r = (int)Math.Min(255, Math.Max(0, pixel.R * contrastFactor));
                int g = (int)Math.Min(255, Math.Max(0, pixel.G * contrastFactor));
                int b = (int)Math.Min(255, Math.Max(0, pixel.B * contrastFactor));
                image.SetPixel(x, y, Color.FromArgb(r, g, b));
            }
        }
    }

    public void ApplyBrightness(Bitmap image, double brightnessFactor)
    {
        if (brightnessFactor < 0 || brightnessFactor > 1) return;

        for (int y = 0; y < image.Height; y++)
        {
            for (int x = 0; x < image.Width; x++)
            {
                Color pixel = image.GetPixel(x, y);
                int r = (int)Math.Min(255, Math.Max(0, pixel.R + (pixel.R * brightnessFactor)));
                int g = (int)Math.Min(255, Math.Max(0, pixel.G + (pixel.G * brightnessFactor)));
                int b = (int)Math.Min(255, Math.Max(0, pixel.B + (pixel.B * brightnessFactor)));
                image.SetPixel(x, y, Color.FromArgb(r, g, b));
            }
        }
    }

    public void AdjustContrastRange(double percentage)
    {
        _minContrast += (_maxContrast - _minContrast) * percentage;
        _maxContrast = 1; // Ensure upper bound
        if (_minContrast < _maxContrast && _minContrast > 0)
        {
            _minContrast = Math.Max(0, _minContrast);
        }
    }

    public void AdjustBrightnessRange(double percentage)
    {
        _minBrightness += (_maxBrightness - _minBrightness) * percentage;
        _maxBrightness = 1; // Ensure upper bound
        if (_minBrightness < _maxBrightness && _minBrightness > 0)
        {
            _minBrightness = Math.Max(0, _minBrightness);
        }
    }

    public void ProcessImage(string inputFilePath, string outputFilePath, string enhancementRules)
    {
        try
        {
            Bitmap image = new Bitmap(inputFilePath);

            // Example of applying contrast and brightness
            ApplyContrast(image, 1.2); // Increase contrast
            ApplyBrightness(image, 0.5); // Decrease brightness

            // Parse enhancement rules and apply accordingly
            string[] rules = enhancementRules.Split(',');
            foreach (var rule in rules)
            {
                if (rule.Contains("sharpen"))
                {
                    // Apply sharpening logic here
                }
                else if (rule.Contains("blur"))
                {
                    // Apply blurring logic here
                }
            }

            image.Save(outputFilePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing image: {ex.Message}");
        }
    }
}
