        InputStream is = null;

        try {
            socket = new Socket(SERVER_ADDRESS, SERVER_PORT);
            os = socket.getOutputStream();
            is = socket.getInputStream();

            for (NFAPI_CRC_INDICATION_PDU_T pdu : data) {
                byte[] buffer = ByteBuffer.allocate(4 + 2 + 1 + 1)
                    .put((byte)pdu.RX_UE_INFORMATION_TAG)
                    .putShort(pdu.RNTI)
                    .put((byte)pdu.CRC_INDICATION_REL8_TAG)
                    .put((byte)pdu.CRCFLAG)
                    .array();

                os.write(buffer);
            }

            byte[] response = new byte[1024];
            int bytesRead = is.read(response, 0, 1024);
            if (bytesRead != 1) throw new IOException("Invalid server response");
        } catch (IOException e) {
            System.err.println("Error sending data: " + e.getMessage());
        } finally {
            try { if (os != null) os.close(); } catch (IOException e) {}
            try { if (is != null) is.close(); } catch (IOException e) {}
            try { if (socket != null) socket.close(); } catch (IOException e) {}
        }
    }

    public static void main(String[] args) {
        JavaClient client = new JavaClient();
        // Generate and send data
        NFAPI_CRC_INDICATION_PDU_T[] data = generateData(100);
        client.sendData(data);
        freeData(data);
    }

    private static NFAPI_CRC_INDICATION_PDU_T[] generateData(int count) {
        NFAPI_CRC_INDICATION_PDU_T[] data = new NFAPI_CRC_INDICATION_PDU_T[count];

        for (int i = 0; i < count; i++) {
            data[i] = new NFAPI_CRC_INDICATION_PDU_T();
            data[i].RX_UE_INFORMATION_TAG = (byte)(Math.random() * 256);
            data[i].RNTI = (short)(Math.random() * 65536);
            data[i].CRC_INDICATION_REL8_TAG = (byte)(Math.random() * 256);
            data[i].CRCFLAG = (byte)(Math.random() < 0.5 ? 1 : 0);
        }

        return data;
    }

    private static void freeData(NFAPI_CRC_INDICATION_PDU_T[] data) {
        // No need to explicitly free in Java as it's garbage collected
    }
}
