### JavaScript Function (copyBuffer.js)

```javascript
function copyBytesFromBuffers(buffers, offset, length) {
    const newBuffer = Buffer.alloc(length);
    let bytesRead = 0;

    for (const buffer of buffers) {
        if (bytesRead >= length) break;
        const bytesToCopy = Math.min(buffer.length - bytesRead, length - bytesRead);
        buffer.copy(newBuffer, bytesRead, bytesRead, bytesRead + bytesToCopy);
        bytesRead += bytesToCopy;
    }

    return newBuffer.slice(0, bytesRead);
}
