### Logging Mechanism (Logger.java)

```java
import java.io.*;
import java.util.zip.*;

public class Logger {

    private static final String LOG_FILE = "app.log";
    private static final int MAX_LOG_SIZE = 1024 * 1024; // 1MB

    public void log(String message) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE, true))) {
            writer.write(message + "\n");
        } catch (IOException e) {
            System.err.println("Failed to write to log file: " + e.getMessage());
        }

        if (getLogSize() > MAX_LOG_SIZE) {
            rotateLogs();
        }
    }

    private long getLogSize() {
        File logFile = new File(LOG_FILE);
        return logFile.exists() ? logFile.length() : 0;
    }

    private void rotateLogs() {
        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream("logs.zip"))) {
            File logFile = new File(LOG_FILE);
            FileInputStream fis = new FileInputStream(logFile);
            zos.putNextEntry(new ZipEntry(logFile.getName()));
            byte[] buffer = new byte[1024];
            int length;
            while ((length = fis.read(buffer)) > 0) {
                zos.write(buffer, 0, length);
            }
            zos.closeEntry();
            fis.close();
        } catch (IOException e) {
            System.err.println("Failed to rotate logs: " + e.getMessage());
        }

        // Optionally delete the log file after compression
    }
}
