public class MemoryPool<T> : IDisposable
{
    private T[] buffer;
    private int index;
    private readonly int capacity;

    public MemoryPool(int initialCapacity)
    {
        capacity = initialCapacity;
        buffer = new T[capacity];
        index = 0;
    }

    public T Get(T minValue, T maxValue)
    {
        if (index >= capacity)
        {
            Resize();
        }
        return AssignRandomValue(minValue, maxValue);
