public class AdvancedRandomValueGenerator
{
    private Dictionary<string, Range> ranges = new Dictionary<string, Range>();
    private MemoryPool memoryPool;
    private float totalWeight;

    public AdvancedRandomValueGenerator(int initialAllocationSize, float fragmentationThreshold, int reclamationFrequency)
    {
        memoryPool = new MemoryPool(initialAllocationSize, fragmentationThreshold);
        totalWeight = 0;
    }

    public void AddRange(string name, float min, float max, float weight)
    {
        if (ranges.ContainsKey(name))
        {
            RemoveRange(name);
        }
        ranges[name] = new Range(min, max, weight);
        totalWeight += weight;
    }

    public void RemoveRange(string name)
    {
        if (ranges.ContainsKey(name))
        {
            totalWeight -= ranges[name].Weight;
            ranges.Remove(name);
        }
    }

    public float GetRandomFloat(string rangeName)
    {
        Range range = GetRange(rangeName);
        return UnityEngine.Random.Range(range.Min, range.Max);
