using System;
using System.Security.Cryptography;

public class SecureRandomValueGenerator
{
    private int min;
    private int max;

    public SecureRandomValueGenerator(int min, int max)
    {
        this.min = min;
        this.max = max;
    }

    public int GetSecureRandomInt()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[4];
            rng.GetBytes(randomBytes);
            int randomValue = BitConverter.ToInt32(randomBytes, 0);
            return min + (int)(randomValue % (max - min + 1));
        }
    }

    public float GetSecureRandomFloat()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[4];
            rng.GetBytes(randomBytes);
            int randomValue = BitConverter.ToInt32(randomBytes, 0);
            return min + (randomValue / (float)int.MaxValue * (max - min));
        }
    }

    public override string ToString()
    {
        return $"Range: {min} to {max}";
    }
}
