using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private Dictionary<int, double> distribution;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.distribution = GenerateUniformDistribution(minValue, maxValue);
    }

    private Dictionary<int, double> GenerateUniformDistribution(int min, int max)
    {
        Dictionary<int, double> distribution = new Dictionary<int, double>();
        for (int i = min; i <= max; i++)
        {
            distribution[i] = 1.0 / (double)(max - min + 1);
        }
        return distribution;
    }

    public void SetCustomDistribution(Dictionary<int, double> customDistribution)
    {
        if (!IsValidDistribution(customDistribution))
        {
            throw new ArgumentException("Invalid distribution.");
        }
        this.distribution = customDistribution;
    }

    private bool IsValidDistribution(Dictionary<int, double> distribution)
    {
        foreach (var value in distribution.Values)
        {
            if (value < 0 || value > 1)
                return false;
        }
        return distribution.Sum(pair => pair.Value) == 1;
    }

    public float GenerateRandomFloat()
    {
        Random rand = new Random();
        double randomValue = rand.NextDouble() * distribution.Values.Sum();
        double cumulativeProbability = 0.0;
        foreach (var value in distribution)
        {
            cumulativeProbability += value.Value;
            if (randomValue < cumulativeProbability)
                return value.Key;
        }
        return maxValue; // Fallback to avoid infinite loop
    }

    public int GenerateRandomInt()
    {
        Random rand = new Random();
        double randomValue = rand.NextDouble() * distribution.Values.Sum();
        double cumulativeProbability = 0.0;
        foreach (var value in distribution)
        {
            cumulativeProbability += value.Value;
            if (randomValue < cumulativeProbability)
                return value.Key;
        }
        return maxValue; // Fallback to avoid infinite loop
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}, Distribution: {string.Join(", ", distribution)}";
    }
}
