using System;
using System.IO;
using System.Threading;
using UnityEngine;

[Serializable]
public struct ValueRange<T>
{
    public T Min { get; set; }
    public T Max { get; set; }
}

public class ValueGenerator : MonoBehaviour
{
    private static readonly Random random = new Random();
    private static Dictionary<string, ValueRange<float>> floatRanges = new Dictionary<string, ValueRange<float>>();
    private static Dictionary<string, ValueRange<int>> intRanges = new Dictionary<string, ValueRange<int>>();

    public static void SetSeed(long seed)
    {
        random = new Random(seed);
    }

    public static float GetRandomFloat(string rangeName)
    {
        if (floatRanges.TryGetValue(rangeName, out var range))
        {
            return range.Min + (range.Max - range.Min) * (float)random.NextDouble();
        }
        throw new ArgumentException("Range not found");
    }

    public static int GetRandomInt(string rangeName)
    {
        if (intRanges.TryGetValue(rangeName, out var range))
        {
            return random.Next((int)range.Min, (int)range.Max + 1);
        }
        throw new ArgumentException("Range not found");
    }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void LoadRanges()
    {
        try
        {
            var xml = File.ReadAllText(Application.dataPath + "/ValueRanges.xml");
            var doc = System.Xml.Linq.XDocument.Parse(xml);

            foreach (var floatRange in doc.Descendants("floatRange"))
            {
                var name = floatRange.Attribute("name").Value;
                var min = Convert.ToSingle(floatRange.Attribute("min").Value);
                var max = Convert.ToSingle(floatRange.Attribute("max").Value);
                if (min > max)
                    throw new InvalidOperationException("Invalid range");
                floatRanges[name] = new ValueRange<float> { Min = min, Max = max };
            }

            foreach (var intRange in doc.Descendants("intRange"))
            {
                var name = intRange.Attribute("name").Value;
                var min = Convert.ToInt32(intRange.Attribute("min").Value);
                var max = Convert.ToInt32(intRange.Attribute("max").Value);
                if (min > max)
                    throw new InvalidOperationException("Invalid range");
                intRanges[name] = new ValueRange<int> { Min = min, Max = max };
            }
        }
        catch (Exception ex)
        {
            Debug.LogError("Failed to load value ranges: " + ex.Message);
        }
    }

    public override string ToString()
    {
        return $"ValueGenerator with ranges loaded from config";
    }

    public override bool Equals(object obj)
    {
        if (obj == null || GetType() != obj.GetType())
            return false;
        var other = (ValueGenerator)obj;
        return floatRanges.SequenceEqual(other.floatRanges) && intRanges.SequenceEqual(other.intRanges);
    }
}
```

