using System;
using Newtonsoft.Json;

public class RandomValueGenerator
{
    private int minValue;
    private int maxValue;
    private double[] distributionWeights;
    private Random random;
    private ILogger logger;

    public RandomValueGenerator(string settingsFilePath, ILogger logger)
    {
        this.logger = logger;
        var settings = LoadSettings(settingsFilePath);
        Initialize(settings);
    }

    private Settings LoadSettings(string filePath)
    {
        try
        {
            string jsonContent = System.IO.File.ReadAllText(filePath);
            return JsonConvert.DeserializeObject<Settings>(jsonContent);
        }
        catch (Exception ex)
        {
            logger.LogError("Failed to load settings file: " + filePath, ex);
            throw new InvalidOperationException("Failed to load settings.", ex);
        }
    }

    private void Initialize(Settings settings)
    {
        if (settings.MinValue >= settings.MaxValue)
        {
            logger.LogError("Invalid range specified. MinValue must be less than MaxValue.");
            throw new ArgumentException("MinValue must be less than MaxValue.");
        }

        minValue = settings.MinValue;
        maxValue = settings.MaxValue;
        distributionWeights = settings.DistributionWeights;

        random = new Random(settings.Seed);
    }

    public int GenerateRandomValue()
    {
        return GenerateRandomValue(minValue, maxValue, distributionWeights);
    }

    private int GenerateRandomValue(int min, int max, double[] weights)
    {
        double totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }

        double randomValue = random.NextDouble() * totalWeight;

        for (int i = 0; i < weights.Length; i++)
        {
            if (randomValue < weights[i])
            {
                return min + i;
            }
            randomValue -= weights[i];
        }

        logger.LogWarning("Unexpected behavior in weight distribution. Returning default value.");
        return min;
    }

    public class Settings
    {
        public int MinValue { get; set; }
        public int MaxValue { get; set; }
        public double[] DistributionWeights { get; set; }
        public int Seed { get; set; }
    }

    public interface ILogger
    {
        void LogError(string message, Exception ex);
        void LogWarning(string message);
    }
}
