#include <openssl/evp.h>
#include <openssl/rand.h>

int initAES256CBC(const char* password, unsigned char* key, unsigned char* iv)
{
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return -1;

    int len, plen;
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, iv))
    {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (!EVP_EncryptUpdate(ctx, key, &len, (unsigned char*)"password", 8))
    {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plen = len;

    if (!EVP_EncryptFinal_ex(ctx, key + len, &len)) 
    {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    len += plen;
    EVP_CIPHER_CTX_free(ctx);

    // Generate IV
    if (RAND_bytes(iv, EVP_CIPHER_BLOCK_SIZE) != 1)
    {
        return -1;
    }

    return len;
}
