['```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class NetworkDataProcessor {
    private static final int MAX_CLIENTS = 100;
    private static final int BUFFER_SIZE = 64 * 1024; // 64KB
    private DatagramSocket serverSocket;
    private ExecutorService clientHandlerPool;

    public NetworkDataProcessor() throws IOException {
        serverSocket = new DatagramSocket(5000); // Bind to port 5000
        clientHandlerPool = Executors.newFixedThreadPool(MAX_CLIENTS);
        startListening();
    }

    private void startListening() {
        while (true) {
            byte[] buffer = new byte[BUFFER_SIZE];
            DatagramPacket packet = new DatagramPacket(buffer, buffer.length);
            try {
                serverSocket.receive(packet);
                clientHandlerPool.submit(() -> handleClientRequest(packet));
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleClientRequest(DatagramPacket request) {
        byte[] data = request.getData();
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(bis);
            Object message = ois.readObject();
            // Process the message and send a response
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(bos);
            oos.writeObject(message);
            byte[] response = bos.toByteArray();
            DatagramPacket reply = new DatagramPacket(response, response.length,
                    request.getAddress(), request.getPort());
            serverSocket.send(reply);
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            try {
                if (ois != null) ois.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public void stop() {
        clientHandlerPool.shutdown();
        serverSocket.close();
    }
}
