    private static int _seed;

    public SecureRandomValueGenerator(string configFilePath)
    {
        LoadConfig(configFilePath);
        InitializeSeed();
    }

    private void LoadConfig(string configFilePath)
    {
        if (!File.Exists(configFilePath))
            throw new FileNotFoundException("Configuration file not found.");

        var config = JsonConvert.DeserializeObject<Dictionary<string, object>>(File.ReadAllText(configFilePath));
        if (config.TryGetValue("distributionWeights", out var weightsObj) && weightsObj is Dictionary<string, double> weights)
        {
            _distributionWeights = weights;
        }
    }

    private void InitializeSeed()
    {
        byte[] seedBytes = new byte[4];
        _rng.GetBytes(seedBytes);
        _seed = BitConverter.ToInt32(seedBytes, 0);
        Random = new Random(_seed);
    }

    public int GenerateRandomValue(int min, int max, bool exclusive = false)
    {
        if (exclusive)
            return Random.Next(min, max - 1);

        return Random.Next(min, max + 1);
    }

    public double GenerateWeightedRandomValue()
    {
        var totalWeight = _distributionWeights.Values.Sum();
        var randomValue = Random.NextDouble() * totalWeight;

        foreach (var kvp in _distributionWeights)
        {
            if ((randomValue -= kvp.Value) <= 0)
                return kvp.Key;
        }

        throw new InvalidOperationException("Failed to generate weighted random value.");
    }

