typedef struct {
    int MessageType;
    int MessageSequenceNumber;
} NetworkMessage;

int generateNetworkMessages(int numMessages, NetworkMessage **messages) {
    if (!messages || numMessages <= 0) return -1;

    *messages = (NetworkMessage *)malloc(numMessages * sizeof(NetworkMessage));
    if (!*messages) return -2;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < numMessages; i++) {
        (*messages)[i].MessageType = rand() % 5 + 1; // Random MessageType value
        (*messages)[i].MessageSequenceNumber = i + 1;
    }

    return 0;
}

void freeNetworkMessages(NetworkMessage *messages, int numMessages) {
