import json
from datetime import datetime

class FileProcessor:
    def __init__(self, config_file_path):
        self.config = self.load_config(config_file_path)

    def load_config(self, file_path):
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            raise ValueError("Config file not found")
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON format in config file")

    def serialize_data(self, data):
        try:
            return json.dumps(data)
        except TypeError:
            raise ValueError("Data contains non-serializable types")

    def process_files(self, files):
        processed_records = []
        for file_path in files:
            record = {
                'file_id': str(uuid.uuid4()),
                'timestamp': datetime.now().isoformat(),
                'status': 'processed'
            }
            try:
                with open(file_path, 'r') as file:
                    data = json.load(file)
                    # Process the data
                    processed_record = self.serialize_data(data)
                    record['data'] = processed_record
                    processed_records.append(record)
            except FileNotFoundError:
                record['status'] = 'error'
                record['message'] = f"File not found: {file_path}"
                processed_records.append(record)
            except json.JSONDecodeError:
                record['status'] = 'error'
                record['message'] = f"Invalid JSON format in file: {file_path}"
                processed_records.append(record)

        return processed_records
