#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>
#include <crypt.h>

#define MAX_CONTEXT_COUNT 1000
#define HASH_SIZE 256
#define RETRY_DELAY_BASE 1000 // ms

typedef struct {
    uint32_t CELL_ID;
    uint16_t PCI;
    uint8_t TIME_SLOT_INDEX;
    uint8_t SUBFRAME_INDEX;
} PHY_CONTEXT_T;

typedef struct {
    PHY_CONTEXT_T *contexts[MAX_CONTEXT_COUNT];
    pthread_mutex_t lock;
    int count;
    uint8_t hash_table[HASH_SIZE];
} PHY_CONTEXT_LIST_T;

PHY_CONTEXT_LIST_T context_list = {0};

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_context_list() {
    pthread_mutex_init(&context_list.lock, NULL);
}

void cleanup_context_list() {
    pthread_mutex_destroy(&context_list.lock);
}

int hash_pci(uint16_t pci) {
    return pci % HASH_SIZE;
}

int is_pci_unique(uint16_t pci) {
    int index = hash_pci(pci);
    pthread_mutex_lock(&context_list.lock);
    for (int i = 0; i < context_list.count; i++) {
        if (index == hash_pci(context_list.contexts[i]->PCI)) {
            pthread_mutex_unlock(&context_list.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&context_list.lock);
    return 1;
}

int insert_context(PHY_CONTEXT_T *new_context) {
    if (is_pci_unique(new_context->PCI) && context_list.count < MAX_CONTEXT_COUNT) {
        pthread_mutex_lock(&global_lock);
        pthread_mutex_lock(&context_list.lock);
        context_list.contexts[context_list.count++] = new_context;
        pthread_mutex_unlock(&context_list.lock);
        pthread_mutex_unlock(&global_lock);
        return 1;
    }
    return 0;
}

void delete_context(PHY_CONTEXT_T *context) {
    pthread_mutex_lock(&global_lock);
    pthread_mutex_lock(&context_list.lock);
    for (int i = 0; i < context_list.count; i++) {
        if (context_list.contexts[i] == context) {
            free(context_list.contexts[i]);
            memmove(&context_list.contexts[i], &context_list.contexts[i + 1], sizeof(PHY_CONTEXT_T *) * (context_list.count - i - 1));
            context_list.count--;
            break;
        }
    }
    pthread_mutex_unlock(&context_list.lock);
    pthread_mutex_unlock(&global_lock);
}

void calculate_subframe_index(PHY_CONTEXT_T *context) {
    char salt[256];
    snprintf(salt, sizeof(salt), "%d%d", context->CELL_ID, context->TIME_SLOT_INDEX);
    uint8_t hash[16];
    crypt_r(context->PCI, salt, hash);
    memcpy(&context->SUBFRAME_INDEX, &hash[0], sizeof(uint8_t));
}

PHY_CONTEXT_T* create_context(uint32_t cell_id, uint16_t pci, uint8_t time_slot_index) {
    PHY_CONTEXT_T *new_context = malloc(sizeof(PHY_CONTEXT_T));
    if (new_context == NULL) {
        return NULL;
    }
    new_context->CELL_ID = cell_id;
    new_context->PCI = pci;
    new_context->TIME_SLOT_INDEX = time_slot_index;
    calculate_subframe_index(new_context);
    return new_context;
}

void destroy_context(PHY_CONTEXT_T *context) {
    free(context);
}
