    DATA_PROCESSOR_T data;
    struct LIST_NODE_T* next;
} LIST_NODE_T;

typedef struct LIST_HEADER_T {
    LIST_NODE_T* head;
    LIST_NODE_T* tail;
    int size;
} LIST_HEADER_T;

LIST_HEADER_T processor_list = {NULL, NULL, 0};

int is_id_unique(int id) {
    LIST_NODE_T* node = processor_list.head;
    while (node != NULL) {
        if (node->data.PROCESSOR_ID == id) {
            return 0;
        }
        node = node->next;
    }
    return 1;
}

void add_processor(DATA_PROCESSOR_T data) {
    if (!is_id_unique(data.PROCESSOR_ID)) {
        printf("Error: ID already exists.\n");
        return;
    }
    LIST_NODE_T* new_node = (LIST_NODE_T*)malloc(sizeof(LIST_NODE_T));
    new_node->data = data;
    new_node->next = NULL;

    if (processor_list.head == NULL) {
        processor_list.head = new_node;
        processor_list.tail = new_node;
    } else {
        processor_list.tail->next = new_node;
        processor_list.tail = new_node;
    }
    processor_list.size++;
}

void* process_data(void* arg) {
    // Simulate data processing
    pthread_exit(NULL);
}

int main() {
    DATA_PROCESSOR_T processor1 = {1, MAX_BUFFER_SIZE, time(NULL), 0};
