    int ERROR_COUNT;
} DATA_PROCESSOR_T;

DATA_PROCESSOR_T** processor_list = NULL;
int list_size = 0;
int max_processors = 0;

void init_processor_list(int initial_capacity) {
    max_processors = initial_capacity;
    processor_list = (DATA_PROCESSOR_T**)malloc(max_processors * sizeof(DATA_PROCESSOR_T*));
}

int add_processor(int PROCESSOR_ID, size_t BUFFER_SIZE) {
    if (list_size >= max_processors) {
        max_processors *= 2;
        processor_list = (DATA_PROCESSOR_T**)realloc(processor_list, max_processors * sizeof(DATA_PROCESSOR_T*));
    }
    for (int i = 0; i < list_size; i++) {
        if (processor_list[i]->PROCESSOR_ID == PROCESSOR_ID) {
            return -1;
        }
    }
    processor_list[list_size] = (DATA_PROCESSOR_T*)malloc(sizeof(DATA_PROCESSOR_T));
    processor_list[list_size]->PROCESSOR_ID = PROCESSOR_ID;
    processor_list[list_size]->BUFFER_SIZE = BUFFER_SIZE;
    processor_list[list_size]->LAST_DATA_PROCESSED = time(NULL);
    processor_list[list_size]->ERROR_COUNT = 0;
    list_size++;
    return 0;
}

void free_processor_list() {
    for (int i = 0; i < list_size; i++) {
        free(processor_list[i]);
    }
    free(processor_list);
