        if (list->streams[i]->video_id == stream->video_id) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate video ID
        }
    }
    list->streams[list->count++] = stream;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
