            free(list->streams[i]);
            memmove(&list->streams[i], &list->streams[i + 1], sizeof(MEDIA_STREAM_T*) * (list->count - i - 1));
            --list->count;
            pthread_cond_signal(&list->cond);
            pthread_mutex_unlock(&list->lock);
