    float memory_consumption;
    float disk_I_O;
    float network_throughput;
} PerformanceMetrics_t;

NFAPI_CRC_INDICATION_PDU_T* initialize_NFAPI_structures() {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 100;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return array;
}

PerformanceMetrics_t* initialize_PerformanceMetrics() {
    PerformanceMetrics_t* metrics = (PerformanceMetrics_t*)malloc(N * sizeof(PerformanceMetrics_t));
    if (!metrics) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        metrics[i].CPU_usage = (float)(rand() % 100) / 100.0;
        metrics[i].memory_consumption = (float)(rand() % 100) / 100.0;
        metrics[i].disk_I_O = (float)(rand() % 100) / 100.0;
        metrics[i].network_throughput = (float)(rand() % 100) / 100.0;
    }
    return metrics;
}

void* thread_function(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* array = initialize_NFAPI_structures();
    PerformanceMetrics_t* metrics = initialize_PerformanceMetrics();

    if (array && metrics) {
        // Process performance metrics
        free(array);
        free(metrics);
    }

    return NULL;
}

int main() {
    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
