typedef struct {
    PHY_CONTEXT_T *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PHY_LIST_T;

PHY_LIST_T* phy_list_create() {
    PHY_LIST_T *list = (PHY_LIST_T *)malloc(sizeof(PHY_LIST_T));
    list->capacity = 10;
    list->count = 0;
    list->contexts = (PHY_CONTEXT_T *)malloc(list->capacity * sizeof(PHY_CONTEXT_T));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void phy_list_destroy(PHY_LIST_T *list) {
    free(list->contexts);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

int phy_list_add(PHY_LIST_T *list, PHY_CONTEXT_T context) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->contexts = (PHY_CONTEXT_T *)realloc(list->contexts, list->capacity * sizeof(PHY_CONTEXT_T));
    }
    for (size_t i = 0; i < list->count; i++) {
        if (list->contexts[i].PCI == context.PCI) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
    }
    list->contexts[list->count++] = context;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

