using System;
using System.IO;
using System.Xml.Serialization;
using System.Collections.Generic;

[Serializable]
public class DistributionSettings
{
    public List<DistributionRange> Ranges { get; set; }
}

[Serializable]
public class DistributionRange
{
    public int Min { get; set; }
    public int Max { get; set; }
    public double Weight { get; set; }
}

public class RandomValueGenerator
{
    private Dictionary<string, object> cache;
    private DistributionSettings settings;

    public RandomValueGenerator(string configFilePath)
    {
        LoadSettings(configFilePath);
        InitializeCache();
    }

    private void LoadSettings(string configFilePath)
    {
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        XmlSerializer serializer = new XmlSerializer(typeof(DistributionSettings));
        using (FileStream stream = File.OpenRead(configFilePath))
        {
            settings = (DistributionSettings)serializer.Deserialize(stream);
        }
    }

    private void InitializeCache()
    {
        cache = new Dictionary<string, object>();
    }

    public int GenerateRandomValue(string key)
    {
        if (!cache.ContainsKey(key))
        {
            lock (cache)
            {
                if (!cache.ContainsKey(key))
                {
                    var totalWeight = settings.Ranges.Sum(range => range.Weight);
                    double random = Guid.NewGuid().GetHashCode() / (double)int.MaxValue * totalWeight;
                    double cumulativeWeight = 0;

                    foreach (var range in settings.Ranges)
                    {
                        cumulativeWeight += range.Weight;
                        if (random <= cumulativeWeight)
                        {
                            cache[key] = new Random().Next(range.Min, range.Max + 1);
                            break;
                        }
                    }
                }
            }
        }

        return (int)cache[key];
    }
}
