using System;
using UnityEngine;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;

    public RandomValueGenerator(double initialMin, double initialMax)
    {
        SetRange(initialMin, initialMax);
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public void SetRange(double newMin, double newMax)
    {
        if (newMin > newMax)
        {
            double temp = newMin;
            newMin = newMax;
            newMax = temp;
        }
        minValue = newMin;
        maxValue = newMax;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value)
        );
    }

    public override string ToString()
    {
        return $"Current Range: [{minValue}, {maxValue}]";
    }

    public DateTime GenerateRandomDateTime(DateTime start, DateTime end)
    {
        if (start > end)
        {
            throw new ArgumentException("Start date must be before end date.");
        }
        long range = end.Ticks - start.Ticks;
        return start.AddTicks((long)(UnityEngine.Random.value * range));
    }
}
