    if (!pdu_list->pdu_list) {
        perror("Failed to allocate memory for PDU list");
        exit(EXIT_FAILURE);
    }
    pdu_list->pdu_count = 0;
    pdu_list->max_pdu_count = max_pdu_count;
    pthread_mutex_init(&pdu_list->lock, NULL);
    pthread_cond_init(&pdu_list->cond, NULL);
}

void add_pdu(PDU_LIST_T *pdu_list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pdu_list->lock);
    if (pdu_list->pdu_count >= pdu_list->max_pdu_count) {
        fprintf(stderr, "PDU list is full\n");
        pthread_cond_signal(&pdu_list->cond);
        pthread_mutex_unlock(&pdu_list->lock);
        return;
    }
    memcpy(&pdu_list->pdu_list[pdu_list->pdu_count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu_list->pdu_count++;
    printf("PDU added to list\n");
    pthread_cond_signal(&pdu_list->cond);
    pthread_mutex_unlock(&pdu_list->lock);
}

void free_pdu_list(PDU_LIST_T *pdu_list) {
    pthread_mutex_lock(&pdu_list->lock);
    free(pdu_list->pdu_list);
    pdu_list->pdu_list = NULL;
    pdu_list->pdu_count = 0;
    pthread_mutex_unlock(&pdu_list->lock);
}

int main() {
    PDU_LIST_T pdu_list;
    initialize_pdu_list(&pdu_list, MAX_PDU_COUNT);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 0x123456789ABCDEF0;
    pdu.RNTI = 1234;
    pdu.CRC_INDICATION_REL8_TAG = 0xFF;

    add_pdu(&pdu_list, pdu);

    free_pdu_list(&pdu_list);
    return 0;
}
