    private double minValue;
    private double maxValue;
    private RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();

    public AccountManager(double minValue, double maxValue)
    {
        this.minValue = Math.Min(minValue, maxValue);
        this.maxValue = Math.Max(minValue, maxValue);
    }

    public float GenerateRandomFloat()
    {
        byte[] buffer = new byte[4];
        rng.GetBytes(buffer);
        return BitConverter.ToSingle(buffer, 0) * (float)(maxValue - minValue) + (float)minValue;
    }

    public int GenerateRandomInt()
    {
        byte[] buffer = new byte[4];
        rng.GetBytes(buffer);
        return BitConverter.ToInt32(buffer, 0) % ((int)(maxValue - minValue)) + (int)minValue;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            GenerateRandomFloat(),
            GenerateRandomFloat(),
            GenerateRandomFloat()
        );
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random random = new Random();
        long start = startDate.ToUniversalTime().Ticks;
        long end = endDate.ToUniversalTime().Ticks;
        return new DateTime(random.Next((int)start, (int)end));
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        minValue = Math.Min(newMinValue, newMaxValue);
        maxValue = Math.Max(newMinValue, newMaxValue);
    }

    public override string ToString()
    {
        return $"Current Range: [{minValue}, {maxValue}]";
    }

    public void Dispose()
    {
        rng.Dispose();
    }
