#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int file_id;
    time_t timestamp;
    int status;
} FILE_PROCESS_RECORD;

void generate_records(int N, FILE_PROCESS_RECORD *records) {
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        records[i].file_id = i + 1;
        records[i].timestamp = time(NULL);
        records[i].status = rand() % 2; // Randomly set status
    }
}

void *process_files(void *arg) {
    int N = *(int *)arg;
    FILE_PROCESS_RECORD records[N];
    generate_records(N, records);

    for (int i = 0; i < N; i++) {
        printf("File ID: %d, Timestamp: %ld, Status: %d\n", records[i].file_id, records[i].timestamp, records[i].status);
    }

    return NULL;
}

int main() {
    int N = 5; // Example limit
    pthread_t thread;
    int arg = N;

    if (pthread_create(&thread, NULL, process_files, &arg) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}
