import json

class ConfigManager:
    def __init__(self, config_file):
        self.config_file = config_file
        self.data = None

    def load_config(self):
        try:
            with open(self.config_file, 'r') as f:
                self.data = json.load(f)
        except FileNotFoundError:
            print(f"File {self.config_file} not found")
        except json.JSONDecodeError:
            print(f"Corrupted file {self.config_file}")

    def save_config(self):
        try:
            with open(self.config_file, 'w') as f:
                json.dump(self.data, f, indent=4)
        except IOError:
            print(f"Error saving file {self.config_file}")

# Example usage
config_manager = ConfigManager('path/to/config.json')
config_manager.load_config()
print(config_manager.data)
config_manager.data['NEW_KEY'] = 'new_value'
config_manager.save_config()
