from concurrent.futures import ThreadPoolExecutor, as_completed
from kubernetes import client, config

class KubernetesDeploymentManager:
    def __init__(self, clusters, label_selector):
        self.clusters = clusters
        self.label_selector = label_selector
        self.deployment_report = {
            'total_namespaces': 0,
            'successful_deployments': 0,
            'failures': []
        }

    def load_kube_config(self, cluster_name):
        config.load_kube_config(context=cluster_name)

    def deploy_to_cluster(self, cluster_name):
        self.load_kube_config(cluster_name)
        api_instance = client.CoreV1Api()
        namespaces = api_instance.list_namespace(label_selector=self.label_selector).items
        for namespace in namespaces:
            self.deployment_report['total_namespaces'] += 1
            try:
                # Deploy logic here (e.g., applying a manifest to the namespace)
                print(f"Deploying to {namespace.metadata.name} in {cluster_name}")
                self.deployment_report['successful_deployments'] += 1
            except Exception as e:
                self.deployment_report['failures'].append({
                    'cluster': cluster_name,
                    'namespace': namespace.metadata.name,
                    'error': str(e)
                })

    def deploy_to_clusters(self):
        with ThreadPoolExecutor(max_workers=len(self.clusters)) as executor:
            futures = {executor.submit(self.deploy_to_cluster, cluster): cluster for cluster in self.clusters}
            for future in as_completed(futures):
                try:
                    result = future.result()
                except Exception as e:
                    print(f"Error deploying to cluster: {e}")

    def generate_deployment_report(self):
        return self.deployment_report

# Example usage
clusters = ['cluster1', 'cluster2', 'cluster3']
label_selector = 'env=production'
manager = KubernetesDeploymentManager(clusters, label_selector)
manager.deploy_to_clusters()
report = manager.generate_deployment_report()
print(report)
