#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int CELL_ID;
    int PCI;
    int TIME_SLOT_INDEX;
    int SUBFRAME_INDEX;
} PHY_CONTEXT_T;

typedef struct {
    PHY_CONTEXT_T **contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PHY_LIST_T;

void init_phy_list(PHY_LIST_T *list) {
    list->contexts = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_phy_context(PHY_LIST_T *list, PHY_CONTEXT_T context) {
    pthread_mutex_lock(&list->lock);

    // Check if PCI is unique
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i]->PCI == context.PCI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate PCI
        }
    }

    // Check if exceeding the maximum limit
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        PHY_CONTEXT_T **new_contexts = realloc(list->contexts, new_capacity * sizeof(PHY_CONTEXT_T *));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    list->contexts[list->count] = malloc(sizeof(PHY_CONTEXT_T));
    if (!list->contexts[list->count]) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    *list->contexts[list->count] = context;

    ++list->count;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_phy_list(PHY_LIST_T *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i]);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
}
