        batch_v1.create_namespaced_deployment(namespace, deployment_manifest)
        print(f"Deployment successful in {namespace} of cluster {cluster_url}")
        return True
    except ApiException as e:
        print(f"Failed to deploy to {namespace} of cluster {cluster_url}: {e}")
        raise

# Main function
def main():
    clusters = get_clusters()
    token = os.getenv("KUBE_TOKEN")  # Assume token is passed via environment variable for security reasons

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(deploy_to_cluster, cluster, token, "production") for cluster in clusters]

        results = {future.result() for future in as_completed(futures)}
        print(f"Total namespaces processed: {len(results)}")
        print(f"Successful deployments: {sum(1 for result in results if result)}")
        print(f"Failures: {sum(1 for result in results if not result)}")

if __name__ == "__main__":
    main()
