from compose.config.config import load_config

def deploy_containerized_app(config):
    # Initialize Docker client
    client = docker.from_env()

    # Validate Docker Compose file
    try:
        config_path = 'docker-compose.yml'
        with open(config_path, 'w') as f:
            for service, details in config.items():
                f.write(f'services:\n  {service}:\n    image: {details["image"]}\n')
                if "env" in details:
                    f.write('    environment:\n')
                    for key, value in details["env"].items():
                        f.write(f'      {key}: "{value}"\n')

        config = load_config(config_path)
        print("Docker Compose file is valid.")
    except Exception as e:
        raise ValueError("Validation check failed.") from e

    try:
        # Pull the latest images
        for service in config['services']:
            client.images.pull(service.image, tag=service.tags[0])
            print(f"Pulled latest image for {service.name}")

        # Apply changes using Docker Compose
        os.system('docker-compose up -d --force-recreate')
        print("Deployment successful.")
    except docker.errors.APIError as e:
        raise Exception("Docker command execution failed.") from e

# Example usage
