#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_REGISTRY_SIZE 1024
#define MAX_SERVICE_ID_LENGTH 32
#define MAX_HOST_NAME_LENGTH 64
#define MAX_PORT_NUMBER 65535
#define MAX_PORT_RANGE 1024

typedef struct {
    char service_id[MAX_SERVICE_ID_LENGTH];
    char host_name[MAX_HOST_NAME_LENGTH];
    int port_number;
    char current_status[32];
    time_t last_heartbeat;
} SERVICE_INSTANCE_T;

SERVICE_INSTANCE_T registry[MAX_REGISTRY_SIZE];
int registry_size = 0;

int add_service(const char* service_id, const char* host_name, int port_number) {
    if (registry_size >= MAX_REGISTRY_SIZE) return -1; // Registry full
    for (int i = 0; i < registry_size; i++) {
        if (strcmp(registry[i].service_id, service_id) == 0) return -2; // Duplicate ID
    }
    strcpy(registry[registry_size].service_id, service_id);
    strcpy(registry[registry_size].host_name, host_name);
    registry[registry_size].port_number = port_number;
    time(&registry[registry_size].last_heartbeat);
    strcpy(registry[registry_size].current_status, "Active");
    registry_size++;
    return 0; // Success
}

int update_service(const char* service_id) {
    for (int i = 0; i < registry_size; i++) {
        if (strcmp(registry[i].service_id, service_id) == 0) {
            time(&registry[i].last_heartbeat);
            return 0; // Success
        }
    }
    return -1; // Service not found
}

void remove_service(const char* service_id) {
    for (int i = 0; i < registry_size; i++) {
        if (strcmp(registry[i].service_id, service_id) == 0) {
            for (; i < registry_size - 1; i++) {
                registry[i] = registry[i + 1];
            }
            registry_size--;
            return;
        }
    }
}

void log_operation(const char* operation, int result) {
    printf("%s: %d\n", operation, result);
}
