use tokio::net::{TcpStream, TcpListener};
use tokio_stream::wrappers::TcpListenerStream;
use std::pin::Pin;
use std::future::Future;

pub async fn create_network_client(address: &str) -> Result<NetworkClient, Box<dyn std::error::Error>> {
    let listener = TcpListener::bind(address).await?;
    Ok(NetworkClient { listener })
}

pub struct NetworkClient {
    listener: TcpListener,
}

impl NetworkClient {
    pub fn listen(&mut self) -> impl Future<Output = Result<(), Box<dyn std::error::Error>>> {
        let stream = TcpListenerStream::new(self.listener);
        async move {
            for incoming in stream {
                match incoming {
                    Ok((stream, addr)) => {
                        println!("Accepted connection from {:?}", addr);
                        // Handle the stream asynchronously
                    }
                    Err(e) => {
                        eprintln!("Failed to accept connection: {}", e);
                    }
                }
            }
        }
    }
}

impl Drop for NetworkClient {
    fn drop(&mut self) {
        // Clean up resources if necessary
    }
}
