import subprocess
import os
import yaml

def generate_kubernetes_manifest(service_name, image_tag):
    manifest = {
        'apiVersion': 'apps/v1',
        'kind': 'Deployment',
        'metadata': {
            'name': service_name
        },
        'spec': {
            'replicas': 3,
            'selector': {
                'matchLabels': {
                    'app': service_name
                }
            },
            'template': {
                'metadata': {
                    'labels': {
                        'app': service_name
                    }
                },
                'spec': {
                    'containers': [{
                        'name': service_name,
                        'image': f'{service_name}:{image_tag}',
                        'env': [
                            {'name': 'ENV_VAR1', 'value': 'value1'},
                            {'name': 'ENV_VAR2', 'value': 'value2'}
                        ]
                    }]
                }
            }
        }
    }
    with open(f'{service_name}-deployment.yaml', 'w') as f:
        yaml.dump(manifest, f)

def apply_kubernetes_manifest(service_name):
    try:
        subprocess.run(['kubectl', 'apply', '-f', f'{service_name}-deployment.yaml'], check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f'Failed to apply Kubernetes manifest: {e}')

def update_environment_variables(service_name, env_vars):
    with open(f'{service_name}-deployment.yaml', 'r') as f:
        manifest = yaml.safe_load(f)

    for container in manifest['spec']['template']['spec']['containers']:
        for i, env_var in enumerate(container['env']):
            if env_var['name'] in env_vars:
                container['env'][i]['value'] = env_vars[env_var['name']]

    with open(f'{service_name}-deployment.yaml', 'w') as f:
        yaml.dump(manifest, f)

def enable_horizontal_pod_autoscaling(service_name, metric_name, target_value):
    try:
        subprocess.run(['kubectl', 'autoscale', 'deployment', service_name, '--cpu-percent=50'], check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f'Failed to enable horizontal pod autoscaling: {e}')

def deploy_service(service_name, image_tag, env_vars=None):
    generate_kubernetes_manifest(service_name, image_tag)
    if env_vars:
        update_environment_variables(service_name, env_vars)
    apply_kubernetes_manifest(service_name)
    enable_horizontal_pod_autoscaling(service_name, 'cpu', 50)

if __name__ == '__main__':
    service_name = 'my-service'
    image_tag = 'latest'
    env_vars = {'ENV_VAR1': 'new_value1', 'ENV_VAR2': 'new_value2'}
    deploy_service(service_name, image_tag, env_vars)
```

