import subprocess
import time
import requests

def fetch_encrypted_password(vault_url, max_attempts=5, backoff_factor=2):
    attempt = 0
    while attempt < max_attempts:
        try:
            response = requests.get(vault_url)
            response.raise_for_status()
            encrypted_password = response.json().get('password')
            if encrypted_password and isinstance(encrypted_password, str):
                return encrypted_password
            else:
                raise ValueError("Invalid password format from vault")
        except (requests.RequestException, ValueError) as e:
            attempt += 1
            if attempt == max_attempts:
                raise Exception("Failed to fetch encrypted password from vault") from e
            time.sleep(backoff_factor * (2 ** attempt))

def modify_kickstart_file(input_file, output_file, placeholder_values):
    with open(input_file, 'r') as infile, open(output_file, 'w') as outfile:
        for line in infile:
            for key, value in placeholder_values.items():
                line = line.replace(key, value)
            if 'encrypted_password' in placeholder_values:
                encrypted_password = fetch_encrypted_password(placeholder_values['vault_url'])
                new_line = f"new_option {encrypted_password}\n"
                outfile.write(new_line)

# Example usage
input_file = 'kickstart.cfg'
output_file = 'modified_kickstart.cfg'
placeholder_values = {
    'PLACEHOLDER1': 'value1',
    'PLACEHOLDER2': 'value2',
