using System;
using System.Data.SqlClient;
using System.Threading;

public class SecureAccountManager : IDisposable
{
    private double minValue;
    private double maxValue;
    private Random random = new Random();

    public SecureAccountManager(double minValue, double maxValue)
    {
        SetRange(minValue, maxValue);
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue <= maxValue)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
        else
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        double randomValue = random.NextDouble() * (maxValue - minValue) + minValue;
        return Convert.ToInt32(randomValue);
    }

    public Vector3 GenerateRandomVector3()
    {
        float x = GenerateRandomFloat();
        float y = GenerateRandomFloat();
        float z = GenerateRandomFloat();
        return new Vector3(x, y, z);
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("Start date must be less than or equal to end date.");
        }

        long randomTicks = startDate.Ticks + (long)(random.NextDouble() * (endDate.Ticks - startDate.Ticks));
        return new DateTime(randomTicks);
    }

    public override string ToString()
    {
        if (minValue == maxValue)
        {
            return $"Range: Single value {minValue}";
        }
        else
        {
            return $"Range: {minValue} to {maxValue}";
        }
    }

    public byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode padding)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Padding = padding;

            ICryptoTransform decryptor = aes.CreateDecryptor();
            return decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
        }
    }

    public void SimulateNetworkLatency(int minDelay, int maxDelay)
    {
        int delay = random.Next(minDelay, maxDelay + 1);
        Thread.Sleep(delay);
    }

    // Implement IDisposable pattern
    private bool disposed = false;
    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                // Dispose managed resources here.
            }

            // Dispose unmanaged resources here.

            disposed = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    ~SecureAccountManager()
    {
        Dispose(false);
    }
}
