void logError(const char* message) {
    // Implement error logging logic here
    printf("ERROR: %s\n", message);
}

void logWarning(const char* message) {
    // Implement warning logging logic here
    printf("WARNING: %s\n", message);
}

int initializeDataPacketArray(DataPacket** packets, size_t initialSize) {
    *packets = (DataPacket*)malloc(initialSize * sizeof(DataPacket));
    if (*packets == NULL) {
        logError("Failed to allocate memory for DataPacket array");
        return -1;
    }
    srand(time(NULL));
    for (size_t i = 0; i < initialSize; ++i) {
        (*packets)[i].timestamp = time(NULL);
        (*packets)[i].sourceID = rand() % 256;
        (*packets)[i].payloadLength = rand() % 1024;
    }
    return 0;
}

int addDataPacket(DataPacket** packets, size_t* currentSize, size_t* maxSize) {
    if (*currentSize >= *maxSize) {
        *maxSize *= 2;
        DataPacket* newPackets = (DataPacket*)realloc(*packets, *maxSize * sizeof(DataPacket));
        if (newPackets == NULL) {
            logError("Failed to reallocate memory for DataPacket array");
            return -1;
        }
        *packets = newPackets;
    }
    (*packets)[*currentSize].timestamp = time(NULL);
    (*packets)[*currentSize].sourceID = rand() % 256;
    (*packets)[*currentSize].payloadLength = rand() % 1024;
    ++(*currentSize);
    return 0;
}

void exportDataPacketArray(DataPacket* packets, size_t size) {
    // Implement data packet array export logic here
    for (size_t i = 0; i < size; ++i) {
        printf("Timestamp: %ld, Source ID: %d, Payload Length: %zu\n", 
               packets[i].timestamp, packets[i].sourceID, packets[i].payloadLength);
    }
}

int main() {
    DataPacket* packets;
    size_t currentSize = 0;
    size_t maxSize = 100;

    if (initializeDataPacketArray(&packets, maxSize) != 0) {
        return -1;
    }

    for (size_t i = 0; i < 500; ++i) {
        if (addDataPacket(&packets, &currentSize, &maxSize) != 0) {
            break;
        }
    }

    exportDataPacketArray(packets, currentSize);

    free(packets);
    return 0;
}
