using System;
using System.Security.Cryptography;
using Microsoft.AspNet.Identity;

public class SecureAccountManager : IDisposable
{
    private double minValue = 0.0;
    private double maxValue = 1.0;
    private static readonly RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();

    public SecureAccountManager(double initialValue, double maxValue)
    {
        if (maxValue < initialValue) throw new ArgumentException("Max value must be greater than min value.");
        this.minValue = initialValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        byte[] buffer = new byte[4];
        rng.GetBytes(buffer);
        return BitConverter.ToSingle(buffer, 0) * (float)(maxValue - minValue) + (float)minValue;
    }

    public int GenerateRandomInt()
    {
        byte[] buffer = new byte[4];
        rng.GetBytes(buffer);
        return BitConverter.ToInt32(buffer, 0) % ((int)maxValue - (int)minValue + 1) + (int)minValue;
    }

    public Vector3 GenerateRandomVector3()
    {
        float x = GenerateRandomFloat();
        float y = GenerateRandomFloat();
        float z = GenerateRandomFloat();
        return new Vector3(x, y, z);
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMaxValue < newMinValue) throw new ArgumentException("New max value must be greater than new min value.");
        minValue = newMinValue;
        maxValue = newMaxValue;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random rnd = new Random();
        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        long ticks = (long)(rnd.NextDouble() * (endTicks - startTicks)) + startTicks;
        return new DateTime(ticks);
    }

    public override string ToString()
    {
        if (maxValue == minValue) return "Range is zero or negative.";
        return $"Range: {minValue} to {maxValue}";
    }

    #region IDisposable Support
    private bool disposed = false;

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                // Dispose managed state (managed objects).
            }

            // Free unmanaged resources (unmanaged objects) and override a finalizer below.
            rng.Dispose();

            disposed = true;
        }
    }

    // Override a finalizer only if Dispose(bool disposing) above has code to free unmanaged resources.
    ~SecureAccountManager()
    {
        Dispose(false);
    }

    // This code added to correctly implement the disposable pattern.
    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
    #endregion

    // Additional methods and properties can be added here as needed
}
