import os
import subprocess
from collections import defaultdict

def process_config_files(directory, config_dict):
    report = defaultdict(int)
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.conf'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r') as f:
                        content = f.read()
                    for key, value in config_dict.items():
                        content = content.replace(key, value)
                    with open(file_path, 'w') as f:
                        f.write(content)
                    subprocess.run(['chmod', '+r', file_path], check=True)
                    report['successful_replacements'] += 1
                except Exception as e:
                    print(f"Failed to process {file_path}: {e}")
                    report['failures'] += 1
    report['total_files_processed'] = len(report) - 2
    return dict(report)

# Example usage
directory_path = '/path/to/configs'
configurations = {
    'old_value': 'new_value',
    'another_old_value': 'another_new_value'
}
result = process_config_files(directory_path, configurations)
print(result)
