using System;
using System.IO;
using System.Reflection;

public class DynamicRangeValueGenerator
{
    private float minValue;
    private float maxValue;
    private Random random = new Random();

    public DynamicRangeValueGenerator()
    {
        LoadRangeFromConfig();
    }

    public DynamicRangeValueGenerator(float min, float max)
    {
        SetRange(min, max);
    }

    public void SetRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Min value must be less than max value.");
        minValue = min;
        maxValue = max;
    }

    private void LoadRangeFromConfig()
    {
        string configPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "config.txt");
        try
        {
            string[] lines = File.ReadAllLines(configPath);
            if (lines.Length != 2)
                throw new FormatException("Invalid configuration file format.");
            float min = float.Parse(lines[0]);
            float max = float.Parse(lines[1]);
            SetRange(min, max);
        }
        catch (FileNotFoundException)
        {
            Console.WriteLine("Configuration file not found. Using default range.");
        }
        catch (FormatException)
        {
            Console.WriteLine("Invalid configuration format. Using default range.");
        }
    }

    public float GetRandomFloat()
    {
        return random.Next((int)(minValue * 100), (int)(maxValue * 100)) / 100f;
    }

    public int GetRandomInt()
    {
        return random.Next((int)minValue, (int)Math.Ceiling(maxValue));
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }
}
