#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <mutex>
#include <condition_variable>
#include <queue>

class NetworkDataProcessor {
private:
    std::vector<std::function<void(const std::string&)>> processingRules;
    std::queue<std::string> packetBuffer;
    mutable std::mutex bufferMutex;
    std::condition_variable bufferCond;

public:
    NetworkDataProcessor() {
        // Load default rules or handle dependency on external configuration file
        loadDefaultRules();
    }

    void addProcessingRule(const std::function<void(const std::string&)>& rule) {
        processingRules.push_back(rule);
    }

    void processIncomingPacket(const std::string& packet) {
        std::lock_guard<std::mutex> lock(bufferMutex);
        packetBuffer.push(packet);
        bufferCond.notify_one();
    }

    std::vector<std::string> getProcessedData() {
        std::vector<std::string> results;
        std::unique_lock<std::mutex> lock(bufferMutex);
        while (!packetBuffer.empty()) {
            std::string packet = packetBuffer.front();
            packetBuffer.pop();
            for (auto& rule : processingRules) {
                rule(packet);
            }
            results.push_back(packet);
        }
        return results;
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(bufferMutex);
        std::ostringstream oss;
        oss << "Packet Buffer Size: " << packetBuffer.size() << "\n";
        oss << "Processing Rules: ";
        for (const auto& rule : processingRules) {
            oss << "[Rule] ";
        }
        return oss.str();
    }

private:
    void loadDefaultRules() {
        // Load default rules or handle dependency on external configuration file
        processingRules.push_back([](const std::string& packet) {
            std::cout << "Processing Packet: " << packet << "\n";
        });
    }
};
