#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
} CRC_Management_T;

CRC_Management_T* crc_management_init() {
    CRC_Management_T *manager = (CRC_Management_T*)malloc(sizeof(CRC_Management_T));
    if (!manager) {
        return NULL; // Memory allocation failure
    }
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL; // Memory allocation failure for array
    }
    manager->count = 0;
    manager->capacity = MAX_ELEMENTS;
    srand(time(NULL)); // Seed for random number generation
    return manager;
}

void crc_management_add(CRC_Management_T *manager, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (manager->count >= manager->capacity) {
        return; // Array is full, no more elements can be added
    }
    manager->array[manager->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->array[manager->count].RNTI = RNTI;
    manager->array[manager->count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    manager->count++;
}

size_t crc_management_get_count(CRC_Management_T *manager) {
    return manager->count;
}

void crc_management_reset_crcflags(CRC_Management_T *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        manager->array[i].CRCFLAG = 0; // Reset CRCFLAG to default state
    }
}

void crc_management_free(CRC_Management_T *manager) {
    free(manager->array);
    free(manager);
}
