    private int resourcePoolMin;
    private int resourcePoolMax;
    private readonly object lockObject = new object();
    private Dictionary<string, byte[]> cache = new Dictionary<string, byte[]>();

    public DynamicResourceManager(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("resourcePoolMin must be less than or equal to resourcePoolMax");
        resourcePoolMin = min;
        resourcePoolMax = max;
    }

    public void AllocateResource()
    {
        lock (lockObject)
        {
            // Logic to allocate a resource
        }
    }

    public void ReleaseResource()
    {
        lock (lockObject)
        {
            // Logic to release a resource
        }
    }

    public void AdjustPool(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("resourcePoolMin must be less than or equal to resourcePoolMax");
        lock (lockObject)
        {
            resourcePoolMin = min;
            resourcePoolMax = max;
        }
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random rnd = new Random();
        return startDate.AddTicks((long)(rnd.NextDouble() * (endDate.Ticks - startDate.Ticks)));
    }

    public override string ToString()
    {
        return $"Resource Pool: Min={resourcePoolMin}, Max={resourcePoolMax}";
    }

    public byte[] DecryptAES(string ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(ciphertext)))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    return csDecrypt.ToArray();
                }
            }
        }
    }

    public void CacheResource(string key, byte[] data)
    {
        lock (lockObject)
        {
            if (!cache.ContainsKey(key))
                cache[key] = data;
        }
    }

    public byte[] GetCachedResource(string key)
    {
        if (cache.ContainsKey(key))
            return cache[key];
        return null;
    }
}
