import yaml
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)

def generate_kubernetes_manifest(service_name):
    # Generate Kubernetes YAML manifest for the specified service
    manifest = {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {
            "name": service_name
        },
        "spec": {
            "replicas": 1,
            "selector": {
                "matchLabels": {
                    "app": service_name
                }
            },
            "template": {
                "metadata": {
                    "labels": {
                        "app": service_name
                    }
                },
                "spec": {
                    "containers": [
                        {
                            "name": service_name,
                            "image": f"private-registry.com/{service_name}:latest",
                            "env": [
                                {"name": "ENV_VAR_1", "value": "value1"},
                                {"name": "ENV_VAR_2", "value": "value2"}
                            ]
                        }
                    ]
                }
            }
        }
    }
    return yaml.dump(manifest, default_flow_style=False)

def update_environment_variables(manifest, env_vars):
    # Update environment variables in the Kubernetes manifest
    data = yaml.safe_load(manifest)
    for container in data['spec']['template']['spec']['containers']:
        for key, value in env_vars.items():
            if key not in [e['name'] for e in container['env']]:
                container['env'].append({'name': key, 'value': value})
    return yaml.dump(data, default_flow_style=False)

def apply_kubernetes_manifest(manifest):
    # Apply the Kubernetes manifest to the cluster
    try:
        subprocess.run(['kubectl', 'apply', '-f', '-', '--validate'], input=manifest.encode(), check=True)
        logging.info("Manifest applied successfully")
    except subprocess.CalledProcessError as e:
        logging.error(f"Failed to apply manifest: {e}")
        raise

def validate_manifest(manifest):
    # Validate the integrity of the Kubernetes manifest
    try:
        subprocess.run(['kubectl', 'api-versions'], check=True)
        yaml.safe_load(manifest)  # This will raise an error if the YAML is invalid
        logging.info("Manifest validation successful")
    except (subprocess.CalledProcessError, yaml.YAMLError) as e:
        logging.error(f"Manifest validation failed: {e}")
        raise

