    {
        return (int)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public Vector3 GenerateRandomVector3()
    {
        float x = (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
        float y = (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
        float z = (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
        return new Vector3(x, y, z);
    }

