#define MAX_PDU_COUNT 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

uint32_t calculate_crc(uint32_t tag, uint32_t rnti) {
    // Simple rolling checksum algorithm
    return (tag + rnti) % 0xFF;
}

int validate_rx_tag(uint32_t tag) {
    // Simulate external data source validation
    // Replace with actual validation logic
    return (tag > 100); // Example condition
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(uint32_t *rx_tags, size_t rx_count, uint32_t max_rnti) {
    if (rx_count == 0 || max_rnti < 100 || max_rnti > 65535) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(rx_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    uint8_t rnti_set[65536] = {0}; // Assuming RNTI values are within 16-bit range
    size_t pdu_index = 0;

    for (size_t i = 0; i < rx_count && pdu_index < max_rnti; ++i) {
        uint32_t tag = rx_tags[i];
        if (!validate_rx_tag(tag)) continue;

        // Find a unique RNTI
        uint32_t rnti;
        do {
            rnti = rand() % 65536;
        } while (rnti_set[rnti]);

        rnti_set[rnti] = 1;
        pdu_list[pdu_index].RX_UE_INFORMATION_TAG = tag;
        pdu_list[pdu_index].RNTI = rnti;
        pdu_list[pdu_index].CRC_INDICATION_REL8_TAG = calculate_crc(tag, rnti);

        ++pdu_index;
    }

    if (pdu_index < rx_count) {
        // Resize the array to fit the actual number of PDUs
        NFAPI_CRC_INDICATION_PDU_T *new_pdu_list = realloc(pdu_list, pdu_index * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu_list) {
            free(pdu_list);
            return NULL;
        }
        pdu_list = new_pdu_list;
    }

    return pdu_list;
}

void free_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t count) {
    free(pdu_list);
}
