#include <pthread.h>

// Function prototypes
void* process_file(void* arg);
int transform_line(char* line, const char* search, const char* replace);
int is_alpha_only(const char* line);

int main(int argc, char* argv[]) {
    // Command line argument parsing and setup code here

    pthread_t threads[argc];
    for (int i = 0; i < argc - 1; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, (void*)argv[i + 1]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup and finalization code here

    return EXIT_SUCCESS;
}

void* process_file(void* arg) {
    const char* filename = (const char*)arg;
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        pthread_exit(NULL);
    }

    // Process the file line by line
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Apply transformations
        transform_line(buffer, search_substring, replace_substring);

        // Write the transformed line to output or log as needed
        if (output_file) {
            fputs(buffer, output_file);
        } else if (!is_alpha_only(buffer)) {
            log_message(buffer); // Log lines that contain non-alphabetic characters
        }
    }

    fclose(file);
    pthread_exit(NULL);
}

int transform_line(char* line, const char* search, const char* replace) {
    // Replace substring and convert to lowercase
    size_t pos = 0;
    while ((pos = strstr(line + pos, search)) != NULL) {
        strncpy(pos, replace, strlen(replace));
        pos += strlen(replace);
    }

    for (char* c = line; *c; ++c) {
        *c = tolower(*c);
    }

    return 0;
}

int is_alpha_only(const char* line) {
    while (*line) {
        if (!isalpha((unsigned char)*line)) {
            return 0;
        }
        ++line;
    }
    return 1;
}
