public class DynamicValueManager
{
    private decimal minValue;
    private decimal maxValue;
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();
    private readonly IMemoryCache _cache;

    public DynamicValueManager(IMemoryCache cache)
    {
        _cache = cache;
    }

    private void ValidateRange(decimal newMin, decimal newMax)
    {
        if (newMin > newMax || newMin < 0 || newMax < 0)
            throw new ArgumentException("Invalid range values");
        minValue = newMin;
        maxValue = newMax;
    }

    public double GenerateRandomDouble()
    {
        Random random = new Random();
        decimal randomValue = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        return Convert.ToDouble(randomValue);
    }

    public float GenerateRandomFloat()
    {
        Random random = new Random();
        decimal randomValue = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        return Convert.ToSingle(randomValue);
    }

    public int GenerateRandomInt()
    {
        Random random = new Random();
        decimal randomValue = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        return Convert.ToInt32(randomValue);
    }

    public Vector3 GenerateRandomVector3()
    {
        Random random = new Random();
        decimal x = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        decimal y = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        decimal z = minValue + (decimal)random.NextDouble() * (maxValue - minValue);
        return new Vector3(x, y, z);
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random random = new Random();
        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        long diffTicks = endTicks - startTicks;

        long randomTicks = startTicks + (long)(random.NextDouble() * diffTicks);
        return new DateTime(randomTicks);
    }

    public void AdjustRange(decimal newMin, decimal newMax)
    {
        ValidateRange(newMin, newMax);
        _cache.Remove("CurrentRange");
    }

    public void CreateUserWithIdentity(string username, string password)
    {
        var userManager = new UserManager<IdentityUser>(new UserStore<IdentityUser>());
        var user = new IdentityUser { UserName = username };
        var result = userManager.CreateAsync(user, password).Result;

        if (result.Succeeded)
        {
            logger.Info($"User created successfully: {username}");
        }
        else
        {
            logger.Error($"Failed to create user: {username}, Errors: {string.Join(", ", result.Errors)}");
        }
    }

    public void ChangePasswordWithIdentity(string username, string currentPassword, string newPassword)
    {
        var userManager = new UserManager<IdentityUser>(new UserStore<IdentityUser>());
        var user = userManager.FindByNameAsync(username).Result;

        if (user != null && userManager.CheckPasswordAsync(user, currentPassword).Result)
        {
            var result = userManager.ChangePasswordAsync(user, currentPassword, newPassword).Result;

            if (result.Succeeded)
            {
                logger.Info($"Password changed successfully for user: {username}");
            }
            else
            {
                logger.Error($"Failed to change password for user: {username}, Errors: {string.Join(", ", result.Errors)}");
            }
        }
        else
        {
            logger.Warn("Invalid username or current password provided.");
        }
    }

    public void EnableMultiFactorAuthentication(string userId)
    {
        var userManager = new UserManager<IdentityUser>(new UserStore<IdentityUser>());
        var user = userManager.FindByIdAsync(userId).Result;

        if (user != null)
        {
            userManager.AddToRoleAsync(user.Id, "TwoFactorEnabled").Wait();
            logger.Info($"Multi-factor authentication enabled for user: {userId}");
        }
        else
        {
            logger.Warn("User not found.");
        }
    }

    public void LogActivity(string activityType, string username)
    {
        logger.Info($"{activityType} performed by user: {username}");
    }
}
