using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicValueManager
{
    private decimal minValue;
    private decimal maxValue;

    public DynamicValueManager(decimal initialMinValue, decimal initialMaxValue)
    {
        SetRange(initialMinValue, initialMaxValue);
    }

    private void SetRange(decimal min, decimal max)
    {
        if (min <= max)
        {
            minValue = min;
            maxValue = max;
        }
        else
        {
            throw new ArgumentException("Invalid range: minValue must be less than or equal to maxValue.");
        }
    }

    public double GetRandomDouble()
    {
        return (double)GetRandomDecimal();
    }

    public float GetRandomFloat()
    {
        return (float)GetRandomDecimal();
    }

    public int GetRandomInt()
    {
        return (int)Math.Round(GetRandomDecimal());
    }

    public Vector3 GetRandomVector3()
    {
        decimal x = GetRandomDecimal();
        decimal y = GetRandomDecimal();
        decimal z = GetRandomDecimal();
        return new Vector3(x, y, z);
    }

    private decimal GetRandomDecimal()
    {
        Random random = new Random();
        decimal range = maxValue - minValue;
        decimal value = (decimal)random.NextDouble() * range + minValue;
        return Math.Round(value, MidpointRounding.AwayFromZero);
    }

    public void AdjustRange(decimal min, decimal max)
    {
        SetRange(min, max);
    }

    public DateTime GetRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random random = new Random();
        DateTimeOffset offset = endDate - startDate;
        long totalMilliseconds = (long)(offset.TotalMilliseconds * random.NextDouble());
        return startDate.AddMilliseconds(totalMilliseconds);
    }
}
