# Configuration modification script
def modify_config(config_file, placeholders, values):
    try:
        with open(config_file, 'r') as file:
            config_data = file.read()

        for placeholder, value in zip(placeholders, values):
            config_data = config_data.replace(placeholder, value)

        new_file_name = f"{config_file.split('.')[0]}_updated.{config_file.split('.')[-1]}"
        with open(new_file_name, 'w') as file:
            file.write(config_data)

        logging.info(f"Configuration updated and saved to {new_file_name}")
