uint8_t generateCRCFlag(uint64_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    uint8_t crc = 0;
    for (int i = sizeof(RX_UE_INFORMATION_TAG); i > 0; --i) {
        crc += (uint8_t)(RX_UE_INFORMATION_TAG >> ((i - 1) * 8));
    }
    for (int i = sizeof(RNTI); i > 0; --i) {
        crc += (uint8_t)(RNTI >> ((i - 1) * 8));
    }
    return crc;
}

// Helper function to validate RX_UE_INFORMATION_TAG from an external data source
bool validateRX_UE_INFORMATION_TAG(uint64_t RX_UE_INFORMATION_TAG) {
    // Simulate a network timeout and retry mechanism
    static int attempt = 0;
    if (attempt < 3) {
        ++attempt;
        return false; // Retry
    }
    attempt = 0;
    return true; // Valid
}

