['```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY_RESERVATION 1024 * 1024 * 1024 // 1GB

typedef struct {
    int chunkID;
    size_t size;
    void* data;
} DataChunk;

typedef struct {
    sem_t lock;
    sem_t metadata_lock;
    DataChunk** chunks;
    size_t total_chunks;
    size_t reserved_memory;
    double read_latency;
    size_t max_memory_consumption;
    size_t total_data_processed;
} MemoryManager;

MemoryManager* createMemoryManager() {
    MemoryManager* mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    sem_init(&mm->lock, 0, 1);
    sem_init(&mm->metadata_lock, 0, 1);
    mm->chunks = NULL;
    mm->total_chunks = 0;
    mm->reserved_memory = 0;
    mm->read_latency = 0.0;
    mm->max_memory_consumption = 0;
    mm->total_data_processed = 0;
    return mm;
}

void destroyMemoryManager(MemoryManager* mm) {
    sem_destroy(&mm->lock);
    sem_destroy(&mm->metadata_lock);
    for (size_t i = 0; i < mm->total_chunks; ++i) {
        free(mm->chunks[i]->data);
        free(mm->chunks[i]);
    }
    free(mm->chunks);
    free(mm);
}

void* allocateMemory(MemoryManager* mm, int chunkID, size_t size) {
    sem_wait(&mm->lock);
    if (mm->reserved_memory + size > MAX_MEMORY_RESERVATION) {
        sem_post(&mm->lock);
        return NULL;
    }
    DataChunk* new_chunk = (DataChunk*)malloc(sizeof(DataChunk));
    new_chunk->chunkID = chunkID;
    new_chunk->size = size;
    new_chunk->data = malloc(size);
    mm->chunks = realloc(mm->chunks, (mm->total_chunks + 1) * sizeof(DataChunk*));
    mm->chunks[mm->total_chunks] = new_chunk;
    mm->total_chunks++;
    mm->reserved_memory += size;
    sem_post(&mm->lock);
    return new_chunk->data;
}

void deallocateMemory(MemoryManager* mm, int chunkID) {
    sem_wait(&mm->lock);
    for (size_t i = 0; i < mm->total_chunks; ++i) {
        if (mm->chunks[i]->chunkID == chunkID) {
            free(mm->chunks[i]->data);
            free(mm->chunks[i]);
            memmove(&mm->chunks[i], &mm->chunks[i + 1], (mm->total_chunks - i - 1) * sizeof(DataChunk*));
            mm->total_chunks--;
            mm->reserved_memory -= mm->chunks[i]->size;
            break;
        }
    }
    sem_post(&mm->lock);
}

void updateMetrics(MemoryManager* mm, double latency, size_t consumption, size_t processed_data) {
    sem_wait(&mm->metadata_lock);
    if (latency > mm->read_latency) {
        mm->read_latency = latency;
    }
    if (consumption > mm->max_memory_consumption) {
        mm->max_memory_consumption = consumption;
    }
    mm->total_data_processed += processed_data;
    sem_post(&mm->metadata_lock);
}
