    int RNTI;
    char CRC_INDICATION_REL8_TAG[1];
} NFAPI_CRC_INDICATION_PDU_T;

int validate_rx_ue_info(int tag) {
    // Simulated validation function
    return (tag >= 1 && tag <= 100);
}

void generate_crc_flag(char *crc_flag, int rx_tag, int rnti) {
    // Simulated CRC flag generation using rolling checksum algorithm
    snprintf(crc_flag, 2, "%d", (rx_tag + rnti) % 256);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(int num_pdus, int max_rnti, int *error_code) {
    if (num_pdus > MAX_PDU_COUNT || num_pdus <= 0) {
        *error_code = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        *error_code = -2;
        return NULL;
    }

    int rnti_set[100] = {0}; // Assuming max RNTI is 100 for simplicity
    int current_rnti = 1;

    for (int i = 0; i < num_pdus; i++) {
        while (rnti_set[current_rnti]) {
            current_rnti++;
            if (current_rnti > max_rnti) {
                free(pdu_list);
                *error_code = -3;
                return NULL;
            }
        }

        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1; // Simulated RX_UE_INFORMATION_TAG
        while (!validate_rx_ue_info(pdu_list[i].RX_UE_INFORMATION_TAG)) {
            pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        }

        rnti_set[current_rnti] = 1;
        pdu_list[i].RNTI = current_rnti;

        generate_crc_flag(pdu_list[i].CRC_INDICATION_REL8_TAG, pdu_list[i].RX_UE_INFORMATION_TAG, current_rnti);
    }

    *error_code = 0;
    return pdu_list;
}

int main() {
    srand(time(NULL));
    int num_pdus = 5;
    int max_rnti = 100;
    int error_code;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_pdu_list(num_pdus, max_rnti, &error_code);
    if (pdu_list == NULL) {
        printf("Failed to create PDU list with error code: %d\n", error_code);
        return 1;
    }

    for (int i = 0; i < num_pdus; i++) {
        printf("PDU %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%s\n",
               i, pdu_list[i].RX_UE_INFORMATION_TAG, pdu_list[i].RNTI, pdu_list[i].CRC_INDICATION_REL8_TAG);
    }

    free(pdu_list);
    return 0;
}
