import hashlib

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(4096):  # Read in chunks to handle large files
            hasher.update(chunk)
    return hasher.hexdigest()
```

