using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private static readonly Random random = new Random();
    private string lastOperation = "";

    public DynamicValueGenerator(double initialMin, double initialMax)
    {
        if (initialMin < 0 || initialMax < 0 || initialMin > initialMax)
        {
            throw new ArgumentException("Invalid range. Ensure minValue is less than or equal to maxValue.");
        }

        minValue = initialMin;
        maxValue = initialMax;
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + random.NextDouble() * (maxValue - minValue));
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(minValue + random.NextDouble() * (maxValue - minValue));
    }

    public double GenerateRandomDouble()
    {
        return minValue + random.NextDouble() * (maxValue - minValue);
    }

    public void AdjustRange(double newMin, double newMax)
    {
        if (newMin < 0 || newMax < 0 || newMin > newMax)
        {
            Console.WriteLine("Warning: New range is invalid. Operation not performed.");
            return;
        }

        minValue = newMin;
        maxValue = newMax;
        lastOperation = $"Adjusted range to ({minValue}, {maxValue})";
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)(minValue + random.NextDouble() * (maxValue - minValue)),
            (float)(minValue + random.NextDouble() * (maxValue - minValue)),
            (float)(minValue + random.NextDouble() * (maxValue - minValue))
        );
    }

    public Quaternion GenerateRandomQuaternion()
    {
        float angleX = (float)(minValue + random.NextDouble() * (maxValue - minValue));
        float angleY = (float)(minValue + random.NextDouble() * (maxValue - minValue));
        float angleZ = (float)(minValue + random.NextDouble() * (maxValue - minValue));
        return Quaternion.Euler(angleX, angleY, angleZ);
    }

    public override string ToString()
    {
        return $"Current Range: ({minValue}, {maxValue}), Last Operation: {lastOperation}";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("Invalid date range.");
        }

        return startDate.AddMilliseconds(random.Next((int)(endDate - startDate).TotalMilliseconds));
    }
}
