    }

    if (!config.dry_run) {
        // Simulate file processing
        std::ofstream output_file(config.output_directory + file_path.filename().stem() + "_" + std::to_string(std::chrono::system_clock::now().time_since_epoch().count()) + ".txt");
        for (int i = 0; i < local_line_count; ++i) {
            output_file << "Processed line " << i << std::endl;
        }
    }

    line_count += local_line_count;

    if (config.verbose) {
        std::lock_guard<std::mutex> lock(log_mutex);
        std::cout << "Processed lines: " << local_line_count << std::endl;
    }
}

void process_directory(const fs::path& dir_path, const Config& config) {
    for (const auto& entry : fs::directory_iterator(dir_path)) {
        if (entry.is_regular_file() && std::regex_match(entry.path().filename().string(), std::regex(config.filter))) {
            process_file(entry.path(), config);
        } else if (entry.is_directory()) {
            process_directory(entry.path(), config);
        }
    }
}

void compress_files(const fs::path& output_dir) {
    zip_t* zip = zip_open((output_dir / "processed_files.zip").c_str(), ZIP_CREATE | ZIP_TRUNCATE, NULL);
    if (!zip) {
        std::cerr << "Failed to create ZIP file" << std::endl;
        return;
    }

    for (const auto& entry : fs::directory_iterator(output_dir)) {
        if (entry.is_regular_file() && entry.path().filename().string().find(config.output_directory) != std::string::npos) {
            zip_source_t* source = zip_source_file(zip, entry.path().c_str(), 0, 0);
            if (!source || zip_file_add(zip, entry.path().filename().c_str(), source, ZIP_FL_ENC_GUESS) < 0) {
                std::cerr << "Failed to add file to ZIP archive" << std::endl;
                zip_source_free(source);
                break;
            }
        }
    }

    zip_close(zip);
}

void log(const std::string& message, const Config& config) {
    // Log message to external logging system
    if (config.verbose) {
        std::lock_guard<std::mutex> lock(log_mutex);
        std::cout << message << std::endl;
    }
}

int main(int argc, char* argv[]) {
    Config config;
    // Parse command line arguments and populate config

    if (config.help) {
        std::cerr << "Usage: program_name [options] <input_directory>" << std::endl;
        return 1;
    }

    fs::path input_dir = argv[argc - 1];

    if (!fs::exists(input_dir) || !fs::is_directory(input_dir)) {
        std::cerr << "Invalid input directory" << std::endl;
        return 1;
    }

    log("Starting file processing", config);

    auto start_time = std::chrono::high_resolution_clock::now();

    if (config.dry_run) {
        process_directory(input_dir, config);
    } else {
        fs::path output_dir = config.output_directory + std::to_string(std::chrono::system_clock::now().time_since_epoch().count());
        fs::create_directories(output_dir);

        std::vector<std::thread> threads;
        for (const auto& entry : fs::directory_iterator(input_dir)) {
            if (entry.is_regular_file() && std::regex_match(entry.path().filename().string(), std::regex(config.filter))) {
                threads.emplace_back(process_file, entry.path(), config);
            } else if (entry.is_directory()) {
                threads.emplace_back(process_directory, entry.path(), config);
            }
        }

        for (auto& thread : threads) {
            thread.join();
        }

        if (config.compress) {
            compress_files(output_dir);
        }
    }

    auto end_time = std::chrono::high_resolution_clock::now();

    log("File processing complete", config);

    if (config.summary) {
        std::cout << "Total lines processed: " << line_count << std::endl;
    }

    return 0;
}
