using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue < double.MinValue || maxValue > double.MaxValue)
            throw new ArgumentException("Range limits exceed system double precision.");
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than or equal to max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)GenerateRandomDouble();
    }

    public int GenerateRandomInt()
    {
        return Convert.ToInt32(GenerateRandomDouble());
    }

    public double GenerateRandomDouble()
    {
        // Uniform distribution
        Random random = new Random();
        return minValue + (maxValue - minValue) * random.NextDouble();
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)GenerateRandomDouble(),
            (float)GenerateRandomDouble(),
            (float)GenerateRandomDouble());
    }

    public Quaternion GenerateRandomQuaternion()
    {
        // Limiting to prevent physically impossible rotations
        float angle = (float)(2 * Math.PI * GenerateRandomDouble());
        return Quaternion.Euler(0, angle, 0);
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        Random random = new Random();
        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        long ticks = (long)(random.NextDouble() * (endTicks - startTicks));
        return new DateTime(startTicks + ticks);
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}, Last Operation: GenerateRandomDouble";
    }
}
