import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.SecretKeySpec;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.security.spec.KeySpec;
import java.util.Base64;

public class FileEncryptionUtils {
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int KEY_SIZE = 256;

    public byte[] encryptFile(String filePath, String password) throws Exception {
        byte[] iv = generateIV();
        SecretKey secretKey = getSecretKey(password);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, new IvParameterSpec(iv));
        byte[] encryptedData = cipher.doFinal(readFile(filePath));
        return concatenateArrays(iv, encryptedData);
    }

    public byte[] decryptFile(String filePath, String password) throws Exception {
        byte[] data = readFile(filePath);
        byte[] iv = extractIV(data);
        SecretKey secretKey = getSecretKey(password);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, new IvParameterSpec(iv));
        return cipher.doFinal(extractEncryptedData(data));
    }

    private byte[] generateIV() {
        // Generate a random IV
        return new byte[16];
    }

    private SecretKey getSecretKey(String password) throws Exception {
        KeySpec spec = new PBEKeySpec(password.toCharArray(), "salt".getBytes(), 65536, KEY_SIZE);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, ALGORITHM.split("/")[0]);
    }

    private byte[] readFile(String filePath) throws Exception {
        // Read the file in chunks
        return Base64.getDecoder().decode(readFileInChunks(filePath));
    }

    private String readFileInChunks(String filePath) {
