from cryptography.fernet import Fernet

def validate_placeholders(config, placeholders):
    missing = [ph for ph in placeholders if ph not in config]
    if missing:
        raise ValueError(f"Missing required placeholders: {', '.join(missing)}")

def encrypt_password(password, key):
    fernet = Fernet(key)
    return fernet.encrypt(password.encode())

def execute_command(command, log_error=True):
    try:
        subprocess.run(command, check=True, shell=True)
    except subprocess.CalledProcessError as e:
        if log_error:
            print(f"Command failed: {e}", file=sys.stderr)
        raise

def process_config_file(input_file, output_file, config, placeholders, password_encryption_key):
    validate_placeholders(config, placeholders)

    with open(input_file, 'r') as infile, open(output_file, 'w') as outfile:
        for line in infile:
            for key, value in config.items():
                line = line.replace(key, str(value))
            outfile.write(line)

    encrypted_password = encrypt_password(config['password'], password_encryption_key)
    execute_command(f"echo 'encrypted_password={encrypted_password.decode()}' >> {output_file}")

if __name__ == "__main__":
