from Crypto.Util.Padding import pad
from Crypto.Random import get_random_bytes

def validate_placeholders(config_dict, required_placeholders):
    missing_placeholders = [placeholder for placeholder in required_placeholders if placeholder not in config_dict]
    if missing_placeholders:
        raise ValueError(f"Missing placeholders: {', '.join(missing_placeholders)}")

def encrypt_password(password, key):
    cipher = AES.new(key, AES.MODE_CBC)
    ct_bytes = cipher.encrypt(pad(password.encode(), AES.block_size))
    iv = bytes(cipher.iv)
    return f"{iv.decode('utf-8')}:{ct_bytes.decode('base64')}"

def modify_config_file(input_file, output_file, config_dict):
    required_placeholders = ["placeholder1", "placeholder2"]
    validate_placeholders(config_dict, required_placeholders)

    with open(input_file, 'r') as file:
        content = file.read()

    for key, value in config_dict.items():
        content = re.sub(rf'{key}\b', str(value), content)

    encrypted_password = encrypt_password(config_dict['password'], b'your_key_here')
    content += f"\nnew_line_with_encrypted_password:{encrypted_password}"

    with open(output_file, 'w') as file:
        file.write(content)

if __name__ == "__main__":
    input_file = sys.argv[1]
    output_file = sys.argv[2]
    config_dict = {
        "placeholder1": "value1",
        "placeholder2": "value2",
