            logger.error(f"Failed to deploy to cluster {cluster_name}: {e}")
            raise

    def deploy_all_clusters(self):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.deploy_to_cluster, cluster) for cluster in self.api_clients]
