#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 1000
#define CONFIG_FILE "tasks.conf"
#define DEFAULT_LOG_MODE "synchronous"

typedef struct {
    char *task;
} Task;

Task tasks[MAX_TASKS];
int task_count = 0;
FILE *log_file;
char *log_mode = DEFAULT_LOG_MODE;

void log_operation(const char *operation, const char *details) {
    fprintf(log_file, "%s: %s\n", operation, details);
}

void load_tasks(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (file == NULL) {
        printf("Failed to open config file.\n");
        return;
    }
    while (fgets(tasks[task_count].task, 256, file)) {
        tasks[task_count].task[strcspn(tasks[task_count].task, "\n")] = '\0';
        task_count++;
    }
    fclose(file);
}

void save_tasks(const char *config_file) {
    FILE *file = fopen(config_file, "w");
    if (file == NULL) {
        printf("Failed to open config file for writing.\n");
        return;
    }
    for (int i = 0; i < task_count; i++) {
        fprintf(file, "%s\n", tasks[i].task);
    }
    fclose(file);
}

void add_task(const char *task) {
    if (task_count >= MAX_TASKS) {
        printf("Task list is full.\n");
        return;
    }
    tasks[task_count].task = strdup(task);
    task_count++;
    log_operation("Added Task", task);
}

void remove_task(int index) {
    if (index < 0 || index >= task_count) {
        printf("Invalid task index.\n");
        return;
    }
    free(tasks[index].task);
    for (int i = index; i < task_count - 1; i++) {
        tasks[i] = tasks[i + 1];
    }
    task_count--;
    log_operation("Removed Task", "Index: ");
}

void update_task(int index, const char *new_task) {
    if (index < 0 || index >= task_count) {
        printf("Invalid task index.\n");
        return;
    }
    free(tasks[index].task);
    tasks[index].task = strdup(new_task);
    log_operation("Updated Task", "Index: ");
}

void query_tasks() {
    for (int i = 0; i < task_count; i++) {
        printf("%d: %s\n", i, tasks[i].task);
    }
}

int main(int argc, char *argv[]) {
    const char *config_file = CONFIG_FILE;
    log_mode = DEFAULT_LOG_MODE;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            config_file = argv[++i];
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            add_task(argv[++i]);
        } else if (strcmp(argv[i], "-r") == 0 && i + 1 < argc) {
            remove_task(atoi(argv[++i]));
        } else if (strcmp(argv[i], "-u") == 0 && i + 2 < argc) {
            update_task(atoi(argv[++i]), argv[++i]);
        } else if (strcmp(argv[i], "-q") == 0) {
            query_tasks();
        }
    }

    load_tasks(config_file);
    save_tasks(config_file);

    log_operation("Program End", "All tasks saved and operations logged.");

    return 0;
}
