typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFapi_CrcIndicationPdu;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFapi_RxFramePdu;

// Function to generate random number
int genRandomNumber(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to create and populate list of structures
NFapi_CrcIndicationPdu* createCrcList(int N, int *UEtags, int maxLimit) {
    if (N > maxLimit) {
        printf("Error: Maximum PDU count exceeded.\n");
        return NULL;
    }

    NFapi_CrcIndicationPdu *list = (NFapi_CrcIndicationPdu*)malloc(N * sizeof(NFapi_CrcIndicationPdu));
    srand(time(0)); // Seed for random number generation

    int usedRNTIs[1000] = {0}; // Assuming max RNTI value is 1000 for simplicity
    int uniqueRNTIs = 0;

    for (int i = 0; i < N; i++) {
        if (uniqueRNTIs >= 1000) {
            printf("Error: Maximum number of unique RNTIs reached.\n");
            free(list);
            return NULL;
        }

        int rnti;
        do {
            rnti = genRandomNumber(1, 1000); // Assuming max RNTI value is 1000
        } while (usedRNTIs[rnti]);

        usedRNTIs[rnti] = 1;
        uniqueRNTIs++;

        list[i].RX_UE_INFORMATION_TAG = UEtags[i];
        list[i].RNTI = rnti;

        // Simulate rolling checksum for CRCFLAG
        int crcFlag = ((list[i].RX_UE_INFORMATION_TAG ^ rnti) % 256);
        list[i].CRCFLAG = crcFlag;
    }

    return list;
}

// Function to clear the list of structures
void clearCrcList(NFapi_CrcIndicationPdu *list, int N) {
    free(list);
}
