    private static List<LogEntry> logEntries = new List<LogEntry>();

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue < 0 || maxValue < 0 || minValue > maxValue)
            throw new ArgumentException("Invalid range");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        float value = (float)(random.NextDouble() * (maxValue - minValue) + minValue);
        logEntries.Add(new LogEntry(DateTime.Now, "Generated float", value));
        return value;
    }

    public int GenerateRandomInt()
    {
        int value = random.Next((int)minValue, (int)maxValue + 1);
        logEntries.Add(new LogEntry(DateTime.Now, "Generated int", value));
        return value;
    }

    public double GenerateRandomDouble()
    {
        double value = random.NextDouble() * (maxValue - minValue) + minValue;
        logEntries.Add(new LogEntry(DateTime.Now, "Generated double", value));
        return value;
    }

    public Vector3 GenerateRandomVector3()
    {
        Vector3 value = new Vector3(
            (float)(random.NextDouble() * (maxValue - minValue) + minValue),
            (float)(random.NextDouble() * (maxValue - minValue) + minValue),
            (float)(random.NextDouble() * (maxValue - minValue) + minValue)
        );
        logEntries.Add(new LogEntry(DateTime.Now, "Generated Vector3", value));
        return value;
    }

    public Quaternion GenerateRandomQuaternion()
    {
        Quaternion value = Quaternion.Euler(
            (float)(random.NextDouble() * (maxValue - minValue)),
            (float)(random.NextDouble() * (maxValue - minValue)),
            (float)(random.NextDouble() * (maxValue - minValue))
        );
        logEntries.Add(new LogEntry(DateTime.Now, "Generated Quaternion", value));
        return value;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        long ticks = random.Next(startDate.Ticks, endDate.Ticks);
        DateTime value = new DateTime(ticks);
        logEntries.Add(new LogEntry(DateTime.Now, "Generated DateTime", value));
        return value;
    }

    public void AdjustRange(double minValue, double maxValue)
    {
        if (minValue < 0 || maxValue < 0 || minValue > maxValue)
            throw new ArgumentException("Invalid range");

        this.minValue = minValue;
        this.maxValue = maxValue;
        logEntries.Add(new LogEntry(DateTime.Now, "Adjusted range", $"Min: {minValue}, Max: {maxValue}"));
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}\n" +
               $"Floats generated: {floatCount}\n" +
               $"Integers generated: {intCount}\n" +
               $"Doubles generated: {doubleCount}\n" +
               $"Vector3s generated: {vector3Count}\n" +
               $"Quaternions generated: {quaternionCount}\n" +
               $"DateTimes generated: {dateTimeCount}";
