}

public class LogEntry
{
    public DateTime Timestamp { get; }
    public string Operation { get; }
    public object Value { get; }

    public LogEntry(DateTime timestamp, string operation, object value)
    {
        Timestamp = timestamp;
        Operation = operation;
        Value = value;
    }
