    private readonly double minValue;
    private readonly double maxValue;
    private Dictionary<string, int> valueGenerationCount = new Dictionary<string, int>();

    public DynamicValueGenerator(double initialMin, double initialMax)
    {
        if (initialMin >= initialMax)
            throw new ArgumentException("Initial min must be less than initial max.");

        minValue = initialMin;
        maxValue = initialMax;

        // Initialize logging
        LogRangeChange(initialMin, initialMax);
    }

    private void LogRangeChange(double oldMin, double oldMax, double newMin, double newMax)
    {
        // Simulated logging method
        Debug.Log($"Range changed from [{oldMin}, {oldMax}] to [{newMin}, {newMax}] at {DateTime.Now}");
    }

    public float GenerateRandomFloat()
    {
        valueGenerationCount.TryGetValue("float", out int count);
        valueGenerationCount["float"] = count + 1;
        return (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public int GenerateRandomInt()
    {
        valueGenerationCount.TryGetValue("int", out int count);
        valueGenerationCount["int"] = count + 1;
        return (int)Math.Round(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public double GenerateRandomDouble()
    {
        valueGenerationCount.TryGetValue("double", out int count);
        valueGenerationCount["double"] = count + 1;
        return minValue + (maxValue - minValue) * UnityEngine.Random.value;
    }

    public Vector3 GenerateRandomVector3()
    {
        valueGenerationCount.TryGetValue("Vector3", out int count);
        valueGenerationCount["Vector3"] = count + 1;
        return new Vector3(
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value)
        );
    }

    public Quaternion GenerateRandomQuaternion()
    {
        valueGenerationCount.TryGetValue("Quaternion", out int count);
        valueGenerationCount["Quaternion"] = count + 1;
        return Random.rotation;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate >= endDate)
            throw new ArgumentException("Start date must be before end date.");

        Random random = new Random();
        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        long randomTicks = (long)(random.NextDouble() * (endTicks - startTicks));
        return new DateTime(startTicks + randomTicks);
    }

    public override string ToString()
    {
        string valueTypes = string.Join(", ", valueGenerationCount.Keys);
        int totalCount = 0;
        foreach (int count in valueGenerationCount.Values)
            totalCount += count;

        return $"Range [{minValue}, {maxValue}], Value types: {valueTypes}, Total values generated: {totalCount}";
    }
}
