            throw new ArgumentException("Initial minimum value must be less than or equal to initial maximum value.");
        minValue = initialMin;
        maxValue = initialMax;
    }

    // Private constructor for deserialization
    protected DynamicValueGenerator(SerializationInfo info, StreamingContext context)
    {
        minValue = info.GetDouble(nameof(minValue));
        maxValue = info.GetDouble(nameof(maxValue));
    }

    public void GetObjectData(SerializationInfo info, StreamingContext context)
    {
        info.AddValue(nameof(minValue), minValue);
        info.AddValue(nameof(maxValue), maxValue);
    }

    public float GenerateRandomFloat()
    {
        return (float)GenerateRandomNumber();
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(GenerateRandomNumber());
    }

    public double GenerateRandomDouble()
    {
        return GenerateRandomNumber();
    }

    private double GenerateRandomNumber()
    {
        if (minValue == maxValue)
            return minValue;
        return minValue + (maxValue - minValue) * UnityEngine.Random.value;
    }

    public void AdjustRange(double newMin, double newMax)
    {
