using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private static readonly double maxRangeSize = 1000.0; // Example system limit

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Initial range is invalid.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        EnsureRangeIsValid();
        return (float)(UnityEngine.Random.Range(minValue, maxValue));
    }

    public int GenerateRandomInt()
    {
        EnsureRangeIsValid();
        return UnityEngine.Random.Range((int)minValue, (int)maxValue + 1);
    }

    public double GenerateRandomDouble()
    {
        EnsureRangeIsValid();
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public Vector3 GenerateRandomVector3()
    {
        EnsureRangeIsValid();
        return new Vector3(
            UnityEngine.Random.Range((float)minValue, (float)maxValue),
            UnityEngine.Random.Range((float)minValue, (float)maxValue),
            UnityEngine.Random.Range((float)minValue, (float)maxValue)
        );
    }

    public Quaternion GenerateRandomQuaternion()
    {
        EnsureRangeIsValid();
        return new Quaternion(
            UnityEngine.Random.Range((float)minValue, (float)maxValue),
            UnityEngine.Random.Range((float)minValue, (float)maxValue),
            UnityEngine.Random.Range((float)minValue, (float)maxValue),
            UnityEngine.Random.Range((float)minValue, (float)maxValue)
        );
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue > newMaxValue || newMaxValue - newMinValue > maxRangeSize)
        {
            Debug.LogError("Invalid range adjustment.");
            return;
        }
        minValue = newMinValue;
        maxValue = newMaxValue;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("Date range is invalid.");
        }
        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        long randomTicks = UnityEngine.Random.Range(startTicks, endTicks);
        return new DateTime(randomTicks);
    }

    private void EnsureRangeIsValid()
    {
        if (minValue > maxValue)
        {
            throw new InvalidOperationException("Current range is invalid.");
        }
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Range [{minValue}, {maxValue}]";
    }
}
