        threads = []
        for system in [self.aws_s3, self.gcp_storage, self.azure_blob_storage]:
            thread = threading.Thread(target=self._process_cloud_storage_system, args=(system,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

    def _process_cloud_storage_system(self, storage):
        try:
            buckets = storage.buckets.all() if hasattr(storage, 'buckets') else []
            for bucket in buckets:
                if self._bucket_has_sync_tag(bucket):
                    self._sync_bucket_profiles(bucket)
        except Exception as e:
            self.failures.append((storage.__class__.__name__, str(e)))

    def _bucket_has_sync_tag(self, bucket):
        return any(tag.key == 'profile_sync' for tag in bucket.tags)

    def _sync_bucket_profiles(self, bucket):
        try:
            profiles = bucket.objects.all()
            for profile in profiles:
                self._update_profile(profile)
                self.successfully_synced += 1
        except Exception as e:
            self.failures.append((bucket.name, str(e)))

