public class DynamicValueGenerator : IDisposable
{
    private readonly double minValue;
    private readonly double maxValue;
    private static readonly Random random = new Random();
    private static readonly int MaxRetryCount = 5;
    private static readonly TimeSpan RetryDelay = TimeSpan.FromSeconds(1);

    public string Type => GetRandomType();

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value must be less than or equal to max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateFloat()
    {
        return (float)(random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GenerateInt()
    {
        return (int)Math.Round(GenerateFloat());
    }

    public double GenerateDouble()
    {
        return GenerateFloat();
    }

    public Vector3 GenerateVector3()
    {
        return new Vector3(
            (float)(random.NextDouble() * (maxValue - minValue) + minValue),
            (float)(random.NextDouble() * (maxValue - minValue) + minValue),
            (float)(random.NextDouble() * (maxValue - minValue) + minValue)
        );
    }

    public Quaternion GenerateQuaternion()
    {
        return new Quaternion(
            (float)(random.NextDouble() * 2.0f - 1.0f),
            (float)(random.NextDouble() * 2.0f - 1.0f),
            (float)(random.NextDouble() * 2.0f - 1.0f),
            (float)Math.Sqrt(1 - Math.Pow(random.NextDouble(), 2))
        );
    }

    public DateTime GenerateDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate) throw new ArgumentException("Start date must be less than or equal to end date.");

        long startTicks = startDate.Ticks;
        long endTicks = endDate.Ticks;
        return new DateTime(startTicks + (long)(random.NextDouble() * (endTicks - startTicks)));
    }

    public string GetRandomType()
    {
        int typeIndex = random.Next(5);
        switch (typeIndex)
        {
            case 0: return "float";
            case 1: return "int";
            case 2: return "double";
            case 3: return "Vector3";
            default: return "Quaternion";
        }
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        int retryCount = 0;
        while (retryCount < MaxRetryCount)
        {
            try
            {
                if (newMinValue > newMaxValue) throw new ArgumentException("New min value must be less than or equal to new max value.");

                minValue = newMinValue;
                maxValue = newMaxValue;
                return;
            }
            catch (Exception ex)
            {
                retryCount++;
                Console.WriteLine($"Adjustment failed: {ex.Message}. Retrying...");
                Thread.Sleep(RetryDelay);
            }
        }

        throw new InvalidOperationException("Failed to adjust range after maximum retries.");
    }

    public void Dispose()
    {
        // Implement IDisposable pattern if needed
    }
}
