// Java component for managing file encryption and decryption

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.KeyFactory;
import java.security.spec.PKCS8EncodedKeySpec;
import java.util.Base64;

public class FileEncryption {
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private SecretKey secretKey;
    private IvParameterSpec iv;

    public FileEncryption(String password, int iterations) throws Exception {
        byte[] salt = generateSalt();
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt, iterations);
        KeyFactory factory = KeyFactory.getInstance("PBKDF2WithHmacSHA256");
        secretKey = new SecretKeySpec(factory.generateSecret(spec).getEncoded(), ALGORITHM);
    }

    public byte[] encrypt(byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        iv = new IvParameterSpec(generateIv());
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);
        return cipher.doFinal(data);
    }

    public byte[] decrypt(byte[] encryptedData) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);
        return cipher.doFinal(encryptedData);
    }

    private byte[] generateSalt() {
        // Generate a random salt
        return new byte[16];
    }

    private byte[] generateIv() {
        // Generate a unique IV for each operation
        return new byte[16];
    }
}
