        resourcePool = new List<T>();
    }

    public T AcquireResource()
    {
        if (resourcePool.Count == 0)
            throw new InvalidOperationException("No resources available.");

        var resource = resourcePool.First();
        resourcePool.RemoveAt(0);
        logger.Log($"Acquired resource: {resource}");
        return resource;
    }

    public void ReleaseResource(T resource)
    {
        try
        {
            if (resource != null && !resource.IsDisposed)
            {
                resource.Dispose();
                resourcePool.Add(resource);
                logger.Log($"Released and disposed resource: {resource}");
            }
        }
        catch (Exception ex)
        {
            logger.LogError($"Error releasing resource: {ex.Message}");
        }
