            return;
        }
        cru_pdus[i].RX_UE_INFORMATION_TAG = rand();
        rnti_counter++;
        cru_pdus[i].RNTI = rnti_counter;
        memcpy(cru_pdus[i].CRC_INDICATION_REL8_TAG, &cru_pdus[i].RX_UE_INFORMATION_TAG, sizeof(uint32_t));
        rx_pdus[i].RX_UE_INFORMATION_TAG = cru_pdus[i].RX_UE_INFORMATION_TAG;
        rx_pdus[i].RNTI = cru_pdus[i].RNTI;
    }
}

