public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private int floatGenerationCount = 0;
    private int intGenerationCount = 0;
    private int doubleGenerationCount = 0;
    private int vector3GenerationCount = 0;
    private int quaternionGenerationCount = 0;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue || minValue < double.MinValue || maxValue > double.MaxValue)
            throw new ArgumentException("Invalid range");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        floatGenerationCount++;
        return (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public int GenerateRandomInt()
    {
        intGenerationCount++;
        if (minValue == maxValue)
            return (int)minValue;
        return (int)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public double GenerateRandomDouble()
    {
        doubleGenerationCount++;
        if (minValue == maxValue)
            return minValue;
        return minValue + (maxValue - minValue) * UnityEngine.Random.value;
    }

    public Vector3 GenerateRandomVector3()
    {
        vector3GenerationCount++;
        float x = (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
        float y = (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
        float z = (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
        return new Vector3(x, y, z);
    }

    public Quaternion GenerateRandomQuaternion()
    {
        quaternionGenerationCount++;
        float x = (float)(-1.0 + 2.0 * UnityEngine.Random.value);
        float y = (float)(-1.0 + 2.0 * UnityEngine.Random.value);
        float z = (float)(-1.0 + 2.0 * UnityEngine.Random.value);
        float w = (float)(-1.0 + 2.0 * UnityEngine.Random.value);
        return new Quaternion(x, y, z, w).normalized;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
            throw new ArgumentException("Invalid date range");
        TimeSpan length = endDate - startDate;
        long ticks = startDate.Ticks + (long)(length.TotalTicks * UnityEngine.Random.value);
        return new DateTime(ticks);
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
