import java.net.*;
import java.io.*;
import java.security.MessageDigest;
import java.util.concurrent.*;

public class NetworkClient {

    private static final String SERVER_ADDRESS = "remote.server.address";
    private static final int SERVER_PORT = 12345;

    public static void main(String[] args) {
        try {
            NFAPI_CRC_INDICATION_PDU_T[] pduList = createPduList(10);
            sendData(pduList);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static NFAPI_CRC_INDICATION_PDU_T[] createPduList(int N) {
        NFAPI_CRC_INDICATION_PDU_T[] list = new NFAPI_CRC_INDICATION_PDU_T[N];
        Random rand = new Random();
        for (int i = 0; i < N; i++) {
            list[i] = new NFAPI_CRC_INDICATION_PDU_T();
            list[i].RX_UE_INFORMATION_TAG = rand.nextInt(100);
            list[i].RNTI = rand.nextInt(256);
            list[i].CRC_INDICATION_REL8_TAG = rand.nextInt(100);
            list[i].CRCFLAG = rand.nextInt(2); // Randomly set CRCFLAG
        }
        return list;
    }

    private static void sendData(NFAPI_CRC_INDICATION_PDU_T[] pduList) throws IOException {
        Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT);
        ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
        oos.writeObject(pduList);
        ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
        boolean success = (boolean) ois.readObject();
        if (!success) {
            retrySendData(pduList);
        }
    }

    private static void retrySendData(NFAPI_CRC_INDICATION_PDU_T[] pduList) {
        int retries = 0;
        while (retries < 5) {
            try {
                sendData(pduList);
                break;
            } catch (IOException e) {
                e.printStackTrace();
                retries++;
                if (retries < 5) {
                    Thread.sleep((long) Math.pow(2, retries) * 100); // Exponential backoff
                }
            }
        }
    }

    public static String computeMd5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public static CompletableFuture<String> computeMd5Async(String input, ExecutorService executor, int concurrencyLimit) {
        return CompletableFuture.supplyAsync(() -> computeMd5(input), executor);
    }
}
