    private static final String[] VALIDATION_SERVICES = {"service1", "service2"};
    private HashMap<String, String> cache = new HashMap<>();

    public String getMD5(String input) {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        for (String service : VALIDATION_SERVICES) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] messageDigest = md.digest(input.getBytes());
                StringBuilder hexString = new StringBuilder();
                for (byte b : messageDigest) {
                    String hex = Integer.toHexString(0xff & b);
                    if(hex.length() == 1) hexString.append('0');
                    hexString.append(hex);
                }
                cache.put(input, hexString.toString());
                return hexString.toString();
            } catch (NoSuchAlgorithmException e) {
                // Handle exception
            }
        }

        throw new RuntimeException("No available validation services.");
    }

    public String getMD5WithRetry(String input, int maxRetries) {
        for (int i = 0; i <= maxRetries; i++) {
            try {
                return getMD5(input);
            } catch (RuntimeException e) {
                // Retry logic with exponential backoff
                if (i == maxRetries) throw e;
                Thread.sleep((long) Math.pow(2, i) * 100);
            }
        }
        return null; // Placeholder
