#include <fcntl.h>
#include <openssl/md5.h>

// Define constants for buffer sizes and file chunk size
#define BUFFER_SIZE 1024
#define FILE_CHUNK_SIZE 1024 * 1024

// Function to calculate MD5 hash of a file
void calculateMD5Hash(const char* filename, unsigned char digest[MD5_DIGEST_LENGTH]) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    MD5_CTX md5;
    MD5_Init(&md5);

    int bytesRead;
    while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, file)) != 0) {
        MD5_Update(&md5, buffer, bytesRead);
    }

    MD5_Final(digest, &md5);

    fclose(file);
}

// Function to process files in chunks and calculate hash
void processFileChunks(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    calculateMD5Hash(filename, digest);

    // Print MD5 hash in hex format
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", digest[i]);
    }
    printf("\n");

    close(fd);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processFileChunks(argv[1]);

    return EXIT_SUCCESS;
}
