NFAPI_CRC_INDICATION_PDU_T* manage_and_populate_list(int max_pdus) {
    if (max_pdus > MAX_PDU_COUNT) {
        printf("Error: Exceeds maximum PDU count.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < max_pdus; i++) {
        // Generate unique RNTI
        list[i].ue_info.RNTI = rand() % 1000 + 1;

        // Fetch valid RX_UE_INFORMATION_TAG from external data source
        int tag;
        if (!fetch_valid_tag(&tag)) {
            printf("Error: Invalid or missing RX_UE_INFORMATION_TAG.\n");
            free(list);
            return NULL;
        }
        list[i].ue_info.RX_UE_INFORMATION_TAG = tag;

        // Calculate CRCFLAG using rolling checksum
        list[i].CRCFLAG = calculate_crcflag(tag, list[i].ue_info.RNTI);

        // Validate RNTI uniqueness
        for (int j = 0; j < i; j++) {
