public class ValueGenerator
{
    private int _minValue;
    private int _maxValue;
    private Random _random;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public int GetRandomInt(bool inclusiveMax = true)
    {
        return inclusiveMax ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
    }

    public float GetRandomFloat(bool exclusiveMax = false)
    {
        double randomValue = _random.NextDouble();
        return (float)(exclusiveMax ? randomValue * (_maxValue - _minValue) + _minValue : randomValue * (_maxValue - _minValue) + _minValue);
    }

    public bool GetRandomBoolean(double probabilityOfTrue = 0.5)
    {
        double randomValue = _random.NextDouble();
        return randomValue < probabilityOfTrue;
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
