    {
        byte[] data = new byte[4];
        _rng.GetBytes(data);
        return BitConverter.ToInt32(data, 0) % (_intMax - _intMin + 1) + _intMin;
    }

    public float GetRandomFloat()
    {
        byte[] data = new byte[4];
        _rng.GetBytes(data);
        return BitConverter.ToSingle(data, 0) * (_floatMax - _floatMin) + _floatMin;
    }

    public bool GetRandomBoolean(float probability)
    {
        byte[] data = new byte[1];
        _rng.GetBytes(data);
        float randomValue = Convert.ToByte(data[0]) / 256f;
        return randomValue < probability;
    }

    public override string ToString()
    {
        return $"Int Range: {_intMin}-{_intMax}, Float Range: {_floatMin}-{_floatMax}";
    }
}
