```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5HashGenerator {
    // Method to compute MD5 hash of a string or list of strings
    public static String[] computeHash(String... inputs) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            String[] hashes = new String[inputs.length];
            for (int i = 0; i < inputs.length; i++) {
                byte[] hashBytes = md.digest(inputs[i].getBytes());
                hashes[i] = bytesToHex(hashBytes);
            }
            return hashes;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
