char* appendSlashIfWithinLimit(const char* input, size_t limit, char* buffer) {
    if (strlen(input) < limit) {
        if (buffer != NULL) {
            snprintf(buffer, limit + 2, "%s/", input);
            return buffer;
        } else {
            char* result = malloc(limit + 2);
            if (result == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }
            snprintf(result, limit + 2, "%s/", input);
            return result;
        }
    }
    return NULL;
}
