        return 1;
    }

    const char* input_path = argv[1];
    int mode = strcmp(argv[2], "-c") == 0 || strcmp(argv[2], "--count-only") == 0 ? 1 :
               strcmp(argv[2], "-d") == 0 || strcmp(argv[2], "--digest") == 0 ? 2 : 3;
    const char* output_path = argv[4];

    process_file(input_path, output_path, mode);

    return 0;
}

void process_file(const char* input_path, const char* output_path, int mode) {
    FILE* input_file = fopen(input_path, "rb");
    if (!input_file) {
        perror("Error opening input file");
        exit(1);
    }

    if (mode == 1) {
        fprintf(stdout, "%d\n", count_lines(input_path));
    } else if (mode == 2) {
        unsigned long buffer_size = 4096; // Example buffer size
        FILE* output_file = fopen(output_path, "wb");
        if (!output_file) {
            perror("Error opening output file");
            fclose(input_file);
            exit(1);
        }
        calculate_md5_sum(input_path, buffer_size, output_file);
        fclose(output_file);
    } else {
        // Additional modes can be implemented here
    }

    fclose(input_file);
}

int count_lines(const char* file_path) {
    int line_count = 0;
    FILE* file = fopen(file_path, "r");
    if (file) {
        char buffer[128];
        while (fgets(buffer, sizeof(buffer), file)) {
            line_count++;
        }
        fclose(file);
    }
    return line_count;
}

unsigned long calculate_md5_sum(const char* file_path, unsigned long buffer_size, FILE* output_file) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5_context;
    MD5_Init(&md5_context);

    FILE* file = fopen(file_path, "rb");
    if (file) {
        char* buffer = malloc(buffer_size);
        size_t bytes_read;
        while ((bytes_read = fread(buffer, 1, buffer_size, file)) > 0) {
            MD5_Update(&md5_context, buffer, bytes_read);
        }
        free(buffer);
        fclose(file);
    }

    MD5_Final(hash, &md5_context);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        fprintf(output_file, "%02x", hash[i]);
    }

    return 0;
}

void generate_random_range(int min_value, int max_value, float* random_float, int* random_int) {
    if (min_value >= max_value) {
        fprintf(stderr, "Invalid range: minValue must be less than maxValue\n");
        exit(1);
    }

    *random_float = ((float)rand() / RAND_MAX) * (max_value - min_value) + min_value;
    *random_int = (int)((*random_float) / 5.0) * 5; // Ensure integer is divisible by 5
}

