namespace fs = std::filesystem;

class FileProcessor {
public:
    struct Options {
        bool help = false;
        bool verbose = false;
        bool summary = false;
        std::string filter = "";
        std::string output_directory = "";
        size_t max_file_size = 0;
        size_t line_count = 0;
    };

    void processDirectory(const fs::path& dir, const Options& options) {
        if (!fs::exists(dir) || !fs::is_directory(dir)) {
            std::cerr << "Invalid directory: " << dir << std::endl;
            return;
        }

        for (const auto& entry : fs::recursive_directory_iterator(dir)) {
            if (entry.is_regular_file() && matchesFilter(entry.path(), options.filter)) {
                processFile(entry.path(), options);
            }
        }

        if (options.summary) {
            std::cout << "Total lines processed: " << options.line_count << std::endl;
        }
    }

private:
    bool matchesFilter(const fs::path& path, const std::string& filter) {
        return std::regex_match(path.filename().string(), std::regex(filter));
    }

    void processFile(const fs::path& file, const Options& options) {
        if (fs::file_size(file) > options.max_file_size) {
            std::cout << "Skipping large file: " << file << std::endl;
            return;
        }

        std::ifstream in(file);
        std::string line;

        while (std::getline(in, line)) {
            ++options.line_count;
            if (options.verbose) {
                std::cout << "Processing line " << options.line_count << ": " << line << std::endl;
            }
        }

        in.close();
    }
};

int main(int argc, char* argv[]) {
    FileProcessor::Options options;

    for (int i = 1; i < argc; ++i) {
        if (argv[i] == "-h" || argv[i] == "--help") {
            options.help = true;
        } else if (argv[i] == "-v" || argv[i] == "--verbose") {
            options.verbose = true;
        } else if (argv[i] == "-s" || argv[i] == "--summary") {
            options.summary = true;
        } else if (argv[i] == "-f" || argv[i] == "--filter") {
            if (i + 1 < argc) {
                options.filter = argv[++i];
            }
        } else if (argv[i] == "-o" || argv[i] == "--output-directory") {
            if (i + 1 < argc) {
                options.output_directory = argv[++i];
            }
        } else if (argv[i] == "-m" || argv[i] == "--max-file-size") {
            if (i + 1 < argc) {
                options.max_file_size = std::stoul(argv[++i]);
            }
        }
    }

    if (options.help) {
        std::cout << "Usage: program_name [options] directory" << std::endl;
        std::cout << "Options:" << std::endl;
        std::cout << "  -h, --help          Display help message with usage information." << std::endl;
        std::cout << "  -v, --verbose       Output detailed information about each file processed." << std::endl;
        std::cout << "  -s, --summary       Print a summary report of the total number of lines found across all files." << std::endl;
        std::cout << "  -f, --filter        Specify a pattern to filter files based on their names, such as '*.log' or '*.txt'." << std::endl;
        std::cout << "  -o, --output-directory Specify an output directory to save processed files with a modified timestamp appended to their filenames." << std::endl;
        std::cout << "  -m, --max-file-size Specify a custom maximum file size limit for processing, above which files are skipped." << std::endl;
    } else {
        if (argc <= 1) {
            FileProcessor processor;
            processor.processDirectory(".", options);
        } else {
            FileProcessor processor;
            processor.processDirectory(argv[1], options);
        }
    }

    return 0;
}
