#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <zlib.h>

void process_file(const char *file_path, const char *output_dir) {
    // Implement file processing logic here
}

void traverse_directory(const char *dir_path, const char *output_dir) {
    DIR *dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            perror("Failed to get file stats");
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            traverse_directory(full_path, output_dir);
        } else if (S_ISREG(file_stat.st_mode)) {
            process_file(full_path, output_dir);
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_directory> <output_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_dir = argv[1];
    const char *output_dir = argv[2];

    traverse_directory(input_dir, output_dir);

    return EXIT_SUCCESS;
}
