public class RandomValueGenerator
{
    private Random _random;
    private int? _minInt;
    private int? _maxInt;
    private float? _minFloat;
    private float? _maxFloat;
    private HashSet<int> _generatedIntValues = new HashSet<int>();
    private HashSet<float> _generatedFloatValues = new HashSet<float>();

    public RandomValueGenerator(int minInt, int maxInt)
    {
        if (minInt > maxInt) throw new ArgumentException("Min cannot be greater than max for integer range.");
        _random = new Random();
        _minInt = minInt;
        _maxInt = maxInt;
    }

    public RandomValueGenerator(float minFloat, float maxFloat)
    {
        if (minFloat > maxFloat) throw new ArgumentException("Min cannot be greater than max for float range.");
        _random = new Random();
        _minFloat = minFloat;
        _maxFloat = maxFloat;
    }

    public int GetRandomInt(bool inclusive)
    {
        if (!_minInt.HasValue || !_maxInt.HasValue) return 0; // This case should not occur due to constructor checks.
        int value;
        do
        {
            value = inclusive ? _random.Next(_minInt.Value, _maxInt.Value + 1) : _random.Next(_minInt.Value, _maxInt.Value);
        } while (_generatedIntValues.Contains(value));
        _generatedIntValues.Add(value);
        return value;
    }

    public float GetRandomFloat(bool inclusive)
    {
        if (!_minFloat.HasValue || !_maxFloat.HasValue) return 0; // This case should not occur due to constructor checks.
        float value;
        do
        {
            value = inclusive ? (float)(_random.NextDouble() * (_maxFloat.Value - _minFloat.Value + 1)) + _minFloat.Value : (float)(_random.NextDouble() * (_maxFloat.Value - _minFloat.Value));
        } while (_generatedFloatValues.Contains(value));
        _generatedFloatValues.Add(value);
        return value;
    }

    public int GetRandomIndex(int[] array)
    {
        if (array == null || array.Length == 0) throw new ArgumentException("Array cannot be null or empty.");
        return _random.Next(array.Length);
    }

    public bool ValidateValue(object value, Func<object, bool> thresholdCheck)
    {
        if (value is int intValue && _minInt.HasValue && _maxInt.HasValue)
            return thresholdCheck(intValue);
        else if (value is float floatValue && _minFloat.HasValue && _maxFloat.HasValue)
            return thresholdCheck(floatValue);
        else
            throw new ArgumentException("Invalid value type for validation.");
    }

    public override string ToString()
    {
        int validValues = _generatedIntValues.Count + _generatedFloatValues.Count;
        if (_minInt.HasValue && _maxInt.HasValue)
        {
            return $"Integer Range: {_minInt} to {_maxInt}, Valid Values: {validValues}";
        }
        else if (_minFloat.HasValue && _maxFloat.HasValue)
        {
            return $"Float Range: {_minFloat} to {_maxFloat}, Valid Values: {validValues}";
        }
        else
        {
            return "No range set.";
        }
    }
}
