public class DynamicRangeGenerator
{
    private Random _random;
    private Queue<(double Value, bool IsValid)> _valueHistory;
    private int _maxSimultaneousGenerators;
    private IExternalDataSource _externalDataSource;

    public DynamicRangeGenerator(int maxSimultaneousGenerators, IExternalDataSource externalDataSource)
    {
        _random = new Random();
        _valueHistory = new Queue<(double Value, bool IsValid)>();
        _maxSimultaneousGenerators = maxSimultaneousGenerators;
        _externalDataSource = externalDataSource ?? throw new ArgumentNullException(nameof(externalDataSource));
    }

    public int GenerateRandomIndex(int arrayLength)
    {
        return _random.Next(arrayLength);
    }

    public double GenerateRandomValue(double min, double max)
    {
        return _random.NextDouble() * (max - min) + min;
    }

    public bool ValidateValue(double value, Func<double, bool> validationCriteria)
    {
        bool isValid = validationCriteria(value);
        _valueHistory.Enqueue((value, isValid));
        if (_valueHistory.Count > 1000) // Example limit
        {
            _valueHistory.Dequeue();
        }
        return isValid;
    }

    public override string ToString()
    {
        int validValues = _valueHistory.Count(v => v.IsValid);
        return $"DynamicRangeGenerator - Valid Values: {validValues}";
    }

    public async Task<List<double>> GenerateRandomValuesAsync(int count, double min, double max)
    {
        var tasks = new List<Task<double>>();
        for (int i = 0; i < count; i++)
        {
            tasks.Add(GenerateRandomValueAsync(min, max));
        }
        return await Task.WhenAll(tasks);
    }

    private async Task<double> GenerateRandomValueAsync(double min, double max)
    {
        while (_valueHistory.Count >= _maxSimultaneousGenerators)
        {
            await Task.Delay(10); // Wait and retry
        }

        double value = GenerateRandomValue(min, max);
        bool isValid = ValidateValue(value, v => v > min && v < max);

        return value;
    }
}

public interface IExternalDataSource
{
    int GetSeed();
}
