#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <vector>
#include <atomic>

template<typename T>
class StreamingDataProcessor {
public:
    using DataHandler = std::function<void(T)>;

    StreamingDataProcessor(size_t threadCount) : stop(false), numThreads(threadCount) {
        for (size_t i = 0; i < threadCount; ++i) {
            workers.emplace_back([this] {
                for (;;) {
                    T data;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        data = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    try {
                        process(data);
                    } catch (...) {
                        std::cerr << "Exception in processing thread." << std::endl;
                    }
                }
            });
        }
    }

    ~StreamingDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

    void add(const T& data) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.push(data);
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<T> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
    size_t numThreads;

    void process(const T& data) {
        // Implement data processing logic here
        static std::atomic<int> counter(0);
        ++counter;
        std::cout << "Processed item " << counter.load() << ": " << data << std::endl;
    }
};
