#include <stdlib.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    MAC_RX_FRAME_PDU rx_frame_pdu;
    // Additional metadata
} NFAPI_RX_FRAME_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_pdus(uint32_t max_pdu_count, uint32_t* num_pdus_created) {
    if (max_pdu_count == 0) {
        *num_pdus_created = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *num_pdus_created = 0;
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    uint32_t unique_rnti = 1000; // Starting value for RNTI

    for (uint32_t i = 0; i < max_pdu_count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pdus[i].RNTI = unique_rnti++;
        pdus[i].CRC_INDICATION_REL8_TAG = calculate_crc_flag(pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI);
    }

    *num_pdus_created = max_pdu_count;
    return pdus;
}

uint8_t calculate_crc_flag(uint32_t tag1, uint16_t tag2) {
    // Simple rolling checksum algorithm
    uint32_t combined_tag = (tag1 << 16) | tag2;
    uint8_t crc_flag = 0;
    while (combined_tag != 0) {
        crc_flag += combined_tag & 0xFF;
        combined_tag >>= 8;
    }
    return crc_flag;
}
```

