    public double MinValue
    {
        get { return minValue; }
        set
        {
            if (value > maxValue)
                throw new ArgumentException("minValue must be less than or equal to maxValue");
            minValue = value;
        }
    }

    public double MaxValue
    {
        get { return maxValue; }
        set
        {
            if (value < minValue)
                throw new ArgumentException("maxValue must be greater than or equal to minValue");
            maxValue = value;
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + random.NextDouble() * (maxValue - minValue));
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(GenerateRandomFloat());
    }

    public void AdjustRange(double newMin, double newMax)
    {
        MinValue = newMin;
        MaxValue = newMax;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            GenerateRandomFloat(),
            GenerateRandomFloat(),
            GenerateRandomFloat()
        );
    }

    public override string ToString()
    {
        return $"DynamicRangeValueGenerator with range [{minValue}, {maxValue}]";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
            throw new ArgumentException("startDate must be before or equal to endDate");
        return startDate.AddTicks((long)(random.NextDouble() * (endDate.Ticks - startDate.Ticks)));
    }

