            throw new ArgumentException("intList cannot be null or empty");
        return intList.Average();
    }

    public float[] GenerateMultipleRandomFloats(int count)
    {
        if (count <= 0)
            throw new ArgumentException("count must be greater than zero");
        float[] result = new float[count];
        for (int i = 0; i < count; i++)
        {
            result[i] = GenerateRandomFloat();
        }
        return result;
    }

    public string GenerateRandomString(char[] charSet, int length)
    {
        if (charSet == null || charSet.Length == 0)
            throw new ArgumentException("charSet cannot be null or empty");
        if (length <= 0)
            throw new ArgumentException("length must be greater than zero");
        return new string(GenerateRandomStringCharacters(charSet, length));
    }

    private char[] GenerateRandomStringCharacters(char[] charSet, int length)
    {
        char[] result = new char[length];
