// Java component for managing file encryption and decryption

import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.SecureRandom;

public class FileEncryptor {
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private SecretKey secretKey;
    private IvParameterSpec ivSpec;

    public FileEncryptor(String password) throws Exception {
        // Derive key from password
        byte[] salt = generateSalt();
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256, new SecureRandom(salt));
        secretKey = keyGen.generateKey();

        // Generate IV
        ivSpec = generateIv();
    }

    public void encryptFile(String inputFilePath, String outputFilePath) throws Exception {
        try (Cipher cipher = Cipher.getInstance(ALGORITHM)) {
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);
            try (FileInputStream fis = new FileInputStream(inputFilePath);
                 FileOutputStream fos = new FileOutputStream(outputFilePath)) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    fos.write(cipher.update(buffer, 0, bytesRead));
                }
            }
        }
    }

    public void decryptFile(String inputFilePath, String outputFilePath) throws Exception {
        try (Cipher cipher = Cipher.getInstance(ALGORITHM)) {
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivSpec);
            try (FileInputStream fis = new FileInputStream(inputFilePath);
                 FileOutputStream fos = new FileOutputStream(outputFilePath)) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    fos.write(cipher.update(buffer, 0, bytesRead));
                }
            }
        }
    }

    private IvParameterSpec generateIv() throws Exception {
        byte[] iv = new byte[16];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        return new IvParameterSpec(iv);
    }

    private byte[] generateSalt() {
        byte[] salt = new byte[8];
        SecureRandom.getInstanceStrong().nextBytes(salt);
        return salt;
    }
}
```

