using System;
using System.Collections.Generic;
using UnityEngine;

public class DynamicRangeValueGenerator : ILoggable
{
    private double minValue;
    private double maxValue;

    public DynamicRangeValueGenerator(double initialValue)
    {
        SetRange(initialValue);
    }

    private void SetRange(double newValue)
    {
        if (newValue < 0)
        {
            minValue = -Math.Abs(newValue);
            maxValue = Math.Abs(newValue);
        }
        else
        {
            minValue = 0;
            maxValue = newValue;
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.Range(0f, 1f));
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(minValue + (maxValue - minValue) * new Random().NextDouble());
    }

    public void AdjustRange(double newMin, double newMax)
    {
        if (newMin > newMax)
        {
            throw new ArgumentException("New minimum must be less than or equal to new maximum.");
        }
        minValue = newMin;
        maxValue = newMax;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat());
    }

    public override string ToString()
    {
        return $"DynamicRangeValueGenerator: Min={minValue}, Max={maxValue}";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("Start date must be less than or equal to end date.");
        }
        TimeSpan range = endDate - startDate;
        return startDate.AddTicks(new Random().Next(range.Ticks));
    }

    public double CalculateAverage(List<int> values)
    {
        if (values == null || values.Count == 0)
        {
            throw new ArgumentException("List of values cannot be null or empty.");
        }
        return (double)values.Sum() / values.Count;
    }

    public float[] GenerateMultipleRandomFloats(int count)
    {
        float[] floats = new float[count];
        for (int i = 0; i < count; i++)
        {
            floats[i] = GenerateRandomFloat();
        }
        return floats;
    }

    public string GenerateRandomString(char[] charSet, int length)
    {
        if (length < 1 || length > charSet.Length)
        {
            throw new ArgumentException("Length must be between 1 and the length of the character set.");
        }
        Random random = new Random();
        return new string(Enumerable.Repeat(charSet, length).Select(c => c[random.Next(c.Length)]).ToArray());
    }

    public decimal GenerateRandomDecimal()
    {
        return (decimal)(minValue + (maxValue - minValue) * new Random().NextDouble());
    }

    public double GenerateRandomDouble()
    {
        return minValue + (maxValue - minValue) * new Random().NextDouble();
    }

    string ILoggable.LogMessage(string message)
    {
        Console.WriteLine(message);
        return message;
    }
}
