using System;
using System.Collections.Generic;

public class SensorDataPipeline
{
    private double sensorReadingThreshold;
    private int validReadingsCount = 0;
    private int invalidReadingsCount = 0;
    private Stopwatch stopwatch;

    public SensorDataPipeline(double initialThreshold)
    {
        this.sensorReadingThreshold = initialThreshold;
        this.stopwatch = new Stopwatch();
    }

    public void SetSensorReadingThreshold(double threshold)
    {
        sensorReadingThreshold = threshold;
    }

    public double GetSensorReadingThreshold()
    {
        return sensorReadingThreshold;
    }

    public List<double> FilterInvalidData(List<double> readings)
    {
        stopwatch.Start();
        var filteredReadings = new List<double>();
        foreach (var reading in readings)
        {
            if (reading >= sensorReadingThreshold)
            {
                validReadingsCount++;
                filteredReadings.Add(reading);
            }
            else
            {
                invalidReadingsCount++;
            }
        }
        stopwatch.Stop();
        Console.WriteLine($"Filtered {invalidReadingsCount} invalid readings in {stopwatch.ElapsedMilliseconds} ms.");
        return filteredReadings;
    }

    public List<double> ApplyMovingAverage(List<double> readings, int windowSize)
    {
        stopwatch.Start();
        var smoothedReadings = new List<double>();
        for (int i = 0; i < readings.Count; i++)
        {
            double sum = 0;
            int count = 0;
            for (int j = Math.Max(0, i - windowSize); j <= Math.Min(readings.Count - 1, i + windowSize); j++)
            {
                sum += readings[j];
                count++;
            }
            smoothedReadings.Add(sum / count);
        }
        stopwatch.Stop();
        Console.WriteLine($"Applied moving average in {stopwatch.ElapsedMilliseconds} ms.");
        return smoothedReadings;
    }

    public List<double> ConvertToFahrenheit(List<double> celsiusReadings)
    {
        stopwatch.Start();
        var fahrenheitReadings = new List<double>();
        foreach (var reading in celsiusReadings)
        {
            fahrenheitReadings.Add((reading * 9 / 5) + 32);
        }
        stopwatch.Stop();
        Console.WriteLine($"Converted {celsiusReadings.Count} readings to Fahrenheit in {stopwatch.ElapsedMilliseconds} ms.");
        return fahrenheitReadings;
    }

    public override string ToString()
    {
        return $"SensorDataPipeline - Valid Readings: {validReadingsCount}, Invalid Readings: {invalidReadingsCount}";
    }
}
