void loadConfigurationSettings(const char *xmlFilePath, int *tileSize, int *worldWidth, int *worldHeight, float *cameraSpeed) {
    xmlDocPtr doc = xmlReadFile(xmlFilePath, NULL, 0);
    if (doc == NULL) return;

    xmlNode *root_node = xmlDocGetRootElement(doc);
    for (xmlNode *node = root_node->children; node != NULL; node = node->next) {
        if (strcmp(node->name, "tileSize") == 0) {
            *tileSize = atoi(xmlNodeGetContent(node));
        } else if (strcmp(node->name, "worldWidth") == 0) {
            *worldWidth = atoi(xmlNodeGetContent(node));
        } else if (strcmp(node->name, "worldHeight") == 0) {
            *worldHeight = atoi(xmlNodeGetContent(node));
        } else if (strcmp(node->name, "cameraSpeed") == 0) {
            *cameraSpeed = atof(xmlNodeGetContent(node));
        }
    }

    xmlFreeDoc(doc);
}
