using System;
using System.Collections.Generic;
using System.Diagnostics;

public class SensorDataPipeline
{
    private double _threshold = 0.0;
    private List<double> _validReadings = new List<double>();
    private List<double> _invalidReadings = new List<double>();
    private Stopwatch _stopwatch = new Stopwatch();

    public void SetThreshold(double threshold)
    {
        _threshold = threshold;
    }

    public double GetThreshold()
    {
        return _threshold;
    }

    public void ProcessReading(double reading)
    {
        if (_stopwatch.IsRunning) _stopwatch.Stop();
        _stopwatch.Restart();

        if (reading < _threshold)
        {
            _invalidReadings.Add(reading);
        }
        else
        {
            _validReadings.Add(reading);
        }

        ApplyMovingAverageFilter(_validReadings);

        if (_stopwatch.IsRunning) _stopwatch.Stop();
        Console.WriteLine($"Processed reading in {_stopwatch.ElapsedMilliseconds} ms");
    }

    private void ApplyMovingAverageFilter(List<double> readings)
    {
        if (readings.Count < 2) return;

        double sum = 0;
        for (int i = 1; i < readings.Count; i++)
        {
            sum += Math.Abs(readings[i] - readings[i - 1]);
        }

        readings[0] = sum / (readings.Count - 1);
    }

    public double ConvertToFahrenheit(double celsius)
    {
        return (celsius * 9 / 5) + 32;
    }

    public override string ToString()
    {
        return $"Valid Readings: {_validReadings.Count}, Invalid Readings: {_invalidReadings.Count}";
    }
}
