namespace fs = std::filesystem;

class LineCounter {
public:
    void processDirectory(const std::string& path, const std::string& filter, bool verbose, bool summary, const std::string& outputDir);
    void processFile(const std::string& filePath, bool verbose, const std::string& outputDir);
    void setFilterPattern(const std::string& pattern) { filterPattern = pattern; }
    void enableVerbose(bool enable) { verboseMode = enable; }
    void enableSummary(bool enable) { summaryMode = enable; }

private:
    static const size_t CHUNK_SIZE = 1024 * 1024 * 512; // 512MB
    std::mutex countMutex;
    std::atomic<size_t> totalLines(0);
    std::string filterPattern;
    bool verboseMode = false;
    bool summaryMode = false;

    void log(const std::string& message, const std::string& level = "INFO");
};

void LineCounter::processDirectory(const std::string& path, const std::string& filter, bool verbose, bool summary, const std::string& outputDir) {
    for (const auto& entry : fs::recursive_directory_iterator(path)) {
        if (entry.is_regular_file() && (filter.empty() || entry.path().extension() == filterPattern)) {
            processFile(entry.path(), verbose, outputDir);
        }
    }

    if (summaryMode) {
        log("Total lines processed: " + std::to_string(totalLines), "SUMMARY");
    }
}

void LineCounter::processFile(const std::string& filePath, bool verbose, const std::string& outputDir) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        log("Failed to open file: " + filePath, "ERROR");
        return;
    }

    size_t lines = 0;
    while (true) {
        std::string line;
        if (!std::getline(file, line)) break;

        // Process each line
        ++lines;
        if (verbose) {
            log("Processed line: " + line, "DEBUG");
        }
    }

    file.close();

    if (outputDir.empty()) {
        totalLines += lines;
    } else {
        std::string newFileName = fs::path(outputDir) / fs::path(filePath).filename();
        newFileName += "_" + std::to_string(std::chrono::system_clock::now().time_since_epoch().count());
        std::ofstream outFile(newFileName);
        if (outFile.is_open()) {
            outFile << line;
            outFile.close();
            log("Saved processed file: " + newFileName, "INFO");
        } else {
            log("Failed to save processed file: " + newFileName, "ERROR");
        }
    }

    if (verbose) {
        log("Processed file: " + filePath + " with " + std::to_string(lines) + " lines", "INFO");
    }
}

void LineCounter::log(const std::string& message, const std::string& level) {
    // Implement your logging logic here
    std::cout << "[" << level << "] " << message << std::endl;
}
