    int RX_UE_INFORMATION_TAG;
    int RNTI;
    // Other fields as needed
} NFAPI_RX_FRAME_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    for (int i = 0; i < n; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = rand() % 1024;
        pdu_list[i].CRC_INDICATION_REL8_TAG = i + 1;
        pdu_list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return pdu_list;
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int n) {
    free(pdu_list);
}

int send_data(int sockfd, NFAPI_CRC_INDICATION_PDU_T *pdu_list, int n) {
    for (int i = 0; i < n; i++) {
        if (send(sockfd, &pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 0) != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            perror("send");
            return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <server_ip> <port>\n", argv[0]);
        return 1;
    }

    int n = 5; // Number of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu(n);
    if (!pdu_list) {
        fprintf(stderr, "Failed to allocate memory for PDUs\n");
        return 1;
    }

    struct sockaddr_in server_addr;
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        free_crc_indication_pdu(pdu_list, n);
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(argv[2]));
    if (inet_pton(AF_INET, argv[1], &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        free_crc_indication_pdu(pdu_list, n);
        return 1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sockfd);
        free_crc_indication_pdu(pdu_list, n);
        return 1;
    }

    if (send_data(sockfd, pdu_list, n) != 0) {
        fprintf(stderr, "Failed to send data\n");
        close(sockfd);
        free_crc_indication_pdu(pdu_list, n);
        return 1;
    }

    printf("Data sent successfully\n");

    close(sockfd);
    free_crc_indication_pdu(pdu_list, n);

    return 0;
}
