void print_usage(const char *program_name) {
    fprintf(stderr, "Usage: %s [options]\n", program_name);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -i <file>   Specify the input file (required)\n");
    fprintf(stderr, "  -o <file>   Specify the output file\n");
    fprintf(stderr, "  --manpage   Display man page\n");
}

void print_manpage(const char *program_name) {
    printf("NAME\n");
    printf("       %s - Count lines in a file\n", program_name);
    printf("\nSYNOPSIS\n");
    printf("       %s [options]\n", program_name);
    printf("\nDESCRIPTION\n");
    printf("       This program reads from an input file and counts the number of lines.\n");
    printf("       It can also write the processed data to an output file.\n");
    // Add more details here
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            input_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "--manpage") == 0) {
            print_manpage(argv[0]);
            return 0;
        }
    }

    if (!input_file) {
        print_usage(argv[0]);
        fprintf(stderr, "Error: Input file is required.\n");
        return 1;
    }

    FILE *in = fopen(input_file, "r");
    if (!in) {
        perror("Failed to open input file");
        return 1;
    }

    int line_count = 0;
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), in)) {
        ++line_count;
    }
    fclose(in);

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("Failed to open output file");
            return 1;
        }
        fprintf(out, "Line count: %d\n", line_count);
        fclose(out);
    } else {
        printf("Line count: %d\n", line_count);
    }

    return 0;
}
