['### C Function

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; int CRCFLAG; }
#define NFAPI_RX_FRAME_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; }

typedef struct {
    union {
        NFAPI_CRC_INDICATION_PDU_T *crc_indication;
        NFAPI_RX_FRAME_PDU_T *rx_frame;
    };
    int type;
} PDU;

PDU* create_pdu(int type, int RX_UE_INFORMATION_TAG, int RNTI) {
    PDU *pdu = malloc(sizeof(PDU));
    if (type == 0) {
        pdu->crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->crc_indication->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->crc_indication->RNTI = RNTI;
        pdu->crc_indication->CRC_INDICATION_REL8_TAG = rand();
        pdu->crc_indication->CRCFLAG = calculate_crc(pdu->crc_indication);
        pdu->type = 0;
    } else {
        pdu->rx_frame = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
        pdu->rx_frame->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->rx_frame->RNTI = RNTI;
        pdu->type = 1;
    }
    return pdu;
}

void clear_pdu_list(PDU **list, int count) {
    for (int i = 0; i < count; i++) {
        if (list[i]->type == 0)
            free(list[i]->crc_indication);
        else
            free(list[i]->rx_frame);
        free(list[i]);
    }
    free(list);
}

int calculate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simple rolling checksum algorithm
    int crc = 0;
    crc += pdu->RX_UE_INFORMATION_TAG;
    crc += pdu->RNTI;
    crc += pdu->CRC_INDICATION_REL8_TAG;
    return crc;
}
