import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.concurrent.*;

public class NetworkClient {
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_DELAY = 1000; // milliseconds
    private static final int CONCURRENCY_LIMIT = 4;

    public void sendPDUs(List<PDU> pdus, String serverAddress, int serverPort) {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);
        for (PDU pdu : pdus) {
            executor.submit(() -> {
                try {
                    sendData(pdu, serverAddress, serverPort);
                } catch (IOException e) {
                    handleException(e);
                }
            });
        }
        executor.shutdown();
    }

    private void sendData(PDU pdu, String serverAddress, int serverPort) throws IOException {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try (Socket socket = new Socket(serverAddress, serverPort)) {
                ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
                out.writeObject(pdu);
                System.out.println("PDU sent successfully");
                break;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES - 1) {
                    throw e;
                }
                Thread.sleep(RETRY_DELAY * (1 << attempt));
            }
        }
    }

    private void handleException(Exception e) {
        System.err.println("Error sending PDU: " + e.getMessage());
        // Implement retry logic here
    }

    public String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger no = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));
        while (hashtext.length() < 32) {
            hashtext.insert(0, "0");
        }
        return hashtext.toString();
    }

    public String computeMD5(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        FileInputStream fis = new FileInputStream(file);
        byte[] buffer = new byte[8192];
        int bytesRead;
        while ((bytesRead = fis.read(buffer)) != -1) {
            md.update(buffer, 0, bytesRead);
        }
        fis.close();
        byte[] messageDigest = md.digest();
        BigInteger no = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));
        while (hashtext.length() < 32) {
            hashtext.insert(0, "0");
        }
        return hashtext.toString();
    }

    public void clearList(List<PDU> pdus) {
        for (PDU pdu : pdus) {
            if (pdu.type == 0)
                free(pdu.crc_indication);
            else
                free(pdu.rx_frame);
            free(pdu);
        }
        pdus.clear();
    }

    private void free(Object obj) {
        // Implement memory freeing logic here
    }
}
```

