    private static final Logger logger = Logger.getLogger(FileMetadataManager.class.getName());

    public FileMetadataManager(int minFileSize, int maxFileSize, int defaultCompressionLevel) throws IllegalArgumentException {
        if (minFileSize < 0 || maxFileSize < 0 || defaultCompressionLevel < 0) {
            throw new IllegalArgumentException("File size and compression level cannot be negative");
        }
        if (minFileSize > maxFileSize) {
            throw new IllegalArgumentException("Min file size must be less than or equal to max file size");
        }
        if (defaultCompressionLevel < 0 || defaultCompressionLevel > 9) {
            throw new IllegalArgumentException("Default compression level must be between 0 and 9");
        }
        this.minFileSize = minFileSize;
        this.maxFileSize = maxFileSize;
        this.defaultCompressionLevel = defaultCompressionLevel;
    }

    public void processMetadata(int fileSize, int compressionLevel) throws IllegalArgumentException {
        if (fileSize < minFileSize || fileSize > maxFileSize || compressionLevel < 0 || compressionLevel > 9) {
            throw new IllegalArgumentException("Invalid file size or compression level");
        }
        // Process metadata logic here
    }

    public void adjustMetadata(int newMinFileSize, int newMaxFileSize, int newDefaultCompressionLevel) throws Exception {
        if (newMinFileSize < 0 || newMaxFileSize < 0 || newDefaultCompressionLevel < 0) {
            throw new IllegalArgumentException("File size and compression level cannot be negative");
        }
        if (newMinFileSize > newMaxFileSize) {
            throw new IllegalArgumentException("New min file size must be less than or equal to new max file size");
        }
        if (newDefaultCompressionLevel < 0 || newDefaultCompressionLevel > 9) {
            throw new IllegalArgumentException("New default compression level must be between 0 and 9");
        }
        // Adjust metadata logic here
    }

    public void simulateNetworkLatency(int delayMillis, int fileSize, int compressionLevel) throws InterruptedException {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> future = executor.submit(() -> {
            try {
                Thread.sleep(delayMillis);
                processMetadata(fileSize, compressionLevel);
            } catch (InterruptedException e) {
                logger.log(Level.SEVERE, "Network latency simulation interrupted", e);
            }
        });
        future.get(); // Wait for the task to complete
        executor.shutdown();
    }

    public int[] generateRandomFileSizes(int count) {
        if (count <= 0) {
            return new int[0];
        }
        int[] fileSizes = new int[count];
        Random random = new Random();
        for (int i = 0; i < count; i++) {
            fileSizes[i] = minFileSize + random.nextInt(maxFileSize - minFileSize + 1);
        }
        return fileSizes;
    }

    @Override
    public String toString() {
        return "FileMetadataManager{" +
                "minFileSize=" + minFileSize +
                ", maxFileSize=" + maxFileSize +
                ", defaultCompressionLevel=" + defaultCompressionLevel +
                '}';
    }
