        }
        _minValue = newMinValue;
        _maxValue = newMaxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)Random.NextDouble() * (_maxValue - _minValue) + (float)_minValue;
    }

    public int GenerateRandomInt()
    {
        return (int)((Random.NextDouble() * (_maxValue - _minValue)) + _minValue);
    }

    public double GenerateRandomDouble()
    {
        return Random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)(Random.NextDouble() * (_maxValue - _minValue)) + (float)_minValue,
            (float)(Random.NextDouble() * (_maxValue - _minValue)) + (float)_minValue,
            (float)(Random.NextDouble() * (_maxValue - _minValue)) + (float)_minValue
        );
    }

    public Quaternion GenerateRandomQuaternion()
    {
        return new Quaternion(
            (float)(Random.NextDouble() * 2 - 1),
            (float)(Random.NextDouble() * 2 - 1),
            (float)(Random.NextDouble() * 2 - 1),
            (float)(Random.NextDouble() * 2 - 1)
        ).normalized;
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("Invalid date range");
        }
        return startDate.AddTicks((long)((endDate - startDate).TotalTicks * Random.NextDouble()));
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Range {_minValue} to {_maxValue}, Type=float";
    }
}
