using System;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private static readonly double MinRangeSize = 0.1;
    private static readonly double MaxRangeSize = 1e9;

    public DynamicValueGenerator(double initialMinValue, double initialMaxValue)
    {
        if (initialMinValue >= initialMaxValue || initialMaxValue - initialMinValue < MinRangeSize)
        {
            throw new ArgumentException("Invalid range. Ensure minValue is less than maxValue and the difference is greater than the minimum allowed range size.");
        }

        minValue = initialMinValue;
        maxValue = initialMaxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.NextDouble());
    }

    public int GenerateRandomInt()
    {
        return (int)(minValue + (maxValue - minValue) * Random.NextDouble());
    }

    public double GenerateRandomDouble()
    {
        return minValue + (maxValue - minValue) * Random.NextDouble();
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)(minValue + (maxValue - minValue) * Random.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.NextDouble())
        );
    }

    public Quaternion GenerateRandomQuaternion()
    {
        return new Quaternion(
            (float)(minValue + (maxValue - minValue) * Random.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.NextDouble())
        );
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue >= newMaxValue || newMaxValue - newMinValue < MinRangeSize)
        {
            throw new ArgumentException("Invalid range. Ensure newMinValue is less than newMaxValue and the difference is greater than the minimum allowed range size.");
        }

        minValue = newMinValue;
        maxValue = newMaxValue;

        // Log the change
        LogRangeChange(newMinValue, newMaxValue);
    }

    private void LogRangeChange(double newMinValue, double newMaxValue)
    {
        // Implement logging logic here
        Console.WriteLine($"Range changed from ({minValue}, {maxValue}) to ({newMinValue}, {newMaxValue}) at {DateTime.Now}");
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate >= endDate)
        {
            throw new ArgumentException("Invalid date range. Ensure startDate is before endDate.");
        }

        Random random = new Random();
        return startDate.AddTicks(random.Next(startDate.Ticks - startDate.Date.Ticks, endDate.Ticks - startDate.Date.Ticks));
    }

    public void AdjustForPrecision(double valueAdjustment)
    {
        minValue += valueAdjustment;
        maxValue += valueAdjustment;

        if (minValue < 0 || maxValue > double.MaxValue)
        {
            // Fallback mechanism for precision issues
            Console.WriteLine("Adjustment resulted in out-of-range values. Resetting to original range.");
            AdjustRange(minValue, maxValue);
        }
    }

    public void SaveState(string filePath)
    {
        // Implement serialization logic here
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            writer.WriteLine($"MinValue: {minValue}, MaxValue: {maxValue}");
        }
    }

    public void LoadState(string filePath)
    {
        // Implement deserialization logic here
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("State file not found.");
        }

        using (StreamReader reader = new StreamReader(filePath))
        {
            string[] parts = reader.ReadLine().Split(',');
            double loadedMinValue = double.Parse(parts[0]);
            double loadedMaxValue = double.Parse(parts[1]);

            if (loadedMinValue >= loadedMaxValue || loadedMaxValue - loadedMinValue < MinRangeSize)
            {
                throw new ArgumentException("Invalid range in saved state. Ensure minValue is less than maxValue and the difference is greater than the minimum allowed range size.");
            }

            minValue = loadedMinValue;
            maxValue = loadedMaxValue;
        }
    }

    public void ValidateState()
    {
        if (minValue < 0 || maxValue > double.MaxValue)
        {
            throw new InvalidOperationException("Invalid state detected. Range values are out of valid limits.");
        }

        // Add more validation checks as needed
    }
}
