#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MAX_IP_RANGE 16

typedef struct {
    char ip[MAX_IP_RANGE];
    int timeout_flag;
} TCP_CONNECTION_RECORD_T;

TCP_CONNECTION_RECORD_T* populate_tcp_connections(const char* file_path, size_t* count) {
    FILE* file = fopen(file_path, "r");
    if (!file) return NULL;

    *count = 0;
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    TCP_CONNECTION_RECORD_T* records = (TCP_CONNECTION_RECORD_T*)malloc(file_size);
    if (!records) {
        fclose(file);
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        TCP_CONNECTION_RECORD_T record;
        sscanf(line, "%[^,],%d", record.ip, &record.timeout_flag);

        // Validate IP address and timeout flag
        if (!inet_pton(AF_INET, record.ip, NULL) || record.timeout_flag < 0) {
            free(records);
            fclose(file);
            return NULL;
        }

        records[(*count)++] = record;
    }

    fclose(file);
    return records;
}

void* process_tcp_connections(void* arg) {
    TCP_CONNECTION_RECORD_T* records = (TCP_CONNECTION_RECORD_T*)arg;
    size_t count = sizeof(records) / sizeof(TCP_CONNECTION_RECORD_T);

    for (size_t i = 0; i < count; ++i) {
        // Simulate processing each record
        printf("Processing connection %zu: IP=%s, Timeout Flag=%d\n", i, records[i].ip, records[i].timeout_flag);
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    const char* file_path = "connections.txt";
    size_t count;

    TCP_CONNECTION_RECORD_T* records = populate_tcp_connections(file_path, &count);
    if (!records) {
        fprintf(stderr, "Failed to read and process TCP connections.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_tcp_connections, records) != 0) {
        fprintf(stderr, "Failed to create thread for processing TCP connections.\n");
        free(records);
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Failed to join thread after processing TCP connections.\n");
        free(records);
        return EXIT_FAILURE;
    }

    free(records);
    return EXIT_SUCCESS;
}
