std::string computeMD5(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input.c_str(), input.size(), (unsigned char*)&digest);
    char mdString[33];
    for(int i = 0; i < 16; ++i)
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    return std::string(mdString);
}

void processDirectory(const fs::path& dir, int& totalLines, const std::vector<std::string>& options) {
    for (const auto& entry : fs::recursive_directory_iterator(dir)) {
        if (entry.is_regular_file() && entry.path().extension() == ".txt") {
            std::ifstream file(entry.path());
            int lines = 0;
            std::string line;
            while (std::getline(file, line)) ++lines;
            totalLines += lines;
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <directory> [options]\n";
        return 1;
