    int totalLines = 0;
    std::vector<std::string> options;

    for (int i = 2; i < argc; ++i) {
        options.push_back(std::string(argv[i]));
    }

    processDirectory(directory, totalLines, options);

    std::cout << "Total lines in all text files: " << totalLines << "\n";

