    int verbose = 0;
    const char *output_file = NULL;
    const char *schema_file = NULL;
    const char *metadata_field = NULL;
    int max_processes = 10;
    int compress_type = 0; // 0: none, 1: gzip, 2: bzip2

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            display_usage();
            return 0;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_file = argv[i + 1];
            i++;
        } else if (strncmp(argv[i], "-s", 2) == 0) {
            schema_file = argv[i + 1];
            i++;
        } else if (strncmp(argv[i], "-m", 2) == 0) {
            metadata_field = argv[i + 1];
            i++;
        } else if (strncmp(argv[i], "-c", 2) == 0) {
            max_processes = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--gzip") == 0) {
            compress_type = 1;
        } else if (strcmp(argv[i], "--bzip2") == 0) {
            compress_type = 2;
        } else {
            process_file(argv[i]);
        }
    }

    // Process remaining files in the background
    pthread_t thread_ids[argc - 1];
    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            pthread_create(&thread_ids[i - 1], NULL, process_file, argv[i]);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < argc - 1; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    return 0;
}

