import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class NetworkClient {

    private static final String SERVER_ADDRESS = "192.168.1.100";
    private static final int SERVER_PORT = 5000;
    private static final int MAX_RETRIES = 3;

    public void sendData(List<NFAPI_CRC_INDICATION_PDU> crcList, List<NFAPI_RX_FRAME_PDU> rxList) {
        for (int i = 0; i < MAX_RETRIES; i++) {
            try (Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT)) {
                ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
                ObjectInputStream in = new ObjectInputStream(socket.getInputStream());

                out.writeObject(crcList);
                out.writeObject(rxList);

                boolean success = (boolean) in.readObject();
                if (success) {
                    return;
                }
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Connection failed. Retrying...");
                try {
                    Thread.sleep((long) Math.pow(2, i) * 100);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        System.err.println("Failed to send data after multiple attempts.");
    }

    public static void main(String[] args) {
        NetworkClient client = new NetworkClient();

        // Example usage
        List<NFAPI_CRC_INDICATION_PDU> crcList = createRandomCrcList(10);
        List<NFAPI_RX_FRAME_PDU> rxList = createRandomRxList(10);

        client.sendData(crcList, rxList);
    }

    private static List<NFAPI_CRC_INDICATION_PDU> createRandomCrcList(int size) {
        return IntStream.range(0, size)
                .mapToObj(i -> new NFAPI_CRC_INDICATION_PDU())
                .peek(pdu -> pdu.RX_UE_INFORMATION_TAG = ThreadLocalRandom.current().nextInt())
                .peek(pdu -> pdu.RNTI = ThreadLocalRandom.current().nextInt())
                .peek(pdu -> pdu.CRC_INDICATION_REL8_TAG = ThreadLocalRandom.current().nextBoolean())
                .collect(Collectors.toList());
    }

    private static List<NFAPI_RX_FRAME_PDU> createRandomRxList(int size) {
        return IntStream.range(0, size)
                .mapToObj(i -> new NFAPI_RX_FRAME_PDU())
                .peek(pdu -> pdu.RX_UE_INFORMATION_TAG = ThreadLocalRandom.current().nextInt())
                .peek(pdu -> pdu.RNTI = ThreadLocalRandom.current().nextInt())
                .peek(pdu -> pdu.CRC_INDICATION_REL8_TAG = ThreadLocalRandom.current().nextBoolean())
                .collect(Collectors.toList());
    }

    public static class NFAPI_CRC_INDICATION_PDU {
        int RX_UE_INFORMATION_TAG;
        int RNTI;
        boolean CRC_INDICATION_REL8_TAG;
    }

    public static class NFAPI_RX_FRAME_PDU {
        int RX_UE_INFORMATION_TAG;
        int RNTI;
        boolean CRC_INDICATION_REL8_TAG;
    }
}
