public class ResourceAllocator : IDisposable
{
    private readonly List<IResource> _resourcePool;
    private readonly object _lock = new object();
    private bool _disposed = false;

    public ResourceAllocator(IEnumerable<IResource> initialResources)
    {
        if (initialResources == null || !initialResources.Any())
            throw new ArgumentException("Initial resource pool cannot be empty.");

        ValidateResourcePool(initialResources);
        _resourcePool = new List<IResource>(initialResources);
    }

    private void ValidateResourcePool(IEnumerable<IResource> resources)
    {
        // Validate resources against system limits and external monitoring
        if (resources.Count() > SystemLimits.MaxResourceCount)
            throw new InvalidOperationException("Resource pool exceeds maximum allowed size.");

        ExternalMonitoringSystem.TrackResourceUtilization(resources.Count());
    }

    public IResource Allocate()
    {
        lock (_lock)
        {
            if (!_resourcePool.Any())
                return null;

            return _resourcePool.First();
        }
    }

    public void Release(IResource resource)
    {
        lock (_lock)
        {
            if (!_resourcePool.Contains(resource))
                throw new InvalidOperationException("Attempting to release a non-pooled resource.");

            _resourcePool.Add(resource);
        }
    }

    public bool Resize(int newSize)
    {
        if (newSize < SystemLimits.MinResourceCount || newSize > SystemLimits.MaxResourceCount)
            return false;

        lock (_lock)
        {
            while (_resourcePool.Count > newSize)
                Release(_resourcePool.Last());

            // Simulate adding new resources
            for (int i = _resourcePool.Count; i < newSize; i++)
            {
                _resourcePool.Add(new Resource($"Resource{i}"));
            }
        }

        ExternalNotificationSystem.NotifyResourceChange(_resourcePool.Count);
        return true;
    }

    public void GenerateReport()
