        {
            Console.WriteLine($"Total Resources: {_resourcePool.Count}");
            Console.WriteLine($"Available Resources: {_resourcePool.Count}");
            // Add more details as needed while respecting privacy and data protection
        }
    }

    public void Dispose()
    {
        if (_disposed) return;

        _resourcePool.Clear();
        _disposed = true;
        GC.SuppressFinalize(this);
    }

    ~ResourceAllocator()
    {
        Dispose(false);
    }

    private void Dispose(bool disposing)
    {
        if (!disposing) return;

