// Java client to send list of NFAPI_CRC_INDICATION_PDU_T and NFAPI_RX_FRAME_PDU_T structures over TCP connection

import java.io.*;
import java.net.*;

public class TcpClient {
    private static final int MAX_RETRIES = 5;
    private static final long BACKOFF_MULTIPLIER = 2;

    public static void main(String[] args) throws IOException, InterruptedException {
        String serverAddress = "192.168.1.1";
        int serverPort = 12345;

        for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            try {
                Socket socket = new Socket(serverAddress, serverPort);

                // Send data
                sendPdus(socket);

                // Receive confirmation
                receiveConfirmation(socket);

                socket.close();
                break;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES) throw e;

                long backoffTime = (long)(Math.pow(BACKOFF_MULTIPLIER, attempt) * 1000);
                Thread.sleep(backoffTime);
            }
        }
    }

    private static void sendPdus(Socket socket) throws IOException {
        // Get data to send
        NFAPI_CRC_INDICATION_PDU_T[] crcIndicationPdus = CFunction.create_crc_indication_pdu(10);
        NFAPI_RX_FRAME_PDU_T[] rxFramePdus = CFunction.create_rx_frame_pdu(10);

        // Send data over socket
        DataOutputStream out = new DataOutputStream(socket.getOutputStream());
        for (NFAPI_CRC_INDICATION_PDU_T pdu : crcIndicationPdus) {
            out.writeInt(pdu.RX_UE_INFORMATION_TAG);
            out.writeInt(pdu.RNTI);
            out.writeInt(pdu.CRCFLAG);
        }
        for (NFAPI_RX_FRAME_PDU_T pdu : rxFramePdus) {
            out.writeInt(pdu.RX_UE_INFORMATION_TAG);
            out.writeInt(pdu.RNTI);
            out.writeInt(pdu.DATA_SIZE);
        }

        CFunction.clear_pdus(crcIndicationPdus, 10);
        CFunction.clear_pdus(rxFramePdus, 10);
    }

    private static void receiveConfirmation(Socket socket) throws IOException {
        // Receive confirmation from server
        DataInputStream in = new DataInputStream(socket.getInputStream());
        boolean confirmed = in.readBoolean();

        if (!confirmed) throw new IOException("Server did not confirm processing");
    }
}
