// Java method to compute MD5 hash of a string or file with caching mechanism and asynchronous validation

import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;

public class Md5Hash {
    private static final int CONCURRENCY_LIMIT = 5;

    public static String computeMd5(String input) throws NoSuchAlgorithmException, InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);
        Future<String> future = executor.submit(() -> computeMd5Async(input));
        return future.get();
    }

    private static String computeMd5Async(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger no = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));

        // Add leading zeros
        while (hashtext.length() < 32) {
            hashtext.insert(0, '0');
        }

        return hashtext.toString();
    }

    public static String computeMd5File(File file) throws NoSuchAlgorithmException, IOException, InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);
        Future<String> future = executor.submit(() -> computeMd5AsyncFile(file));
        return future.get();
    }

    private static String computeMd5AsyncFile(File file) throws NoSuchAlgorithmException, IOException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        FileInputStream fis = new FileInputStream(file);

        byte[] byteArray = new byte[1024];
        int bytesCount;

        while ((bytesCount = fis.read(byteArray)) != -1) {
            md.update(byteArray, 0, bytesCount);
        }

        fis.close();

        BigInteger no = new BigInteger(1, md.digest());
        StringBuilder hashtext = new StringBuilder(no.toString(16));

        // Add leading zeros
        while (hashtext.length() < 32) {
            hashtext.insert(0, '0');
        }

        return hashtext.toString();
    }
}
