int calculate_crc_flag(NFAPI_CRC_INDICATION_PDU_T pdu) {
    int crcFlag = 0;
    crcFlag += (pdu.RX_UE_INFORMATION_TAG * 7) % 13;
    crcFlag += (pdu.RNTI * 5) % 11;
    crcFlag += (pdu.CRCFLAG * 3) % 9;

    return crcFlag % 2; // Simplified for demonstration
}
