#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
} NFapiCrcArray;

void initNfapiCrcArray(NFapiCrcArray *array) {
    array->count = 0;
}

int addEntryToNfapiCrcArray(NFapiCrcArray *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    for (int i = 0; i < array->count; i++) {
        if (array->entries[i].RNTI == entry.RNTI) {
            return -1; // Duplicate RNTI
        }
    }
    if (array->count >= MAX_ENTRIES) {
        return -2; // Array full
    }
    array->entries[array->count++] = entry;
    return 0;
}

int getNfapiCrcArraySize(NFapiCrcArray *array) {
    return array->count;
}

int updateEntryInNfapiCrcArray(NFapiCrcArray *array, int index, uint8_t newCRCFLAG) {
    if (index < 0 || index >= array->count) {
        return -1; // Invalid index
    }
    array->entries[index].CRCFLAG = newCRCFLAG;
    return 0;
}

int deleteEntryFromNfapiCrcArray(NFapiCrcArray *array, uint32_t RNTI) {
    for (int i = 0; i < array->count; i++) {
        if (array->entries[i].RNTI == RNTI) {
            memmove(&array->entries[i], &array->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->count - i - 1));
            array->count--;
            return 0;
        }
    }
    return -1; // RNTI not found
}

void printNfapiCrcArray(NFapiCrcArray *array) {
    for (int i = 0; i < array->count; i++) {
        printf("Entry %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u, CRCFLAG=%hhu\n",
               i, array->entries[i].RX_UE_INFORMATION_TAG, array->entries[i].RNTI,
               array->entries[i].CRC_INDICATION_REL8_TAG, array->entries[i].CRCFLAG);
    }
}

