#define MAX_PDU_COUNT 1000

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(uint32_t start_tag, uint16_t max_rnti, uint16_t *pdu_count) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_PDU_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    uint16_t rnti = max_rnti - 100; // Assuming unique RNTIs within this range
    uint32_t tag = start_tag;

    for (uint16_t i = 0; i < *pdu_count && i < MAX_PDU_COUNT; ++i) {
        pthread_mutex_lock(&mutex);
        pdus[i].RX_UE_INFORMATION_TAG = tag;
        pdus[i].RNTI = rnti++;
        if (rnti > max_rnti) rnti = max_rnti - 100;

        // Simulate CRCFLAG using a rolling checksum
        uint8_t crcflag = 0;
        for (uint32_t j = 0; j < sizeof(tag); ++j) {
            crcflag ^= ((tag >> (j * 8)) & 0xFF);
        }
        pdus[i].CRCFLAG = crcflag;

        tag++;
        pthread_mutex_unlock(&mutex);
    }

    *pdu_count = i;
    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, uint16_t count) {
    free(pdus);
}
