import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class HashValidator {
    private ExecutorService executor = Executors.newFixedThreadPool(3);

    public String getMD5Hash(String input, boolean validate) throws InterruptedException, ExecutionException {
        String md5Hash = calculateMD5(input);

        if (validate) {
            md5Hash = validateHash(md5Hash);
        }

        return md5Hash;
    }

    private String calculateMD5(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    private String validateHash(final String hash) throws InterruptedException, ExecutionException {
        Callable<String> validator = new Callable<String>() {
            @Override
            public String call() throws Exception {
                // Simulate API validation
                Thread.sleep(100); // Delay for simulation
                return "Valid"; // Return result from actual validation logic
            }
        };

        Future<String> future = executor.submit(validator);
        return future.get();
    }

    private void logTimeTaken(String hash, long startTime) {
        System.out.println("Hash: " + hash + ", Time taken: " + (System.currentTimeMillis() - startTime) + "ms");
    }

    public void shutdown() {
        executor.shutdown();
    }
}
