namespace fs = std::filesystem;

void countLines(const fs::path& path, int& totalLines, bool verbose) {
    if (fs::is_regular_file(path)) {
        std::ifstream file(path);
        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                ++totalLines;
                if (verbose) {
                    std::cout << "Processed: " << path.filename() << ", Line: " << totalLines << std::endl;
                }
            }
            file.close();
        } else {
            std::cerr << "Error opening file: " << path << std::endl;
        }
    } else if (fs::is_directory(path)) {
        for (const auto& entry : fs::directory_iterator(path)) {
            countLines(entry.path(), totalLines, verbose);
        }
    }
}

int main(int argc, char* argv[]) {
    bool help = false;
    bool verbose = false;
    bool summary = false;
    std::string filterPattern = ".*";
    fs::path outputDirectory;
    int argIndex = 1;

    while (argIndex < argc) {
        if (argv[argIndex] == "-h" || argv[argIndex] == "--help") {
            help = true;
        } else if (argv[argIndex] == "-v" || argv[argIndex] == "--verbose") {
            verbose = true;
        } else if (argv[argIndex] == "-s" || argv[argIndex] == "--summary") {
            summary = true;
        } else if (argv[argIndex] == "-f" || argv[argIndex] == "--filter") {
            if (argIndex + 1 < argc) {
                filterPattern = argv[++argIndex];
            }
        } else if (argv[argIndex] == "-o" || argv[argIndex] == "--output-directory") {
            if (argIndex + 1 < argc) {
                outputDirectory = argv[++argIndex];
            }
        } else {
            break;
        }
        ++argIndex;
    }

    if (help) {
        std::cout << "Usage: program_name [options]\n";
        std::cout << "Options:\n";
        std::cout << "  -h, --help\tDisplay this help message\n";
        std::cout << "  -v, --verbose\tOutput detailed information about each file processed\n";
        std::cout << "  -s, --summary\tPrint a summary report of the total number of lines\n";
        std::cout << "  -f, --filter PATTERN\tFilter files by name using regex pattern\n";
        std::cout << "  -o, --output-directory DIR\tSave processed files with modified timestamp appended to their filenames\n";
        return 0;
    }

    if (argIndex >= argc) {
        std::cerr << "Error: No input directory specified.\n";
        return 1;
    }

    fs::path inputDirectory = argv[argIndex];
    int totalLines = 0;

    auto start = std::chrono::high_resolution_clock::now();
    countLines(inputDirectory, totalLines, verbose);
    auto end = std::chrono::high_resolution_clock::now();

    if (summary) {
        std::cout << "Total lines processed: " << totalLines << std::endl;
    }

    std::chrono::duration<double> elapsed = end - start;
    std::cout << "Elapsed time: " << elapsed.count() << " seconds" << std::endl;

    return 0;
}
