NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int N, int mode) {
    static NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    static int current_size = 0;
    static uint16_t last_rnti = MIN_RNTI - 1;

    if (N > MAX_RNTI - MIN_RNTI + 1) {
        printf("Error: RNTI range too small for requested number of PDUs\n");
        return NULL;
    }

    if (mode == MODE_BATCH) {
        // Batch mode processing
        if (current_size < N) {
            if (pdu_list != NULL) {
                free(pdu_list);
            }
            pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current_size = N;
        }
    } else if (mode == MODE_REAL_TIME) {
        // Real-time mode processing
        if (current_size < N) {
            if (pdu_list != NULL) {
                free(pdu_list);
            }
            pdu_list = realloc(pdu_list, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current_size = N;
        } else {
            // Adjust list size based on system load
            int new_size = current_size * 2;
            if (new_size > N) {
                new_size = N;
            }
            pdu_list = realloc(pdu_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current_size = new_size;
        }
    } else {
        printf("Error: Invalid mode\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = generate_rx_ue_information_tag();
        while (1) {
            pdu_list[i].RNTI = generate_random_rnti(last_rnti, MIN_RNTI, MAX_RNTI);
            if (pdu_list[i].RNTI != last_rnti) {
                break;
            }
        }
        last_rnti = pdu_list[i].RNTI;
        pdu_list[i].CRCFLAG = generate_random_crcflag();
    }

    return pdu_list;
}

uint32_t generate_rx_ue_information_tag() {
    // Generate a valid RX_UE_INFORMATION_TAG
    return rand() % 0xFFFFFFFF;
}

uint16_t generate_random_rnti(uint16_t last_rnti, uint16_t min_rnti, uint16_t max_rnti) {
    uint16_t rnti = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    while (rnti == last_rnti) {
        rnti = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    }
    return rnti;
}

uint8_t generate_random_crcflag() {
    // Generate a random CRCFLAG
    return rand() % 2;
}
