// Java client to send list of structures over TCP connection

import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class NetworkClient {
    private static final int MAX_RETRIES = 5;
    private static final double BACKOFF_FACTOR = 2.0;

    public void sendData(NFAPI_CRC_INDICATION_PDU_T[] crcList, NFAPI_RX_FRAME_PDU_T[] rxList) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            try (Socket socket = new Socket("server_address", server_port)) {
                // Send data over TCP connection
                ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
                out.writeObject(crcList);
                out.writeObject(rxList);

                // Confirm successful processing
                ObjectInputStream in = new ObjectInputStream(socket.getInputStream());
                boolean success = (boolean) in.readObject();
                if (success) {
                    System.out.println("Data sent successfully.");
                    return;
                }
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Error sending data: " + e.getMessage());
            }

            // Exponential backoff
            try {
                Thread.sleep((long) (Math.pow(BACKOFF_FACTOR, retries) * 100));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            retries++;
        }
        System.err.println("Failed to send data after " + MAX_RETRIES + " attempts.");
    }

    public static void main(String[] args) {
        NetworkClient client = new NetworkClient();

        // Create lists of structures
        NFAPI_CRC_INDICATION_PDU_T[] crcList = create_crc_list(10);
        NFAPI_RX_FRAME_PDU_T[] rxList = create_rx_list(10);

        // Send data over network
