public class HashValidator {

    private static final int MAX_RETRIES = 3;
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static String getSHA256(String input, boolean validate) {
        try {
            if (cache.containsKey(input)) {
                return cache.get(input);
            }

            String hash = computeSHA256(input);
            if (validate) {
                if (!isHashValid(hash)) {
                    throw new RuntimeException("Invalid hash");
                }
            }

            cache.put(input, hash);
            logTimeTaken(System.currentTimeMillis(), input);
            return hash;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static String computeSHA256(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] encodedhash = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder(2 * encodedhash.length);
        for (int i = 0; i < encodedhash.length; i++) {
            String hex = Integer.toHexString(0xff & encodedhash[i]);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static boolean isHashValid(String hash) {
        // Simulate external API service validation
        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                Thread.sleep((long) (Math.random() * 100));
                if (validateWithService(hash)) {
                    return true;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return false;
    }

    private static boolean validateWithService(String hash) {
        // Simulate external API service validation
        return Math.random() > 0.5;
    }

    private static void logTimeTaken(long startTime, String input) {
        long endTime = System.currentTimeMillis();
        long timeTaken = endTime - startTime;
        writeLog(input + " - Time taken: " + timeTaken + " ms");
    }

    private static void writeLog(String message) {
        // Write log to file
        System.out.println(message);
    }
}
