    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue > newMaxValue || newMaxValue - newMinValue > MaxRangeSize)
        {
            LogError(newMinValue, newMaxValue);
        }
        else
        {
            _minValue = newMinValue;
            _maxValue = newMaxValue;
        }
    }

    private void LogError(double minValue, double maxValue)
    {
        Console.WriteLine($"{DateTime.Now}: Error - Invalid range attempt: Min={minValue}, Max={maxValue}");
    }

    public float GenerateRandomFloat()
    {
        return (float)GenerateRandomDouble();
    }

    public int GenerateRandomInt()
    {
        return (int)(GenerateRandomDouble() * 2147483648); // Assuming Int32 range
    }

    public double GenerateRandomDouble()
    {
        Random random = new Random();
        return _minValue + (random.NextDouble() * (_maxValue - _minValue));
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            GenerateRandomFloat(),
            GenerateRandomFloat(),
            GenerateRandomFloat());
    }

    public Quaternion GenerateRandomQuaternion()
    {
        Random random = new Random();
        return new Quaternion(
            (float)GenerateRandomDouble(),
            (float)GenerateRandomDouble(),
            (float)GenerateRandomDouble(),
            (float)GenerateRandomDouble()).normalized;
    }

    public DateTime GenerateRandomDateTime(DateTime start, DateTime end)
    {
        if (start > end) throw new ArgumentException("Start date cannot be after end date.");
        Random random = new Random();
        return start.AddMilliseconds(random.Next((int)(end - start).TotalMilliseconds));
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Min={_minValue}, Max={_maxValue}";
    }
