using UnityEngine;

public class RandomValueGenerator : MonoBehaviour
{
    private float minValue;
    private float maxValue;
    private int seed = 0;

    public RandomValueGenerator(float min, float max)
    {
        SetRange(min, max);
    }

    public void SetRange(float min, float max)
    {
        if (min <= max)
        {
            minValue = min;
            maxValue = max;
        }
        else
        {
            Debug.LogWarning("Invalid range: min should be less than or equal to max. Using default values.");
            minValue = 0;
            maxValue = 1;
        }
    }

    public float GetRandomFloat()
    {
        UnityEngine.Random.InitState((int)seed);
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        UnityEngine.Random.InitState((int)seed);
        if (minValue == maxValue)
        {
            return Mathf.RoundToInt(minValue);
        }
        else
        {
            return UnityEngine.Random.Range(Mathf.Min(minValue, maxValue), Mathf.Max(minValue, maxValue) + 1);
        }
    }

    public override string ToString()
    {
        if (maxValue < minValue)
        {
            return "Invalid range";
        }
        else if (maxValue == minValue)
        {
            return $"Range: [{minValue}]";
        }
        else
        {
            return $"Range: [{minValue}, {maxValue})";
        }
    }
}
