    if (pduCount >= MAX_PDU_COUNT) {
        printf("Error: Maximum PDU count reached.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    uint64_t tag = getUlUeInformationTagFromExternalSource(rand() % 1000000);
    if (tag == 0) {
