        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    NFAPI_UL_TX_FRAME_PDU_T pdu = { tag, rand() % 1024, ((rand() % 100) / 10.0f) };
    struct PduNode* newNode = (struct PduNode*)malloc(sizeof(struct PduNode));
    newNode->pdu = pdu;
    newNode->next = pdus[pduCount];
    pdus[pduCount] = newNode;

    pduCount++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void clearPduList() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        while (pdus[i]) {
            struct PduNode* temp = pdus[i];
            pdus[i] = pdus[i]->next;
            free(temp);
        }
    }

    pduCount = 0;
    pthread_mutex_unlock(&mutex);
}
