import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class HashService {

    private static final List<String> API_SERVICES = List.of("https://api1.example.com/validate", "https://api2.example.com/validate");
    private static final long MAX_RESPONSE_TIME_MILLIS = 5000;

    public static String getSha256Hash(String input, boolean validate) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }

        if (!validate) {
            return sb.toString();
        }

        String mostReliableService = getMostReliableService();
        int retries = 3;
        while (retries > 0) {
            boolean isValid = callValidationApi(mostReliableService, sb.toString());
            if (isValid) {
                return sb.toString();
            }
            retries--;
            Thread.sleep(100 * new Random().nextInt(5)); // Random delay between retries
        }

        throw new Exception("Failed to validate hash after multiple attempts.");
    }

    private static String getMostReliableService() throws Exception {
        long startTime = System.currentTimeMillis();
        List<String> responses = API_SERVICES.stream()
                .map(service -> callValidationApi(service, "dummyHash"))
                .toList();

        long endTime = System.currentTimeMillis();
        double averageResponseTime = (endTime - startTime) / (double) API_SERVICES.size();

        return API_SERVICES.get(responses.indexOf(Boolean.TRUE));
    }

    private static boolean callValidationApi(String serviceUrl, String hash) {
        try {
            URL url = new URL(serviceUrl + "?hash=" + hash);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            int responseCode = conn.getResponseCode();

            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                String inputLine;
                StringBuilder content = new StringBuilder();
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();

                return Boolean.parseBoolean(content.toString());
            } else {
                System.out.println("Invalid response code: " + responseCode);
                return false;
            }
        } catch (IOException e) {
            System.out.println("Error calling validation API: " + e.getMessage());
            return false;
        }
    }

    public static void logHashProcessingTime(String input, long startTime, boolean isValid) {
        long endTime = System.currentTimeMillis();
        double processingTime = (endTime - startTime) / 1000.0;

        try (BufferedWriter writer = new BufferedWriter(new FileWriter("hash_processing_logs.txt", true))) {
            writer.write("Input: " + input + ", Processing Time: " + processingTime + " seconds, Valid: " + isValid);
            writer.newLine();
        } catch (IOException e) {
            System.out.println("Error logging hash processing time: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        try {
            String input = "exampleData";
            long startTime = System.currentTimeMillis();
            boolean validate = true; // Set to false to skip validation
            String hash = getSha256Hash(input, validate);
            logHashProcessingTime(input, startTime, true); // Simulate successful validation
            System.out.println("SHA-256 Hash: " + hash);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}
