import java.io.*;
import java.net.Socket;
import java.util.concurrent.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class NetworkClient {
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_DELAY = 1000; // in milliseconds

    public void sendPDUList(NFAPI_CRC_INDICATION_PDU_T[] pduList, String serverAddress, int serverPort) throws IOException {
        for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            try (Socket socket = new Socket(serverAddress, serverPort)) {
                // Send data over the socket
                System.out.println("Data sent successfully");
                break;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES) {
                    throw e;
                }
                System.err.println("Failed to send data. Retrying in " + RETRY_DELAY / 1000 + " seconds...");
                Thread.sleep(RETRY_DELAY);
            }
        }
    }

    public String computeMD5(String input, int concurrencyLimit) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(concurrencyLimit);
        CompletionService<String> completionService = new ExecutorCompletionService<>(executor);

        // Submit tasks to the executor
        for (int i = 0; i < input.length(); i += concurrencyLimit) {
            final int start = i;
            completionService.submit(() -> {
                String md5Hash = computeMD5ForPart(input, start, Math.min(start + concurrencyLimit, input.length()));
                return md5Hash;
            });
        }

        // Collect results
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < input.length(); i += concurrencyLimit) {
            Future<String> future = completionService.take();
            result.append(future.get());
        }

        executor.shutdown();
        return result.toString();
    }

    private String computeMD5ForPart(String input, int start, int end) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = md.digest(input.substring(start, end).getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        NetworkClient client = new NetworkClient();
        NFAPI_CRC_INDICATION_PDU_T[] pduList = createCrcPduList(10);
        client.sendPDUList(pduList, "example.com", 8080);

        String input = "exampleInput";
        String md5Hash = client.computeMD5(input, 4);
        System.out.println("MD5 Hash: " + md5Hash);
    }
}
