        _maxValue = maxValue;
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue > newMaxValue)
            throw new ArgumentException("New min value must be less than or equal to new max value.");

        // Validate against system limits and log error if exceeded
        if (newMaxValue - newMinValue > SomeSystemLimit)
