#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    char *data;
} FILE_PROCESS_RECORD;

FILE_PROCESS_RECORD* read_file(const char *filename, int *line_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    FILE_PROCESS_RECORD *records = malloc(sizeof(FILE_PROCESS_RECORD));
    records->data = malloc(MAX_LINE_LENGTH);
    if (!records || !records->data) {
        perror("Memory allocation failed");
        fclose(file);
        free(records);
        return NULL;
    }

    *line_count = 0;
    while (fgets(records->data, MAX_LINE_LENGTH, file)) {
        (*line_count)++;
        records = realloc(records, sizeof(FILE_PROCESS_RECORD) * (*line_count + 1));
        if (!records) {
            perror("Memory reallocation failed");
            fclose(file);
            return NULL;
        }
        records[*line_count].data = malloc(MAX_LINE_LENGTH);
        if (!records[*line_count].data) {
            perror("Memory allocation failed");
            free_records(records, *line_count);
            fclose(file);
            return NULL;
        }
        strcpy(records[*line_count].data, records->data);
    }

    fclose(file);
    return records;
}

void free_records(FILE_PROCESS_RECORD *records, int line_count) {
    for (int i = 0; i <= line_count; i++) {
        free(records[i].data);
    }
    free(records);
}

void write_output(const char *filename, FILE_PROCESS_RECORD *records, int line_count) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    for (int i = 0; i < line_count; i++) {
        fprintf(file, "%s", records[i].data);
    }

    fclose(file);
}

void print_usage() {
    printf("Usage: program [options]\n");
    printf("Options:\n");
    printf("  -i inputfile   Specify the input file\n");
    printf("  -o outputfile  Specify the output file\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    const char *input_file = NULL;
    const char *output_file = "output.txt";

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            input_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else {
            print_usage();
            return EXIT_FAILURE;
        }
    }

    if (!input_file) {
        fprintf(stderr, "Error: No input file specified\n");
        return EXIT_FAILURE;
    }

    int line_count;
    FILE_PROCESS_RECORD *records = read_file(input_file, &line_count);
    if (records) {
        write_output(output_file, records, line_count);
        free_records(records, line_count);
    }

    return EXIT_SUCCESS;
}
