['```python
import os
import re
import logging
from concurrent.futures import ThreadPoolExecutor

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ConfigProcessor:
    def __init__(self, directory, config_service):
        self.directory = directory
        self.config_service = config_service

    def process_files(self):
        file_pattern = re.compile(r'.*\.conf')
        processed_count = 0
        successful_replacements = 0
        failed_replacements = 0

        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = {executor.submit(self.process_file, file): file for file in os.listdir(self.directory) if file_pattern.match(file)}

            for future in futures.values():
                try:
                    file_name, replacements = future.result()
                    processed_count += 1
                    successful_replacements += replacements
                except Exception as e:
                    logging.error(f"Failed to process {future.result()}: {e}")
                    failed_replacements += 1

        logging.info(f"Processed {processed_count} files: {successful_replacements} successful, {failed_replacements} failed")

    def process_file(self, file_name):
        temp_file_name = f"{file_name}.tmp"
        replacements = 0
        with open(os.path.join(self.directory, file_name), 'r') as infile, open(temp_file_name, 'w') as outfile:
            for line in infile:
                new_line, replacements_in_line = self.replace_variables(line)
                outfile.write(new_line)
                replacements += replacements_in_line
        os.rename(temp_file_name, os.path.join(self.directory, file_name))
        return file_name, replacements

    def replace_variables(self, line):
        variables = re.findall(r'\$\{([^}]+)\}', line)
        for var in variables:
            value = self.config_service.get(var)
            if value is None:
                logging.warning(f"No value found for variable {var}, using default")
                value = var  # Fallback to variable name if no value is available
            line = line.replace(f'${{{var}}}', value)
        return line, len(variables)

class ConfigService:
    def __init__(self):
        self.variables = {
            'DB_HOST': 'localhost',
            'DB_PORT': '5432'
            # Add more variables as needed
        }

    def get(self, key):
        return self.variables.get(key)
```

This Python script defines a `ConfigProcessor` class that processes configuration files in a specified directory, replacing environment-specific settings with values from an external configuration service. The script uses multi-threading to optimize file processing performance and integrates with an existing logging framework for detailed error and success logging.

The `process_files` method reads all files matching the `.conf` pattern in the specified directory and submits them for processing using a thread pool executor. Each file is processed by the `process_file` method, which reads the file line by line, replaces variables using regular expressions, and writes the modified lines to a temporary file. After processing, the original file is replaced with the modified file.

The script also includes a `ConfigService` class that simulates an external configuration service. The `get` method retrieves values for environment-specific variables from a dictionary. If no value is found for a variable, the script falls back to using the variable name as its value.

This design ensures efficient performance, scalability, and integration with the current system's logging framework while handling potential integration issues and ensuring data consistency.']

