### MD5 Hash Function with Caching

```c
#include <openssl/md5.h>
#include <stdlib.h>

typedef struct {
    char* key;
    unsigned char hash[MD5_DIGEST_LENGTH];
} CacheEntry;

CacheEntry** cache = NULL;
int cacheSize = 0;
int cacheCapacity = 100;

unsigned char* compute_md5(const char* str) {
    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5_Init(&md5);
    MD5_Update(&md5, str, strlen(str));
    MD5_Final(digest, &md5);

    return digest;
}

unsigned char* get_md5_from_cache(const char* key) {
    for (int i = 0; i < cacheSize; i++) {
        if (strcmp(cache[i]->key, key) == 0) {
            return cache[i]->hash;
        }
    }
    return NULL;
}

void add_to_cache(const char* key, unsigned char* hash) {
    if (cacheSize >= cacheCapacity) {
        // Resize the cache
        cacheCapacity *= 2;
        cache = realloc(cache, cacheCapacity * sizeof(CacheEntry));
    }

    CacheEntry* entry = malloc(sizeof(CacheEntry));
    entry->key = strdup(key);
    memcpy(entry->hash, hash, MD5_DIGEST_LENGTH);

    cache[cacheSize++] = entry;
}

unsigned char* md5_with_cache(const char* str) {
    unsigned char* cachedHash = get_md5_from_cache(str);
    if (cachedHash != NULL) {
        return cachedHash;
    }

    unsigned char* hash = compute_md5(str);
    add_to_cache(str, hash);

    return hash;
}
```

