            raise Exception("Encryption failed: " + encrypted_key.stderr)

        with open(config_path, 'a') as f:
            f.write(f"\n\"encrypted_secret_key\": \"{encrypted_key.stdout}\"")

    except IOError as e:
        logger.error(f"File operation error: {e}")
        raise

def clear_config_file():
    """Clear old parameters from the configuration file."""
    config_path = 'config.json'

    with file_lock:
        try:
            with open(config_path, 'w') as f:
                json.dump({}, f)
        except IOError as e:
            logger.error(f"File operation error: {e}")
            raise

def send_config_to_server(url):
    """Send updated configuration to the remote server."""
    config_path = 'config.json'

    try:
        with open(config_path, 'r') as f:
            config_data = json.load(f)

        response = requests.post(url, json=config_data, timeout=10)
        if response.status_code == 200:
            logger.info("Config sent successfully")
        else:
            raise Exception(f"Failed to send config: {response.status_code}")

    except requests.RequestException as e:
        logger.error(f"Network error: {e}")
        raise

def md5_hash(data, max_concurrency=10):
    """Compute MD5 hash of a string or file with caching and concurrency."""
    from hashlib import md5

    def compute_md5(item):
        if isinstance(item, str):
            return md5(item.encode()).hexdigest()
        elif isinstance(item, bytes):
            return md5(item).hexdigest()

    def read_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                return f.read()
        except FileNotFoundError:
            logger.error(f"File not found: {file_path}")
            raise

    if isinstance(data, str) or isinstance(data, bytes):
        return compute_md5(data)
    elif isinstance(data, list):
        with ThreadPoolExecutor(max_workers=max_concurrency) as executor:
            results = list(executor.map(compute_md5, data))
        return results
    else:
        logger.error("Invalid data type for MD5 hash")
        raise ValueError("Invalid data type")

