    public static void updateConfigAndSend() throws Exception {
        // Simulate dynamic parameters
        String configData = "{\"key\":\"value\"}";

        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                sendConfigToServer(SERVER_URL, configData);
                break;
            } catch (Exception e) {
                logger.warn("Failed to send config, retrying...", e);
                retryCount++;
                time.sleep((long) Math.pow(2, retryCount));
            }
        }

        if (retryCount == MAX_RETRIES) {
            throw new Exception("Failed to send config after " + MAX_RETRIES + " retries");
        }
    }

    public static void sendConfigToServer(String url, String configData) throws Exception {
        Socket socket = null;
        try {
            socket = new Socket(url.split(":")[0], Integer.parseInt(url.split(":")[1]));
            BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            socket.getOutputStream().write(configData.getBytes());
            logger.info("Config sent successfully");
        } catch (Exception e) {
            throw new Exception("Failed to send config", e);
        } finally {
            if (socket != null && !socket.isClosed()) {
                try {
                    socket.close();
                } catch (IOException e) {
                    logger.error("Error closing socket", e);
                }
            }
        }
    }

