    public RandomValueGenerator(int seed = 0)
    {
        random = new Random(seed);
        SetRange(0, 100, 0.0f, 1.0f); // Default range
    }

    public void SetRange(int minInt, int maxInt, float minFloat, float maxFloat)
    {
        if (minInt < maxInt)
        {
            minIntRange = minInt;
            maxIntRange = maxInt;
        }
        else
        {
            throw new ArgumentException("Minimum integer value must be less than maximum.");
        }

        if (minFloat < maxFloat)
        {
            minFloatRange = minFloat;
            maxFloatRange = maxFloat;
        }
        else
        {
            throw new ArgumentException("Minimum float value must be less than maximum.");
        }
    }

    public int GetRandomInt(bool inclusiveMax = true)
    {
        if (inclusiveMax)
            return random.Next(minIntRange, maxIntRange + 1);
        else
            return random.Next(minIntRange, maxIntRange);
    }

    public float GetRandomFloat(bool inclusiveMax = true)
    {
        if (inclusiveMax)
            return (float)(minFloatRange + (maxFloatRange - minFloatRange) * random.NextDouble());
        else
            return (float)(minFloatRange + (maxFloatRange - minFloatRange) * (random.NextDouble() - 0.5));
    }

    public override string ToString()
    {
        return $"Int Range: {minIntRange} to {maxIntRange}, Float Range: {minFloatRange} to {maxFloatRange}";
    }
