using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private const int MaxAdjustmentAttempts = 100;
    private static readonly Random random = new Random();

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)(random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(GenerateRandomDouble());
    }

    public double GenerateRandomDouble()
    {
        return random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public void AdjustRange(double newMin, double newMax)
    {
        int attempts = 0;
        while (newMin > newMax || newMin < this.minValue || newMax > this.maxValue && attempts++ < MaxAdjustmentAttempts)
        {
            newMin *= 0.99; // Safeguard against infinite loops
            newMax *= 1.01;
        }
        if (attempts == MaxAdjustmentAttempts) throw new InvalidOperationException("Failed to adjust range within system limits.");
        minValue = newMin;
        maxValue = newMax;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat());
    }

    public Quaternion GenerateRandomQuaternion()
    {
        while (true)
        {
            float x = GenerateRandomFloat();
            float y = GenerateRandomFloat();
            float z = GenerateRandomFloat();
            if (x * x + y * y + z * z <= 1f) return new Quaternion(x, y, z, Mathf.Sqrt(1f - x * x - y * y - z * z));
        }
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: [{minValue}, {maxValue}]";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate) throw new ArgumentException("Start date cannot be after end date.");
        long ticks = (long)random.NextDouble() * (endDate.Ticks - startDate.Ticks);
        return startDate.AddTicks(ticks);
    }

    public float GenerateValue(double range)
    {
        if (range <= 0) return 0; // Handle edge cases for zero or negative range
        return (float)(random.NextDouble() * range + minValue);
    }
}
