import subprocess
from cryptography.fernet import Fernet
import logging

class FileModificationError(Exception):
    pass

def custom_encrypt_password(password):
    key = Fernet.generate_key()
    fernet = Fernet(key)
    encrypted_password = fernet.encrypt(password.encode())
    return key, encrypted_password

def modify_kickstart_file(params, input_path, output_path):
    logging.basicConfig(filename='kickstart_modification.log', level=logging.INFO)

    for placeholder, value in params.items():
        command = f"sed -i 's/{placeholder}/{value}/' {input_path}"
        try:
            subprocess.check_call(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            raise FileModificationError(f"Sed command failed: {e}")

    key, encrypted_password = custom_encrypt_password(params['PASSWORD'])
    logging.info(f"Encrypted password with key: {key.decode()}")

    try:
        with open(input_path, 'r') as file:
            lines = file.readlines()

        with open(output_path, 'w') as file:
            for line in lines:
                if 'PASSWORD' in line:
                    line = line.replace('PASSWORD', encrypted_password.decode())
                file.write(line)

    except IOError as e:
        raise FileModificationError(f"File operation failed: {e}")

def check_modification(input_path, params):
    with open(input_path, 'r') as file:
        content = file.read()

    for placeholder, value in params.items():
        if f'${placeholder}' not in content:
            print(f"Warning: Placeholder ${placeholder} not found in the file.")

    key, encrypted_password = custom_encrypt_password(params['PASSWORD'])
    if encrypted_password.decode() not in content:
        raise FileModificationError("Encrypted password not found in the file.")

# Example usage
params = {
    'ROOT_PASSWORD': 'new_root_password',
    'USER_PASSWORD': 'new_user_password'
}
modify_kickstart_file(params, '/path/to/kickstart.cfg', '/path/to/output.kickstart')
