import os
import subprocess
import logging
from contextlib import contextmanager

class ServiceConfigurationError(Exception):
    pass

def replace_placeholders(file_path, params):
    with open(file_path, 'r') as file:
        content = file.read()

    for key, value in params.items():
        content = content.replace(key, value)

    return content

@contextmanager
def atomic_file_write(file_path, temp_dir=None):
    if temp_dir is None:
        temp_dir = os.getcwd()

    temp_path = os.path.join(temp_dir, 'temp_' + os.path.basename(file_path))

    with open(file_path, 'r') as file:
        content = file.read()

    with open(temp_path, 'w') as file:
        file.write(content)

    yield

    try:
        os.replace(temp_path, file_path)
    except Exception as e:
        raise ServiceConfigurationError(f"Failed to replace file: {e}") from None

def validate_service_status(service_name):
    result = subprocess.run(['systemctl', 'is-active', '--quiet', service_name], capture_output=True, text=True)
    if result.returncode != 0:
        raise ServiceConfigurationError(f"Service {service_name} is not running")
    return True

def log_operations(message, level='info'):
    logging.log(getattr(logging, level), message)

def check_placeholder_replacement(file_path, params):
    with open(file_path, 'r') as file:
        content = file.read()

    for key in params.keys():
        if key not in content:
            raise ServiceConfigurationError(f"Placeholder {key} not found in the configuration file")

def main(service_name, config_params, temp_dir=None, auto_restart=True):
    logging.basicConfig(filename='service_config.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    try:
        validate_service_status(service_name)
        log_operations(f"Service {service_name} is running")

        with atomic_file_write(config_params['config_file'], temp_dir):
            new_content = replace_placeholders(config_params['config_file'], config_params['params'])
            check_placeholder_replacement(config_params['config_file'], config_params['params'])
            with open(config_params['config_file'], 'w') as file:
                file.write(new_content)

        log_operations(f"Configuration updated successfully in {config_params['config_file']}")

        if auto_restart:
            subprocess.run(['systemctl', 'restart', service_name])
            log_operations(f"Service {service_name} restarted")

    except ServiceConfigurationError as e:
        log_operations(str(e), level='error')
        raise

if __name__ == "__main__":
    config_params = {
        'config_file': '/etc/my_service.conf',
        'params': {
            '${PLACEHOLDER_1}': 'new_value_1',
            '${PLACEHOLDER_2}': 'new_value_2'
        }
    }

    main('my_service', config_params)
