import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class NetworkClient {

    private static final String SERVER_ADDRESS = "remote_server_address";
    private static final int SERVER_PORT = 12345;
    private static final int MAX_RETRIES = 5;
    private static final long INITIAL_BACKOFF_MS = 100;
    private static final int CONCURRENCY_LIMIT = 10;

    public void sendPDUList(NFAPI_CRC_INDICATION_PDU_T[] list) {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);
        for (NFAPI_CRC_INDICATION_PDU_T pdu : list) {
            executor.submit(() -> {
                try (Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT)) {
                    sendPDU(socket, pdu);
                } catch (IOException e) {
                    retrySend(pdu);
                }
            });
        }
        executor.shutdown();
    }

    private void sendPDU(Socket socket, NFAPI_CRC_INDICATION_PDU_T pdu) throws IOException {
        // Implement sending the PDU over TCP
        PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
        out.println("PDU: " + pdu.RX_UE_INFORMATION_TAG + ", " + pdu.RNTI + ", " + pdu.CRC_INDICATION_REL8_TAG);
    }

    private void retrySend(NFAPI_CRC_INDICATION_PDU_T pdu) {
        int retries = 0;
        long backoff = INITIAL_BACKOFF_MS;
        while (retries < MAX_RETRIES) {
            try {
                sendPDU(new Socket(SERVER_ADDRESS, SERVER_PORT), pdu);
                break;
            } catch (IOException e) {
                retries++;
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {}
                backoff *= 2; // Exponential backoff
            }
        }
    }

    public static String md5(String input) {
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) {
        NetworkClient client = new NetworkClient();
        NFAPI_CRC_INDICATION_PDU_T[] list = new NFAPI_CRC_INDICATION_PDU_T[10000];
        for (int i = 0; i < list.length; i++) {
            list[i] = new NFAPI_CRC_INDICATION_PDU_T();
            // Initialize fields
        }
        client.sendPDUList(list);
    }
}
