using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Invalid range: Min must be less than Max.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)GenerateRandomDouble(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(GenerateRandomDouble(minValue, maxValue));
    }

    public double GenerateRandomDouble()
    {
        return GenerateRandomDouble(minValue, maxValue);
    }

    private double GenerateRandomDouble(double min, double max)
    {
        Random random = new Random();
        return random.NextDouble() * (max - min) + min;
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat());
    }

    public Quaternion GenerateRandomQuaternion()
    {
        return new Quaternion(GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat()).normalized;
    }

    public string ToString()
    {
        return $"DynamicValueGenerator: {minValue} to {maxValue}";
    }
}
