import os
import re
import glob
from concurrent.futures import ThreadPoolExecutor
from shutil import copy2

# Configuration dictionary with environment-specific settings
config_dict = {
    "database_url": "prod_db_url",
    "api_key": "prod_api_key"
}

def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()

        updated_content = re.sub(r'{{\s*database_url\s*}}', config_dict['database_url'], content)
        updated_content = re.sub(r'{{\s*api_key\s*}}', config_dict['api_key'], updated_content)

        with open(file_path, 'w') as file:
            file.write(updated_content)

        print(f"Processed {file_path}")
    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def rollback_file(file_path):
    try:
        backup_path = file_path + '.bak'
        if os.path.exists(backup_path):
            copy2(backup_path, file_path)
            print(f"Rolled back {file_path}")
        else:
            print(f"No backup found for {file_path} to roll back")
    except Exception as e:
        print(f"Error rolling back {file_path}: {e}")

def main():
    directory = 'config_files'
    file_pattern = '*.conf'

    try:
        # Create a backup of all files before processing
        for root, _, files in os.walk(directory):
            for file in files:
                if re.match(file_pattern, file):
                    original_file_path = os.path.join(root, file)
                    backup_file_path = original_file_path + '.bak'
                    copy2(original_file_path, backup_file_path)

        # Process files in parallel
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(process_file, os.path.join(root, file)) for root, _, files in os.walk(directory) for file in files if re.match(file_pattern, file)]
            for future in futures:
                future.result()

    except Exception as e:
        print(f"Error during processing: {e}")
        # Rollback all changes
        for root, _, files in os.walk(directory):
            for file in files:
                if re.match(file_pattern, file):
                    rollback_file(os.path.join(root, file))

if __name__ == "__main__":
    main()
