void parse_arguments(int argc, char *argv[]) {
    int opt_index = 1;
    while (opt_index < argc) {
        if (strcmp(argv[opt_index], OPT_USAGE) == 0) {
            handle_usage();
        } else if (strcmp(argv[opt_index], OPT_PROCESS) == 0 && opt_index + 1 < argc) {
            process_input_file(argv[opt_index + 1]);
            opt_index += 2;
        } else if (strcmp(argv[opt_index], OPT_OUTPUT) == 0 && opt_index + 1 < argc) {
            generate_output_file(argv[opt_index + 1]);
            opt_index += 2;
        } else if (strcmp(argv[opt_index], OPT_DOCUMENTATION) == 0) {
            generate_documentation();
            opt_index++;
        } else if (strcmp(argv[opt_index], OPT_COLOR) == 0) {
            enable_color_output();
            opt_index++;
        } else if (strcmp(argv[opt_index], OPT_CACHE) == 0) {
            configure_cache();
            opt_index++;
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[opt_index]);
            exit(EXIT_FAILURE);
