typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    char device_id[20];
    float location[2];
} SensorReading;

SensorReading* generate_sensor_readings(int count) {
    SensorReading* readings = (SensorReading*)calloc(count, sizeof(SensorReading));
    if (!readings) return NULL;

    for (int i = 0; i < count; i++) {
        readings[i].timestamp = time(NULL);
        readings[i].temperature = rand() % 50;
        readings[i].humidity = (rand() % 100) / 2.0f;
        readings[i].pressure = rand() % 100 + 973.86f; // Approximately between 973.86 and 1073.86
        snprintf(readings[i].device_id, sizeof(readings[i].device_id), "Device%d", i);
        readings[i].location[0] = (rand() % 180) / 2.0f - 90;
        readings[i].location[1] = (rand() % 360) / 2.0f - 180;
    }

    return readings;
}

void clear_sensor_readings(SensorReading* readings, int count) {
    free(readings);
}
