import asyncio
import websockets
from threading import ThreadLocal

class SensorDataClient:
    def __init__(self, uri):
        self.uri = uri
        self.log = ThreadLocal()
        self.retry_count = 0

    async def send_data(self, data):
        for _ in range(3):  # Retry mechanism with exponential backoff
            try:
                async with websockets.connect(self.uri) as websocket:
                    await websocket.send(data)
                    response = await websocket.recv()
                    if response == "ACK":
                        self.log.info("Data sent successfully")
                        return True
            except (websockets.ConnectionClosed, asyncio.TimeoutError):
                self.retry_count += 1
                await asyncio.sleep(2 ** self.retry_count)
        self.log.error("Failed to send data after multiple retries")
        return False

    def calculate_average(self, readings):
        total_temperature = sum(r.temperature for r in readings)
        total_humidity = sum(r.humidity for r in readings)
        total_pressure = sum(r.pressure for r in readings)
        count = len(readings)

        if count == 0:
            return None

        average = {
            'temperature': total_temperature / count,
            'humidity': total_humidity / count,
            'pressure': total_pressure / count
        }

        return average

# Example usage
client = SensorDataClient('wss://example.com/data')
readings = generate_sensor_readings(10)
average_data = client.calculate_average(readings)
print("Average Temperature:", average_data['temperature'])
print("Average Humidity:", average_data['humidity'])
print("Average Pressure:", average_data['pressure'])

# Simulate sending data
asyncio.run(client.send_data(json.dumps(readings)))
