using System;
using UnityEngine;

public class DynamicRangeGenerator
{
    private double minValue;
    private double maxValue;

    public DynamicRangeGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than or equal to max value.");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return (float)Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)Math.Round(Random.Range(minValue, maxValue));
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(
            (float)Random.Range(minValue, maxValue),
            (float)Random.Range(minValue, maxValue),
            (float)Random.Range(minValue, maxValue)
        );
    }

    public DateTime GetRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
            throw new ArgumentException("Start date must be less than or equal to end date.");
        return startDate.AddTicks((long)(Random.Range(0.0, 1.0) * (endDate.Ticks - startDate.Ticks)));
    }

    public void AdjustRange(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value must be less than or equal to max value.");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public override string ToString()
    {
        return $"DynamicRangeGenerator: {minValue}-{maxValue}";
    }

    public double GetMidpoint()
    {
        return (minValue + maxValue) / 2.0;
    }

    public bool IsSymmetricAroundMidpoint()
    {
        return Math.Abs(minValue - GetMidpoint()) == Math.Abs(maxValue - GetMidpoint());
    }

    public decimal GetRandomDecimal()
    {
        return new decimal(Random.Range((int)minValue, (int)maxValue));
    }

    public void PerformStatisticalAnalysis(double[] values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Values array cannot be empty.");

        double sum = 0;
        double sumOfSquares = 0;
        foreach (var value in values)
        {
            sum += value;
            sumOfSquares += value * value;
        }
        double mean = sum / values.Length;
        double variance = (sumOfSquares / values.Length) - (mean * mean);
        double standardDeviation = Math.Sqrt(variance);

        Console.WriteLine($"Mean: {mean}, Standard Deviation: {standardDeviation}");
    }

    public void HandleEdgeCases()
    {
        if (minValue <= 0 && maxValue >= 0)
        {
            // Handle zero or negative range
            AdjustRange(Math.Abs(minValue), Math.Abs(maxValue));
        }
    }
}
