int main(int argc, char* argv[]) {
    int opt;
    const char* inputFile = NULL;
    const char* outputFile = NULL;
    int enableDoc = 0;
    int enableColor = 0;

    while ((opt = getopt(argc, argv, "hfo:d:c")) != -1) {
        switch (opt) {
            case 'h':
                displayUsage();
                return 0;
            case 'f':
                inputFile = optarg;
                break;
            case 'o':
                outputFile = optarg;
                break;
            case 'd':
                enableDoc = 1;
                break;
            case 'c':
                enableColor = 1;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                displayUsage();
                return 1;
        }
    }

    if (inputFile == NULL) {
        fprintf(stderr, "Input file is required.\n");
        displayUsage();
        return 1;
    }

    if (enableDoc) {
        generateDocumentation();
    }

    processFile(inputFile, outputFile);

    if (enableColor) {
        enableColorOutput();
    }

    return 0;
}
