using System;
using UnityEngine;

public class DynamicRangeGenerator
{
    private double minValue;
    private double maxValue;

    public DynamicRangeGenerator(double initialMinValue, double initialMaxValue)
    {
        if (initialMinValue > initialMaxValue)
        {
            throw new ArgumentException("minValue must be less than or equal to maxValue");
        }
        minValue = initialMinValue;
        maxValue = initialMaxValue;
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public int GetRandomInt()
    {
        if ((int)minValue == (int)maxValue)
        {
            return (int)minValue;
        }
        return (int)Math.Round(minValue + (maxValue - minValue) * UnityEngine.Random.value);
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value),
            (float)(minValue + (maxValue - minValue) * UnityEngine.Random.value)
        );
    }

    public DateTime GetRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("startDate must be less than or equal to endDate");
        }
        return startDate + TimeSpan.FromSeconds((endDate - startDate).TotalSeconds * UnityEngine.Random.value);
    }

    public void AdjustRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue > newMaxValue)
        {
            throw new ArgumentException("minValue must be less than or equal to maxValue");
        }
        minValue = newMinValue;
        maxValue = newMaxValue;
    }

    public decimal GetRandomDecimal()
    {
        return decimal.Parse(((decimal)minValue + ((decimal)maxValue - (decimal)minValue) * UnityEngine.Random.value).ToString());
    }

    public override string ToString()
    {
        if (typeof(DynamicRangeGenerator).GetMethod(System.Reflection.MethodBase.GetCurrentMethod().Name) == null)
        {
            return $"DynamicRangeGenerator: {minValue} to {maxValue}";
        }
        else
        {
            return base.ToString();
        }
    }

    // Additional methods and properties can be added here as per the requirements.
}
