typedef struct {
    int MESSAGE_ID;
    int SOURCE_ID;
    int DESTINATION_ID;
    int DATA_LENGTH;
    char* DATA;
} CUSTOM_MESSAGE_T;

typedef struct {
    CUSTOM_MESSAGE_T* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} MESSAGE_QUEUE_T;

void message_queue_init(MESSAGE_QUEUE_T* queue, size_t initial_capacity) {
    queue->messages = (CUSTOM_MESSAGE_T*)malloc(initial_capacity * sizeof(CUSTOM_MESSAGE_T));
    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
}

void message_queue_push(MESSAGE_QUEUE_T* queue, CUSTOM_MESSAGE_T message) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        queue->messages = (CUSTOM_MESSAGE_T*)realloc(queue->messages, new_capacity * sizeof(CUSTOM_MESSAGE_T));
        queue->capacity = new_capacity;
    }
    memcpy(&queue->messages[queue->count], &message, sizeof(CUSTOM_MESSAGE_T));
    queue->count++;
    pthread_mutex_unlock(&queue->mutex);
}

int message_queue_pop(MESSAGE_QUEUE_T* queue, CUSTOM_MESSAGE_T* out_message) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is empty
    }
    memcpy(out_message, &queue->messages[0], sizeof(CUSTOM_MESSAGE_T));
    memmove(queue->messages, queue->messages + 1, (queue->count - 1) * sizeof(CUSTOM_MESSAGE_T));
    queue->count--;
    pthread_mutex_unlock(&queue->mutex);
    return 0; // Success
}

void message_queue_destroy(MESSAGE_QUEUE_T* queue) {
    pthread_mutex_lock(&queue->mutex);
    free(queue->messages);
    queue->messages = NULL;
    queue->capacity = 0;
    queue->count = 0;
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
}

void* message_transmission_thread(void* arg) {
    MESSAGE_QUEUE_T* queue = (MESSAGE_QUEUE_T*)arg;
    CUSTOM_MESSAGE_T message;

    while (message_queue_pop(queue, &message) == 0) {
        // Simulate message transmission over a network
        printf("Transmitting message with ID: %d\n", message.MESSAGE_ID);
        // Add actual network transmission code here

        // Free allocated memory for the data payload
        free(message.DATA);
    }

    return NULL;
}

int main() {
    MESSAGE_QUEUE_T queue;
    message_queue_init(&queue, 10);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, message_transmission_thread, &queue);

    // Simulate adding messages to the queue
    CUSTOM_MESSAGE_T msg1 = {1, 2, 3, 10, (char*)malloc(10)};
    memcpy(msg1.DATA, "Hello", 6);
    message_queue_push(&queue, msg1);

    CUSTOM_MESSAGE_T msg2 = {2, 4, 5, 15, (char*)malloc(15)};
    memcpy(msg2.DATA, "World", 6);
    message_queue_push(&queue, msg2);

    // Wait for the transmission thread to finish
    pthread_join(thread_id, NULL);

    // Clean up queue and threads
    message_queue_destroy(&queue);

    return 0;
}
