            return pdu.RX_UE_INFORMATION_TAG == tag && pdu.RNTI == rnti;
        }) != pdus.end()) {
            rnti = rntiDist(gen); // Ensure unique RNTI
        }

        uint32_t rollingChecksum = 0;
        rollingChecksum ^= (tag & 0xFF);
        rollingChecksum ^= ((tag >> 8) & 0xFF);
