import hashlib

def calculate_md5_hash(file_path, chunk_size=8192):
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hash_object.update(data)
    return hash_object.hexdigest()
