std::vector<NFAPI_CRC_INDICATION_PDU_T> FileAndCRCProcessor(int N, int maxLimit) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1000, 10000);

    for (int i = 0; i < N && pduList.size() < maxLimit; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = dis(gen);
        int rnti = dis(gen);
        // Ensure uniqueness of RNTI
        while (std::find_if(pduList.begin(), pduList.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& p) { return p.RNTI == rnti; }) != pduList.end()) {
            rnti = dis(gen);
        }
        pdu.RNTI = rnti;

        // Calculate CRCFLAG using a rolling checksum algorithm
        int crcFlag = 0;
        for (int j = 0; j < sizeof(pdu.RX_UE_INFORMATION_TAG) + sizeof(pdu.RNTI); ++j) {
            crcFlag += static_cast<unsigned char>((reinterpret_cast<unsigned char*>(&pdu.RX_UE_INFORMATION_TAG))[j]) * static_cast<unsigned char>((reinterpret_cast<unsigned char*>(&pdu.RNTI))[j]);
        }
        pdu.CRCFLAG = (crcFlag % 2) == 0 ? 1 : 0;

        pduList.push_back(pdu);
    }

    return pduList;
}
