using UnityEngine;
using System;

public static class RandomValueGenerator
{
    private static int _seed = (int)DateTime.Now.Ticks;
    private static bool _logEnabled = true;

    public static void SetSeed(int seed)
    {
        _seed = seed;
        UnityEngine.Random.InitState(seed);
    }

    public static void EnableLogging(bool enable)
    {
        _logEnabled = enable;
    }

    public static T GenerateRandomValue<T>(T min, T max) where T : IComparable
    {
        if (min.CompareTo(max) > 0)
        {
            throw new ArgumentException("Min value cannot be greater than Max value.");
        }

        if (_logEnabled)
        {
            Log($"Generating random value between {min} and {max}");
        }

        return GenerateRandomValueInternal(min, max);
    }

    private static T GenerateRandomValueInternal<T>(T min, T max) where T : IComparable
    {
        if (typeof(T) == typeof(int))
        {
            int minValue = (int)(object)min;
            int maxValue = (int)(object)max;

            return (T)(object)UnityEngine.Random.Range(minValue, maxValue + 1);
        }
        else if (typeof(T) == typeof(long))
        {
            long minValue = (long)(object)min;
            long maxValue = (long)(object)max;

            return (T)(object)UnityEngine.Random.Range(minValue, maxValue + 1);
        }
        else if (typeof(T) == typeof(float))
        {
            float minValue = (float)(object)min;
            float maxValue = (float)(object)max;

            return (T)(object)UnityEngine.Random.Range(minValue, maxValue);
        }
        else if (typeof(T) == typeof(double))
        {
            double minValue = (double)(object)min;
            double maxValue = (double)(object)max;

            return (T)(object)UnityEngine.Random.Range((float)minValue, (float)maxValue);
        }
        else
        {
            throw new NotSupportedException("Unsupported data type for random value generation.");
        }
    }

    private static void Log(string message)
    {
        Debug.Log(message);
    }
}
