using System;
using UnityEngine;

public static class DynamicValueGenerator
{
    private static int _seed = DateTime.Now.GetHashCode();
    private static Random _random = new Random(_seed);
    private static bool _logEnabled = false;

    public static void SetSeed(int seed)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public static void EnableLogging(bool enable)
    {
        _logEnabled = enable;
    }

    public static int GenerateRandomInt(int min, int max, bool inclusiveMin, bool inclusiveMax)
    {
        if (inclusiveMin && inclusiveMax) return _random.Next(min, max + 1);
        else return _random.Next(min, max);
    }

    public static float GenerateRandomFloat(float min, float max, bool inclusiveMin, bool inclusiveMax)
    {
        if (inclusiveMin && inclusiveMax) return (float)_random.NextDouble() * (max - min) + min;
        else return (float)_random.NextDouble() * (max - min);
    }

    public static double GenerateRandomDouble(double min, double max, bool inclusiveMin, bool inclusiveMax)
    {
        if (inclusiveMin && inclusiveMax) return _random.NextDouble() * (max - min) + min;
        else return _random.NextDouble() * (max - min);
    }

    // Additional methods for custom probability distributions
    public static float GenerateGaussian(float mean, float standardDeviation)
    {
        while (true)
        {
            var u1 = (float)_random.NextDouble();
            var u2 = (float)_random.NextDouble();
            var z0 = (float)Math.Sqrt(-2.0 * Math.Log(u1));
            var z1 = (float)(2.0 * Math.PI * u2);
            if (u1 != 0)
            {
                return mean + standardDeviation * z0 * Math.Sin(z1);
            }
        }
    }

    public static float GenerateExponential(float lambda)
    {
        while (true)
        {
            var u = (float)_random.NextDouble();
            if (u != 0)
            {
                return -Math.Log(u) / lambda;
            }
        }
    }

    // Retry mechanism with backoff strategy
    public static T GetFromDataSource<T>(Func<T> dataSource, int maxRetries = 5, double initialDelay = 100, double delayMultiplier = 2)
    {
        for (int i = 0; i <= maxRetries; i++)
        {
            try
            {
                return dataSource();
            }
            catch (Exception ex)
            {
                if (i == maxRetries)
                    throw;
                System.Threading.Thread.Sleep((int)(initialDelay * Math.Pow(delayMultiplier, i)));
            }
        }

        return default(T);
    }
}
