NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU(int N, unsigned int seed) {
    if (N <= 0) {
        return NULL; // Handle invalid input size
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        return NULL; // Memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_info.RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].rx_info.RNTI = rand() % 65535; // Random RNTI
        pdu_list[i].crc_indication.CRC_INDICATION_REL8_TAG = i + 1;
        pdu_list[i].crc_indication.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    }

    return pdu_list;
}

int verify_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int N) {
    if (!pdu_list || N <= 0) {
        return -1; // Invalid input
    }

    for (int i = 0; i < N; i++) {
        if (pdu_list[i].rx_info.RX_UE_INFORMATION_TAG <= 0 ||
            pdu_list[i].rx_info.RNTI > 65535 ||
            pdu_list[i].crc_indication.CRC_INDICATION_REL8_TAG <= 0) {
            return -1; // Invalid data found
        }
    }

    return 0; // Verification successful
}

