    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_event_list(EventList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->eventType);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        list->events = realloc(list->events, new_capacity * sizeof(NetworkEvent *));
        list->capacity = new_capacity;
    }
    list->events[list->count++] = event;
    pthread_mutex_unlock(&list->lock);
}

void delete_event(EventList *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index < list->count) {
        free(list->events[index]->eventType);
        free(list->events[index]);
        for (size_t i = index; i < list->count - 1; ++i) {
            list->events[i] = list->events[i + 1];
        }
        --list->count;
    }
    pthread_mutex_unlock(&list->lock);
}

NetworkEvent* get_event(EventList *list, size_t index) {
    NetworkEvent *event = NULL;
    pthread_mutex_lock(&list->lock);
    if (index < list->count) {
        event = list->events[index];
    }
    pthread_mutex_unlock(&list->lock);
    return event;
}

