int initialize_network_configs(NetworkInterfaceConfig **configs, int N, const char *ip_list[]) {
    *configs = malloc(N * sizeof(NetworkInterfaceConfig));
    if (*configs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

