        }

        // Check for duplicate IP addresses
        for (int j = 0; j < i; j++) {
            if (strcmp((*configs)[j].ip_address, (*configs)[i].ip_address) == 0) {
                printf("Duplicate IP address %s\n", (*configs)[i].ip_address);
                (*configs)[i].status = false;
            }
        }
    }

