import socket
import logging

# Setup basic configuration for logging
logging.basicConfig(level=logging.ERROR)

def resolve_hostnames_to_ips(csv_file):
    try:
        with open(csv_file, 'r') as file:
            hostnames = file.read().splitlines()

        ip_addresses = []
        for hostname in hostnames:
            if not hostname.strip():
                continue
            try:
                ip_address = socket.gethostbyname(hostname)
                ip_addresses.append((hostname, ip_address))
            except socket.gaierror:
                logging.error(f"Could not resolve hostname: {hostname}")

        if not ip_addresses:
            return "No valid IP addresses resolved."

        return ip_addresses

    except FileNotFoundError:
        logging.error("File not found")
        return "Error: File does not exist"
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        return "An unexpected error occurred"

# Example usage
csv_file = 'hostnames.csv'
result = resolve_hostnames_to_ips(csv_file)
print(result)
