import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class NetworkClient {
    private static final String SERVER_ADDRESS = "remote.server.com";
    private static final int SERVER_PORT = 12345;
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public static void sendNetworkData(NFAPI_CRC_INDICATION_PDU_T[] data) throws IOException, InterruptedException {
        Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT);
        ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
        out.writeObject(data);
        out.flush();
        ObjectInputStream in = new ObjectInputStream(socket.getInputStream());
        boolean success = (boolean) in.readObject();
        socket.close();

        if (!success) {
            retrySendNetworkData(data, 3);
        }
    }

    private static void retrySendNetworkData(NFAPI_CRC_INDICATION_PDU_T[] data, int retries) throws IOException, InterruptedException {
        for (int i = 0; i < retries; i++) {
            try {
                sendNetworkData(data);
                return;
            } catch (IOException e) {
                if (i == retries - 1) throw e;
                Thread.sleep((long) Math.pow(2, i) * 100); // Exponential backoff
            }
        }
    }

