public class RandomValueGenerator
{
    private Random _random;
    private int _min;
    private int _max;
    private Dictionary<int, bool> _subRanges;

    public RandomValueGenerator(int min, int max)
    {
        SetRange(min, max);
        _random = new Random();
        _subRanges = new Dictionary<int, bool>();
    }

    public void SetRange(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Min value cannot be greater than max value.");
        _min = min;
        _max = max;
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_max - _min + 1) + _min;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_min, _max);
    }

    public void ResetGenerator(int seed)
    {
        _random = new Random(seed);
    }

    public bool IsInRange(int value)
    {
        return value >= _min && value < _max;
    }

    public void AddSubRange(int start, int end)
    {
        if (start < _min || end > _max || start > end)
            throw new ArgumentException("Invalid sub-range.");
        for (int i = start; i <= end; i++)
            _subRanges[i] = true;
    }

    public bool IsInSubRange(int value)
    {
        return _subRanges.ContainsKey(value);
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.Append($"Main Range: {_min}-{_max}");
        if (_subRanges.Count > 0)
            sb.Append(", Sub-Ranges: " + string.Join(", ", _subRanges.Keys));
        return sb.ToString();
    }
}
