    private float? checkRangeMax;
    private System.Random random;

    public void SetRange(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        minValue = min;
        maxValue = max;
        RecalculateRandomValue();
    }

    public void ResetGeneratorToSeed(int seed)
    {
        random = new System.Random(seed);
        RecalculateRandomValue();
    }

    private void RecalculateRandomValue()
    {
        RandomValue = random.NextFloat(minValue, maxValue);
    }

    public float GenerateRandomFloat(bool inclusiveMin = true, bool exclusiveMax = false)
    {
        return UnityEngine.Random.Range(inclusiveMin ? minValue : minValue + 0.001f, exclusiveMax ? maxValue - 0.001f : maxValue);
    }

    public int GenerateRandomInt(int min, int max, bool inclusiveMin = true, bool exclusiveMax = false)
    {
        return UnityEngine.Random.Range(inclusiveMin ? min : min + 1, exclusiveMax ? max - 1 : max);
    }

    public void SetCheckRange(float? subMin, float? subMax)
    {
        checkRangeMin = subMin;
        checkRangeMax = subMax;
    }

    public bool IsCurrentRandomValueInRange()
    {
        if (!checkRangeMin.HasValue || !checkRangeMax.HasValue) return true;
        return CurrentRandomValue >= checkRangeMin.Value && CurrentRandomValue <= checkRangeMax.Value;
    }

    public override string ToString()
    {
        var baseInfo = $"Range: {minValue} to {maxValue}";
        if (checkRangeMin.HasValue && checkRangeMax.HasValue)
            baseInfo += $", Check Range: {checkRangeMin.Value} to {checkRangeMax.Value}";
        return baseInfo;
    }

    private float RandomValue
    {
        get => random.NextFloat();
        set => RandomValue = value;
    }
}
