using System;
using UnityEngine;

public class EnhancedRandomValueGenerator : IDisposable
{
    private int _minValue;
    private int _maxValue;
    private Random _random;
    private object _lock = new object();

    public EnhancedRandomValueGenerator(int minValue, int maxValue)
    {
        SetRange(minValue, maxValue);
    }

    ~EnhancedRandomValueGenerator()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _random = null;
        }
    }

    public void SetRange(int minValue, int maxValue)
    {
        lock (_lock)
        {
            if (minValue > maxValue || minValue == maxValue)
                throw new ArgumentException("Invalid range");

            _minValue = minValue;
            _maxValue = maxValue;
            _random?.ReSeed(_random.Seed);
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            return UnityEngine.Random.Range(_minValue, _maxValue);
        }
    }

    public int GenerateRandomInt(bool includeMin, bool includeMax)
    {
        lock (_lock)
        {
            if (includeMin && includeMax)
                return UnityEngine.Random.Range(_minValue, _maxValue + 1);
            else if (includeMin && !includeMax)
                return UnityEngine.Random.Range(_minValue, _maxValue);
            else if (!includeMin && includeMax)
                return UnityEngine.Random.Range(_minValue + 1, _maxValue);
            else
                return UnityEngine.Random.Range(_minValue + 1, _maxValue - 1);
        }
    }

    public void ResetGenerator(int seed)
    {
        lock (_lock)
        {
            _random = new Random(seed);
        }
    }

    public bool IsCurrentRandomInRange(int subMin, int subMax)
    {
        lock (_lock)
        {
            return GenerateRandomInt(false, false) >= subMin && GenerateRandomInt(false, false) <= subMax;
        }
    }

    public override string ToString()
    {
        return $"Range: {_minValue}-{_maxValue}";
    }

    // Additional methods for distribution adjustments and management of multiple generators can be added here
}
