    void serializeToFile(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::out | std::ios::binary);
        if (!ofs.is_open()) throw std::runtime_error("Failed to open file for writing");

        z_stream stream;
        deflateInit(&stream, Z_DEFAULT_COMPRESSION);
        stream.next_in = reinterpret_cast<Bytef*>(dataset.data());
        stream.avail_in = dataset.size() * sizeof(int);
        stream.next_out = nullptr;
        stream.avail_out = 0;

        std::vector<char> compressedData(1024); // Initial buffer size
        do {
            stream.avail_out = compressedData.size();
            stream.next_out = reinterpret_cast<Bytef*>(compressedData.data());
            deflate(&stream, Z_FINISH);
            ofs.write(compressedData.data(), compressedData.size() - stream.avail_out);
            if (stream.avail_out == compressedData.size()) {
                compressedData.resize(compressedData.size() * 2); // Double the buffer size
            }
        } while (stream.avail_out == 0);

        deflateEnd(&stream);
    }

    void deserializeFromFile(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::in | std::ios::binary);
        if (!ifs.is_open()) throw std::runtime_error("Failed to open file for reading");

        z_stream stream;
        inflateInit(&stream);
        stream.next_in = nullptr;
        stream.avail_in = 0;

        std::vector<char> compressedData(1024); // Initial buffer size
        do {
            ifs.read(compressedData.data(), compressedData.size());
            int bytesRead = ifs.gcount();
            if (bytesRead == 0) break; // End of file

            stream.next_in = reinterpret_cast<Bytef*>(compressedData.data());
            stream.avail_in = bytesRead;
            std::vector<char> decompressedData(1024 * 1024); // Initial buffer size
            do {
                stream.avail_out = decompressedData.size();
                stream.next_out = reinterpret_cast<Bytef*>(decompressedData.data() + (decompressedData.size() - stream.avail_out));
                inflate(&stream, Z_NO_FLUSH);
                if (stream.avail_in == 0) break;
            } while (stream.avail_out == 0);

            int decompressedSize = decompressedData.size() - stream.avail_out;
            dataset.assign(reinterpret_cast<int*>(decompressedData.data()), reinterpret_cast<int*>(decompressedData.data()) + decompressedSize / sizeof(int));
        } while (true);

        inflateEnd(&stream);
    }

    double calculateMean() {
        if (dataset.empty()) return 0.0;
        int sum = std::accumulate(dataset.begin(), dataset.end(), 0);
        return static_cast<double>(sum) / dataset.size();
    }

