void populate_pdu_list(int N, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&mutex);
    if (pdu_count >= MAX_PDU_COUNT) {
        fprintf(stderr, "Error: Maximum PDU count exceeded.\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        int RNTI = generate_unique_RNTI();
        if (RNTI == -1) {
            fprintf(stderr, "Error: Failed to generate unique RNTI.\n");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = calculate_crc_tag(RX_UE_INFORMATION_TAG, RNTI);

        pdu_list[pdu_count++] = pdu;
    }
    pthread_mutex_unlock(&mutex);
}

void clear_pdu_list() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < pdu_count; i++) {
        free(pdu_list[i]);
    }
    pdu_count = 0;
    pthread_mutex_unlock(&mutex);
