        {
            throw new ArgumentException("Start time must be earlier than end time.");
        }
        _startTime = startTime;
        _endTime = endTime;
    }

    public void AddSample(DateTime timestamp, float dataPoint)
    {
        if (timestamp < _startTime || timestamp > _endTime)
        {
            throw new ArgumentOutOfRangeException(nameof(timestamp), "Timestamp is outside the processing window.");
        }
        _dataPoints[timestamp] = dataPoint;
    }

    public float GetAverageWithinWindow()
    {
        var validData = _dataPoints.Where(d => d.Key >= _startTime && d.Key <= _endTime);
        return validData.Any() ? validData.Average(d => d.Value) : 0.0f;
    }

