    public Dictionary<TimeSpan, (int Count, float Sum, float Average)> AggregateByInterval(TimeSpan interval)
    {
        var result = new Dictionary<TimeSpan, (int Count, float Sum, float Average)>();

        foreach (var timestamp in _dataPoints.Keys.Where(k => k >= _startTime && k <= _endTime))
        {
            var intervalKey = TimeSpan.FromTicks((timestamp.Ticks / interval.Ticks) * interval.Ticks);
            if (!result.ContainsKey(intervalKey))
            {
                result[intervalKey] = (0, 0.0f, 0.0f);
            }
            var dataPoint = _dataPoints[timestamp];
            var currentCount = result[intervalKey].Count;
            var currentSum = result[intervalKey].Sum;
            result[intervalKey] = (currentCount + 1, currentSum + dataPoint, (currentSum + dataPoint) / (currentCount + 1));
        }

        return result;
    }

    public void SetCustomWeights(Dictionary<DateTime, float> weights)
    {
        if (!weights.Values.All(w => w >= 0.0f))
        {
            throw new ArgumentException("Weights must be non-negative.");
        }
        var totalWeight = weights.Values.Sum();
