import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import java.io.*;
import java.security.SecureRandom;
import java.util.Base64;

public class FileEncryptor {
    private SecretKey key;
    private IvParameterSpec iv;

    public void init(String password) throws Exception {
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256, new SecureRandom());
        this.key = kg.generateKey();

        byte[] ivBytes = new byte[16];
        SecureRandom.getInstanceStrong().nextBytes(ivBytes);
        this.iv = new IvParameterSpec(ivBytes);

        // Store the IV securely
        storeIv(ivBytes);
    }

    public String encrypt(String filePath) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key, iv);

        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] inputBuffer = new byte[4096];
            ByteArrayOutputStream baos = new ByteArrayOutputStream();

            while (fis.read(inputBuffer) != -1) {
                byte[] outputBuffer = cipher.update(inputBuffer);
                if (outputBuffer != null) {
                    baos.write(outputBuffer);
                }
            }

            byte[] outputBuffer = cipher.doFinal();
            if (outputBuffer != null) {
                baos.write(outputBuffer);
            }

            return Base64.getEncoder().encodeToString(baos.toByteArray());
        }
    }

    public String decrypt(String encryptedFilePath, String ivPath) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, key, readIv(ivPath));

        try (FileInputStream fis = new FileInputStream(encryptedFilePath)) {
            byte[] inputBuffer = new byte[4096];
            ByteArrayOutputStream baos = new ByteArrayOutputStream();

            while (fis.read(inputBuffer) != -1) {
                byte[] outputBuffer = cipher.update(inputBuffer);
                if (outputBuffer != null) {
                    baos.write(outputBuffer);
                }
            }

            byte[] outputBuffer = cipher.doFinal();
            if (outputBuffer != null) {
                baos.write(outputBuffer);
            }

            return new String(baos.toByteArray());
        }
    }

    private IvParameterSpec readIv(String ivPath) throws Exception {
        try (FileInputStream fis = new FileInputStream(ivPath)) {
            byte[] ivBytes = new byte[16];
            fis.read(ivBytes);
            return new IvParameterSpec(ivBytes);
        }
    }

    private void storeIv(byte[] ivBytes) throws Exception {
        try (FileOutputStream fos = new FileOutputStream("iv.bin")) {
            fos.write(ivBytes);
        }
    }

    public static void main(String[] args) {
        FileEncryptor encryptor = new FileEncryptor();
        try {
            encryptor.init("your-password");
            String encrypted = encryptor.encrypt("path/to/large/file.txt");
            System.out.println("Encrypted: " + encrypted);
            String decrypted = encryptor.decrypt("path/to/encrypted/file.enc", "iv.bin");
            System.out.println("Decrypted: " + decrypted);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
