    if (packet == NULL) return NULL;

    packet->packet_id = id;
    packet->timestamp = time(NULL);
    packet->payload_size = size;
    packet->payload = (unsigned char *)malloc(size);
    if (packet->payload == NULL) {
        free(packet);
        return NULL;
    }

    // Initialize payload with some data (e.g., zero)
    for (size_t i = 0; i < size; i++) {
        packet->payload[i] = 0;
    }

    packet->next = NULL;
    return packet;
}

void append_packet(DataPacket **head, DataPacket *new_packet) {
    if (new_packet == NULL) return;

    new_packet->next = *head;
    *head = new_packet;
}

DataPacket* find_packet(DataPacket *head, int id) {
    while (head != NULL) {
        if (head->packet_id == id) {
            return head;
        }
        head = head->next;
    }
    return NULL;
}

void update_payload(DataPacket *packet, size_t new_size) {
    if (packet == NULL || packet->payload == NULL) return;

    unsigned char *new_payload = (unsigned char *)realloc(packet->payload, new_size);
    if (new_payload == NULL) return; // Handle error or return

    packet->payload = new_payload;
    packet->payload_size = new_size;

    // Initialize new part of payload with zero
    for (size_t i = 0; i < new_size - packet->payload_size; i++) {
        packet->payload[packet->payload_size + i] = 0;
    }
}

void free_packets(DataPacket **head) {
    DataPacket *current, *next;
    current = *head;

    while (current != NULL) {
        next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }

    *head = NULL;
}
