    public void sendData(NFAPI_CRC_INDICATION_PDU[] data, String serverAddress, int port) throws IOException {
        // Simulate sending data to a remote server
        try (Socket socket = new Socket(serverAddress, port)) {
            socket.setSoTimeout(5000);
            // Send data logic here
        } catch (SocketTimeoutException e) {
            retrySendData(data, serverAddress, port);
        }
    }

    private void retrySendData(NFAPI_CRC_INDICATION_PDU[] data, String serverAddress, int port) {
        for (int i = 0; i < 5; ++i) {
            try {
                sendData(data, serverAddress, port);
                return;
            } catch (IOException e) {
                // Exponential backoff
                try {
                    Thread.sleep((long) Math.pow(2, i) * 100);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

