FrameList* create_frame_list() {
    FrameList* list = (FrameList*)malloc(sizeof(FrameList));
    list->frames = (NFAPI_RX_FRAME_PDU_T**)calloc(MAX_FRAMES, sizeof(NFAPI_RX_FRAME_PDU_T*));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_frame(FrameList* list, NFAPI_RX_FRAME_PDU_T* frame) {
    pthread_mutex_lock(&list->lock);
    if (list->size < MAX_FRAMES && find_frame_by_rnti(list, frame->RNTI) == -1) {
        list->frames[list->size++] = frame;
    } else {
        // Handle error: max frames reached or RNTI already exists
    }
    pthread_mutex_unlock(&list->lock);
}

int find_frame_by_rnti(FrameList* list, int rnti) {
    for (int i = 0; i < list->size; i++) {
        if (list->frames[i]->RNTI == rnti) return i;
    }
    return -1;
}

void free_frame_list(FrameList* list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        free(list->frames[i]);
    }
    free(list->frames);
    free(list);
    pthread_mutex_unlock(&list->lock);
}
