    private static final String THRESHOLD = "-t";
    private static final String LOAD_BALANCE = "-l";

    public static void main(String[] args) {
        if (args.length < 2) {
            printHelp();
            return;
        }

        String filePath = args[0];
        Set<String> options = new HashSet<>(Arrays.asList(args).subList(1, args.length));

        try {
            List<FinancialTransaction> transactions = readTransactions(filePath);

            if (options.contains(HELP)) {
                printHelp();
            } else if (options.contains(STATS)) {
                generateSummaryReport(transactions);
            } else if (options.contains(DETAILS)) {
                outputDetailedMetrics(transactions);
            } else if (options.contains(THRESHOLD) && options.contains("--threshold")) {
                double threshold = Double.parseDouble(options.stream()
                        .filter(o -> o.startsWith("--threshold="))
                        .map(s -> s.substring("--threshold=".length()))
                        .findFirst()
                        .orElse("0"));
                filterAndOutputTransactions(transactions, threshold);
            } else if (options.contains(LOAD_BALANCE)) {
                distributeProcessing(transactions);
            }
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

    private static void printHelp() {
