    }

    private static List<FinancialTransaction> readTransactions(String filePath) throws IOException {
        List<FinancialTransaction> transactions = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                // Parse each transaction line and add to the list
                FinancialTransaction transaction = parseTransaction(line);
                transactions.add(transaction);
            }
        }
        return transactions;
    }

