    }

    private static void outputDetailedMetrics(List<FinancialTransaction> transactions) {
        // Output detailed metrics
    }

    private static void filterAndOutputTransactions(List<FinancialTransaction> transactions, double threshold) {
        List<FinancialTransaction> filteredTransactions = transactions.stream()
                .filter(t -> t.getAmount() > threshold)
                .collect(Collectors.toList());
        outputDetailedMetrics(filteredTransactions);
    }

    private static void distributeProcessing(List<FinancialTransaction> transactions) {
        int numThreads = Runtime.getRuntime().availableProcessors();
        ExecutorService executor = Executors.newFixedThreadPool(numThreads);

        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < numThreads; i++) {
            int partitionSize = transactions.size() / numThreads;
            if (i == numThreads - 1) {
                partitionSize += transactions.size() % numThreads;
            }
            List<FinancialTransaction> partition = transactions.subList(i * partitionSize, (i + 1) * partitionSize);
            futures.add(executor.submit(() -> processPartition(partition)));
        }

        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Error processing partition: " + e.getMessage());
            }
        }

        executor.shutdown();
    }

    private static void processPartition(List<FinancialTransaction> partition) {
