using System;
using System.Diagnostics;
using System.Linq;
using System.Net.NetworkInformation;
using System.Numerics;
using System.Text;

public class SecureValueGenerator
{
    private double minValue;
    private double maxValue;
    private string domainName;

    public SecureValueGenerator(double minValue, double maxValue, string domainName)
    {
        SetRange(minValue, maxValue);
        this.domainName = GetIPAddress(domainName);
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(GenerateRandomFloat());
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble()),
            (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble())
        );
    }

    public void SetRange(double minValue, double maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    private string GetIPAddress(string domainName)
    {
        try
        {
            IPHostEntry hostEntry = Dns.GetHostEntry(domainName);
            return hostEntry.AddressList.FirstOrDefault()?.ToString() ?? "";
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"DNS resolution failed for {domainName}: {ex.Message}");
            return "";
        }
    }

    public override string ToString()
    {
        return $"Current Range: [{minValue}, {maxValue}], Domain IP: {domainName}";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate >= endDate)
        {
            throw new ArgumentException("Start date must be earlier than end date.");
        }
        Random random = new Random();
        return startDate.AddTicks(random.Next(startDate.Ticks, endDate.Ticks));
    }
}
