using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;

    public DynamicValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat() => (float)(new Random().NextDouble() * (maxValue - minValue) + minValue);
    public int GenerateRandomInt() => (int)Math.Round(new Random().NextDouble() * (maxValue - minValue));
    public double GenerateRandomDouble() => new Random().NextDouble() * (maxValue - minValue);

    public void AdjustRange(double newMin, double newMax)
    {
        if (newMin < minValue || newMax > maxValue) throw new InvalidOperationException("New range must be within current range.");
        minValue = newMin;
        maxValue = newMax;
    }

    public Vector3 GenerateRandomVector3() => new Vector3((float)GenerateRandomDouble(), (float)GenerateRandomDouble(), (float)GenerateRandomDouble());

    public Quaternion GenerateRandomQuaternion()
    {
        var x = (float)GenerateRandomDouble();
        var y = (float)GenerateRandomDouble();
        var z = (float)GenerateRandomDouble();
        return new Quaternion(x, y, z, 1);
    }

    public override string ToString() => $"Range: {minValue} to {maxValue}";
}

