MemoryPool *create_memory_pool(size_t initial_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->pool = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->pool_size = initial_size;
    pool->pool_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_pdu(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->pool_index >= pool->pool_size) {
        size_t new_size = pool->pool_size ? pool->pool_size * 2 : 1;
        pool->pool = realloc(pool->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->pool_size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pool[pool->pool_index++];
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

