using System;

public class DynamicRangeManager
{
    private double minValue;
    private double maxValue;

    public DynamicRangeManager(double initialMinValue, double initialMaxValue)
    {
        SetRange(initialMinValue, initialMaxValue);
    }

    private void SetRange(double newMinValue, double newMaxValue)
    {
        if (newMinValue <= newMaxValue)
        {
            minValue = newMinValue;
            maxValue = newMaxValue;
        }
        else
        {
            throw new ArgumentException("minValue must be less than or equal to maxValue");
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public int GenerateRandomInt()
    {
        return (int)Math.Round(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public UnityEngine.Vector3 GenerateRandomVector3()
    {
        return new UnityEngine.Vector3(GenerateRandomFloat(), GenerateRandomFloat(), GenerateRandomFloat());
    }

    public override string ToString()
    {
        return $"Current range: {minValue} to {maxValue}, Type: float";
    }

    public DateTime GenerateRandomDateTime(DateTime startDate, DateTime endDate)
    {
        if (startDate > endDate)
        {
            throw new ArgumentException("StartDate must be less than or equal to EndDate");
        }
        TimeSpan difference = endDate - startDate;
        TimeSpan randomTimeSpan = new TimeSpan(Random.Shared.Next((int)difference.TotalMilliseconds));
        return startDate + randomTimeSpan;
    }
}
