import java.util.Random;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class ServiceManager {
    private static final int MAX_PDU_COUNT = 1000;
    private static final String DB_URL = "jdbc:mysql://localhost:3306/service_db";
    private static final String USER = "username";
    private static final String PASS = "password";

    public void startAndStopService() {
        Random random = new Random();
        int delay = random.nextInt(10) + 1; // Random delay between 1 to 10 seconds
        try {
            Thread.sleep(delay * 1000);
            stopService();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private void stopService() {
        Connection conn = null;
        PreparedStatement pstmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, USER, PASS);
            String sql = "INSERT INTO service_log (start_time, end_time, messages_sent) VALUES (?, ?, ?)";
            pstmt = conn.prepareStatement(sql);
            pstmt.setTimestamp(1, new Timestamp(System.currentTimeMillis()));
            pstmt.setTimestamp(2, new Timestamp(System.currentTimeMillis()));
            pstmt.setInt(3, 5); // Example number of messages sent
            pstmt.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                if (pstmt != null) pstmt.close();
                if (conn != null) conn.close();
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager();
        while (true) {
            serviceManager.startAndStopService();
        }
    }
}
