#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void createAndPopulatePDUs(uint32_t ueInfoTag, uint16_t maxRnti, NFAPI_CRC_INDICATION_PDU_T** pdus, int* count) {
    *count = 0;
    if (ueInfoTag >= maxRnti) {
        printf("Invalid RX_UE_INFORMATION_TAG\n");
        return;
    }
    *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    uint16_t rnti = ueInfoTag + 1;
    for (; rnti < maxRnti; rnti++) {
        if (*count >= MAX_PDU_COUNT - 1) break;
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = ueInfoTag;
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = calculateCrcFlag(ueInfoTag, rnti);
        (*pdus)[*count] = pdu;
        *count += 1;
    }
}

uint8_t calculateCrcFlag(uint32_t rxUeInfoTag, uint16_t rnti) {
    uint64_t value = (uint64_t)rxUeInfoTag << 32 | rnti;
    uint8_t crcFlag = 0;
    while (value != 0) {
        crcFlag += (value & 1);
        value >>= 1;
    }
    return crcFlag;
}

void freePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int count) {
    if (pdus != NULL) {
        free(pdus);
    }
}
