using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using UnityEngine;

[Serializable]
public class RandomConfigManager
{
    private Dictionary<string, Distribution> parameters = new Dictionary<string, Distribution>();
    private static readonly object lockObject = new object();

    public void AddParameter(string name, float min, float max, DistributionType distributionType)
    {
        lock (lockObject)
        {
            if (!parameters.ContainsKey(name))
            {
                parameters[name] = new Distribution(min, max, distributionType);
            }
        }
    }

    public int GetRandomInt(string name)
    {
        lock (lockObject)
        {
            if (parameters.TryGetValue(name, out var distribution) && distribution.Type == DistributionType.Uniform)
            {
                return UnityEngine.Random.Range((int)distribution.Min, (int)distribution.Max + 1);
            }
            throw new InvalidOperationException("Invalid distribution type for integer parameter.");
        }
    }

    public float GetRandomFloat(string name)
    {
        lock (lockObject)
        {
            if (parameters.TryGetValue(name, out var distribution))
            {
                return distribution.Type == DistributionType.Uniform
                    ? UnityEngine.Random.Range((float)distribution.Min, (float)distribution.Max)
                    : UnityEngine.Random.value * (float)distribution.StdDev + (float)distribution.Mean;
            }
            throw new InvalidOperationException("Invalid distribution type for float parameter.");
        }
    }

    public double GetRandomDouble(string name)
    {
        lock (lockObject)
        {
            if (parameters.TryGetValue(name, out var distribution))
            {
                return distribution.Type == DistributionType.Uniform
                    ? UnityEngine.Random.Range((double)distribution.Min, (double)distribution.Max)
                    : UnityEngine.Random.value * distribution.StdDev + distribution.Mean;
            }
            throw new InvalidOperationException("Invalid distribution type for double parameter.");
        }
    }

    public Vector3 GetRandomVector(string name)
    {
        lock (lockObject)
        {
            if (parameters.TryGetValue(name, out var distribution))
            {
                return UnityEngine.Random.insideUnitSphere * (float)distribution.Max;
            }
            throw new InvalidOperationException("Invalid distribution type for vector parameter.");
        }
    }

    public Quaternion GetRandomQuaternion(string name)
    {
        lock (lockObject)
        {
            if (parameters.TryGetValue(name, out var distribution))
            {
                return UnityEngine.Random.rotation;
            }
            throw new InvalidOperationException("Invalid distribution type for quaternion parameter.");
        }
    }

    public byte[] Serialize()
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream stream = new MemoryStream())
        {
            formatter.Serialize(stream, this);
            return stream.ToArray();
        }
    }

    public static RandomConfigManager Deserialize(byte[] data)
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream stream = new MemoryStream(data))
        {
            return (RandomConfigManager)formatter.Deserialize(stream);
        }
    }

    public override string ToString()
    {
        lock (lockObject)
        {
            return $"Parameters: {string.Join(", ", parameters)}";
        }
    }

    [Serializable]
    private class Distribution
    {
        public object Min { get; set; }
        public object Max { get; set; }
        public double Mean { get; set; } = 0;
        public double StdDev { get; set; } = 1;
        public DistributionType Type { get; set; }

        public Distribution(object min, object max, DistributionType type)
        {
            Min = min;
            Max = max;
            Type = type;
        }
    }

    public enum DistributionType
    {
        Uniform,
        Normal
    }
}
