class DataStreamProcessor {
public:
    // Define a generic data type for sensor readings
    struct SensorReading {
        std::string source;
        double value;
        // Add other fields as needed
    };

    // Define a transformation function type
    using Transformation = std::function<double(double)>;

private:
    std::vector<std::thread> ingestionThreads;
    std::vector<std::thread> processingThreads;
    std::mutex queueMutex;
    std::condition_variable dataReadyCondition;
    std::queue<SensorReading> incomingDataQueue;
    std::vector<Transformation> transformations;
    bool running;

public:
    DataStreamProcessor(size_t numIngestionThreads, size_t numProcessingThreads) : running(true) {
        // Initialize ingestion threads
        for (size_t i = 0; i < numIngestionThreads; ++i) {
            ingestionThreads.emplace_back(&DataStreamProcessor::ingestData, this);
        }

        // Initialize processing threads
        for (size_t i = 0; i < numProcessingThreads; ++i) {
            processingThreads.emplace_back(&DataStreamProcessor::processData, this);
        }
    }

    ~DataStreamProcessor() {
        running = false;
        dataReadyCondition.notify_all();
        for (auto& thread : ingestionThreads) {
            if (thread.joinable()) thread.join();
        }
        for (auto& thread : processingThreads) {
            if (thread.joinable()) thread.join();
        }
    }

    void addTransformation(Transformation transformation) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transformations.push_back(transformation);
    }

    void ingestData() {
        // Simulate data ingestion
        while (running) {
            SensorReading reading;
            // Populate reading from sensor
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                incomingDataQueue.push(reading);
            }
            dataReadyCondition.notify_one();
        }
    }

    void processData() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataReadyCondition.wait(lock, [this] { return !incomingDataQueue.empty() || !running; });
            if (!running && incomingDataQueue.empty()) break;
            SensorReading reading = incomingDataQueue.front();
            incomingDataQueue.pop();
            lock.unlock();

            // Apply transformations
            double transformedValue = reading.value;
            for (const auto& transformation : transformations) {
                transformedValue = transformation(transformedValue);
            }

            // Process the transformed data
            // ...
        }
    }

    void generateReport() {
        // Generate a report based on performance metrics
        // ...
    }
};

int main() {
    DataStreamProcessor processor(4, 4);

    // Add transformations to the pipeline
    processor.addTransformation([](double value) { return value * 0.9; }); // Example transformation

    // Simulate adding more data sources and processing stages as needed

    return 0;
