import json
import threading

class FileProcessor:
    def __init__(self):
        self.lock = threading.Lock()

    def deserialize_json(self, json_str):
        with self.lock:
            try:
                data = json.loads(json_str)
                if not isinstance(data, list):
                    raise ValueError("Invalid JSON format")
                return [dict(item) for item in data]
            except json.JSONDecodeError as e:
                raise ValueError(f"JSON decode error: {e}")

    def serialize_json(self, data):
        with self.lock:
            try:
                return json.dumps(data)
            except (TypeError, OverflowError) as e:
                raise ValueError(f"Serialization error: {e}")

# Example usage
if __name__ == "__main__":
    processor = FileProcessor()
    records = generate_file_records(10)
    json_str = processor.serialize_json(records)
    print("Serialized JSON:", json_str)

    deserialized_records = processor.deserialize_json(json_str)
    print("Deserialized Records:", deserialized_records)
