#include <pthread.h>
#include <time.h>

typedef struct {
    int file_id;
    time_t timestamp;
    char status_flag;
} FILE_PROCESS_RECORD;

FILE_PROCESS_RECORD* generate_records(int n) {
    FILE_PROCESS_RECORD* records = (FILE_PROCESS_RECORD*)malloc(n * sizeof(FILE_PROCESS_RECORD));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&mutex);
        records[i].file_id = i + 1;
        records[i].timestamp = time(NULL);
        records[i].status_flag = 'A';
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return records;
}
