    private readonly object lockObject = new object();

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void UpdateMaxValue(int newValue)
    {
        lock (lockObject)
        {
            if (newValue < minValue)
            {
                throw new ArgumentException("New max value cannot be less than current min value.");
            }
            maxValue = newValue;
        }
    }

    public int GenerateRandomInteger()
    {
        lock (lockObject)
        {
            Random random = new Random();
            return random.Next(minValue, maxValue + 1);
        }
    }

    public double GenerateRandomFloat()
    {
        lock (lockObject)
        {
            Random random = new Random();
            return random.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
