['```csharp
using System;
using System.Collections.Concurrent;

public class DynamicValueGenerator
{
    private int minValue;
    private int maxValue;
    private ConcurrentDictionary<int, Random> randomCache = new ConcurrentDictionary<int, Random>();

    public DynamicValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void UpdateMaxValue(int newValue)
    {
        if (newValue < minValue)
            throw new ArgumentException("New max value must not be less than current min value.");

        Interlocked.Exchange(ref maxValue, newValue);
    }

    public float GenerateRandomFloat()
    {
        Random random = GetOrCreateRandom(minValue, maxValue);
        return (float)random.NextDouble() * (maxValue - minValue + 1) + minValue;
    }

    public int GenerateRandomInt()
    {
        Random random = GetOrCreateRandom(minValue, maxValue);
        return random.Next(minValue, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }

    private Random GetOrCreateRandom(int min, int max)
    {
        var key = min * 397 ^ max;
        if (randomCache.TryGetValue(key, out Random random))
            return random;

        randomCache.TryAdd(key, new Random());
        return randomCache[key];
    }
}
