#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PDU_COUNT 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* PDUs[MAX_PDU_COUNT];
    int count;
    pthread_mutex_t mutex;
} PDU_LIST_T;

pthread_mutex_t global_config_mutex = PTHREAD_MUTEX_INITIALIZER;
PDU_LIST_T pdu_list = {0};

void init_pdu_list() {
    pthread_mutex_init(&pdu_list.mutex, NULL);
}

int create_pdu(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&global_config_mutex);

    if (pdu_list.count >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&global_config_mutex);
        return -1; // Maximum PDU count reached
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&global_config_mutex);
        return -2; // Memory allocation failed
    }

    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;

    uint32_t concatenated_value = (RX_UE_INFORMATION_TAG << 16) | RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = (concatenated_value & 0xFF); // Simple checksum for demonstration

    pthread_mutex_lock(&pdu_list.mutex);
    pdu_list.PDUs[pdu_list.count++] = new_pdu;
    pthread_mutex_unlock(&pdu_list.mutex);

    return 0; // Success
}

void free_pdu_list() {
    for (int i = 0; i < pdu_list.count; i++) {
        free(pdu_list.PDUs[i]);
    }
    pthread_mutex_destroy(&pdu_list.mutex);
}
