    unsigned short rnti;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDU_COUNT];
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PDUList;

void initialize_pdulist(PDUList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroy_pdulist(PDUList *list) {
    for (int i = 0; i < list->count; ++i) {
        free(list->pdus[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rx_ue_info_tag, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->rx_ue_info_tag = rx_ue_info_tag;
    pdu->rnti = rnti;
    // Initialize CRC flag based on rolling checksum algorithm
    pdu->crc_flag = calculate_crc_flag(rx_ue_info_tag, rnti);
    return pdu;
}

void add_pdu(PDUList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->count >= MAX_PDU_COUNT) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    list->pdus[list->count++] = pdu;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

void* pdu_creation_thread(void *arg) {
    PDUList *list = (PDUList *)arg;
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        unsigned short rnti = generate_unique_rnti();
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(i, rnti);
        if (!pdu) {
            // Handle error
            continue;
        }
        add_pdu(list, pdu);
    }
    return NULL;
}

void run_pdu_creation_system(PDUList *list) {
    pthread_t threads[MAX_PDU_COUNT];
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        pthread_create(&threads[i], NULL, pdu_creation_thread, list);
    }
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }
}

