['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_MEMORY_RESERVATION 1024 * 1024 * 1024 // 1 GB
#define MAX_THREADS 100

typedef struct {
    int chunkID;
    void* data;
    size_t size;
} DataChunk;

typedef struct {
    pthread_mutex_t lock;
    sem_t available_chunks;
    DataChunk** chunks;
    size_t capacity;
    size_t count;
    size_t reserved_memory;
    int max_threads;
} MemoryManager;

MemoryManager* createMemoryManager(int max_threads) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&manager->available_chunks, 0, MAX_THREADS);
    manager->chunks = (DataChunk**)malloc(max_threads * sizeof(DataChunk*));
    manager->capacity = max_threads;
    manager->count = 0;
    manager->reserved_memory = 0;
    manager->max_threads = max_threads;
    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->chunks[i]->data);
        free(manager->chunks[i]);
    }
    free(manager->chunks);
    sem_destroy(&manager->available_chunks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int allocateMemory(MemoryManager* manager, int chunkID, size_t size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->reserved_memory + size > MAX_MEMORY_RESERVATION) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory reservation exceeded
    }
    DataChunk* chunk = (DataChunk*)malloc(sizeof(DataChunk));
    chunk->chunkID = chunkID;
    chunk->data = malloc(size);
    chunk->size = size;
    manager->chunks[manager->count++] = chunk;
    manager->reserved_memory += size;
    sem_post(&manager->available_chunks);
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void deallocateMemory(MemoryManager* manager, int chunkID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->chunks[i]->chunkID == chunkID) {
            free(manager->chunks[i]->data);
            free(manager->chunks[i]);
            manager->reserved_memory -= manager->chunks[i]->size;
            memmove(&manager->chunks[i], &manager->chunks[i + 1], (manager->count - i - 1) * sizeof(DataChunk*));
            --manager->count;
            sem_post(&manager->available_chunks);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void* processData(void* arg) {
    MemoryManager* manager = (MemoryManager*)arg;
    int chunkID;
    while ((chunkID = sem_wait(&manager->available_chunks)) != -1) {
        // Process data for chunkID
        printf("Processing chunk %d\n", chunkID);
        allocateMemory(manager, chunkID + 1, 1024); // Example allocation
        deallocateMemory(manager, chunkID);
    }
    return NULL;
}

int main() {
    MemoryManager* manager = createMemoryManager(MAX_THREADS);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, processData, manager);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroyMemoryManager(manager);
    return 0;
}
```

