    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println(USAGE);
            return;
        }

        boolean summary = false;
        boolean detailedMetrics = false;
        double threshold = Double.MAX_VALUE;
        boolean loadBalancing = false;

        for (String arg : args) {
            switch (arg) {
                case "-s":
                    summary = true;
                    break;
                case "-d":
                    detailedMetrics = true;
                    break;
                case "-t:<threshold>":
                    String[] parts = arg.split(":");
                    if (parts.length == 2 && !parts[1].isEmpty()) {
                        threshold = Double.parseDouble(parts[1]);
                    } else {
                        System.err.println("Invalid threshold format. Use -t:<threshold>");
                        return;
                    }
                    break;
                case "-l":
                    loadBalancing = true;
                    break;
                default:
                    System.err.println("Unknown option: " + arg);
                    System.err.println(USAGE);
                    return;
