#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    int transaction_id;
    double amount;
    char currency[3];
    char card_info[20];
} Transaction;

typedef struct {
    Transaction *queue;
    int front, rear, size;
    sem_t mutex, empty, full;
} Queue;

void initQueue(Queue *q, int size) {
    q->queue = (Transaction *)malloc(size * sizeof(Transaction));
    q->front = q->rear = -1;
    q->size = size;
    sem_init(&q->mutex, 0, 1);
    sem_init(&q->empty, 0, size);
    sem_init(&q->full, 0, 0);
}

void enqueue(Queue *q, Transaction item) {
    sem_wait(&q->empty);
    sem_wait(&q->mutex);
    if (q->rear == q->size - 1) {
        q->rear = -1;
    }
    if (q->front == -1) {
        q->front = 0;
    }
    q->queue[++q->rear] = item;
    sem_post(&q->mutex);
    sem_post(&q->full);
}

Transaction dequeue(Queue *q) {
    Transaction item;
    sem_wait(&q->full);
    sem_wait(&q->mutex);
    if (q->front == -1) {
        q->front = q->rear = 0;
    }
    item = q->queue[q->front++];
    if (q->front > q->rear) {
        q->front = q->rear = -1;
    }
    sem_post(&q->mutex);
    sem_post(&q->empty);
    return item;
}

void destroyQueue(Queue *q) {
    free(q->queue);
    sem_destroy(&q->mutex);
    sem_destroy(&q->empty);
    sem_destroy(&q->full);
}
