void print_usage() {
    printf("Usage: program [-h] [-m] [-c] [-o] [-s] [-d] [-t threshold]\n");
    printf("Options:\n");
    printf("  -h, --help         Show this help message\n");
    printf("  -m, --mode mode    Specify the operation mode (default: read)\n");
    printf("  -c, --count        Count lines in input file\n");
    printf("  -o, --output file  Output results to a specified file\n");
    printf("  -s, --summary      Output summary report of the input file\n");
    printf("  -d, --details      Output detailed metrics for each line\n");
    printf("  -t, --threshold N  Filter lines with word count >= N\n");
}

int main(int argc, char *argv[]) {
    int opt;
    char *input_file = NULL;
    char mode = 'r';
    int summary = 0;
    int details = 0;
    int threshold = -1;

    while ((opt = getopt(argc, argv, ":h:m:c:o:sdt:")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                exit(0);
            case 'm':
                mode = optarg[0];
                break;
            case 'c':
                printf("Counting lines in input file...\n");
                // Implement line counting logic
                break;
            case 'o':
                output_file = optarg;
                break;
            case 's':
                summary = 1;
                break;
            case 'd':
                details = 1;
                break;
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0) {
                    fprintf(stderr, "Threshold must be a non-negative integer\n");
                    exit(1);
                }
                break;
            default:
                print_usage();
                exit(1);
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    }

    if (!input_file) {
        print_usage();
        printf("No input file provided. Use -h for help.\n");
        exit(1);
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Failed to open input file");
        exit(1);
    }

    // Implement file processing logic based on mode and options
    // ...

    fclose(file);

    return 0;
}
