using System;
using System.IO;

public class SecureFileProcessor
{
    private int _minValue;
    private int _maxValue;

    public SecureFileProcessor(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than max value.");
        }
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _minValue + (float)(new Random().NextDouble() * (_maxValue - _minValue));
    }

    public int GenerateRandomInt()
    {
        while (true)
        {
            int randomValue = new Random().Next(_minValue, _maxValue + 1);
            if (randomValue % 5 == 0)
                return randomValue;
        }
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(double shrinkFactor)
    {
        _minValue = (int)(_minValue * shrinkFactor);
        _maxValue = (int)(_maxValue * shrinkFactor);
    }

    public void ExpandRange(double expandFactor)
    {
        _minValue = (int)(_minValue / expandFactor);
        _maxValue = (int)(_maxValue / expandFactor);
    }
}
