using System;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Numerics;
using System.Threading.Tasks;
using Microsoft.AspNet.Identity.EntityFramework;

public class DynamicAccountAndValueManager
{
    private double minValue;
    private double maxValue;

    public DynamicAccountAndValueManager(double initialValue)
    {
        SetRange(initialValue, initialValue);
    }

    private void SetRange(double min, double max)
    {
        if (min < 0 || max < 0 || min > max)
        {
            throw new ArgumentException("Invalid range values.");
        }
        minValue = min;
        maxValue = max;
    }

    public float GenerateRandomFloat()
    {
        return (float)(RandomNumberGenerator.GetRandomBytes(4)[0] / 256.0);
    }

    public int GenerateRandomInt()
    {
        byte[] randomBytes = new byte[4];
        RandomNumberGenerator.GetBytes(randomBytes);
        int result = BitConverter.ToInt32(randomBytes, 0);
        return (int)(result * (maxValue - minValue) / uint.MaxValue + minValue);
    }

    public Vector3 GenerateRandomVector3()
    {
        return new Vector3(
            GenerateRandomFloat(),
            GenerateRandomFloat(),
            GenerateRandomFloat()
        );
    }

    public void AdjustRange(double newMin, double newMax)
    {
        SetRange(newMin, newMax);
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}, Generated Type: Vector3";
    }
}
