#include <stdlib.h>
#include <time.h>

typedef struct {
    int file_id;
    time_t timestamp;
    int status_flag;
} FILE_PROCESS_RECORD;

FILE_PROCESS_RECORD* generate_file_records(int N) {
    FILE_PROCESS_RECORD* records = (FILE_PROCESS_RECORD*)malloc(N * sizeof(FILE_PROCESS_RECORD));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }
    srand(time(NULL)); // Seed the random number generator for thread safety
    for (int i = 0; i < N; ++i) {
        records[i].file_id = rand() % 1000;
        records[i].timestamp = time(NULL);
        records[i].status_flag = rand() % 2; // Random status flag: 0 or 1
    }
    return records;
}

void free_file_records(FILE_PROCESS_RECORD* records, int N) {
    free(records); // Free the allocated memory
}
