    printf("Filesystem ID: %d\n", record->FILESYSTEM_ID);
    printf("Total Space: %lld bytes\n", record->TOTAL_SPACE);
    printf("Used Space: %lld bytes\n", record->USED_SPACE);
    printf("Available Space: %lld bytes\n", record->AVAIL_SPACE);
    printf("Percentage Used: %.2f%%\n", ((double)record->USED_SPACE / record->TOTAL_SPACE) * 100.0);
}

void free_file_system_record(FILE_SYSTEM_USAGE_RECORD *record) {
    free(record);
