#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    uint32_t RNTI;
    bool CRCFLAG;
} CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* buffer;
    size_t block_size;
    size_t num_blocks;
    size_t free_block_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

CRC_INDICATION_PDU_T** entries;
size_t num_entries;
pthread_mutex_t entries_lock;

void init_memory_pool(size_t initial_size) {
    pool.buffer = malloc(initial_size * sizeof(CRC_INDICATION_PDU_T));
    pool.block_size = sizeof(CRC_INDICATION_PDU_T);
    pool.num_blocks = initial_size;
    pool.free_block_count = initial_size;
    pthread_mutex_init(&pool.lock, NULL);
}

void* allocate_memory() {
    pthread_mutex_lock(&pool.lock);
    if (pool.free_block_count == 0) {
        // Resize the memory pool
        pool.buffer = realloc(pool.buffer, pool.num_blocks * 2 * sizeof(CRC_INDICATION_PDU_T));
        pool.block_size = sizeof(CRC_INDICATION_PDU_T);
        pool.num_blocks *= 2;
        pool.free_block_count = pool.num_blocks - pool.free_block_count;
    }
    void* block = pool.buffer + (pool.num_blocks - pool.free_block_count) * pool.block_size;
    pool.free_block_count--;
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void free_memory(void* block) {
    pthread_mutex_lock(&pool.lock);
    size_t index = ((char*)block - (char*)pool.buffer) / pool.block_size;
    pool.buffer[index * pool.block_size] = 0; // Mark as unused
    pool.free_block_count++;
    pthread_mutex_unlock(&pool.lock);
}

void init_entries() {
    entries = malloc(MAX_ENTRIES * sizeof(CRC_INDICATION_PDU_T*));
    num_entries = 0;
    pthread_mutex_init(&entries_lock, NULL);
}

void add_entry(uint32_t RNTI, bool CRCFLAG) {
    pthread_mutex_lock(&entries_lock);
    for (size_t i = 0; i < num_entries; i++) {
        if (entries[i]->RNTI == RNTI) {
            free_memory(entries[i]);
            entries[i] = NULL;
        }
    }

    entries[num_entries] = allocate_memory();
    entries[num_entries]->RNTI = RNTI;
    entries[num_entries]->CRCFLAG = CRCFLAG;
    num_entries++;
    pthread_mutex_unlock(&entries_lock);
}

size_t get_num_entries() {
    return num_entries;
}

void update_entry(size_t index, bool new_flag) {
    if (index >= num_entries) {
        printf("Error: Invalid index\n");
        return;
    }
    entries[index]->CRCFLAG = new_flag;
}

void delete_entry(uint32_t RNTI) {
    pthread_mutex_lock(&entries_lock);
    for (size_t i = 0; i < num_entries; i++) {
        if (entries[i]->RNTI == RNTI) {
            free_memory(entries[i]);
            entries[i] = NULL;
        }
    }
    pthread_mutex_unlock(&entries_lock);
}

void print_entries() {
    pthread_mutex_lock(&entries_lock);
    for (size_t i = 0; i < num_entries; i++) {
        if (entries[i]) {
            printf("RNTI: %u, CRCFLAG: %d\n", entries[i]->RNTI, entries[i]->CRCFLAG);
        } else {
            printf("Error: Invalid entry at index %zu\n", i);
        }
    }
    pthread_mutex_unlock(&entries_lock);
}

void cleanup() {
    for (size_t i = 0; i < num_entries; i++) {
        free_memory(entries[i]);
    }
    free(entries);
    pthread_mutex_destroy(&entries_lock);
    free(pool.buffer);
    pthread_mutex_destroy(&pool.lock);
}
