#include <stdlib.h>
#include <time.h>

typedef struct DATABASE_CONNECTION_POOL_RECORD {
    int CONNECTION_POOL_ID;
    int MAX_CONNECTIONS;
    int CURRENTLY_ACTIVE_CONNECTIONS;
    int CURRENTLY_IDLE_CONNECTIONS;
    int CONNECTION_TIMEOUT;
    time_t LAST_HEARTBEAT_TIME;
} DATABASE_CONNECTION_POOL_RECORD;

typedef struct NODE {
    DATABASE_CONNECTION_POOL_RECORD data;
    struct NODE* next;
} NODE;

typedef struct LIST {
    NODE* head;
    pthread_mutex_t lock;
} LIST;

LIST* create_list() {
    LIST* list = (LIST*)malloc(sizeof(LIST));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_connection(LIST* list, DATABASE_CONNECTION_POOL_RECORD record) {
    NODE* new_node = (NODE*)malloc(sizeof(NODE));
    if (new_node == NULL) return;
    new_node->data = record;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_idle_connections(LIST* list, int timeout) {
    time_t current_time = time(NULL);

    NODE* prev = NULL;
    NODE* curr = list->head;

    while (curr != NULL) {
        if (current_time - curr->data.LAST_HEARTBEAT_TIME > timeout) {
            if (prev == NULL) {
                list->head = curr->next;
            } else {
                prev->next = curr->next;
            }
            free(curr);
            curr = prev ? prev->next : list->head;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void update_connection_stats(LIST* list, int pool_id, int active, int idle) {
    NODE* curr = list->head;

    while (curr != NULL) {
        if (curr->data.CONNECTION_POOL_ID == pool_id) {
            curr->data.CURRENTLY_ACTIVE_CONNECTIONS += active;
            curr->data.CURRENTLY_IDLE_CONNECTIONS += idle;
            time(&curr->data.LAST_HEARTBEAT_TIME);
            break;
        }
        curr = curr->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LIST* list) {
    NODE* curr = list->head;
    while (curr != NULL) {
        NODE* next = curr->next;
        free(curr);
        curr = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
