    for (int i = 0; i < tagCount; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rxUeInfoTags[i];
        pdu->RNTI = rand(); // Generate unique RNTI for each PDU

        uint16_t tagAndRnti = (pdu->RX_UE_INFORMATION_TAG << 16) | pdu->RNTI;
        pdu->CRCFLAG = (tagAndRnti % 256); // Simple rolling checksum example

        (*pduList)[i].crc_indication_pdu = pdu;
