                case 'image':
                    html += `<div class="widget"><h3>${widget.title}</h3><img src="${widget.content}" alt="${widget.title}"></div>`;
                    break;
                case 'video':
                    html += `<div class="widget"><h3>${widget.title}</h3><iframe src="${widget.content}" frameborder="0"></iframe></div>`;
                    break;
            }
        }
    });

