        int randomInt = rand.Next(_minValue, _maxValue + 1);
        while (randomInt % 5 != 0)
        {
            randomInt = rand.Next(_minValue, _maxValue + 1);
        }
        return randomInt;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(double percentage)
    {
        int newMin = (int)(_minValue * (1 - percentage));
        int newMax = (int)(_maxValue * (1 - percentage));
        if (newMin < _minValue) newMin = _minValue;
        if (newMax > _maxValue) newMax = _maxValue;
        _minValue = newMin;
        _maxValue = newMax;
    }

    public void ExpandRange(double percentage)
    {
        int newMin = (int)(_minValue * (1 + percentage));
        int newMax = (int)(_maxValue * (1 + percentage));
        if (newMin < _minValue) newMin = _minValue;
        if (newMax > _maxValue) newMax = _maxValue;
        _minValue = newMin;
        _maxValue = newMax;
