#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>

class SensorDataProcessor {
public:
    void start() {
        producer_thread_ = std::thread(&SensorDataProcessor::producer, this);
        consumer_thread_ = std::thread(&SensorDataProcessor::consumer, this);
    }

    void stop() {
        stop_flag_.store(true);
        producer_condition_.notify_all();
        consumer_condition_.notify_all();

        if (producer_thread_.joinable()) producer_thread_.join();
        if (consumer_thread_.joinable()) consumer_thread_.join();
    }

    void pushData(const std::vector<double>& data) {
        std::unique_lock<std::mutex> lock(producer_mutex_);
        producer_queue_.push(data);
        producer_condition_.notify_one();
    }

private:
    std::thread producer_thread_;
    std::thread consumer_thread_;
    std::queue<std::vector<double>> producer_queue_;
    std::mutex producer_mutex_;
    std::condition_variable producer_condition_;

    std::atomic<bool> stop_flag_{false};

    void producer() {
        while (true) {
            std::unique_lock<std::mutex> lock(producer_mutex_);
            producer_condition_.wait(lock, [this]{ return !stop_flag_ || !producer_queue_.empty(); });
            if (stop_flag_ && producer_queue_.empty()) break;

            auto data = producer_queue_.front();
            producer_queue_.pop();

            // Process data
            processSensorData(data);
        }
    }

    void consumer() {
        while (true) {
            std::unique_lock<std::mutex> lock(producer_mutex_);
            producer_condition_.wait(lock, [this]{ return !stop_flag_ || !producer_queue_.empty(); });
            if (stop_flag_ && producer_queue_.empty()) break;

            auto data = producer_queue_.front();
            producer_queue_.pop();

            // Process data
            processSensorData(data);
        }
    }

    void processSensorData(const std::vector<double>& data) {
        // Hierarchical clustering algorithm implementation here
        std::cout << "Processing sensor data: ";
        for (double val : data) std::cout << val << " ";
        std::cout << std::endl;
    }
};

int main() {
    SensorDataProcessor processor;
    processor.start();

    std::vector<double> sensor_data = {1.2, 3.4, 5.6};
    processor.pushData(sensor_data);

    // Simulate data generation
    for (int i = 0; i < 10; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        sensor_data[0] += 0.5;
        sensor_data[1] += 0.3;
        sensor_data[2] -= 0.2;
        processor.pushData(sensor_data);
    }

    processor.stop();
    return 0;
}
