// Java method to calculate MD5 hash of a string
String md5(String str) {
    try {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(str.getBytes());
        BigInteger bigInt = new BigInteger(1, hashBytes);
        String hashtext = bigInt.toString(16).toUpperCase();
        return String.format("%-32s", hashtext).replace(' ', '0');
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException(e);
    }
}

// Java method to calculate MD5 hash of a file
String md5File(String filePath) throws IOException, NoSuchAlgorithmException {
    MessageDigest digest = MessageDigest.getInstance("MD5");
    try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(filePath))) {
        byte[] buffer = new byte[8192];
        int bytesRead;
        while ((bytesRead = bis.read(buffer)) != -1) {
            digest.update(buffer, 0, bytesRead);
        }
    }
    BigInteger bigInt = new BigInteger(1, digest.digest());
    return String.format("%-32s", bigInt.toString(16).toUpperCase()).replace(' ', '0');
}

// Python function to calculate MD5 hash of a file
def md5_file(file_path):
    with open(file_path, "rb") as f:
        hasher = hashlib.md5()
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()
