    private int sampleSize;
    private string distributionType;
    private double noiseLevel;

    public AdvancedDataSynthesizer(int sampleSize, string distributionType, double noiseLevel)
    {
        this.sampleSize = sampleSize;
        this.distributionType = distributionType;
        this.noiseLevel = noiseLevel;
    }

    public List<double> SynthesizeData()
    {
        List<double> data = new List<double>();

        switch (distributionType)
        {
            case "normal":
                data = GenerateNormalDistribution(sampleSize);
                break;
            case "uniform":
                data = GenerateUniformDistribution(sampleSize);
                break;
            case "exponential":
                data = GenerateExponentialDistribution(sampleSize);
                break;
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }

        return data.Select(x => AddNoise(x, noiseLevel)).ToList();
    }

    private List<double> GenerateNormalDistribution(int size)
    {
        Random random = new Random();
        return Enumerable.Range(0, size).Select(_ => random.NextDouble() * 10).ToList(); // Simplified normal distribution generation
    }

    private List<double> GenerateUniformDistribution(int size)
    {
        Random random = new Random();
        return Enumerable.Range(0, size).Select(_ => random.NextDouble()).ToList();
    }

    private List<double> GenerateExponentialDistribution(int size)
    {
        Random random = new Random();
        return Enumerable.Range(0, size).Select(_ => Math.Exp(random.NextDouble())).ToList(); // Simplified exponential distribution generation
    }

    private double AddNoise(double value, double noiseLevel)
    {
        Random random = new Random();
        double noise = noiseLevel * (random.NextDouble() - 0.5);
        return value + noise;
    }
}

