public class AdvancedBinaryFileProcessor
{
    private float _minValue;
    private float _maxValue;
    private Dictionary<string, Func<float, float>> _cache = new Dictionary<string, Func<float, float>>();

    public AdvancedBinaryFileProcessor(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(maxValue), "Max value must be greater than min value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return (float)(_minValue + (_maxValue - _minValue) * Random.Shared.NextDouble());
    }

    public int GenerateRandomInt()
    {
        return Convert.ToInt32(GenerateRandomFloat()) * 5;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    public void ShrinkRange(float percentage)
    {
        _minValue += (_maxValue - _minValue) * percentage / 100f;
        _maxValue -= (_maxValue - _minValue) * percentage / 100f;
    }

    public void ExpandRange(float percentage)
    {
        _minValue -= (_maxValue - _minValue) * percentage / 100f;
        _maxValue += (_maxValue - _minValue) * percentage / 100f;
    }

    public async Task ProcessFileAsync(string inputFilePath, string outputFilePath, string rules)
    {
        ValidateInputData(inputFilePath);

        using (var reader = new BinaryReader(File.OpenRead(inputFilePath)))
        using (var writer = new BinaryWriter(File.OpenWrite(outputFilePath)))
        {
            while (reader.BaseStream.Position < reader.BaseStream.Length)
            {
                float value = reader.ReadSingle();
                float transformedValue = ApplyTransformation(value, rules);
                writer.Write(transformedValue);
            }
        }

        LogTransformationSteps(inputFilePath, outputFilePath, rules);
    }

    private void ValidateInputData(string filePath)
    {
        using (var reader = new BinaryReader(File.OpenRead(filePath)))
        {
            while (reader.BaseStream.Position < reader.BaseStream.Length)
            {
                float value = reader.ReadSingle();
                if (value < _minValue || value > _maxValue)
                    throw new InvalidDataException("Input data contains out-of-range values.");
            }
        }
    }

    private void LogTransformationSteps(string inputFilePath, string outputFilePath, string rules)
    {
        // Custom logging implementation here
    }

    private float ApplyTransformation(float value, string rules)
    {
        if (!_cache.ContainsKey(rules))
        {
            _cache[rules] = CreateTransformationFunction(rules);
        }

        return _cache[rules](value);
    }

    private Func<float, float> CreateTransformationFunction(string rules)
    {
        // Custom transformation logic here
        return value => value * 2; // Example transformation: multiply by 2
    }

    public void LoadCustomRules(string configFilePath)
    {
        // Load custom rules from configuration file
    }

    public async Task BatchProcessFilesAsync(string[] inputFiles, string outputPrefix)
    {
        var tasks = new List<Task>();

        for (int i = 0; i < inputFiles.Length; i++)
        {
            string outputFilePath = $"{outputPrefix}_{i + 1}.bin";
            tasks.Add(ProcessFileAsync(inputFiles[i], outputFilePath, "custom_rules"));
        }

        await Task.WhenAll(tasks);
    }
