struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNFAPIList(int N) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList(N);
    srand(std::chrono::system_clock::now().time_since_epoch().count());

    for (int i = 0; i < N; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pduList[i].RNTI = rand() % 1000;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        pduList[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    return pduList;
}

// Main function to demonstrate the generation of NFAPI list
int main(int argc, char* argv[]) {
    int N = 10; // Example size
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList = generateNFAPIList(N);

    for (const auto& pdu : pduList) {
        std::cout << "RX_UE_INFORMATION_TAG: " << pdu.RX_UE_INFORMATION_TAG 
                  << ", RNTI: " << pdu.RNTI 
                  << ", CRC_INDICATION_REL8_TAG: " << pdu.CRC_INDICATION_REL8_TAG 
                  << ", CRCFLAG: " << (pdu.CRCFLAG ? "true" : "false") << std::endl;
    }

    return 0;
}
