namespace fs = std::filesystem;

struct LogMessage {
    std::string message;
    LogLevel level;
};

class Logger {
private:
    static std::mutex logMutex;
    static std::condition_variable logCond;
    static std::queue<LogMessage> logQueue;
    static std::thread logThread;
    static std::atomic<bool> running;

public:
    static void initialize() {
        running = true;
        logThread = std::thread([]() {
            while (running) {
                std::unique_lock<std::mutex> lock(logMutex);
                logCond.wait(lock, []{ return !logQueue.empty(); });
                LogMessage msg = logQueue.front();
                logQueue.pop();
                lock.unlock();

                // Log the message to different destinations
                // Example: write to file or console based on msg.level
            }
        });
    }

    static void shutdown() {
        running = false;
        logCond.notify_all();
        logThread.join();
    }

    static void log(const std::string& message, LogLevel level) {
        LogMessage msg{message, level};
        std::lock_guard<std::mutex> lock(logMutex);
        logQueue.push(msg);
        logCond.notify_one();
    }
};

std::mutex Logger::logMutex;
std::condition_variable Logger::logCond;
std::queue<LogMessage> Logger::logQueue;
