#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    unsigned long long FILESYSTEM_ID;
    unsigned long long TOTAL_SPACE;
    unsigned long long USED_SPACE;
    unsigned long long AVAIL_SPACE;
    float PERCENTAGE利用率;
} FILE_SYSTEM_USAGE_RECORD;

typedef struct {
    FILE_SYSTEM_USAGE_RECORD *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} FILESYSTEM_LIST;

void initializeFilesystemList(FILESYSTEM_LIST *list) {
    list->records = (FILE_SYSTEM_USAGE_RECORD *)malloc(10 * sizeof(FILE_SYSTEM_USAGE_RECORD));
    if (!list->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = 10;
    pthread_mutex_init(&list->lock, NULL);
}

void resizeFilesystemList(FILESYSTEM_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    FILE_SYSTEM_USAGE_RECORD *new_records = (FILE_SYSTEM_USAGE_RECORD *)realloc(list->records, new_capacity * sizeof(FILE_SYSTEM_USAGE_RECORD));
    if (!new_records) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }
    list->records = new_records;
    list->capacity = new_capacity;
}

int addOrUpdateFilesystemRecord(FILESYSTEM_LIST *list, FILE_SYSTEM_USAGE_RECORD record, int update_flag) {
    pthread_mutex_lock(&list->lock);

    if (record.TOTAL_SPACE < record.USED_SPACE || record.TOTAL_SPACE < record.AVAIL_SPACE) {
        fprintf(stderr, "Error: TOTAL_SPACE must be greater than or equal to USED_SPACE and AVAIL_SPACE\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (update_flag) {
        for (size_t i = 0; i < list->count; ++i) {
            if (list->records[i].FILESYSTEM_ID == record.FILESYSTEM_ID) {
                list->records[i] = record;
                pthread_mutex_unlock(&list->lock);
                return 0;
            }
        }
    } else if (list->count >= list->capacity) {
        resizeFilesystemList(list);
    }

    list->records[list->count++] = record;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void removeFilesystemRecord(FILESYSTEM_LIST *list, unsigned long long FILESYSTEM_ID) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].FILESYSTEM_ID == FILESYSTEM_ID) {
            for (size_t j = i; j < list->count - 1; ++j) {
                list->records[j] = list->records[j + 1];
            }
            --list->count;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void iterateFilesystemList(FILESYSTEM_LIST *list, void (*operation)(FILE_SYSTEM_USAGE_RECORD *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        operation(&list->records[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

int countFlaggedFilesystemRecords(FILESYSTEM_LIST *list, float threshold_percentage) {
    int count = 0;
    iterateFilesystemList(list, (void (*)(FILE_SYSTEM_USAGE_RECORD *))[
        if ((*record).PERCENTAGE利用率 < threshold_percentage) {
            ++count;
        }
    ]);
    return count;
}

void getFlaggedFilesystemRecords(FILESYSTEM_LIST *list, float threshold_percentage, FILE_SYSTEM_USAGE_RECORD **flagged_records, size_t *count) {
    pthread_mutex_lock(&list->lock);

    *count = 0;
    iterateFilesystemList(list, (void (*)(FILE_SYSTEM_USAGE_RECORD *))[
        if ((*record).PERCENTAGE利用率 < threshold_percentage) {
            flagged_records[(*count)++] = *record;
        }
    ]);

    pthread_mutex_unlock(&list->lock);
}

void freeFilesystemList(FILESYSTEM_LIST *list) {
    free(list->records);
    pthread_mutex_destroy(&list->lock);
}
```

