    // Parse JSON
    json_object* token_obj = json_tokener_parse(json_str);
    if (!token_obj) {
        error_handler("Failed to parse JSON");
        return false;
    }

    // Validate scope
    json_object* scope_obj;
    if (!json_object_object_get_ex(token_obj, "scope", &scope_obj) || !json_object_is_type(scope_obj, json_type_string)) {
        error_handler("Missing or invalid 'scope' field");
        json_object_put(token_obj);
        return false;
    }

    // Validate issued_at
    json_object* issued_at_obj;
    if (!json_object_object_get_ex(token_obj, "issued_at", &issued_at_obj) || !json_object_is_type(issued_at_obj, json_type_int)) {
        error_handler("Missing or invalid 'issued_at' field");
        json_object_put(token_obj);
        return false;
    }

    // Validate token_type
    json_object* token_type_obj;
    if (!json_object_object_get_ex(token_obj, "token_type", &token_type_obj) || !json_object_is_type(token_type_obj, json_type_string)) {
        error_handler("Missing or invalid 'token_type' field");
        json_object_put(token_obj);
        return false;
    }
    const char* token_type = json_object_get_string(token_type_obj);
    if (strcmp(token_type, "Bearer") != 0) {
        error_handler("Invalid token type");
        json_object_put(token_obj);
        return false;
    }

    // Validate expires_in
    json_object* expires_in_obj;
    if (!json_object_object_get_ex(token_obj, "expires_in", &expires_in_obj) || !json_object_is_type(expires_in_obj, json_type_int)) {
        error_handler("Missing or invalid 'expires_in' field");
        json_object_put(token_obj);
        return false;
    }
    int expires_in = json_object_get_int(expires_in_obj);
    if (expires_in <= 0) {
        error_handler("Invalid 'expires_in' value");
        json_object_put(token_obj);
        return false;
    }

    // Validate scope values
    const char* scope_str = json_object_get_string(scope_obj);
    bool valid_scope = false;
    for (size_t i = 0; i < config->num_scopes; ++i) {
        if (strcmp(scope_str, config->valid_scopes[i]) == 0) {
            valid_scope = true;
            break;
        }
    }
    if (!valid_scope) {
        error_handler("Invalid scope value");
        json_object_put(token_obj);
        return false;
    }

    // Validate issued_at timestamp
    time_t current_time = time(NULL);
    if (current_time - json_object_get_int(issued_at_obj) > config->grace_period) {
        error_handler("Token expired");
        json_object_put(token_obj);
        return false;
    }

    // Perform cryptographic operations and store encrypted data securely

    json_object_put(token_obj);
    return true;
}

unsigned char* md5_hash(const char* input, size_t input_len, unsigned char* output) {
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return NULL;

    if (1 != EVP_DigestInit_ex(ctx, EVP_md5(), NULL)) {
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_DigestUpdate(ctx, input, input_len)) {
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    unsigned int output_len = 0;
    if (1 != EVP_DigestFinal_ex(ctx, output, &output_len)) {
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    EVP_MD_CTX_free(ctx);
    return output;
}
