#define MAX_CONNECTIONS_PER_POOL 100

typedef struct DATABASE_CONNECTION_POOL_RECORD {
    int CONNECTION_POOL_ID;
    int MAX_CONNECTIONS;
    int CURRENTLY_ACTIVE_CONNECTIONS;
    int CURRENTLY_IDLE_CONNECTIONS;
    int CONNECTION_TIMEOUT;
    time_t LAST_HEARTBEAT_TIME;
    // Add other fields as needed
} DATABASE_CONNECTION_POOL_RECORD;

typedef struct CONNECTION_POOL_NODE {
    DATABASE_CONNECTION_POOL_RECORD record;
    struct CONNECTION_POOL_NODE* next;
} CONNECTION_POOL_NODE;

typedef struct DATABASE_CONNECTION_POOL_LIST {
    pthread_mutex_t lock;
    CONNECTION_POOL_NODE* head;
} DATABASE_CONNECTION_POOL_LIST;

DATABASE_CONNECTION_POOL_LIST* create_connection_pool_list() {
    DATABASE_CONNECTION_POOL_LIST* list = (DATABASE_CONNECTION_POOL_LIST*)malloc(sizeof(DATABASE_CONNECTION_POOL_LIST));
    if (list) {
        pthread_mutex_init(&list->lock, NULL);
        list->head = NULL;
    }
    return list;
}

void destroy_connection_pool_list(DATABASE_CONNECTION_POOL_LIST* list) {
    pthread_mutex_lock(&list->lock);
    CONNECTION_POOL_NODE* current = list->head;
    while (current) {
        CONNECTION_POOL_NODE* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_connection_pool_record(DATABASE_CONNECTION_POOL_LIST* list, DATABASE_CONNECTION_POOL_RECORD record) {
    pthread_mutex_lock(&list->lock);
    CONNECTION_POOL_NODE* new_node = (CONNECTION_POOL_NODE*)malloc(sizeof(CONNECTION_POOL_NODE));
    if (new_node) {
        new_node->record = record;
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_idle_connections(DATABASE_CONNECTION_POOL_LIST* list, int timeout) {
    pthread_mutex_lock(&list->lock);
    CONNECTION_POOL_NODE* current = list->head;
    CONNECTION_POOL_NODE* prev = NULL;
    while (current) {
        if ((time(NULL) - current->record.LAST_HEARTBEAT_TIME) > timeout) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            current = prev ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Add other functions as needed for managing connection pools

