#include <pthread.h>

#define MAX_CONNECTIONS 100
#define CONNECTION_TIMEOUT 60

typedef struct {
    int id;
    int max_connections;
    int currently_active_connections;
    int currently_idle_connections;
    int connection_timeout;
    time_t last_heartbeat_time;
} DATABASE_CONNECTION_POOL_RECORD;

typedef struct {
    DATABASE_CONNECTION_POOL_RECORD *record;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool* initDatabaseConnectionPool(int pool_size) {
    ConnectionPool *pool = (ConnectionPool*)malloc(pool_size * sizeof(ConnectionPool));
    for (int i = 0; i < pool_size; ++i) {
        pool[i].record = (DATABASE_CONNECTION_POOL_RECORD*)malloc(sizeof(DATABASE_CONNECTION_POOL_RECORD));
        pthread_mutex_init(&pool[i].lock, NULL);
    }
    return pool;
}

void addNewConnection(ConnectionPool *pool, int pool_index) {
    pthread_mutex_lock(&pool[pool_index].lock);
    if (pool[pool_index].record->currently_idle_connections > 0) {
        pool[pool_index].record->currently_active_connections++;
        pool[pool_index].record->currently_idle_connections--;
        time_t current_time = time(NULL);
        pool[pool_index].record->last_heartbeat_time = current_time;
    }
    pthread_mutex_unlock(&pool[pool_index].lock);
}

void removeIdleConnections(ConnectionPool *pool, int pool_index) {
    pthread_mutex_lock(&pool[pool_index].lock);
    if (time(NULL) - pool[pool_index].record->last_heartbeat_time > CONNECTION_TIMEOUT) {
        pool[pool_index].record->currently_active_connections--;
        pool[pool_index].record->currently_idle_connections++;
    }
