#define MAX_BUFFER_SIZE 1024 * 1024 // 1MB

typedef struct {
    int streamID;
    int reservedSpace;
} StreamInfo;

typedef struct {
    StreamInfo *streams;
    int maxStreams;
    int bufferSize;
    pthread_mutex_t lock;
} DataPipeline;

DataPipeline pipeline = { NULL, 0, MAX_BUFFER_SIZE, PTHREAD_MUTEX_INITIALIZER };

void initializePipeline(int maxStreams) {
    pipeline.maxStreams = maxStreams;
    pipeline.streams = (StreamInfo *)malloc(maxStreams * sizeof(StreamInfo));
    memset(pipeline.streams, 0, maxStreams * sizeof(StreamInfo));
}

int validateStreamID(int streamID) {
    // Simulate metadata store validation
    if (streamID >= 1 && streamID <= 10) {
        return 1;
    }
    return 0;
}

void allocateBufferSpace(int streamID, int dataVolume) {
    pthread_mutex_lock(&pipeline.lock);
    for (int i = 0; i < pipeline.maxStreams; ++i) {
        if (pipeline.streams[i].streamID == streamID) {
            pipeline.streams[i].reservedSpace += dataVolume;
            break;
        }
    }
    pthread_mutex_unlock(&pipeline.lock);
}

void freeBufferSpace(int streamID, int dataVolume) {
    pthread_mutex_lock(&pipeline.lock);
    for (int i = 0; i < pipeline.maxStreams; ++i) {
        if (pipeline.streams[i].streamID == streamID) {
            pipeline.streams[i].reservedSpace -= dataVolume;
            break;
        }
    }
    pthread_mutex_unlock(&pipeline.lock);
}

void processDataStream(int streamID, int dataVolume) {
    if (!validateStreamID(streamID)) {
        printf("Invalid stream ID\n");
        return;
    }

    allocateBufferSpace(streamID, dataVolume);

    // Simulate data processing
    printf("Processing stream %d with volume %d\n", streamID, dataVolume);

    freeBufferSpace(streamID, dataVolume);
}

void *pipelineThread(void *arg) {
    int streamID = *(int *)arg;
    while (1) {
        processDataStream(streamID, rand() % 1024); // Simulate random data volume
        sleep(1); // Simulate periodic processing
    }
    return NULL;
}

void startPipeline(int numThreads) {
    pthread_t threads[numThreads];
    int streamIDs[numThreads];

    initializePipeline(numThreads);

    for (int i = 0; i < numThreads; ++i) {
        streamIDs[i] = i + 1;
        pthread_create(&threads[i], NULL, pipelineThread, &streamIDs[i]);
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    int numThreads = 5;
    startPipeline(numThreads);
    return 0;
}
