typedef struct DynamicList {
    NetworkEvent** events;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicList;

DynamicList* createDynamicList(size_t initialCapacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->events = (NetworkEvent**)calloc(initialCapacity, sizeof(NetworkEvent*));
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyDynamicList(DynamicList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertEvent(DynamicList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->events = (NetworkEvent**)realloc(list->events, list->capacity * sizeof(NetworkEvent*));
    }
    list->events[list->size++] = event;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int deleteEvent(DynamicList* list, size_t index) {
    if (index >= list->size) return -1;
    pthread_mutex_lock(&list->lock);
    free(list->events[index]);
    for (size_t i = index; i < list->size - 1; ++i) {
        list->events[i] = list->events[i + 1];
    }
    list->size--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NetworkEvent* getEvent(DynamicList* list, size_t index) {
    if (index >= list->size) return NULL;
    pthread_mutex_lock(&list->lock);
    NetworkEvent* event = list->events[index];
    pthread_mutex_unlock(&list->lock);
    return event;
}

