        uint32_t combinedValue = (pduList[i].RX_UE_INFORMATION_TAG << 16) | pduList[i].RNTI;
        pduList[i].CRCFLAG = combinedValue % 256; // Simplified rolling checksum

        printf("PDU %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n", i, pduList[i].RX_UE_INFORMATION_TAG, pduList[i].RNTI, pduList[i].CRCFLAG);
    }

    return pduList;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pduList = createNfadLogInit(5);
    if (pduList != NULL) {
        free(pduList); // Clean up allocated memory
    }
    return 0;
}
