#define MAX_MEMORY_RESERVATION 1024 * 1024 * 1024 // 1GB

typedef struct {
    int chunkID;
    size_t size;
    void* data;
} MemoryChunk;

typedef struct {
    MemoryChunk** memoryChunks;
    size_t totalMemory;
    size_t reservedMemory;
    sem_t memorySemaphore;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* createMemoryManager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->memoryChunks = (MemoryChunk**)calloc(MAX_MEMORY_RESERVATION, sizeof(MemoryChunk*));
    manager->totalMemory = MAX_MEMORY_RESERVATION;
    manager->reservedMemory = 0;
    sem_init(&manager->memorySemaphore, 0, MAX_MEMORY_RESERVATION);
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    for (int i = 0; i < MAX_MEMORY_RESERVATION; i++) {
        if (manager->memoryChunks[i]) {
            free(manager->memoryChunks[i]->data);
            free(manager->memoryChunks[i]);
        }
    }
    sem_destroy(&manager->memorySemaphore);
    pthread_mutex_destroy(&manager->lock);
    free(manager->memoryChunks);
    free(manager);
}

void* allocateMemory(MemoryManager* manager, int chunkID, size_t size) {
    pthread_mutex_lock(&manager->lock);
    while (sem_wait(&manager->memorySemaphore) != 0) {
        // Handle network timeouts and retries for failed validation attempts
    }

    if (manager->reservedMemory + size > MAX_MEMORY_RESERVATION) {
        sem_post(&manager->memorySemaphore);
        pthread_mutex_unlock(&manager->lock);
        return NULL; // Memory allocation failure, handle with retry logic or alerts
    }

    MemoryChunk* chunk = (MemoryChunk*)malloc(sizeof(MemoryChunk));
    chunk->chunkID = chunkID;
    chunk->size = size;
    chunk->data = malloc(size);

    manager->memoryChunks[manager->reservedMemory / size] = chunk;
    manager->reservedMemory += size;

    pthread_mutex_unlock(&manager->lock);
    return chunk->data;
}

void deallocateMemory(MemoryManager* manager, int chunkID) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_MEMORY_RESERVATION; i++) {
        if (manager->memoryChunks[i] && manager->memoryChunks[i]->chunkID == chunkID) {
            free(manager->memoryChunks[i]->data);
            free(manager->memoryChunks[i]);
            manager->memoryChunks[i] = NULL;
            manager->reservedMemory -= manager->memoryChunks[i]->size;
            sem_post(&manager->memorySemaphore);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

