    byte[] data = Encoding.UTF8.GetBytes(rxUeInfoTag + rnti);
    uint crcValue = 0xFFFFFFFF;
    foreach (byte b in data)
    {
        crcValue ^= (uint)b << 24;
        for (int i = 0; i < 8; ++i)
        {
            if ((crcValue & 0x80000000) != 0)
                crcValue = (crcValue << 1) ^ 0xEDB88320;
            else
                crcValue <<= 1;
        }
    }
    return (byte)(crcValue >> 24);
