MEDIA_PROCESS_RECORD* generate_media_records(int count, int* error_code) {
    if (count <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    MEDIA_PROCESS_RECORD* records = (MEDIA_PROCESS_RECORD*)malloc(count * sizeof(MEDIA_PROCESS_RECORD));
    if (records == NULL) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        snprintf(records[i].media_id, 128, "ID-%d", i);
        records[i].timestamp = time(NULL) + i * 100;
        snprintf(records[i].metadata_tags, 256, "Tag-%d", i);
        records[i].playback_status = (i % 2 == 0) ? 1 : 0; // Simulating playback status
    }

    *error_code = 0; // Success
    return records;
}
