#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* buffer;
    size_t element_size;
    size_t allocated_count;
    size_t free_count;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t initial_elements) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->buffer = malloc(element_size * initial_elements);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }

    pool->element_size = element_size;
    pool->allocated_count = initial_elements;
    pool->free_count = initial_elements;

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->free_count == 0) {
        size_t new_size = pool->allocated_count * 2;
        void* new_buffer = realloc(pool->buffer, pool->element_size * new_size);
        if (!new_buffer) return NULL;

        pool->buffer = new_buffer;
        pool->allocated_count = new_size;
    }

    void* ptr = (char*)pool->buffer + pool->free_count * pool->element_size;
    pool->free_count--;
    return ptr;
}

void memory_pool_free(MemoryPool* pool, void* ptr) {
    size_t index = ((char*)ptr - (char*)pool->buffer) / pool->element_size;
    if (index < pool->allocated_count && index >= pool->allocated_count - pool->free_count) {
        pool->free_count++;
    }
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(size_t N, MemoryPool* pool) {
    if (N == 0 || !pool) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(pool);
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate RX_UE_INFORMATION_TAG
        pdus[i].RNTI = rand() % 256;                // Simulate RNTI

        // Probabilistic CRC flag based on a hypothetical error rate
        if (rand() % 2 == 0) {
            pdus[i].CRCFLAG = 1; // Error detected
        } else {
            pdus[i].CRCFLAG = 0; // No error
        }
    }

    return pdus;
}

void print_crc_indications(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t N) {
    for (size_t i = 0; i < N; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               pdus[i].RX_UE_INFORMATION_TAG,
               pdus[i].RNTI,
               pdus[i].CRCFLAG);
    }
}

int main() {
    size_t N = 10; // Example input size
    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), N);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_crc_indications(N, pool);
    if (pdus) {
        print_crc_indications(pdus, N);
        memory_pool_free(pool, pdus);
    } else {
        fprintf(stderr, "Failed to generate CRC indications\n");
    }

    destroy_memory_pool(pool);

    return 0;
}
```

