#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROC_COUNT 100

typedef struct LTE_PHY_RX_PROC {
    int CELL_ID;
    char PHY_RRC_RX_Procedure[256];
    unsigned long PHY_RX_DATA;
} LTE_PHY_RX_PROC;

LTE_PHY_RX_PROC *procedure_list[MAX_PROC_COUNT] = {NULL};
int current_proc_count = 0;

unsigned long rolling_checksum(unsigned char *data, size_t length) {
    unsigned long sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += data[i];
        sum %= 0xFFFFFFFF;
    }
    return sum;
}

int add_procedure(int CELL_ID, const char *PHY_RRC_RX_Procedure) {
    if (current_proc_count >= MAX_PROC_COUNT) {
        printf("Maximum number of procedures reached.\n");
        return -1;
    }

    for (int i = 0; i < current_proc_count; ++i) {
        if (procedure_list[i]->CELL_ID == CELL_ID) {
            printf("CELL_ID already exists.\n");
            return -2;
        }
    }

    LTE_PHY_RX_PROC *new_procedure = malloc(sizeof(LTE_PHY_RX_PROC));
    if (!new_procedure) {
        printf("Memory allocation failed.\n");
        return -3;
    }

    new_procedure->CELL_ID = CELL_ID;
    strncpy(new_procedure->PHY_RRC_RX_Procedure, PHY_RRC_RX_Procedure, sizeof(new_procedure->PHY_RRC_RX_Procedure) - 1);
    new_procedure->PHY_RRC_RX_Procedure[sizeof(new_procedure->PHY_RRC_RX_Procedure) - 1] = '\0';

    time_t timestamp = time(NULL);
    unsigned char data[5];
    memcpy(data, &CELL_ID, sizeof(CELL_ID));
    memcpy(data + sizeof(CELL_ID), &timestamp, sizeof(timestamp));

    new_procedure->PHY_RX_DATA = rolling_checksum(data, sizeof(data));

    procedure_list[current_proc_count++] = new_procedure;

    return 0;
}

void free_procedures() {
    for (int i = 0; i < current_proc_count; ++i) {
        if (procedure_list[i]) {
            free(procedure_list[i]);
            procedure_list[i] = NULL;
        }
    }
    current_proc_count = 0;
}

int main() {
    // Example usage
    if (add_procedure(123, "ProcedureA") == 0) {
        printf("Procedure added successfully.\n");
    }

    free_procedures();
    return 0;
}
```

This code snippet defines a function `add_procedure` to manage a dynamic list of `LTE_PHY_RX_PROC` structures. It ensures uniqueness of `CELL_ID`, manages memory efficiently, and handles potential errors gracefully. The example usage in the `main` function demonstrates how to add a procedure and clean up resources when done.']

