#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    FILE *file;
    long start_line;
    long end_line;
    int line_count;
} FileSection;

void* process_file_section(void* arg) {
    FileSection *section = (FileSection*)arg;
    for (long i = section->start_line; i <= section->end_line; ++i) {
        char buffer[MAX_LINE_LENGTH];
        if (fgets(buffer, MAX_LINE_LENGTH, section->file)) {
            ++section->line_count;
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    const char *input_file = "default.txt";
    int num_threads = 4;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            input_file = argv[++i];
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            num_threads = atoi(argv[++i]);
        }
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    fseek(file, 0L, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0L, SEEK_SET);

    pthread_t threads[num_threads];
    FileSection sections[num_threads];

    long lines_per_thread = file_size / (num_threads * MAX_LINE_LENGTH);
    for (int i = 0; i < num_threads; ++i) {
        sections[i].file = file;
        sections[i].start_line = i * lines_per_thread;
        sections[i].end_line = (i + 1) * lines_per_thread - 1;
        sections[i].line_count = 0;
        pthread_create(&threads[i], NULL, process_file_section, &sections[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    long total_lines = 0;
    for (int i = 0; i < num_threads; ++i) {
        total_lines += sections[i].line_count;
    }

    printf("Total lines: %ld\n", total_lines);

    fclose(file);
    return EXIT_SUCCESS;
}
