#define MAX_LINES 10000

typedef struct {
    FILE *file;
    int line_count;
} FileContext;

void* process_file(void* arg) {
    FileContext* ctx = (FileContext*)arg;
    char buffer[MAX_LINES];

    while (fgets(buffer, sizeof(buffer), ctx->file)) {
        ctx->line_count++;
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s [input_file]\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    FileContext ctx = {file, 0};
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, process_file, &ctx) != 0) {
        perror("Thread creation failed");
        fclose(file);
        return 1;
    }

    pthread_join(thread_id, NULL);

    printf("Total lines: %d\n", ctx.line_count);

    fclose(file);
    return 0;
}
