#define MAX_MEMORY_RESERVATION 1024 * 1024 // 1 MB

typedef struct {
    int chunkID;
    void* memoryBlock;
    size_t size;
} MemoryBlock;

typedef struct {
    pthread_mutex_t lock;
    MemoryBlock* blocks;
    size_t allocatedSize;
    size_t reservedMemory;
    int maxConcurrency;
} MemoryManager;

MemoryManager* createMemoryManager(int maxConcurrency) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    manager->blocks = NULL;
    manager->allocatedSize = 0;
    manager->reservedMemory = 0;
    manager->maxConcurrency = maxConcurrency;
    return manager;
}

void freeMemoryManager(MemoryManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->allocatedSize; i++) {
        if (manager->blocks[i].memoryBlock != NULL) {
            free(manager->blocks[i].memoryBlock);
        }
    }
    free(manager->blocks);
    pthread_mutex_unlock(&manager->lock);
    free(manager);
}

void* allocateMemory(MemoryManager* manager, int chunkID, size_t size) {
    void* memory = NULL;
    // Simulate metadata store validation and network timeout handling
    if (validateChunkID(chunkID)) {
        pthread_mutex_lock(&manager->lock);
        if (manager->reservedMemory + size <= MAX_MEMORY_RESERVATION) {
            manager->reservedMemory += size;
            memory = malloc(size);
            if (memory != NULL) {
                MemoryBlock block = {chunkID, memory, size};
                manager->blocks = realloc(manager->blocks, sizeof(MemoryBlock) * (manager->allocatedSize + 1));
                manager->blocks[manager->allocatedSize++] = block;
            }
        }
        pthread_mutex_unlock(&manager->lock);
    } else {
        // Handle validation failure with retry logic or fallback method
    }
    return memory;
}

void deallocateMemory(MemoryManager* manager, int chunkID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->allocatedSize; i++) {
        if (manager->blocks[i].chunkID == chunkID) {
            free(manager->blocks[i].memoryBlock);
            memmove(&manager->blocks[i], &manager->blocks[i + 1], sizeof(MemoryBlock) * (manager->allocatedSize - i - 1));
            manager->allocatedSize--;
            manager->reservedMemory -= manager->blocks[i].size;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

int validateChunkID(int chunkID) {
    // Simulate metadata store validation
    return (chunkID % 2 == 0); // For demonstration purposes, only even IDs are valid
}

