typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode* next;
} MemoryPoolNodeT;

typedef struct MemoryPool {
    MemoryPoolNodeT* head;
    pthread_mutex_t lock;
    int pool_size;
    int used_count;
    int reclamation_threshold;
    double throughput_rate;
    int current_memory_utilization;
    int fragmentation_level;
} MemoryPoolT;

MemoryPoolT* create_memory_pool(int pool_size, int reclamation_threshold, double throughput_rate) {
    MemoryPoolT* pool = malloc(sizeof(MemoryPoolT));
    if (!pool) return NULL;
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->pool_size = pool_size;
    pool->used_count = 0;
    pool->reclamation_threshold = reclamation_threshold;
    pool->throughput_rate = throughput_rate;
    pool->current_memory_utilization = 0;
    pool->fragmentation_level = 0;
    return pool;
}

void destroy_memory_pool(MemoryPoolT* pool) {
    pthread_mutex_lock(&pool->lock);
    MemoryPoolNodeT* node = pool->head;
    while (node) {
        MemoryPoolNodeT* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure(MemoryPoolT* pool, STRUCT_TYPE_E type) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count >= pool->pool_size - pool->reclamation_threshold) {
        // Reclaim memory based on reclamation threshold
        reclaim_memory(pool);
    }
    if (pool->used_count >= pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory allocation failed
    }
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(metadata[type].min_size);
    if (!data) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Memory allocation failed
    }
    pool->used_count++;
    pool->current_memory_utilization += metadata[type].min_size;
    pthread_mutex_unlock(&pool->lock);
    data->valid_tag = true;
    data->rnti = get_valid_rnti();
    if (!data->rnti) {
        free(data);
        return NULL; // Invalid RNTI value
