}

void deallocate_structure(MemoryPoolT* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pool->lock);
    if (!data || !data->valid_tag) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid or uninitialized structure
    }
    free(data);
    pool->used_count--;
    pool->current_memory_utilization -= metadata[data->type].min_size;
    pthread_mutex_unlock(&pool->lock);
}

void reclaim_memory(MemoryPoolT* pool) {
