#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UF {
    int parent[N];
    int rank[N];
} UnionFind;

void initUF(UnionFind *uf) {
    for (int i = 0; i < N; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSet(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY])
            uf->parent[rootY] = rootX;
        else if (uf->rank[rootX] < uf->rank[rootY])
            uf->parent[rootX] = rootY;
        else {
            uf->parent[rootY] = rootX;
            ++uf->rank[rootX];
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateArray(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % N;
        array[i].RNTI = rand() % N;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return array;
}

int countDisjointPairs(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    UnionFind uf;
    initUF(&uf);

    for (int i = 0; i < N; ++i) {
        unionSet(&uf, array[i].RX_UE_INFORMATION_TAG, array[i].RNTI);
    }

    int disjointPairs = 0;
    for (int i = 0; i < N; ++i) {
        if (find(&uf, array[i].RX_UE_INFORMATION_TAG) != find(&uf, array[i].RNTI)) {
            ++disjointPairs;
            unionSet(&uf, array[i].RX_UE_INFORMATION_TAG, array[i].RNTI);
        }
    }

    return disjointPairs;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = createAndPopulateArray(N);
    clock_t start = clock();
    int count = countDisjointPairs(array, N);
    clock_t end = clock();

    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;

    printf("Count of disjoint pairs: %d\n", count);
    printf("Time taken in milliseconds: %.2f\n", time_taken);

    free(array);
    return 0;
}
