        printf("Thread %d: Tag=%s, CPU=%d%%, Memory=%.2fMB, Disk I/O=%.3fKB/s, Network Throughput=%.3fMB/s\n",
               thread_id, metrics[i].tag, metrics[i].cpu_usage, metrics[i].memory_consumption,
               metrics[i].disk_io, metrics[i].network_throughput);
    }

    free(pdu_list);
    free(metrics);

    pthread_exit(NULL);
}

int main() {
    pthread_t threads[N];
    int thread_ids[N];

    for (int i = 0; i < N; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, populate_performance_metrics, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
