#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 100000

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    int protocol;
    int payload_length;
} PacketHeader;

typedef struct {
    PacketHeader *packet;
    int next;
} HashNode;

typedef struct {
    HashNode nodes[MAX_PACKETS];
    int head[MAX_PACKETS];
    int count;
} HashTable;

typedef struct {
    PacketHeader packets[MAX_PACKETS];
    int priority;
    int next;
} PriorityQueue;

void initHashTable(HashTable *ht) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        ht->head[i] = -1;
    }
    ht->count = 0;
}

unsigned int hashFunction(const char *ip, int port) {
    // Implement a simple hash function
    return port ^ (port >> 16);
}

void insertPacket(HashTable *ht, PacketHeader *packet) {
    unsigned int index = hashFunction(packet->src_ip, packet->payload_length) % MAX_PACKETS;
    HashNode *newNode = &ht->nodes[ht->count++];
    newNode->packet = packet;
    newNode->next = ht->head[index];
    ht->head[index] = newNode - ht->nodes;
}

int findPacket(HashTable *ht, const char *src_ip, const char *dst_ip) {
    unsigned int index = hashFunction(src_ip, 0) % MAX_PACKETS;
    for (int i = ht->head[index]; i != -1; i = ht->nodes[i].next) {
        if (strcmp(ht->nodes[i].packet->src_ip, src_ip) == 0 && strcmp(ht->nodes[i].packet->dst_ip, dst_ip) == 0) {
            return 1;
        }
    }
    return 0;
}

void initPriorityQueue(PriorityQueue *pq) {
    for (int i = 0; i < MAX_PACKETS; i++) {
        pq->packets[i].payload_length = -1;
    }
    pq->count = 0;
}

void insertToPriorityQueue(PriorityQueue *pq, PacketHeader *packet) {
    int index = pq->count++;
    while (index > 0 && pq->packets[(index - 1) / 2].payload_length < packet->payload_length) {
        pq->packets[index] = pq->packets[(index - 1) / 2];
        index = (index - 1) / 2;
    }
    pq->packets[index] = *packet;
}

PacketHeader extractFromPriorityQueue(PriorityQueue *pq) {
    PacketHeader maxElement = pq->packets[0];
    int lastElementIndex = --pq->count;
    int parentIndex, childIndex, temp;

    for (parentIndex = 0; parentIndex * 2 + 1 <= pq->count; parentIndex = childIndex) {
        childIndex = parentIndex * 2 + 1;
        if (childIndex < lastElementIndex && pq->packets[childIndex].payload_length < pq->packets[childIndex + 1].payload_length) {
            childIndex++;
        }
        if (pq->packets[lastElementIndex].payload_length >= pq->packets[childIndex].payload_length) {
            break;
        } else {
            temp = pq->packets[parentIndex];
            pq->packets[parentIndex] = pq->packets[childIndex];
            pq->packets[childIndex] = temp;
        }
    }

    return maxElement;
}

int processPackets(PacketHeader *packetList, int packetCount) {
    HashTable ht;
    PriorityQueue pq;
    int uniquePairs = 0, totalPayloadLength = 0;

    initHashTable(&ht);
    initPriorityQueue(&pq);

    for (int i = 0; i < packetCount; i++) {
        insertPacket(&ht, &packetList[i]);
        insertToPriorityQueue(&pq, &packetList[i]);
        totalPayloadLength += packetList[i].payload_length;
        if (!findPacket(&ht, packetList[i].src_ip, packetList[i].dst_ip)) {
            uniquePairs++;
        }
    }

    double averagePayloadLength = (double)totalPayloadLength / packetCount;

    // Process packets based on payload length
    for (int i = 0; i < packetCount; i++) {
        PacketHeader currentPacket = extractFromPriorityQueue(&pq);
        printf("Processing packet: src=%s, dst=%s, protocol=%d, payload_length=%d\n",
               currentPacket.src_ip, currentPacket.dst_ip, currentPacket.protocol, currentPacket.payload_length);
    }

    return uniquePairs;
}

int main() {
    PacketHeader packetList[MAX_PACKETS];
    // Populate packetList with actual data
    int packetCount = 100; // Example count

    clock_t start = clock();
    int result = processPackets(packetList, packetCount);
    clock_t end = clock();

    double timeTaken = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;

    printf("Unique source-destination pairs: %d\n", result);
    printf("Average payload length: %.2f\n", averagePayloadLength);
    printf("Time taken to process packets: %.2f ms\n", timeTaken);

    return 0;
}
```

