#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_PDU_COUNT 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduList;

uint32_t rollingChecksum(uint32_t prev, uint16_t rnti) {
    return (prev + rnti) * 1103515245 + 12345; // Simplified rolling checksum
}

PduList* createPduList(size_t initialCapacity) {
    PduList *list = malloc(sizeof(PduList));
    if (!list) return NULL;

    list->pdus = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyPduList(PduList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdus);
        free(list);
    }
}

int addPduToList(PduList *list, uint32_t rxTag, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    if (rnti == 0 || list->count >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid RNTI or max count reached
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
    }

    size_t index = list->count;
    if (index >= list->capacity) {
        list->capacity = (list->capacity > 0) ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *newPdus = realloc(list->pdus, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPdus) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Memory allocation failed
        }
        list->pdus = newPdus;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdus[index];
    pdu->RX_UE_INFORMATION_TAG = rxTag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rollingChecksum(rxTag, rnti) % 256;

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

